INSERT INTO public.assistant_faq_entries
  (id, category, intent, user_questions, short_answer_sv, answer_sv, sources, required_permissions, related_routes, risk_level, escalation, updated_at, seeded_at)
VALUES
  ('bank-001', 'Bankkoppling & transaktioner', 'koppla_bank', $faq$["Hur kopplar jag banken?","Hur ansluter jag mitt bankkonto via PSD2?","Aktivera banksynk?"]$faq$::jsonb, $faq$Inställningar → Bank → Anslut bank. Identifiera dig med BankID hos banken och välj vilka konton som ska synkas.$faq$, $faq$Gå till Inställningar → Bank och välj din bank. Du skickas till bankens eget flöde där du godkänner läsbehörighet med BankID (PSD2-samtycke via Enable Banking). Välj sedan vilka konton som ska synkas och vilket BAS-konto (19xx) varje bankkonto mappas till. Första synken hämtar upp till ~90 dagars historik.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/banking']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-002', 'Bankkoppling & transaktioner', 'synk_schema', $faq$["Hur ofta synkas banken?","När hämtas nya transaktioner?","Kan jag synka manuellt?"]$faq$::jsonb, $faq$Automatisk synk körs varje natt; du kan alltid trycka "Synka nu" för en manuell hämtning.$faq$, $faq$Banksynken körs automatiskt varje natt (ca kl 05 UTC) och hämtar de senaste dagarnas transaktioner per aktivt konto. Knappen "Synka nu" på banksidan gör en djupare manuell hämtning (upp till 120 dagar bakåt). Endast bokförda transaktioner hos banken hämtas — preliminära kortköp dyker upp när banken bokfört dem.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/banking', '/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-003', 'Bankkoppling & transaktioner', 'samtycke_gar_ut', $faq$["Mitt bankmedgivande har gått ut — vad gör jag?","Varför slutade banken synka?","Förnya PSD2-samtycke?"]$faq$::jsonb, $faq$PSD2-samtycken gäller max 180 dagar — förnya kopplingen under Inställningar → Bank när du får aviseringen.$faq$, $faq$PSD2-samtycken har begränsad livslängd (ofta 90–180 dagar beroende på bank). Nordklart mejlar dig 7 och 3 dagar innan utgång, och markerar kopplingen som utgången när den slutar fungera. Förnya genom att klicka "Förnya koppling" och göra om BankID-godkännandet — historiken och kontomappningen behålls.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/banking']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-004', 'Bankkoppling & transaktioner', 'synk_misslyckas', $faq$["Banksynken misslyckades — varför?","Felmeddelande på bankkopplingen","Ett av mina konton synkar inte"]$faq$::jsonb, $faq$Kolla kopplingens felstatus på banksidan. Ett konto som felar stoppar inte de andra — förnya samtycket om felet kvarstår.$faq$, $faq$Öppna Inställningar → Bank och läs felmeddelandet på kopplingen. Vanliga orsaker: utgånget samtycke (förnya), tillfälligt bankfel (försök igen senare) eller ett enskilt konto som banken slutat exponera. Sedan synk-härdningen isoleras fel per konto: övriga konton fortsätter synka och kopplingen visar vilka konton som misslyckades.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/banking']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-005', 'Bankkoppling & transaktioner', 'importera_kontoutdrag', $faq$["Kan jag importera ett kontoutdrag som fil?","Hur läser jag in CSV från banken?","Bankfilsimport?"]$faq$::jsonb, $faq$Ja — ladda upp kontoutdraget (CSV/CAMT.053) under Import → Bankfil; formatet detekteras automatiskt.$faq$, $faq$Under Import → Bankfil laddar du upp bankens exportfil. Stödda format: SEB, Swedbank, Handelsbanken, Nordea, Nordea Business, Länsförsäkringar, ICA Banken, Skandia, Lunar, Northmill, generisk CSV samt CAMT.053 (ISO 20022). Du får en förhandsgranskning innan importen körs. Max filstorlek 10 MB; UTF-8 och Windows-1252 hanteras automatiskt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-006', 'Bankkoppling & transaktioner', 'dubbel_import', $faq$["Vad händer om jag importerar samma fil två gånger?","Blir det dubbletter om banken synkar och jag också laddar upp CSV?","Dubblettskydd vid import?"]$faq$::jsonb, $faq$Nej — samma fil blockeras per företag, och transaktioner dedupliceras på externt id, datum, belopp och text.$faq$, $faq$Dubblettskyddet har flera lager: 1) samma fil (innehålls-hash) kan bara importeras en gång per företag, 2) varje transaktion får ett stabilt externt id som dedupliceras, 3) en innehållsbrygga fångar samma transaktion som kommer både via PSD2 och CSV (datum + belopp + beskrivning), även när banken berikat texten. Redan bokförda transaktioner dupliceras aldrig.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import', '/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-007', 'Bankkoppling & transaktioner', 'transaktion_status', $faq$["Vad betyder statusarna på transaktionerna?","Vad är skillnaden på föreslagen och bokförd?","Vad innebär \"behöver granskas\"?"]$faq$::jsonb, $faq$Statusflödet: ej hanterad → föreslagen/behöver granskas → bokförd/matchad/avstämd. Automatiken sätter status och skäl.$faq$, $faq$Varje importerad transaktion får en automationsstatus: "Föreslagen" betyder att en trolig match eller kontering finns men kräver ditt godkännande. "Behöver granskas" betyder osäkert läge (t.ex. flera kandidater, delbetalning eller SIE-överlapp). "Auto-bokförd" visas när säker automatik bokfört den — alltid med skälkoder. "Avstämd" betyder länkad till en befintlig verifikation via bankavstämningen.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-008', 'Bankkoppling & transaktioner', 'varfor_inte_matchad', $faq$["Varför matchades inte transaktionen mot fakturan?","Transaktionen hittade inte min faktura — varför?","Ingen automatisk matchning skedde?"]$faq$::jsonb, $faq$Öppna transaktionen och se skälkoderna — vanligast är avvikande belopp, fel valuta, tvetydiga kandidater eller att fakturan inte är öppen.$faq$, $faq$Varje matchningsförsök loggas med skälkoder. Vanliga orsaker: beloppet avviker från fakturans restbelopp (delbetalning/överbetalning kräver granskning), OCR/referens saknas i betalningen, två fakturor är för lika (tvetydigt — automatiken vägrar gissa), fakturan är redan betald/bestriden, eller valutorna skiljer sig. Fråga assistenten "varför matchades inte transaktionen?" så hämtar den loggen och förklarar konkret.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/pending']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-009', 'Bankkoppling & transaktioner', 'auto_bokforing_regler', $faq$["När vågar systemet bokföra automatiskt?","Vilka regler gäller för säker automatik?","Vad krävs för auto-bokföring?"]$faq$::jsonb, $faq$Bara när alla spärrar passerar: rätt läge, hög träffsäkerhet, entydig kandidat, öppen period, ingen SIE-överlapp, under beloppsgränsen.$faq$, $faq$Automatiken bokför aldrig om: läget är Av/Föreslå, träffsäkerheten är under företagets tröskel (standard 95 %), två kandidater ligger nära varandra, perioden är stängd/låst, momshanteringen är oklar, en SIE-import överlappar datumintervallet, transaktionen redan är kopplad, eller beloppet överstiger din maxgräns. Kundfakturor auto-avräknas bara vid exakt belopp med stark referens; leverantörsbetalningar kräver att du uttryckligen tillåtit det.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/automation']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-010', 'Bankkoppling & transaktioner', 'godkann_forslag', $faq$["Hur godkänner jag ett matchningsförslag?","Var accepterar jag automatikens förslag?","Godkänna föreslagen bokföring?"]$faq$::jsonb, $faq$Öppna transaktionen eller Väntande åtgärder och klicka Godkänn — du ser hela verifikatet innan.$faq$, $faq$Förslag visas dels direkt på transaktionen (föreslagen faktura/kontering), dels som väntande åtgärder när det finns ett konkret verifikat att godkänna. Du ser alltid bokföringsraderna, underlaget och skälen innan du godkänner. Vid avslag anger du gärna orsak — det förbättrar framtida förslag.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/pending']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-011', 'Bankkoppling & transaktioner', 'egen_overforing', $faq$["Hur bokförs överföringar mellan mina egna konton?","Systemet föreslog fel på en intern överföring","Egen överföring mellan 1930 och 1932?"]$faq$::jsonb, $faq$Interna överföringar detekteras via motpartens IBAN och bokförs som 19xx→19xx i stället för kostnad/intäkt.$faq$, $faq$När motpartens IBAN på en transaktion matchar ett annat av företagets egna likvidkonton föreslår Nordklart en överföring mellan de två BAS-kontona (t.ex. 1930→1932) i stället för en kostnad. Valutaväxlingar mellan egna konton kräver alltid granskning (kursdifferens). Ser detektorn inte kontot? Kontrollera att båda kontona finns under Inställningar → Bank med IBAN.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/settings/banking']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-012', 'Bankkoppling & transaktioner', 'bankavgift', $faq$["Hur bokförs bankavgifter?","Kan bankavgifter bokföras automatiskt?","Vilket konto för bankkostnader?"]$faq$::jsonb, $faq$Bankavgifter bokförs på 6570; med säker automatik och avgiftsflaggan på bokförs små tydliga avgifter automatiskt.$faq$, $faq$Bankavgifter (kontoavgift, kortavgift m.m.) konteras Dr 6570 Bankkostnader / Kr 19xx, utan moms (finansiella tjänster är momsfria). Under Inställningar → Automatisering finns "Bokför bankavgifter automatiskt" — då auto-bokförs avgifter när texten tydligt är en avgift, beloppet är litet och riktningen stämmer. Allt annat blir förslag.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/automation', '/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-013', 'Bankkoppling & transaktioner', 'kategorisera_manuellt', $faq$["Hur bokför jag en transaktion manuellt?","Kategorisera en banktransaktion?","Var väljer jag konto för ett köp?"]$faq$::jsonb, $faq$Öppna transaktionen och välj kategori/konto — momsraderna byggs automatiskt utifrån vald behandling.$faq$, $faq$Klicka på transaktionen under Transaktioner och välj kategori (t.ex. kontorsmaterial, telefon, representation). Nordklart bygger verifikatet med rätt kostnadskonto, momssats och motkonto (ditt likvidkonto). Du kan även redigera raderna fritt eller ange att köpet är privat (bokförs mot eget uttag/2893). Vid godkännande skapas verifikationen atomiskt med nästa löpnummer.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-014', 'Bankkoppling & transaktioner', 'bulk_bokforing', $faq$["Kan jag bokföra många transaktioner samtidigt?","Massbokföring av liknande transaktioner?","Bulk-godkänna kategoriseringar?"]$faq$::jsonb, $faq$Ja — markera flera transaktioner och använd bulk-bokför; lika motparter föreslås samma kontering.$faq$, $faq$I transaktionslistan kan du markera flera rader och köra "Bokför valda". Transaktioner med samma motpart får samma konteringsförslag baserat på dina tidigare val (motpartsmallar). Hela batchen förhandsgranskas och bokförs som separata verifikationer. Osäkra rader hoppar automatiken över och lämnar för granskning.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-015', 'Bankkoppling & transaktioner', 'motpartsmallar', $faq$["Kommer systemet ihåg hur jag bokför en leverantör?","Vad är motpartsmallar?","Lär sig systemet mina konteringar?"]$faq$::jsonb, $faq$Ja — varje godkänd kontering lär upp en motpartsmall som återanvänds vid nästa köp från samma motpart.$faq$, $faq$När du bokför en transaktion sparas motpart + kontering som en mall (counterparty template). Nästa transaktion från samma motpart föreslås automatiskt med samma konton och momsbehandling, med stigande träffsäkerhet ju fler gånger du bekräftat. Mallarna är per företag och kan ses som en del av automatikens regelverk.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-016', 'Bankkoppling & transaktioner', 'ignorera_transaktion', $faq$["Kan jag dölja en transaktion som inte ska bokföras?","Ignorera en rad i bankflödet?","Privat transaktion på företagskontot?"]$faq$::jsonb, $faq$Ja — markera transaktionen som ignorerad, eller bokför den som privat (eget uttag).$faq$, $faq$En transaktion som inte ska bokföras i näringsverksamheten kan antingen markeras som ignorerad (döljs från avstämningen men finns kvar spårbart) eller bokföras som privat: eget uttag (2013) i enskild firma respektive fordran/skuld ägare (2893) i AB. Observera att bokslutet blockerar om obehandlade transaktioner finns kvar — ignorera är alltså ett aktivt, loggat val.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-017', 'Bankkoppling & transaktioner', 'flera_valutor', $faq$["Hur hanteras transaktioner i EUR/USD?","Valutakonto — funkar det?","Hur räknas växelkursen?"]$faq$::jsonb, $faq$Utländska transaktioner konverteras till SEK med Riksbankens kurs för transaktionsdatumet.$faq$, $faq$Varje icke-SEK-transaktion prissätts med Riksbankens mittkurs för transaktionens egen dag (med helgfallback) och lagrar både originalbelopp, kurs och SEK-belopp. Valutakonton mappas till egna 19xx-konton och hålls isär i bankavstämningen. Kursvinster/förluster vid betalning bokförs på 3960/7960.$faq$, $faq$["ML 8 kap 21–23 §§"]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-018', 'Bankkoppling & transaktioner', 'bankavstamning', $faq$["Hur gör jag bankavstämning?","Stämmer banksaldot mot 1930?","Vad är bankavstämningsvyn?"]$faq$::jsonb, $faq$Bankavstämningsvyn jämför banktransaktioner mot bokförda 19xx-rader och låter dig länka dem säkert.$faq$, $faq$Under Avstämning → Bank ser du differensen mellan bankens transaktioner och bokförda rader på likvidkontot för perioden. Verktyget föreslår länkningar (exakt belopp+datum, OCR-referens, ±3 dagar) som du godkänner; ingenting länkas i tysthet vid import. Öppningsbalanser och rättelserader exkluderas automatiskt från periodens rörelse så differensen blir rättvisande.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reconciliation/bank']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-019', 'Bankkoppling & transaktioner', 'sie_overlapp_bank', $faq$["Jag importerade en SIE-fil och nu vägrar systemet auto-bokföra — varför?","Vad betyder SIE-överlapp?","Dubbelbokningsrisk efter import?"]$faq$::jsonb, $faq$När en SIE-import täcker samma datumintervall som bankimporten blockeras automatisk kontering — verifikaten finns troligen redan.$faq$, $faq$Om en slutförd SIE-import överlappar bankimportens datumintervall innehåller den importerade bokföringen sannolikt redan verifikat för samma banktransaktioner. Nordklart blockerar då automatisk kategoribokning (dubbelbokningsskydd), flaggar transaktionerna med en varning och kör i stället avstämningsförslag som LÄNKAR banktransaktionerna till de befintliga verifikaten. Fakturamatchning tillåts fortfarande när den är säker och inget redan är bokfört.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/reconciliation/bank', '/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-020', 'Bankkoppling & transaktioner', 'transaktion_saknas', $faq$["En transaktion saknas i Nordklart — var är den?","Banken visar ett köp som inte kommit in","Synken hämtar inte allt?"]$faq$::jsonb, $faq$Kontrollera att transaktionen är bokförd hos banken, att rätt konto är aktiverat, och kör "Synka nu".$faq$, $faq$Vanliga orsaker: 1) transaktionen är ännu preliminär hos banken (endast bokförda hämtas), 2) kontot är avaktiverat i kontovalet under bankkopplingen, 3) transaktionen ligger utanför synkfönstret — kör "Synka nu" med fler dagar bakåt, eller 4) den dedupliceras korrekt mot en redan importerad rad. Kvarstår problemet, ladda upp ett kontoutdrag som fil så fångas den upp.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/banking', '/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-021', 'Bankkoppling & transaktioner', 'ta_bort_transaktion', $faq$["Kan jag radera en banktransaktion?","Ta bort felaktig importrad?","Transaktionen är fel — delete?"]$faq$::jsonb, $faq$Obokförda transaktioner kan tas bort/ignoreras; bokförda kräver storno av verifikationen först.$faq$, $faq$En importerad transaktion som inte är bokförd kan markeras som ignorerad eller tas bort. Är den bokförd får verifikationen inte ändras (BFL) — du gör i stället en rättelse: storno-vända verifikationen, varpå transaktionen frigörs och kan hanteras om. Allt loggas i händelsehistoriken.$faq$, $faq$["BFL 5 kap 5 §"]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-022', 'Bankkoppling & transaktioner', 'kvitto_pa_transaktion', $faq$["Hur kopplar jag ett kvitto till en transaktion?","Bifoga underlag på ett kortköp?","Kvittomatchning?"]$faq$::jsonb, $faq$Fota/ladda upp kvittot — det matchas mot transaktionen på belopp, datum och handlare, eller bifogas manuellt.$faq$, $faq$Ladda upp kvittot (foto eller PDF). Nordklart tolkar handlare, datum och belopp och föreslår matchning mot rätt korttransaktion. Du kan också öppna transaktionen och välja "Bifoga underlag". När transaktionen bokförs kopplas dokumentet till verifikationen och arkiveras enligt BFL 7 kap.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/documents']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-023', 'Bankkoppling & transaktioner', 'swish', $faq$["Hur hanteras Swish-betalningar?","Swish-försäljning — hur bokförs den?","Swish-utbetalningar från banken?"]$faq$::jsonb, $faq$Swish-transaktioner kommer in via banksynken som vanliga banktransaktioner och bokförs/matchas därifrån.$faq$, $faq$Swish-betalningar syns som transaktioner på det bankkonto Swish-numret är kopplat till och flödar in via banksynken. Försäljning via Swish bokförs som intäkt med rätt moms (dagskassa eller per betalning), och kundfakturor betalda med Swish matchas på belopp + referens som andra betalningar.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-024', 'Bankkoppling & transaktioner', 'beloppsgrans', $faq$["Kan jag sätta en maxgräns för automatisk bokföring?","Stoppa automatiken över ett visst belopp?","Beloppsgräns för auto-bokning?"]$faq$::jsonb, $faq$Ja — sätt "Max belopp för automatisk bokföring" under Inställningar → Automatisering.$faq$, $faq$Under Inställningar → Automatisering kan du ange ett maxbelopp (i SEK). Transaktioner över gränsen bokförs aldrig automatiskt oavsett träffsäkerhet — de blir förslag med skälkoden "amount_over_auto_cap". Gränsen gäller alla automatiska bokningar inklusive fakturaavräkning och bankavgifter.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/automation']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-025', 'Bankkoppling & transaktioner', 'stanga_av_automatik', $faq$["Hur stänger jag av all automatik?","Jag vill godkänna allt själv","Inaktivera auto-bokföring?"]$faq$::jsonb, $faq$Sätt bankläget till "Föreslå" (eller "Av") under Inställningar → Automatisering — då bokförs inget utan ditt godkännande.$faq$, $faq$Välj läget Föreslå så byggs matchningar och konteringsförslag men ingenting bokförs utan godkännande. Läget Av stänger även av förslagen. Ändringen gäller direkt för nya importer; redan skapade förslag ligger kvar för granskning. Alla lägen loggas i företagets granskningslogg.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/automation']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-026', 'Bankkoppling & transaktioner', 'skatteverket_betalning', $faq$["Hur bokförs betalningen till skattekontot?","Transaktion till Skatteverket — vilket konto?","Skattekontoinbetalning?"]$faq$::jsonb, $faq$Inbetalningar till skattekontot bokförs Dr 1630 / Kr 19xx; automatiken föreslår men bokför inte skattebetalningar utan tillstånd.$faq$, $faq$Betalningar till Skatteverkets bankgiro 5050-1055 identifieras som skattebetalningar och föreslås som Dr 1630 Skattekonto / Kr 19xx. Auto-bokning av skattebetalningar kräver att du aktivt slagit på flaggan under Automatisering (standard av). Med Skatteverket-kopplingen stäms 1630 dessutom av mot skattekontots faktiska rader (moms, AGI, F-skatt).$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/skattekonto', '/settings/automation']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-027', 'Bankkoppling & transaktioner', 'lonebetalning_match', $faq$["Matchas löneutbetalningar automatiskt?","Banktransaktionen för lön — hur bokförs den?","Lön betald från banken, dubbelbokning?"]$faq$::jsonb, $faq$Ja — utbetalningar som matchar en bokförd lönekörnings nettolön länkas till lönens befintliga verifikation.$faq$, $faq$När en lönekörning är bokförd väntar dess bankleg (nettolönen) på den faktiska utbetalningen. En utgående transaktion med samma datum och belopp som körningens nettolön länkas till lönens befintliga verifikation — ingen ny bokning skapas, så dubbelbokning undviks. Automatisk länkning kräver flaggan "Lönebetalningar" under Automatisering; annars läggs den som förslag.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/salary', '/settings/automation']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-028', 'Bankkoppling & transaktioner', 'delbetalning_kund', $faq$["Kunden betalade bara halva fakturan — vad händer?","Delbetalning av kundfaktura via bank?","Restbelopp efter betalning?"]$faq$::jsonb, $faq$Delbetalningar auto-bokförs aldrig — de blir en väntande åtgärd där du bekräftar avräkning mot fakturan.$faq$, $faq$Vid delbetalning (beloppet understiger fakturans restbelopp) skapar automatiken en väntande åtgärd i stället för att bokföra tyst. Godkänner du den avräknas beloppet mot fakturan (Dr 19xx / Kr 1510 med delbeloppet), fakturan får status delbetald och restbeloppet ligger kvar i kundreskontran. Underbetalningar med små differenser hanteras som betalningsdifferens.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/pending', '/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-029', 'Bankkoppling & transaktioner', 'overbetalning_kund', $faq$["Kunden betalade för mycket — hur bokförs det?","Överbetalning på faktura?","Vad är kundsaldo/tillgodo?"]$faq$::jsonb, $faq$Överskottet bokförs som kundsaldo (tillgodo) — aldrig tyst; du godkänner via väntande åtgärd.$faq$, $faq$Betalar kunden mer än restbeloppet avräknas fakturan fullt och överskottet bokförs som skuld till kund (kundsaldo/tillgodohavande). Det kan sedan användas mot nästa faktura eller återbetalas. Överbetalningar auto-bokförs aldrig i valutafakturor och kräver alltid godkännande; kundsaldon syns i kundreskontran.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/customers', '/pending']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-030', 'Bankkoppling & transaktioner', 'kontanter', $faq$["Hur bokför jag kontantförsäljning?","Dagskassa utan bankkoppling?","Kassakonto 1910?"]$faq$::jsonb, $faq$Kontanthändelser registreras manuellt som verifikationer mot 1910 Kassa — bankflödet berörs först vid insättning.$faq$, $faq$Kontantförsäljning bokförs som manuell verifikation (Dr 1910 / Kr 30xx + utgående moms) senast påföljande arbetsdag enligt BFL. När kontanterna sätts in på banken bokförs Dr 1930 / Kr 1910, och bankens insättningstransaktion matchas mot den verifikationen i avstämningen.$faq$, $faq$["BFL 5 kap 2 §"]$faq$::jsonb, '{}'::text[], array['/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-031', 'Bankkoppling & transaktioner', 'historik_längd', $faq$["Hur långt bak hämtar banksynken?","Kan jag få äldre transaktioner än 90 dagar?","Historikgräns PSD2?"]$faq$::jsonb, $faq$PSD2 ger normalt ~90 dagars historik utan ny stark autentisering — äldre perioder importeras via kontoutdragsfil.$faq$, $faq$Vid första synken begärs den längsta historik banken tillåter (ofta 90 dagar, ibland mer direkt efter samtycket). Behöver du äldre transaktioner: exportera kontoutdrag som CSV/CAMT.053 från internetbanken och importera under Import → Bankfil — dubblettskyddet ser till att överlappet inte skapar dubbletter.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import', '/settings/banking']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-032', 'Bankkoppling & transaktioner', 'vilka_konton_synkas', $faq$["Kan jag välja vilka konton som synkas?","Stänga av sparkontot från synken?","Ett konto ska inte in i bokföringen"]$faq$::jsonb, $faq$Ja — aktivera/avaktivera konton per bankkoppling under Hantera konton; avaktiverade bevaras men synkas inte.$faq$, $faq$Under Inställningar → Bank → Hantera konton väljer du per konto om det ska synkas. Avaktiverade konton behåller sin historik och mappning men får inga nya transaktioner. Privata konton bör inte kopplas alls — bokföringen ska bara innehålla näringsverksamhetens konton.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/banking']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-033', 'Bankkoppling & transaktioner', 'transaktionstext_redigera', $faq$["Kan jag byta rubrik på en transaktion?","Redigera transaktionens beskrivning?","Bankens text är kryptisk"]$faq$::jsonb, $faq$Ja — rubriken kan redigeras fritt; bankens originaltext bevaras alltid för spårbarhet och dubblettskydd.$faq$, $faq$Öppna transaktionen och redigera titeln. Bankens ursprungliga text sparas oförändrad (original_description) och används för dubblettdetektering och revision, så en rubrikändring kan aldrig orsaka en dubblettimport. Återställ till originalet med ett klick.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-034', 'Bankkoppling & transaktioner', 'felbokad_automatik', $faq$["Automatiken bokförde fel — hur rättar jag?","Ångra en auto-bokförd transaktion?","Fel konto på automatisk bokning?"]$faq$::jsonb, $faq$Storno-vänd verifikationen och bokför om — och justera gärna motpartsmallen/automatikläget så det inte upprepas.$faq$, $faq$Öppna verifikationen och välj Rätta/Vänd (storno). Originalet förblir orört enligt BFL; en vändningsverifikation skapas och transaktionen frigörs för ny kontering. Kontrollera sedan motpartsmallen (den lär sig av rättelsen) och överväg att sänka automatikläget eller beloppsgränsen. Varje automatiskt beslut har skälkoder så du kan se varför den bokfördes.$faq$, $faq$["BFL 5 kap 5 §"]$faq$::jsonb, '{}'::text[], array['/transactions', '/settings/automation']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-035', 'Bankkoppling & transaktioner', 'kortkop_utland', $faq$["Hur bokförs kortköp i utländsk valuta?","Utlandsköp med företagskortet?","Moms på köp från utlandet via kort?"]$faq$::jsonb, $faq$Kortköpet bokförs i SEK med bankens dragna belopp; utländsk moms är normalt inte avdragsgill som svensk ingående moms.$faq$, $faq$Bankraden visar det SEK-belopp banken drog (inkl. växlingspåslag) — det är det som bokförs. För köp från utländska leverantörer gäller ofta omvänd skattskyldighet (tjänster) eller importmoms (varor); utländsk moms på kvittot får inte lyftas som svensk ingående moms. Assistenten hjälper dig välja rätt momsbehandling per kvitto.$faq$, $faq$["ML 13 kap"]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-036', 'Bankkoppling & transaktioner', 'referens_ocr_saknas', $faq$["Betalningen saknar OCR — kan den ändå matchas?","Kunden betalade utan referens","Match utan OCR-nummer?"]$faq$::jsonb, $faq$Ja — då matchas på belopp, kundnamn och datum, men med lägre träffsäkerhet som oftast kräver godkännande.$faq$, $faq$Utan OCR/referens försöker matchningen med exakt belopp + kundnamn i transaktionstexten + datumnärhet. Exakt belopp och kundnamn ger hög träffsäkerhet; enbart belopp ger lägre och blir förslag. Finns två öppna fakturor på samma belopp flaggas det som tvetydigt och du väljer manuellt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-037', 'Bankkoppling & transaktioner', 'se_beslutslogg', $faq$["Var ser jag varför automatiken gjorde som den gjorde?","Finns logg över automatiska beslut?","Granska automationens historik?"]$faq$::jsonb, $faq$Varje beslut sparas med skälkoder, träffsäkerhet och resultat — se transaktionens automationsdetaljer.$faq$, $faq$Alla automationsbeslut sparas i en besluttslogg (kandidater, poäng, skälkoder, vald åtgärd, vem/vad som utförde den) och matchningsförsök i en separat matchlogg. På transaktionen visas beslutet med skälen på svenska. Loggen är append-only och del av företagets revisionsspår.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-038', 'Bankkoppling & transaktioner', 'idempotens_synk', $faq$["Om synken körs två gånger — blir det dubbletter?","Är importen säker att köra om?","Retry av misslyckad import?"]$faq$::jsonb, $faq$Omkörningar är säkra: transaktioner dedupliceras och automationsbeslut är idempotenta (körs aldrig om).$faq$, $faq$Både synk och filimport är säkra att köra igen. Transaktioner dedupliceras på externt id och innehåll, och varje automationsbeslut lagras med en deterministisk idempotensnyckel — en omkörning spelar upp det befintliga beslutet i stället för att bokföra på nytt. En misslyckad import kan därför alltid startas om utan risk för dubbletter.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-039', 'Bankkoppling & transaktioner', 'camt053', $faq$["Stödjer ni CAMT.053?","ISO 20022-filer från banken?","XML-kontoutdrag?"]$faq$::jsonb, $faq$Ja — CAMT.053 (ISO 20022 XML) importeras under Import → Bankfil med stabila referens-id:n.$faq$, $faq$CAMT.053-filer tolkas med posternas entry reference som stabilt externt id, vilket ger exakt deduplicering vid omimport. Referenser (OCR) plockas ur remittance information och används för fakturamatchning. Formatet detekteras automatiskt på filinnehållet.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-040', 'Bankkoppling & transaktioner', 'anslut_flera_banker', $faq$["Kan jag koppla flera banker samtidigt?","Företaget har konton i två banker","Flera bankkopplingar?"]$faq$::jsonb, $faq$Ja — koppla hur många banker som helst; varje konto får sitt eget BAS-konto och stäms av separat.$faq$, $faq$Du kan ha flera aktiva bankkopplingar parallellt (t.ex. SEB för företagskontot och ett kort hos annan bank). Varje bankkonto mappas till sitt eget 19xx-konto och transaktioner scopas per konto, så avstämningarna hålls isär. Synken hanterar kopplingarna oberoende — en banks fel påverkar inte de andra.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/banking']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-041', 'Bankkoppling & transaktioner', 'pengar_in_okand', $faq$["Okänd insättning — hur hanterar jag den?","Pengar in som inte är en fakturabetalning?","Insättning utan förklaring?"]$faq$::jsonb, $faq$Utred källan innan bokning: ägartillskott, lån, bidrag och felinsättningar bokförs olika.$faq$, $faq$En inbetalning utan fakturamatch kan vara ägarinsättning (2018/2093), lån (23xx), bidrag/stöd (39xx, ibland momsfritt) eller en felaktig insättning som ska returneras. Automatiken lämnar sådana som "behöver granskas". Bokför inte som intäkt slentrianmässigt — fel klassificering påverkar både moms och skatt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'medium', $faq$Osäker på klassificeringen av en större insättning? Stäm av med din redovisningskonsult innan bokning.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-042', 'Bankkoppling & transaktioner', 'banken_saknas', $faq$["Min bank finns inte i listan — vad gör jag?","Stöds inte min neobank?","Bank utan PSD2-stöd?"]$faq$::jsonb, $faq$Importera kontoutdrag som fil (CSV/CAMT.053) — flödet nedströms är exakt detsamma som vid synk.$faq$, $faq$Om banken saknar PSD2-stöd i listan använder du filimport: exportera kontoutdrag från internetbanken och ladda upp under Import → Bankfil (generisk CSV funkar för de flesta). Matchning, automatisering och avstämning fungerar identiskt oavsett hur transaktionerna kom in.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-043', 'Bankkoppling & transaktioner', 'transaktions_datum', $faq$["Vilket datum bokförs banktransaktioner på?","Bokföringsdatum vs valutadatum?","Fel dag på verifikationen?"]$faq$::jsonb, $faq$Verifikationen dateras på bankens bokföringsdag för transaktionen (affärshändelsens dag).$faq$, $faq$Nordklart använder bankens bokföringsdatum som verifikationsdatum — det är affärshändelsens dag enligt BFL. Ligger dagen i en låst/stängd period blockeras automatisk bokning och du får hantera den som rättelse i öppen period. Datumet kan inte ändras efter bokföring; rätta via storno vid behov.$faq$, $faq$["BFL 5 kap"]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-044', 'Bankkoppling & transaktioner', 'vilande_forslag', $faq$["Hur länge ligger förslag kvar?","Försvinner omatchade transaktioner?","Gamla förslag städas?"]$faq$::jsonb, $faq$Förslag ligger kvar tills du hanterar dem — bokslutet blockerar tills periodens transaktioner är hanterade.$faq$, $faq$Matchnings- och konteringsförslag har ingen utgångstid; de väntar tills du godkänner, avvisar eller bokför manuellt. Översikten visar antal ohanterade transaktioner per period, och bokslutsguiden blockerar årsavslut tills alla periodens transaktioner är bokförda, matchade eller aktivt ignorerade.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bank-045', 'Bankkoppling & transaktioner', 'api_transaktioner', $faq$["Kan jag skapa transaktioner via API?","Programmatisk import av transaktioner?","API för bankdata?"]$faq$::jsonb, $faq$Ja — POST /api/v1/companies/{id}/transactions/ingest tar en transaktionsarray med samma dedup som övriga flöden.$faq$, $faq$API:et exponerar transaktionsimport (transactions:write-scope): skicka en array med datum, belopp, valuta, beskrivning och externt id. Dedupliceringen och automatiken är identisk med synk/filimport. Det finns även bankfilsimport via multipart (POST .../imports/bank) med operations-id för polling.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/api']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-001', 'Bokföring, verifikationer & BAS-konton', 'skapa_verifikation', $faq$["Hur skapar jag en manuell verifikation?","Bokföra manuellt verifikat?","Ny bokföringspost?"]$faq$::jsonb, $faq$Bokföring → Ny verifikation: ange datum, beskrivning och balanserade debet/kredit-rader.$faq$, $faq$Under Bokföring skapar du en manuell verifikation med datum, beskrivning och rader (konto, debet, kredit). Summan av debet måste vara lika med kredit — annars går den inte att bokföra. Verifikationen sparas först som utkast och får sitt löpnummer när du bokför den. Underlag (PDF/foto) bifogas direkt på verifikationen.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-002', 'Bokföring, verifikationer & BAS-konton', 'andra_verifikation', $faq$["Kan jag ändra en bokförd verifikation?","Redigera ett bokfört verifikat?","Fel i verifikationen — ändra?"]$faq$::jsonb, $faq$Nej — bokförda verifikationer är oföränderliga enligt BFL. Rätta genom att vända (storno) och bokföra om.$faq$, $faq$När en verifikation är bokförd får den inte ändras eller raderas (BFL 5 kap 5 §, spärren ligger i databasen). Rättelse görs som ny verifikation: antingen Vänd (storno — spegelvänd post som nollar originalet) eller Rätta (storno + korrekt ompostering i ett steg). Båda länkas till originalet så kedjan är spårbar.$faq$, $faq$["BFL 5 kap 5 §"]$faq$::jsonb, '{}'::text[], array['/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-003', 'Bokföring, verifikationer & BAS-konton', 'storno', $faq$["Vad är storno?","Hur vänder jag en verifikation?","Ångra bokföring?"]$faq$::jsonb, $faq$Storno är en spegelvänd verifikation som nollställer originalet — Nordklarts sätt att "ångra" bokföring.$faq$, $faq$Storno skapar en ny verifikation där debet och kredit byter plats, daterad i öppen period, länkad till originalet. Nettot blir noll och båda syns i huvudboken — det är det lagliga sättet att ångra. Knappen finns på verifikationen ("Vänd"). Vill du samtidigt bokföra rätt, använd "Rätta" som gör storno + ny post i samma flöde.$faq$, $faq$["BFL 5 kap 5 §","BFNAR 2013:2"]$faq$::jsonb, '{}'::text[], array['/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-004', 'Bokföring, verifikationer & BAS-konton', 'verifikationsnummer', $faq$["Hur sätts verifikationsnumren?","Kan jag välja nummer själv?","Verifikationsnummer hoppar?"]$faq$::jsonb, $faq$Nummer tilldelas automatiskt och atomiskt i löpande följd per serie — de kan aldrig väljas manuellt.$faq$, $faq$Verifikationsnummer tilldelas av databasen i strikt löpande följd per serie och räkenskapsår, i samma ögonblick som posten bokförs. Detta garanterar obruten nummerserie enligt BFL. Uppstår en lucka (t.ex. avbruten bokföring) kräver systemet en dokumenterad förklaring (BFNAR 2013:2) som du anger under Bokföring → Nummerluckor.$faq$, $faq$["BFNAR 2013:2"]$faq$::jsonb, '{}'::text[], array['/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-005', 'Bokföring, verifikationer & BAS-konton', 'underlag_krav', $faq$["Måste varje verifikation ha ett underlag?","Verifikation utan kvitto?","Bokföra utan dokument?"]$faq$::jsonb, $faq$Ja, som huvudregel — varje affärshändelse kräver verifikationsunderlag. Undantag markeras aktivt med motivering.$faq$, $faq$BFL kräver att varje verifikation har ett underlag som visar affärshändelsen (kvitto, faktura, avtal). Nordklart varnar för verifikationer utan dokument. För poster där underlag inte är relevant (t.ex. rena omföringar) kan du markera "underlag krävs ej" med motivering — det loggas och syns i granskningsspåret.$faq$, $faq$["BFL 5 kap 6–7 §§"]$faq$::jsonb, '{}'::text[], array['/bookkeeping', '/documents']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-006', 'Bokföring, verifikationer & BAS-konton', 'hitta_konto', $faq$["Vilket BAS-konto ska jag använda?","Hur hittar jag rätt konto?","Kontoförslag?"]$faq$::jsonb, $faq$Sök i kontoplanen på namn eller nummer — eller fråga assistenten som föreslår konto utifrån händelsen.$faq$, $faq$Kontoplanen (BAS 2026) är sökbar på både nummer och namn. Beskriv annars händelsen för assistenten ("köpt skrivbord för 4 000 kr") så föreslår den konto, momssats och hela verifikatet. Klasserna: 1 tillgångar, 2 eget kapital/skulder, 3 intäkter, 4 varuinköp, 5–6 övriga kostnader, 7 personal/avskrivningar, 8 finansiellt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/bookkeeping', '/chat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-007', 'Bokföring, verifikationer & BAS-konton', 'aktivera_konto', $faq$["Kontot finns inte i min kontoplan — hur lägger jag till det?","Aktivera ett BAS-konto?","Nytt konto i kontoplanen?"]$faq$::jsonb, $faq$Aktivera kontot under Inställningar → Bokföring → Kontoplan; hela BAS 2026 finns tillgänglig.$faq$, $faq$Din kontoplan visar de aktiverade kontona, men hela BAS 2026 finns i systemet. Sök upp kontot under Inställningar → Bokföring och aktivera det. Vid SIE-import aktiveras refererade konton automatiskt. Bokning mot ett inaktivt konto ger ett tydligt fel med möjlighet att aktivera direkt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-008', 'Bokföring, verifikationer & BAS-konton', 'periodlas', $faq$["Vad innebär att en period är låst?","Kan jag bokföra i förra månaden?","Låsa bokföringen till ett datum?"]$faq$::jsonb, $faq$Låst period blockerar alla nya poster t.o.m. låsdatumet — skyddet ligger i databasen och gäller även automatiken.$faq$, $faq$Under Inställningar → Bokföring kan du låsa bokföringen till och med ett datum (t.ex. efter momsdeklarationen). Databasens triggers stoppar då alla verifikationer daterade i det låsta intervallet — även automatikens. Stängda räkenskapsår är alltid låsta. Rättelser görs i öppen period med hänvisning till originalet.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/bookkeeping']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-009', 'Bokföring, verifikationer & BAS-konton', 'rakenskapsperiod_skapas', $faq$["Måste jag skapa räkenskapsår manuellt?","Nytt räkenskapsår i systemet?","Perioden saknas — vad gör jag?"]$faq$::jsonb, $faq$Perioder skapas automatiskt vid behov; nytt år kan skapas manuellt först när föregående är låst.$faq$, $faq$När du bokför en post i ett datum utan öppen period skapas räkenskapsperioden automatiskt utifrån ditt räkenskapsår. Vill du skapa nästa år i förväg kräver systemet att föregående år minst är låst (BFL tillåter parallell löpande bokföring, men gamla året ska inte kunna få nya poster av misstag).$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/bookkeeping/fiscal-periods']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-010', 'Bokföring, verifikationer & BAS-konton', 'moms_konton', $faq$["Vilka momskonton används?","Var hamnar utgående och ingående moms?","26xx-kontona?"]$faq$::jsonb, $faq$Utgående moms: 2611/2621/2631 (25/12/6 %), ingående moms: 2641, momsredovisning: 2650.$faq$, $faq$Standardkontona är 2611 utgående moms 25 %, 2621 12 %, 2631 6 %; 2614 utgående moms omvänd skattskyldighet; 2641 ingående moms; 2645 beräknad ingående moms på förvärv från utlandet; 2650 redovisningskonto för moms. Momsrapporten summerar dessa till rätt rutor automatiskt när du använder systemets momsbehandlingar.$faq$, $faq$["BAS 2026"]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-011', 'Bokföring, verifikationer & BAS-konton', 'representation', $faq$["Hur bokför jag representation?","Får jag dra momsen på kundlunch?","Representationsregler?"]$faq$::jsonb, $faq$Extern representation: måltider ej avdragsgilla, men moms får lyftas på underlag upp till 300 kr/person.$faq$, $faq$Måltidsrepresentation är inte avdragsgill som kostnad (bokförs 6072, ej avdragsgill del), men ingående moms får dras på ett underlag upp till 300 kr exkl. moms per person och tillfälle. Enklare förtäring (fika < ca 60 kr) är avdragsgill (6071). Nordklarts representationsflöde frågar om antal personer och syfte och räknar momsen åt dig.$faq$, $faq$["IL 16 kap 2 §","ML 13 kap 27 §"]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-012', 'Bokföring, verifikationer & BAS-konton', 'friskvard', $faq$["Hur bokförs friskvårdsbidrag?","Är gymkort avdragsgillt?","Friskvård i enskild firma?"]$faq$::jsonb, $faq$Friskvårdsbidrag till anställda bokförs 7699/7690 och är skattefritt upp till 5 000 kr/år — gäller inte ägaren i enskild firma.$faq$, $faq$För anställda (inklusive ägare som är anställd i sitt AB) är friskvårdsbidrag skattefri förmån upp till 5 000 kr/år; bokförs som personalkostnad (76xx) utan momslyft för friskvårdsbidrag mot kvitto. Enskilda näringsidkare räknas inte som anställda och kan inte ge sig själva friskvårdsbidrag.$faq$, $faq$["Skatteverket: friskvårdsbidrag"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-013', 'Bokföring, verifikationer & BAS-konton', 'forbrukningsinventarier', $faq$["När är något förbrukningsinventarie vs inventarie?","Måste jag skriva av datorn?","Halva prisbasbeloppet-regeln?"]$faq$::jsonb, $faq$Under ett halvt prisbasbelopp (29 600 kr år 2026) eller < 3 års livslängd: kostnadsför direkt på 5410.$faq$, $faq$Inköp under ett halvt prisbasbelopp exkl. moms (29 600 kr 2026) eller med kortare livslängd än 3 år bokförs direkt som förbrukningsinventarier (5410). Dyrare tillgångar aktiveras som inventarier (1220) och skrivs av — Nordklart flaggar automatiskt köp över gränsen och föreslår aktivering med avskrivningsplan.$faq$, $faq$["IL 18 kap 4 §"]$faq$::jsonb, '{}'::text[], array['/assets']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-014', 'Bokföring, verifikationer & BAS-konton', 'avskrivningar', $faq$["Hur fungerar avskrivningar i Nordklart?","Bokförs avskrivningar automatiskt?","Avskrivningsplan för inventarier?"]$faq$::jsonb, $faq$Registrera tillgången med avskrivningsplan — månads/årsavskrivningar föreslås och bokförs efter godkännande.$faq$, $faq$Under Tillgångar registrerar du inventarien (anskaffningsvärde, datum, nyttjandeperiod). Nordklart beräknar planenlig avskrivning (Dr 78xx / Kr 12x9) och skapar posterna löpande; bokslutsguiden kontrollerar att årets avskrivningar är bokförda. Räkenskapsenlig avskrivning (30/20-regeln) hanteras som skattemässig justering i bokslutet.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/assets', '/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-015', 'Bokföring, verifikationer & BAS-konton', 'eget_uttag', $faq$["Hur bokför jag eget uttag?","Jag tog ut pengar till mig själv i enskild firma","Eget uttag konto?"]$faq$::jsonb, $faq$Eget uttag i enskild firma bokförs Dr 2013 / Kr 1930 — det är inte lön och utlöser ingen skatt vid uttaget.$faq$, $faq$I enskild firma bokförs ägarens uttag Dr 2013 Eget uttag / Kr 19xx. Det påverkar inte resultatet — du beskattas på verksamhetens överskott oavsett uttag. Egna insättningar bokförs spegelvänt på 2018. I aktiebolag finns inte egna uttag; där gäller lön eller utdelning, och privata utlägg går via 2893.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-016', 'Bokföring, verifikationer & BAS-konton', 'agare_utlagg', $faq$["Jag betalade företagets kostnad privat — hur bokför jag?","Utlägg med privat kort?","Ägarutlägg i AB?"]$faq$::jsonb, $faq$Bokför kostnaden som vanligt men kreditera 2018 (EF) eller 2893 (AB) i stället för bankkontot.$faq$, $faq$Vid privat betalt företagsinköp bokförs kostnaden och momsen som vanligt, men motkontot blir Egen insättning 2018 (enskild firma) eller Skuld till närstående 2893 (AB) i stället för 19xx. I AB återbetalar bolaget sedan via bank (Dr 2893 / Kr 1930). Leverantörsfakturaflödet har en inbyggd "betald privat"-flagga som gör detta åt dig.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-017', 'Bokföring, verifikationer & BAS-konton', 'milersattning', $faq$["Hur bokför jag milersättning?","Skattefri bilersättning egen bil?","Milersättning enskild firma vs AB?"]$faq$::jsonb, $faq$Skattefri milersättning för egen bil i tjänsten är 25 kr/mil (2026) — bokförs 7331 i AB; i EF görs avdraget i deklarationen.$faq$, $faq$I aktiebolag betalar bolaget ut skattefri milersättning (25 kr/mil för egen bil) mot körjournal, bokförd Dr 7331 / Kr 19xx. I enskild firma bokförs ingen ersättning — avdraget (samma schablon) görs i NE-bilagan. Belopp över schablonen är skattepliktig ersättning.$faq$, $faq$["Skatteverket: milersättning"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-018', 'Bokföring, verifikationer & BAS-konton', 'import_moms', $faq$["Hur bokför jag importmoms?","Köpt varor från land utanför EU?","Monetärt tullvärde och moms?"]$faq$::jsonb, $faq$Importmoms redovisas till Skatteverket via momsdeklarationen: beräkna 25 % på beskattningsunderlaget, bokför 2615/2645.$faq$, $faq$Vid varuimport (momsregistrerat företag) redovisas importmomsen i momsdeklarationen, inte till Tullverket. Bokför varukostnaden på 40xx-konto och momsen som utgående importmoms Kr 2615 och samtidigt ingående Dr 2645 (netto noll vid full avdragsrätt). Underlaget är tullvärdet + tull + bikostnader. Nordklarts momsbehandling "import" bygger raderna åt dig.$faq$, $faq$["ML 5 kap"]$faq$::jsonb, '{}'::text[], array['/transactions', '/reports/vat']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-019', 'Bokföring, verifikationer & BAS-konton', 'omvand_byggmoms', $faq$["Hur fungerar omvänd byggmoms?","Fakturera utan moms inom bygg?","Omvänd skattskyldighet byggtjänster?"]$faq$::jsonb, $faq$Byggtjänster B2B faktureras utan moms — köparen redovisar både ut- och ingående moms (2614/2645).$faq$, $faq$Vid försäljning av byggtjänster till byggföretag gäller omvänd skattskyldighet: du fakturerar utan moms med texten "Omvänd betalningsskyldighet" och köparens VAT-nummer. Som köpare bokför du beräknad utgående moms Kr 2614 och ingående Dr 2645 på samma belopp. Nordklart har momsbehandlingen "omvänd byggmoms" som gör konteringen och momsrapportens rutor rätt.$faq$, $faq$["ML 16 kap 13 §"]$faq$::jsonb, '{}'::text[], array['/invoices', '/reports/vat']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-020', 'Bokföring, verifikationer & BAS-konton', 'eu_tjanst_inkop', $faq$["Köpt SaaS/molntjänst från utlandet — hur bokförs momsen?","Google/AWS-faktura utan moms?","Omvänd skattskyldighet EU-tjänster?"]$faq$::jsonb, $faq$Tjänsteköp från utlandet: omvänd skattskyldighet — bokför beräknad moms 2614/2645, kostnaden på vanligt konto.$faq$, $faq$Fakturor från t.ex. AWS, Google Ireland eller OpenAI kommer utan svensk moms. Du redovisar förvärvsmoms: Kr 2614 utgående moms omvänd skattskyldighet och Dr 2645 beräknad ingående moms (25 % av fakturabeloppet), netto noll vid full avdragsrätt. Beloppet hamnar i momsrutorna 21/22 + 30 + 48. Välj momsbehandling "EU-tjänst/utlandstjänst" så byggs raderna automatiskt.$faq$, $faq$["ML 6 kap","ML 16 kap"]$faq$::jsonb, '{}'::text[], array['/transactions', '/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-021', 'Bokföring, verifikationer & BAS-konton', 'eu_varu_inkop', $faq$["Unionsinternt förvärv — hur bokförs det?","Varuköp från EU-land med VAT-nummer?","Moms på EU-varor?"]$faq$::jsonb, $faq$EU-varuinköp med VAT-nummer: omvänd moms (2615/2645), värdet i ruta 20 i momsdeklarationen.$faq$, $faq$Varuköp från EU-leverantör där du angett ditt VAT-nummer faktureras utan moms. Bokför varukostnaden (40xx) och förvärvsmoms Kr 2615 / Dr 2645. Momsdeklarationen får underlaget i ruta 20 och momsen i rutorna 30–32 + 48. Utan giltigt VAT-nummer debiterar säljaren sitt lands moms — som inte får lyftas i Sverige.$faq$, $faq$["ML 5 kap 22 §"]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-022', 'Bokföring, verifikationer & BAS-konton', 'forsaljning_eu', $faq$["Hur fakturerar jag kund i annat EU-land?","Moms på EU-försäljning B2B?","Periodisk sammanställning?"]$faq$::jsonb, $faq$B2B med giltigt VAT-nummer: fakturera utan moms (omvänd skattskyldighet) och rapportera i periodisk sammanställning.$faq$, $faq$Tjänste- och varuförsäljning till momsregistrerade EU-företag faktureras utan svensk moms med köparens VAT-nummer och texten "Reverse charge". Nordklart validerar VAT-numret mot VIES, lägger försäljningen i rätt momsruta (35/39) och genererar periodisk sammanställning. B2C inom EU kan kräva OSS-registrering över tröskeln 99 680 kr.$faq$, $faq$["ML 6 kap","Skatteverket: periodisk sammanställning"]$faq$::jsonb, '{}'::text[], array['/invoices', '/reports/vat']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-023', 'Bokföring, verifikationer & BAS-konton', 'export_utanfor_eu', $faq$["Moms vid export utanför EU?","Fakturera kund i USA/Norge?","Exportförsäljning momsfri?"]$faq$::jsonb, $faq$Export av varor och de flesta tjänster utanför EU är momsfri — försäljningen hamnar i ruta 36/40.$faq$, $faq$Varuexport utanför EU är momsfri (0 %); tjänster till näringsidkare utanför EU är normalt omsatta utomlands och faktureras utan svensk moms. Använd momsbehandlingen "Export" så bokförs försäljningen på 3305/3308 och hamnar i rätt momsruta. Spara exportbevis/tulldokument som underlag.$faq$, $faq$["ML 10 kap"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-024', 'Bokföring, verifikationer & BAS-konton', 'felaktig_momssats', $faq$["Jag bokförde med fel momssats — hur rättar jag?","25 % i stället för 12 % — vad gör jag?","Rätta momsfel?"]$faq$::jsonb, $faq$Rätta verifikationen via storno + ny post; är momsdeklarationen redan lämnad kan den behöva rättas hos Skatteverket.$faq$, $faq$Vänd den felaktiga verifikationen (storno) och bokför om med rätt momssats. Ligger felet i en period vars momsdeklaration redan lämnats: rätta i nästa deklaration om beloppet är litet, annars begär omprövning av den lämnade deklarationen hos Skatteverket. Momsrapporten i Nordklart visar alltid aktuellt bokfört läge.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'high', $faq$Större momsfel i redan inlämnade deklarationer bör stämmas av med redovisningskonsult — skattetillägg kan aktualiseras.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-025', 'Bokföring, verifikationer & BAS-konton', 'huvudbok', $faq$["Var ser jag huvudboken?","Kontoutdrag per BAS-konto?","Alla transaktioner på konto 1930?"]$faq$::jsonb, $faq$Rapporter → Huvudbok visar alla poster per konto med ingående/utgående saldo.$faq$, $faq$Huvudboken (Rapporter → Huvudbok) listar varje kontos poster i datumordning med IB, periodens rörelser och UB. Klicka en rad för att öppna verifikationen. Du kan filtrera på period och konto samt exportera. Balans- och resultatrapport, råbalans och verifikationslista finns under samma meny.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-026', 'Bokföring, verifikationer & BAS-konton', 'rabalans', $faq$["Råbalansen balanserar inte — vad gör jag?","Debet och kredit stämmer inte?","Trial balance diff?"]$faq$::jsonb, $faq$En obalanserad råbalans indikerar datafel — kontrollera ofullständiga importer; systemet förhindrar normalt obalans.$faq$, $faq$Nordklart kräver balans i varje verifikation, så råbalansen ska alltid balansera. En differens beror nästan alltid på en ofullständig äldre import eller manuellt ingripen data. Kör Rapporter → Råbalans för att hitta perioden, och granska SIE-importstatus. Bokslutsguiden blockerar tills balansen stämmer. Kontakta support om obalansen inte går att härleda.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports', '/import']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-027', 'Bokföring, verifikationer & BAS-konton', 'sok_verifikation', $faq$["Hur hittar jag en specifik verifikation?","Söka i bokföringen?","Var är verifikat A57?"]$faq$::jsonb, $faq$Sök på nummer, text eller belopp i verifikationslistan under Bokföring.$faq$, $faq$Verifikationslistan kan filtreras på serie+nummer (t.ex. A57), fritext i beskrivningen, belopp, datumintervall, källtyp (banktransaktion, faktura, import …) och status. Från en transaktion eller faktura kan du alltid hoppa direkt till dess verifikation via länken.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-028', 'Bokföring, verifikationer & BAS-konton', 'arets_resultat', $faq$["Hur bokförs årets resultat?","Konto 8999 och 2099?","Resultatdisposition?"]$faq$::jsonb, $faq$Årets resultat bokförs i bokslutet Dr/Kr 8999 mot 2099; dispositionen görs i bokslutsguiden.$faq$, $faq$Vid årsavslut bokförs årets resultat Dr 8999 / Kr 2099 (vinst) eller omvänt (förlust). I AB omförs 2099 påföljande år till 2098/2091 enligt stämmans beslut, och utdelning bokförs mot 2898. I enskild firma omförs resultatet till eget kapital (2010/2019). Bokslutsguiden skapar dessa poster åt dig.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-029', 'Bokföring, verifikationer & BAS-konton', 'kvittning_förbjuden', $faq$["Kan jag kvitta intäkter mot kostnader i samma verifikat?","Nettobokföring tillåten?","Bruttoredovisning?"]$faq$::jsonb, $faq$Bokför brutto — intäkter och kostnader får inte kvittas mot varandra (ÅRL:s kvittningsförbud).$faq$, $faq$Huvudregeln är bruttoredovisning: en försäljning och en relaterad kostnad bokförs var för sig, inte som netto. Exempel: plattformsförsäljning med avgift bokförs som full intäkt (30xx) och avgiften som kostnad (6xxx), inte bara nettoutbetalningen. Detta styr också hur utbetalningar från Stripe/Klarna ska delas upp.$faq$, $faq$["ÅRL 2 kap 4 §"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-030', 'Bokföring, verifikationer & BAS-konton', 'oresavrundning', $faq$["Hur hanteras öresavrundning?","Verifikationen diffar med några ören?","Konto 3740?"]$faq$::jsonb, $faq$Öresdifferenser bokförs automatiskt på 3740/3741 Öresutjämning — aldrig genom att ändra andra rader.$faq$, $faq$Små avrundningsdifferenser (under 1 kr) hanteras med en explicit öresutjämningsrad på 3740 (löpande) eller 3741 (vid import). Nordklart lägger raden automatiskt t.ex. när banken drog ett öresavrundat belopp mot en faktura. Befintliga rader ändras aldrig — differensraden gör obalansen synlig och spårbar.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], '{}'::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-031', 'Bokföring, verifikationer & BAS-konton', 'leverantorsskuld_konto', $faq$["Vilket konto för leverantörsskulder?","2440 — när används det?","Skillnad leverantörsskuld och direktbokning?"]$faq$::jsonb, $faq$Leverantörsfakturor bokförs mot 2440 vid registrering och clearas vid betalning (fakturametoden).$faq$, $faq$Med fakturametoden bokförs leverantörsfakturan vid ankomst: Dr kostnadskonto + Dr 2641 (moms) / Kr 2440 Leverantörsskulder. Betalningen bokför Dr 2440 / Kr 19xx. Leverantörsreskontran visar öppna poster på 2440. Med kontantmetoden bokförs i stället allt vid betalningen.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-032', 'Bokföring, verifikationer & BAS-konton', 'kundfordran_konto', $faq$["Vilket konto för kundfordringar?","1510 — hur fungerar det?","Kundreskontra och bokföring?"]$faq$::jsonb, $faq$Kundfakturor bokförs mot 1510 Kundfordringar vid fakturering och clearas vid betalning.$faq$, $faq$Med fakturametoden bokförs kundfakturan när den skickas: Dr 1510 / Kr 30xx + Kr 26xx (moms). När betalningen kommer bokförs Dr 19xx / Kr 1510. Kundreskontran (öppna fakturor) ska alltid stämma mot saldot på 1510 — bokslutsguiden kontrollerar just detta.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices', '/reports']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-033', 'Bokföring, verifikationer & BAS-konton', 'periodisering', $faq$["Hur periodiserar jag en kostnad?","Förutbetald försäkring över 12 månader?","Periodiseringar i systemet?"]$faq$::jsonb, $faq$Skapa en periodisering på verifikationen — kostnaden fördelas då automatiskt månad för månad via 17xx/29xx.$faq$, $faq$Vid bokföring av t.ex. en årsförsäkring kan du välja periodisering: beloppet bokförs mot balanskontot (1730 förutbetald kostnad) och löses upp månadsvis till kostnadskontot via automatiska poster (källtyp accrual). Upplösningen körs av ett nattligt jobb och respekterar periodlås. Under Bokföring → Periodiseringar ser du plan och status, och kan lösa upp i förtid.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-034', 'Bokföring, verifikationer & BAS-konton', 'k2_k3', $faq$["Vad är skillnaden mellan K2 och K3?","Vilket regelverk ska jag välja?","Byta från K2 till K3?"]$faq$::jsonb, $faq$K2 är förenklat (schabloner), K3 är huvudregelverket (komponentavskrivning, egenupparbetade tillgångar). De flesta små AB väljer K2.$faq$, $faq$K2 passar mindre AB: färre val, schablonlösningar, inga aktiverade egenutvecklingskostnader. K3 krävs för större företag och tillåter komponentavskrivning och aktivering av utvecklingsutgifter. Regelverket anges på företaget och påverkar bl.a. avskrivningskontroller och årsredovisningens uppställning. Byte K2↔K3 har begränsningar.$faq$, $faq$["BFNAR 2016:10 (K2)","BFNAR 2012:1 (K3)"]$faq$::jsonb, '{}'::text[], array['/settings/company']::text[], 'medium', $faq$Val eller byte av K-regelverk påverkar redovisningen långsiktigt — stäm av med revisor/redovisningskonsult.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-035', 'Bokföring, verifikationer & BAS-konton', 'lan_bokforing', $faq$["Hur bokför jag ett banklån?","Företagslån — vilka konton?","Amortering och ränta?"]$faq$::jsonb, $faq$Lånet in: Dr 1930 / Kr 2350. Amortering: Dr 2350 / Kr 1930. Ränta: Dr 8410 / Kr 1930.$faq$, $faq$När lånet betalas ut bokförs Dr 19xx / Kr 2350 Banklån (eller 2390 övriga skulder). Varje betalning delas i amortering (Dr 2350) och ränta (Dr 8410 Räntekostnader) — bankens avi visar fördelningen. Kortfristig del av lånet kan omklassificeras till 2417 i bokslutet.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-036', 'Bokföring, verifikationer & BAS-konton', 'aktiekapital', $faq$["Hur bokför jag aktiekapitalet?","Nystartat AB — insättning av 25 000 kr?","Konto 2081?"]$faq$::jsonb, $faq$Aktiekapitalets insättning bokförs Dr 1930 / Kr 2081 Aktiekapital.$faq$, $faq$När aktiekapitalet (minst 25 000 kr) sätts in på företagskontot bokförs Dr 1930 / Kr 2081. Detta är ofta bolagets första verifikation. Observera att en insättning på räkenskapsårets första dag med texten "aktiekapital" aldrig klassas som ingående balans av importlogiken — den är en riktig bankhändelse.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-037', 'Bokföring, verifikationer & BAS-konton', 'utdelning', $faq$["Hur bokför jag utdelning i AB?","Aktieutdelning konton?","Utdelning beslutad på stämman?"]$faq$::jsonb, $faq$Beslutad utdelning: Dr 2098 / Kr 2898; utbetalningen: Dr 2898 / Kr 1930. Skatteregler (3:12) hanteras i K10.$faq$, $faq$När stämman beslutat utdelning omförs beloppet Dr 2098 (balanserad vinst) / Kr 2898 Outtagen utdelning. Vid utbetalning bokförs Dr 2898 / Kr 1930. Hur mycket som kan tas till 20 % beskattning styrs av 3:12-reglerna och ditt gränsbelopp — det beräknas i din K10-bilaga, inte i bokföringen.$faq$, $faq$["IL 57 kap"]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'high', $faq$Utdelningsutrymme och 3:12 är skatterådgivning — stäm av gränsbeloppet med din rådgivare innan beslut.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-038', 'Bokföring, verifikationer & BAS-konton', 'pagar_arbeten', $faq$["Hur bokför jag pågående arbeten?","Upparbetad ej fakturerad intäkt?","Konto 1620?"]$faq$::jsonb, $faq$Upparbetade men ofakturerade intäkter periodiseras i bokslut mot 1620; successiv vinstavräkning kräver K3-bedömning.$faq$, $faq$För tjänsteuppdrag som är utförda men inte fakturerade vid periodens slut bokförs upplupen intäkt Dr 1620 / Kr 30xx (eller 1790/2990 beroende på metod). Fastprisuppdrag kan kräva värdering enligt K2:s färdigställandemetod eller K3:s successiva vinstavräkning. Vänd posten när fakturan skickas.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'medium', $faq$Värdering av pågående arbeten på fastprisuppdrag är bedömningsfrågor — involvera din redovisningskonsult.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-039', 'Bokföring, verifikationer & BAS-konton', 'justera_ib', $faq$["Ingående balanserna är fel — hur justerar jag?","Rätta öppningsbalans?","IB stämmer inte mot förra året?"]$faq$::jsonb, $faq$Justera via en rättelseverifikation mot 2099/relevant konto, eller gör om SIE-importen med Ersätt.$faq$, $faq$Kommer felet från en import kan du köra om SIE-importen med ersätt-läget (gamla importens poster tas bort och nya skapas — endast i det berörda företaget). Mindre differenser rättas med en verifikation daterad på årets första dag mot rätt konto. Obalanserade IB bokas automatiskt med justeringsrad mot 2099 vid import, med varning.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import', '/bookkeeping']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-040', 'Bokföring, verifikationer & BAS-konton', 'kontrollbalansrakning', $faq$["Vad är kontrollbalansräkning?","Halva aktiekapitalet förbrukat — vad gör jag?","KBR-varning?"]$faq$::jsonb, $faq$Om eget kapital understiger halva aktiekapitalet måste styrelsen genast upprätta kontrollbalansräkning — annars riskeras personligt ansvar.$faq$, $faq$När det finns skäl att anta att bolagets eget kapital understiger hälften av det registrerade aktiekapitalet ska styrelsen genast upprätta en kontrollbalansräkning och låta revisor granska den (om revisor finns), samt kalla till kontrollstämma. Nordklarts balansrapport visar eget kapital löpande. Detta är en aktiebolagsrättslig skyldighet med personligt betalningsansvar som påföljd.$faq$, $faq$["ABL 25 kap 13–20 §§"]$faq$::jsonb, '{}'::text[], array['/reports']::text[], 'high', $faq$Misstänkt kapitalbrist kräver omedelbar kontakt med redovisningskonsult/jurist — agera snabbt, ansvaret är personligt.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-041', 'Bokföring, verifikationer & BAS-konton', 'verifikationslista', $faq$["Kan jag skriva ut en verifikationslista?","Exportera alla verifikationer?","Journal för revisorn?"]$faq$::jsonb, $faq$Ja — Rapporter → Verifikationslista, eller exportera hela året som SIE-fil till revisorn.$faq$, $faq$Verifikationslistan (grundbok) finns under Rapporter, filtrerbar per period och serie, exporterbar som PDF. Revisorer föredrar ofta SIE4-export (Rapporter → SIE-export) som innehåller kontoplan, balanser och alla verifikationer med rader. Dokumentunderlag hämtas via dokumentarkivet.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-042', 'Bokföring, verifikationer & BAS-konton', 'kryptovaluta', $faq$["Hur bokför jag kryptovaluta?","Företaget köpte Bitcoin?","Krypto i redovisningen?"]$faq$::jsonb, $faq$Krypto bokförs som omsättningstillgång/finansiell placering till anskaffningsvärde — värdering och skatt är komplexa.$faq$, $faq$Kryptotillgångar bokförs vanligen som kortfristig placering (18xx) till anskaffningsvärde; orealiserade vinster får inte tas upp i K2. Vid avyttring beräknas resultat per transaktion (genomsnittsmetoden) och kapitalvinsten beskattas. Betalning i krypto räknas som byte (två händelser).$faq$, $faq$[]$faq$::jsonb, '{}'::text[], '{}'::text[], 'high', $faq$Krypto i näringsverksamhet har osäker praxis kring värdering och moms — anlita expert innan större positioner.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-043', 'Bokföring, verifikationer & BAS-konton', 'leasing', $faq$["Hur bokför jag billeasing?","Leasingavgift konto?","Halv moms på personbilsleasing?"]$faq$::jsonb, $faq$Operationell leasing kostnadsförs löpande (5615 för personbil) — halva momsen får lyftas på personbilsleasing.$faq$, $faq$I K2 kostnadsförs alla leasingavtal som hyra. Personbilsleasing bokförs på 5615 och endast 50 % av momsen får dras (Dr 2641 halva, resten kostnadsförs) förutsatt att bilen körs minst 100 mil/år i verksamheten. Första förhöjd avgift periodiseras över leasingperioden. Lastbilar/transportbilar ger fullt momslyft.$faq$, $faq$["ML 13 kap 20 §"]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-044', 'Bokföring, verifikationer & BAS-konton', 'gava_valgorenhet', $faq$["Är gåvor till välgörenhet avdragsgilla?","Bokföra donation från företaget?","Sponsring vs gåva?"]$faq$::jsonb, $faq$Rena gåvor är inte avdragsgilla (6992); sponsring med motprestation kan vara det (5980).$faq$, $faq$Gåvor till välgörenhet bokförs 6992 (ej avdragsgill kostnad) och återläggs i deklarationen. Sponsring är avdragsgill bara i den mån företaget får en motprestation (exponering, biljetter) av motsvarande värde — bokförs då 5980. Dokumentera motprestationen.$faq$, $faq$["IL 9 kap 2 §","IL 16 kap 1 §"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-045', 'Bokföring, verifikationer & BAS-konton', 'preliminarskatt', $faq$["Hur bokförs F-skatten/preliminärskatten?","Debiterad preliminärskatt konto?","F-skatt varje månad?"]$faq$::jsonb, $faq$AB: Dr 2518 (via 1630) — inte kostnad. Enskild firma: preliminärskatten är privat och bokförs som eget uttag.$faq$, $faq$I aktiebolag är preliminärskatten en skuld: betalningen till skattekontot bokförs Dr 1630 / Kr 1930, och Skatteverkets dragning Dr 2518 Betald F-skatt / Kr 1630. I enskild firma är inkomstskatten privat — betalas den från företagskontot bokförs den som eget uttag (2012/2013).$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/skattekonto']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-046', 'Bokföring, verifikationer & BAS-konton', 'arsredovisning_konton', $faq$["Mappas kontona till årsredovisningen automatiskt?","SRU-koder på konton?","Hur vet systemet vad som är omsättning?"]$faq$::jsonb, $faq$Ja — BAS-kontona bär SRU-koder som mappar till årsredovisningens och INK2:s fält automatiskt.$faq$, $faq$Varje BAS-konto i Nordklart har en SRU-kod (Skatteverkets fältkoder) som styr var saldot hamnar i räkenskapsschemat (INK2R) och årsredovisningens uppställning. Egna konton du aktiverar får koder från BAS-standarden; kontrollera SRU-koden om du använder konton på okonventionellt sätt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/year-end', '/settings/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-047', 'Bokföring, verifikationer & BAS-konton', 'dricks', $faq$["Hur bokförs dricks?","Kvittot har högre belopp än notan?","Dricks på representationskvitto?"]$faq$::jsonb, $faq$Lämnad dricks vid representation ingår i representationskostnaden; på vanliga kvitton bokförs den utan momslyft.$faq$, $faq$Dricks är momsfri (ingår inte i beskattningsunderlaget). När kortdragningen överstiger kvittots belopp bokförs mellanskillnaden som del av kostnaden utan moms. Nordklarts kvittoflöde stödjer avvikande momsbelopp så att verifikatet matchar underlaget exakt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-048', 'Bokföring, verifikationer & BAS-konton', 'valutakursdifferens', $faq$["Hur bokförs valutakursvinster och förluster?","Kursdiff på leverantörsbetalning?","Konto 3960/7960?"]$faq$::jsonb, $faq$Realiserade kursdifferenser i rörelsen bokförs på 3960 (vinst) / 7960 (förlust) — Nordklart räknar dem automatiskt.$faq$, $faq$När en valutafaktura betalas till annan kurs än bokföringskursen uppstår en differens: vinst Kr 3960, förlust Dr 7960. Nordklart beräknar differensen automatiskt vid matchning (fakturans kurs vs Riksbankskursen på betalningsdagen) och lägger raden i betalningsverifikatet. Orealiserade differenser på utestående poster hanteras i bokslutet via valutaomvärderingen.$faq$, $faq$["ML 8 kap 21–23 §§"]$faq$::jsonb, '{}'::text[], array['/transactions', '/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-049', 'Bokföring, verifikationer & BAS-konton', 'langtidsbevakning_konto6351', $faq$["Hur bokför jag en kundförlust?","Kunden gick i konkurs — fakturan betalas aldrig?","Konstaterad kundförlust och momsen?"]$faq$::jsonb, $faq$Konstaterad kundförlust: Dr 6351 + återför utgående moms / Kr 1510 — görs via fakturans "Skriv av"-åtgärd.$faq$, $faq$När förlusten är konstaterad (konkurs, misslyckad indrivning) skrivs fakturan av: Dr 6351 Konstaterade kundförluster (nettobeloppet), Dr 26xx återförd utgående moms, Kr 1510 restbeloppet. Momsen får återtas endast vid konstaterad förlust. I Nordklart använder du fakturans åtgärd "Skriv av" med motivering — verifikatet byggs automatiskt och fakturan får status avskriven.$faq$, $faq$["ML 7 kap 44 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-050', 'Bokföring, verifikationer & BAS-konton', 'befarad_kundforlust', $faq$["Vad är skillnaden mellan befarad och konstaterad kundförlust?","Osäker fordran i bokslutet?","Konto 6352?"]$faq$::jsonb, $faq$Befarad förlust reserveras i bokslut (6352/1519) utan momsåtervinning; konstaterad bokförs slutligt med momsåtertag.$faq$, $faq$Befarad kundförlust (kunden har betalningssvårigheter men förlusten är inte definitiv) reserveras Dr 6352 / Kr 1519 Nedskrivning kundfordringar — momsen röds inte. Blir förlusten konstaterad vänds reserven och bokförs som konstaterad förlust med momsåtervinning. Reservera i bokslutet för fordringar äldre än ~6 månader med indrivningsförsök.$faq$, $faq$["ML 7 kap 44 §"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-051', 'Bokföring, verifikationer & BAS-konton', 'felsokning_verifikat_saknas', $faq$["Ett verifikationsnummer saknas i serien — varför?","Lucka i verifikationsnummer?","Verifikation A15 finns inte?"]$faq$::jsonb, $faq$Nummerluckor uppstår vid avbrutna bokföringar och måste förklaras — se Bokföring → Nummerluckor.$faq$, $faq$En lucka kan uppstå när en bokföring avbryts efter att numret reserverats (t.ex. dubblettskydd som makulerar en post). BFNAR 2013:2 kräver dokumenterad förklaring för varje lucka. Nordklart detekterar luckor automatiskt och samlar dem under Nummerluckor där du anger förklaringen; vissa systemhändelser förklaras automatiskt.$faq$, $faq$["BFNAR 2013:2"]$faq$::jsonb, '{}'::text[], array['/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-052', 'Bokföring, verifikationer & BAS-konton', 'attest', $faq$["Finns attestflöde för verifikationer?","Kan någon annan godkänna min bokföring?","Fyra ögon-princip?"]$faq$::jsonb, $faq$Väntande åtgärder fungerar som attest: en person kan förbereda och en annan godkänna, allt loggat.$faq$, $faq$Nordklarts väntande åtgärder ger ett naturligt attestflöde: assistenten, automatiken eller en medarbetare förbereder posten, och en behörig användare godkänner. Varje godkännande loggas med person, tid och metod på verifikationen (committed_actor). API-nycklar kan scopas så att samma nyckel inte både kan skapa och godkänna.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/pending']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-053', 'Bokföring, verifikationer & BAS-konton', 'bokfora_bidrag', $faq$["Hur bokför jag ett offentligt stöd/bidrag?","Almi-bidrag eller EU-stöd konto?","Är bidrag momspliktiga?"]$faq$::jsonb, $faq$Näringsbidrag bokförs som intäkt (3980er) utan moms; villkorade bidrag kan kräva periodisering.$faq$, $faq$Offentliga stöd (Tillväxtverket, Almi, EU) bokförs på 3980 Erhållna offentliga bidrag, utan utgående moms. Bidrag knutna till specifika kostnader intäktsförs i takt med kostnaderna (matchning); investeringsbidrag minskar tillgångens avskrivningsunderlag alternativt periodiseras. Villkor om återbetalning gör posten till skuld tills villkoren uppfyllts.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-054', 'Bokföring, verifikationer & BAS-konton', 'flytta_verifikationsdatum', $faq$["Kan jag ändra datum på en bokförd verifikation?","Fel bokföringsdatum — flytta posten?","Omdatera verifikat?"]$faq$::jsonb, $faq$Bokförda verifikationers datum kan inte ändras — använd "Omdatera" som gör storno + ny post på rätt dag.$faq$, $faq$Datumet är låst efter bokföring. Nordklarts omdateringsfunktion skapar en storno av originalet och en ny identisk verifikation med rätt datum, båda länkade. Detta bevarar den obrutna kedjan och fungerar bara om både gamla och nya datumets perioder är öppna.$faq$, $faq$["BFL 5 kap 5 §"]$faq$::jsonb, '{}'::text[], array['/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokforing-055', 'Bokföring, verifikationer & BAS-konton', 'api_verifikationer', $faq$["Kan jag skapa verifikationer via API?","Bokföra programmatiskt?","API för journal entries?"]$faq$::jsonb, $faq$Ja — via API:ets voucher-endpoints med samma balans-, period- och behörighetskontroller som UI:t.$faq$, $faq$API:et (scope bookkeeping:write) exponerar verifikationsskapande med samma motor som UI:t: balanskrav, atomisk nummertilldelning, periodlåskontroll ochaudit-loggning. Skrivande anrop kräver Idempotency-Key så omförsök aldrig dubbelbokar. Bokförda poster kan inte ändras via API — endast storno.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/api']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-001', 'Bokslut, årsredovisning, INK2, NE & SRU', 'vad_ar_bokslut', $faq$["Vad är ett bokslut?","Vad innebär det att göra bokslut?","Varför måste jag göra bokslut?"]$faq$::jsonb, $faq$Bokslutet avslutar räkenskapsåret: alla affärshändelser bokförs, periodiseringar och avskrivningar görs, skatten beräknas och årets resultat fastställs.$faq$, $faq$Alla bokföringsskyldiga ska avsluta räkenskapsåret med ett bokslut. Det innebär att den löpande bokföringen kompletteras med bokslutstransaktioner — avskrivningar, periodiseringar, lagervärdering, semesterlöneskuld, skatteberäkning — så att resultat- och balansräkning ger en rättvisande bild per balansdagen. Aktiebolag upprättar alltid årsredovisning; enskilda firmor gör förenklat årsbokslut (omsättning under 3 mkr) eller vanligt årsbokslut. Nordklarts bokslutsflöde under Bokslut guidar dig genom stegen med automatiska kontroller.$faq$, $faq$["BFL 6 kap 1-3 §§"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-002', 'Bokslut, årsredovisning, INK2, NE & SRU', 'arsbokslut_vs_arsredovisning', $faq$["Vad är skillnaden mellan årsbokslut och årsredovisning?","Behöver enskild firma göra årsredovisning?","Vem måste upprätta årsredovisning?"]$faq$::jsonb, $faq$Årsredovisning är en offentlig handling (krävs av AB) som lämnas till Bolagsverket. Årsbokslut är internt och räcker för de flesta enskilda firmor.$faq$, $faq$Aktiebolag ska alltid upprätta årsredovisning enligt årsredovisningslagen — resultaträkning, balansräkning, noter och förvaltningsberättelse — som skickas till Bolagsverket och blir offentlig. Enskilda näringsidkare upprättar i stället årsbokslut: förenklat årsbokslut om omsättningen är högst 3 mkr, annars vanligt årsbokslut. Årsbokslutet lämnas inte in någonstans utan ligger till grund för NE-bilagan i deklarationen. Handelsbolag med juridisk person som delägare och större företag har egna krav.$faq$, $faq$["ÅRL 1 kap","BFL 6 kap"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-003', 'Bokslut, årsredovisning, INK2, NE & SRU', 'k2_vs_k3', $faq$["Vad är skillnaden mellan K2 och K3?","Vilket regelverk ska mitt bolag använda?","Kan jag byta från K3 till K2?"]$faq$::jsonb, $faq$K2 är förenklat med schabloner och färre val — för mindre bolag. K3 är huvudregelverket med komponentavskrivning och möjlighet att aktivera utvecklingskostnader.$faq$, $faq$Mindre aktiebolag (under gränsvärdena: 50 anställda, 40 mkr balansomslutning, 80 mkr omsättning — två av tre, två år i rad) får välja K2, som har schablonlösningar: 5-års avskrivning på vissa tillgångar, inga egenupparbetade immateriella tillgångar, begränsade periodiseringskrav under 5 000 kr. K3 är huvudregelverket med mer principbaserad redovisning: komponentavskrivning på fastigheter, möjlighet att aktivera utveckling, uppskjuten skatt. Byte från K2 till K3 är alltid tillåtet; byte tillbaka kräver särskilda skäl. Nordklart stödjer båda — valet anges i företagsinställningarna och påverkar bokslutsflödet.$faq$, $faq$["BFNAR 2016:10 (K2)","BFNAR 2012:1 (K3)"]$faq$::jsonb, '{}'::text[], array['/year-end', '/settings/company']::text[], 'medium', $faq$Regelverksval påverkar redovisningen i flera år — stäm av med revisor eller redovisningskonsult vid tveksamhet.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-004', 'Bokslut, årsredovisning, INK2, NE & SRU', 'deadline_arsredovisning', $faq$["När ska årsredovisningen lämnas in?","Hur lång tid har jag på mig efter räkenskapsårets slut?","Deadline för årsredovisning till Bolagsverket?"]$faq$::jsonb, $faq$Årsredovisningen ska vara hos Bolagsverket senast 7 månader efter räkenskapsårets utgång — för kalenderår senast 31 juli.$faq$, $faq$Kedjan är: årsredovisningen upprättas och skrivs under av styrelsen, årsstämman fastställer den senast 6 månader efter räkenskapsårets slut, och den kompletta årsredovisningen med fastställelseintyg ska vara Bolagsverket tillhanda senast 7 månader efter räkenskapsårets utgång. För kalenderårsbolag: stämma senast 30 juni, inlämning senast 31 juli. Förseningsavgift utgår direkt vid försening (högre för publika bolag) och trappas upp; efter 11 månader riskerar bolaget tvångslikvidation och styrelsen personligt ansvar. Nordklart visar deadlinen i bevakningen.$faq$, $faq$["ÅRL 8 kap 3 §","ABL 25 kap 11 §"]$faq$::jsonb, '{}'::text[], array['/year-end', '/deadlines']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-005', 'Bokslut, årsredovisning, INK2, NE & SRU', 'bokslutsflode_steg', $faq$["Hur fungerar bokslutsflödet i Nordklart?","Vilka steg ingår i bokslutet?","Var börjar jag med årsbokslutet?"]$faq$::jsonb, $faq$Under Bokslut går du igenom stegen: avstämningar, bokslutstransaktioner, skatteberäkning, resultatdisposition, låsning och rapporter — med automatiska kontroller per steg.$faq$, $faq$Nordklarts bokslutsflöde är en guidad process: 1) Förberedelser — alla perioder bokförda, bank/kund-/leverantörsreskontra avstämda, väntande åtgärder lösta. 2) Bokslutstransaktioner — avskrivningar, periodiseringar, semesterlöneskuld, lager, eventuella periodiseringsfonder och överavskrivningar. 3) Skatteberäkning — skattemässiga justeringar och årets skatt. 4) Årets resultat bokförs (8999/2099). 5) Räkenskapsåret låses. 6) Rapporter — årsredovisning/årsbokslut, INK2/NE-underlag, SIE-export. Varje steg har blockerande kontroller som måste vara gröna innan du kan slutföra, så inget avslutas med kända fel.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-006', 'Bokslut, årsredovisning, INK2, NE & SRU', 'blockerare_bokslut', $faq$["Varför kan jag inte slutföra bokslutet?","Vad är bokslutsblockerare?","Vilka kontroller måste vara klara innan bokslut?"]$faq$::jsonb, $faq$Bokslutet blockeras tills allt är klart: bankavstämning, reskontraavstämningar, momsperioder, olösta väntande åtgärder, obokförda transaktioner och pågående SIE-importer.$faq$, $faq$Nordklart tillåter inte att bokslutet markeras klart med kända brister. Blockerare inkluderar: obokförda eller omatchade banktransaktioner i perioden, olösta väntande åtgärder, oavstämd bank (1930 mot kontoutdrag), kundreskontra som inte stämmer mot 1510, leverantörsreskontra som inte stämmer mot 2440, momsperioder som inte är deklarerade/låsta, ej bokförda avskrivningar och periodiseringar, ofullständiga SIE-importer samt obalanserade verifikationer. Varje blockerare visas med länk till det som behöver åtgärdas. Det här är avsiktligt — ett bokslut på felaktigt underlag ger fel skatt och fel årsredovisning.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/year-end', '/pending', '/transactions']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-007', 'Bokslut, årsredovisning, INK2, NE & SRU', 'bankavstamning_bokslut', $faq$["Hur stämmer jag av banken inför bokslutet?","Bankavstämning — vad krävs?","Saldot på 1930 stämmer inte med banken?"]$faq$::jsonb, $faq$Bokfört saldo på 1930 ska stämma exakt mot bankens kontoutdrag per balansdagen. Avvikelser beror oftast på obokförda transaktioner eller dubbletter.$faq$, $faq$Bankavstämningen jämför huvudbokens saldo på bankkontona (1930 m.fl.) med bankens faktiska saldo per balansdagen. Nordklarts avstämningsvy visar differensen och listar transaktioner som inte matchats mot bokföringen. Vanliga orsaker till differens: banktransaktioner som aldrig bokfördes, manuellt bokförda betalningar som inte länkats till banktransaktionen (dubbelbokning), eller transaktioner bokförda på fel datum över årsskiftet. Åtgärda tills differensen är noll — avstämd bank är en blockerande kontroll i bokslutet.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-008', 'Bokslut, årsredovisning, INK2, NE & SRU', 'kundreskontra_avstamning', $faq$["Hur stämmer jag av kundreskontran?","Kundfordringar stämmer inte mot 1510?","Avstämning av kundfordringar vid bokslut?"]$faq$::jsonb, $faq$Summan av öppna kundfakturor i reskontran ska vara lika med saldot på 1510. Nordklart visar differensen och vilka poster som avviker.$faq$, $faq$Vid bokslut ska kundreskontran (lista över obetalda kundfakturor) stämma exakt mot huvudbokens 1510 kundfordringar. Nordklarts avstämningskontroll summerar öppna fakturor och jämför mot kontosaldot. Avvikelser uppstår när något bokförts direkt på 1510 utanför fakturaflödet, när betalningar bokförts utan att kopplas till fakturan, eller vid felaktiga manuella verifikationer. Granska differensposterna, rätta via rätt flöde (matcha betalning, kreditera, skriv av osäker fordran) och kör om kontrollen. Avstämd kundreskontra krävs för att slutföra bokslutet.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices', '/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-009', 'Bokslut, årsredovisning, INK2, NE & SRU', 'leverantorsreskontra_avstamning', $faq$["Hur stäms leverantörsreskontran av?","2440 stämmer inte med leverantörsfakturorna?","Leverantörsskulder vid bokslut?"]$faq$::jsonb, $faq$Obetalda leverantörsfakturor i reskontran ska summera till saldot på 2440. Kontrollera även att fakturor daterade före balansdagen är registrerade.$faq$, $faq$Leverantörsreskontran ska stämma mot 2440 leverantörsskulder per balansdagen. Utöver den tekniska avstämningen: se till att alla leverantörsfakturor med fakturadatum före årsskiftet är registrerade, även de som anländer i januari (brytdagshantering, normalt vecka 2–3 i januari är rimlig brytdag). Fakturor som avser gamla året men bokförs efter brytdagen periodiseras som upplupen kostnad (2990). Nordklart flaggar tolkningsförslag med fakturadatum i föregående räkenskapsår så att de inte missas.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-010', 'Bokslut, årsredovisning, INK2, NE & SRU', 'momsperioder_klara', $faq$["Måste alla momsperioder vara klara innan bokslut?","Momsdeklarationer och bokslutet?","Momsavstämning vid årsskifte?"]$faq$::jsonb, $faq$Ja, alla momsperioder i räkenskapsåret ska vara deklarerade och bokförda (omförda till 2650/1650) innan bokslutet slutförs.$faq$, $faq$Bokslutskontrollen kräver att varje momsperiod under året är hanterad: momsrapporten skapad, deklarationen inlämnad och momsomföringen bokförd så att 2610–2649 nollställs mot 2650 momsredovisningskonto (eller 1650 momsfordran). Sista periodens moms ska stå som skuld/fordran på balansdagen. Kvarstående saldon på momskontona utöver sista perioden tyder på rättelser som behöver utredas. Momsperiodernas status visas i bokslutsflödet, och låsta momsperioder skyddas mot ny bokföring bakåt.$faq$, $faq$["SFL 26 kap"]$faq$::jsonb, '{}'::text[], array['/reports', '/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-011', 'Bokslut, årsredovisning, INK2, NE & SRU', 'pending_blockerar_bokslut', $faq$["Blockerar väntande åtgärder bokslutet?","Jag har olösta förslag — kan jag ändå slutföra året?","Måste alla pending operations vara klara?"]$faq$::jsonb, $faq$Ja. Olösta väntande åtgärder som rör räkenskapsåret måste godkännas eller avvisas innan bokslutet kan slutföras.$faq$, $faq$Väntande åtgärder representerar ofattade beslut — obokförda leverantörsfakturor, obekräftade matchningar, oklara momsval. Att slutföra bokslutet med sådana öppna poster skulle innebära att resultat och ställning medvetet är ofullständiga. Därför är olösta väntande åtgärder med datum i räkenskapsåret en blockerande kontroll. Gå igenom listan under Väntande åtgärder: godkänn det som ska bokföras, avvisa det som inte hör hemma i bokföringen (avvisningar loggas med motivering). Först när listan är tom för perioden släpper blockeringen.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/pending', '/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-012', 'Bokslut, årsredovisning, INK2, NE & SRU', 'sie_import_status_bokslut', $faq$["Kan jag göra bokslut med en pågående SIE-import?","SIE-importen blockerar bokslutet — varför?","Ofullständig import och årsavslut?"]$faq$::jsonb, $faq$Nej, alla SIE-importer som rör räkenskapsåret måste vara slutförda eller ångrade — en halvfärdig import betyder ofullständig bokföring.$faq$, $faq$En SIE-import som är påbörjad men inte slutförd (eller som misslyckats mitt i) lämnar bokföringen i ett odefinierat läge — vissa verifikationer kan vara skapade, andra inte. Bokslutskontrollen kräver därför att alla importer med verifikationer i räkenskapsåret har status slutförd, alternativt är ångrade i sin helhet. Gå till Import → SIE och slutför eller ångra hängande importer. Kontrollera efteråt att ingående balanser och verifikationsserier ser korrekta ut innan du fortsätter med bokslutet.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import', '/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-013', 'Bokslut, årsredovisning, INK2, NE & SRU', 'obokforda_transaktioner_blockerar', $faq$["Obokförda banktransaktioner stoppar bokslutet?","Vad gör jag med omatchade transaktioner vid årsskiftet?","Transaktioner utan verifikation i bokslutet?"]$faq$::jsonb, $faq$Alla banktransaktioner i räkenskapsåret måste vara bokförda, matchade eller medvetet ignorerade innan bokslutet slutförs.$faq$, $faq$Varje banktransaktion i perioden ska ha en hantering: bokförd med verifikation, matchad mot faktura/lön/skatt, eller markerad som ignorerad med motivering (t.ex. ren intern överföring som bokförs på annat sätt). Transaktioner utan hantering betyder att bokföringen inte är komplett — de listas som blockerare i bokslutsflödet med direktlänk till transaktionsvyn. Använd automationsförslagen där de finns och bokför resten manuellt. Först när alla transaktioner i året är hanterade blir kontrollen grön.$faq$, $faq$["BFL 5 kap 1-2 §§"]$faq$::jsonb, '{}'::text[], array['/transactions', '/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-014', 'Bokslut, årsredovisning, INK2, NE & SRU', 'avskrivningar_bokslut', $faq$["Måste avskrivningarna vara bokförda före bokslut?","Hur hanteras avskrivningar i bokslutet?","Årets avskrivningar saknas — vad gör jag?"]$faq$::jsonb, $faq$Ja, planenliga avskrivningar för hela året ska vara bokförda. Nordklart beräknar dem från anläggningsregistret och visar saknade månader som blockerare.$faq$, $faq$Alla anläggningstillgångar i registret ska vara avskrivna enligt plan fram till balansdagen — t.ex. inventarier på 5 år ger 20 % per år, fördelat månadsvis (debet 7832, kredit 1229). Nordklarts anläggningsregister beräknar avskrivningarna automatiskt och bokför dem löpande eller som samlad bokslutspost; saknade avskrivningsmånader visas som blockerare i bokslutet. Kontrollera också att nyinköp under året aktiverats (inte kostnadsförts) om de överstiger halvt prisbasbelopp, och att sålda/utrangerade tillgångar bokats bort korrekt.$faq$, $faq$["ÅRL 4 kap 4 §","IL 18 kap"]$faq$::jsonb, '{}'::text[], array['/assets', '/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-015', 'Bokslut, årsredovisning, INK2, NE & SRU', 'periodiseringar_bokslut', $faq$["Vilka periodiseringar görs i bokslutet?","Upplupna kostnader och förutbetalda intäkter?","Vad ska periodiseras vid årsskiftet?"]$faq$::jsonb, $faq$Kostnader och intäkter ska hamna på rätt år: förutbetalda kostnader (1790), upplupna kostnader (2990), upplupna intäkter (1790/1620) och förutbetalda intäkter (2990/2970).$faq$, $faq$Periodiseringar flyttar poster till rätt räkenskapsår: hyra betald i förskott blir förutbetald kostnad (1710/1790), elräkning för december som kommer i januari blir upplupen kostnad (2990), utfört men ofakturerat arbete blir upplupen intäkt, och förskottsfakturerat blir förutbetald intäkt (2970). K2 tillåter att poster under 5 000 kr inte periodiseras och att återkommande belopp med liten variation kostnadsförs löpande. Nordklarts periodiseringsmotor upplöser registrerade periodiseringar automatiskt och bokslutskontrollen påminner om vanliga poster.$faq$, $faq$["BFNAR 2016:10 punkt 7.9"]$faq$::jsonb, '{}'::text[], array['/bookkeeping', '/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-016', 'Bokslut, årsredovisning, INK2, NE & SRU', 'periodiseringsfond_avsattning', $faq$["Vad är en periodiseringsfond?","Hur mycket kan jag sätta av till periodiseringsfond?","Bokföra avsättning till periodiseringsfond?"]$faq$::jsonb, $faq$AB kan sätta av 25 % av vinsten (EF 30 %) till periodiseringsfond och skjuta upp skatten. Bokförs 8811 mot 2110-serien, återförs senast år 6.$faq$, $faq$Periodiseringsfond skjuter upp beskattning: aktiebolag får sätta av högst 25 % av skattemässigt resultat före avsättning, enskilda näringsidkare 30 %. Bokföring i AB: debet 8811 avsättning periodiseringsfond, kredit 21X0 (eget konto per år, t.ex. 2110–2116 roterande). Fonden ska återföras senast sjätte året efter avsättningsåret, och AB beskattas årligen på en schablonintäkt beräknad på fondernas ingående värde. Avsättning lönar sig främst när du väntar lägre resultat kommande år eller vill jämna ut resultat. I enskild firma är fonden bara en deklarationspost (NE), ingen bokföring.$faq$, $faq$["IL 30 kap"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'medium', $faq$Avsättningens storlek är skatteplanering — stäm av helheten (utdelningsutrymme, framtida resultat) med rådgivare.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-017', 'Bokslut, årsredovisning, INK2, NE & SRU', 'periodiseringsfond_aterforing', $faq$["När måste periodiseringsfonden återföras?","Hur bokförs återföring av periodiseringsfond?","Vad händer om jag glömmer återföra fonden?"]$faq$::jsonb, $faq$Varje fond återförs senast sjätte året efter avsättningsåret: debet 21X0, kredit 8819. Nordklart bevakar äldsta fondens deadline i bokslutet.$faq$, $faq$En periodiseringsfond får behållas i högst sex år efter avsättningsåret — därefter är återföring obligatorisk och tas upp som skattepliktig intäkt. Bokföring: debet fondens balanskonto (21X0), kredit 8819 återföring periodiseringsfond. Du kan återföra tidigare, helt eller delvis, t.ex. för att kvitta mot ett förlustår. Vid likvidation, ägarförändringar av visst slag eller om bolaget upphör med näringsverksamhet ska fonderna återföras direkt. Nordklarts bokslutsflöde listar fonderna per årgång och flaggar den som måste återföras i år.$faq$, $faq$["IL 30 kap 7-10 §§"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-018', 'Bokslut, årsredovisning, INK2, NE & SRU', 'schablonintakt_periodiseringsfond', $faq$["Vad är schablonintäkten på periodiseringsfonder?","Varför beskattas periodiseringsfonden varje år?","Hur beräknas schablonräntan på fonderna?"]$faq$::jsonb, $faq$AB tar upp en schablonintäkt beräknad som statslåneräntan gånger fondernas ingående värde — en deklarationspost i INK2S, ingen bokföring.$faq$, $faq$Aktiebolag (inte enskilda firmor) beskattas årligen för att de har periodiseringsfonder: schablonintäkten är fondernas sammanlagda ingående balans multiplicerad med statslåneräntan vid utgången av november året före beskattningsåret (med golvvärde). Intäkten bokförs inte utan läggs till som skattemässig justering i INK2S (ruta 4.6 a). Nordklarts skatteberäkning i bokslutet räknar fram schablonintäkten automatiskt utifrån fondsaldona och aktuell ränta, och den följer med till INK2-underlaget.$faq$, $faq$["IL 30 kap 6 a §"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-019', 'Bokslut, årsredovisning, INK2, NE & SRU', 'overavskrivningar', $faq$["Vad är överavskrivningar?","Hur fungerar räkenskapsenlig avskrivning 30-regeln?","Bokföra avskrivning över plan?"]$faq$::jsonb, $faq$Överavskrivningar är skattemässiga avskrivningar utöver plan (30-/20-regeln). Bokförs 8850 mot 2150 som obeskattad reserv.$faq$, $faq$Skattemässigt får inventarier skrivas av snabbare än planenligt: räkenskapsenlig avskrivning tillåter det högsta av 30 % av bokfört restvärde (huvudregeln) eller att kvarvarande värde motsvarar 20 % per år av anskaffningsvärdet (kompletteringsregeln). Skillnaden mellan skattemässig och planenlig avskrivning bokförs som överavskrivning: debet 8850 förändring överavskrivningar, kredit 2150 ackumulerade överavskrivningar (obeskattad reserv). Kravet för räkenskapsenlig avskrivning är att bokföringen stämmer med deklarationen. Nordklart beräknar största tillåtna överavskrivning i bokslutet och visar upplösning när planen kommit ikapp.$faq$, $faq$["IL 18 kap 13-17 §§"]$faq$::jsonb, '{}'::text[], array['/assets', '/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-020', 'Bokslut, årsredovisning, INK2, NE & SRU', 'bolagsskatt_berakning', $faq$["Hur beräknas bolagsskatten?","Vad är skattesatsen för aktiebolag?","Bokföra årets skatt?"]$faq$::jsonb, $faq$Bolagsskatten är 20,6 % av det skattemässiga resultatet (bokfört resultat ± justeringar). Bokförs debet 8910, kredit 2510.$faq$, $faq$Bolagsskatten beräknas på skattemässigt resultat: bokfört resultat före skatt, plus ej avdragsgilla kostnader (representation över gräns, föreningsavgifter, skattekontoränta, böter), minus ej skattepliktiga intäkter, plus schablonintäkt på periodiseringsfonder, justerat för avsättning/återföring av fonder och eventuella underskott från tidigare år. Skattesatsen är 20,6 %. Bokföring: debet 8910 skatt på årets resultat, kredit 2510 skatteskulder (nettas mot betald preliminärskatt). Nordklarts skatteberäkning i bokslutet gör justeringarna och skapar verifikationen — siffrorna följer med till INK2S.$faq$, $faq$["IL 65 kap 10 §"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-021', 'Bokslut, årsredovisning, INK2, NE & SRU', 'ej_avdragsgilla_kostnader', $faq$["Vilka kostnader är inte avdragsgilla?","Vad återläggs i skatteberäkningen?","Ej avdragsgillt — vilka konton?"]$faq$::jsonb, $faq$Vanliga ej avdragsgilla poster: representation över gränsvärden (6072), böter/viten (6992), medlemsavgifter (6982), kostnadsränta skattekonto (8423), gåvor över gränser.$faq$, $faq$Ej avdragsgilla kostnader belastar det bokförda resultatet men återläggs i skatteberäkningen (INK2S ruta 4.3): måltidsrepresentation (avdrag 0 kr vid inkomstbeskattning), böter, viten, skattetillägg och förseningsavgifter, föreningsmedlemsavgifter, kostnadsränta på skattekontot, gåvor utöver reklam-/personalgåvegränser och förmånsbeskattad sjukvårdsförsäkringsdel. Bokför dem på de särskilda ej avdragsgilla kontona (6072, 6982, 6992, 7622, 8423 m.fl.) — då plockar Nordklarts skatteberäkning och INK2S-underlag upp dem automatiskt som justeringar.$faq$, $faq$["IL 9 kap","IL 16 kap 2 §"]$faq$::jsonb, '{}'::text[], array['/year-end', '/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-022', 'Bokslut, årsredovisning, INK2, NE & SRU', 'skattemassiga_justeringar', $faq$["Vad är skattemässiga justeringar?","Skillnad mellan bokfört och skattemässigt resultat?","Vilka justeringar görs i INK2S?"]$faq$::jsonb, $faq$Justeringarna omvandlar bokfört resultat till beskattningsbart: återlägg ej avdragsgillt, dra av ej skattepliktigt, lägg till schablonintäkter och hantera fonder/underskott.$faq$, $faq$Skattemässigt resultat = bokfört resultat före skatt + ej avdragsgilla kostnader − ej skattepliktiga intäkter (t.ex. intäktsränta skattekonto, utdelning på näringsbetingade andelar) + schablonintäkt på periodiseringsfonder ± skillnad mellan bokförda och skattemässiga avskrivningar ± avsättning/återföring periodiseringsfond − outnyttjat underskott från tidigare år. Justeringarna redovisas öppet i INK2S (4.3–4.14). Nordklart bygger justeringslistan automatiskt från konteringen — därför är det viktigt att använda rätt konton för ej avdragsgilla poster under året.$faq$, $faq$["IL 14 kap"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-023', 'Bokslut, årsredovisning, INK2, NE & SRU', 'resultatdisposition', $faq$["Vad är resultatdisposition?","Hur beslutas vad som händer med vinsten?","Balanseras resultatet automatiskt?"]$faq$::jsonb, $faq$Årsstämman beslutar hur fritt eget kapital disponeras: balanseras i ny räkning och/eller delas ut. Bokförs på nya året mot 2091/2098.$faq$, $faq$I årsredovisningens förvaltningsberättelse föreslår styrelsen resultatdisposition: till stämmans förfogande står balanserat resultat plus årets resultat; förslaget anger utdelning och/eller balansering i ny räkning. När stämman beslutat bokförs dispositionen i det nya räkenskapsåret: debet 2098 vinst föregående år, kredit 2091 balanserad vinst (och kredit 2898 beslutad utdelning för utdelningsdelen). Utdelningen får inte inkräkta på bundet eget kapital och ska rymmas inom försiktighetsregeln. Nordklarts bokslutsflöde skapar dispositionsverifikationen utifrån stämmobeslutet.$faq$, $faq$["ABL 18 kap","ÅRL 6 kap 2 §"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-024', 'Bokslut, årsredovisning, INK2, NE & SRU', 'utdelning_bokforing', $faq$["Hur bokförs utdelning?","Aktieutdelning — vilka konton?","När får bolaget betala ut utdelningen?"]$faq$::jsonb, $faq$Vid stämmobeslut: debet 2098, kredit 2898. Vid utbetalning: debet 2898, kredit 1930. KU31 lämnas för mottagarna senast 31 januari.$faq$, $faq$Utdelning bokförs i två steg. När årsstämman (eller extra stämma) beslutat: debet 2098 vinst föregående år, kredit 2898 outtagen utdelning — skulden till aktieägarna uppstår vid beslutet. Vid utbetalning: debet 2898, kredit 1930. Utdelningen är inte avdragsgill för bolaget. För mottagarna gäller 3:12-reglerna (K10) och bolaget lämnar KU31 senast 31 januari året efter. Kontrollera innan beslut att utdelningen ryms i fritt eget kapital enligt senast fastställda balansräkning och försiktighetsregeln.$faq$, $faq$["ABL 17-18 kap"]$faq$::jsonb, '{}'::text[], array['/year-end', '/bookkeeping']::text[], 'medium', $faq$Olovlig utdelning kan medföra återbäringsskyldighet — vid tveksamhet om utrymmet, stäm av med revisor eller jurist.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-025', 'Bokslut, årsredovisning, INK2, NE & SRU', 'balanserat_resultat', $faq$["Vad är balanserat resultat?","Vad betyder balanserad vinst i ny räkning?","Var hamnar gamla års vinster?"]$faq$::jsonb, $faq$Balanserat resultat (2091) är ackumulerade vinster och förluster från tidigare år som stämman valt att behålla i bolaget.$faq$, $faq$Konto 2091 balanserad vinst/förlust samlar tidigare års resultat som inte delats ut. Flödet: årets resultat bokförs på 2099 vid bokslutet → förs om till 2098 vid nästa års ingång → efter stämmans beslut flyttas det till 2091 (minus eventuell utdelning). Balanserat resultat är fritt eget kapital och ingår i utdelningsbara medel. En ansamlad förlust på 2091 minskar egna kapitalet — håll koll på om halva aktiekapitalet är förbrukat, då gäller reglerna om kontrollbalansräkning.$faq$, $faq$["ÅRL 5 kap 14 §"]$faq$::jsonb, '{}'::text[], array['/reports', '/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-026', 'Bokslut, årsredovisning, INK2, NE & SRU', 'arets_resultat_bokforing', $faq$["Hur bokförs årets resultat?","Vad är konto 8999 och 2099?","Sista verifikationen i bokslutet?"]$faq$::jsonb, $faq$Årets resultat bokförs som sista verifikation: vinst ger debet 8999, kredit 2099 — därmed nollställs resultaträkningen mot balansräkningen.$faq$, $faq$När alla bokslutstransaktioner inklusive skatt är bokförda återstår att flytta årets resultat till eget kapital: vid vinst debet 8999 årets resultat, kredit 2099 årets resultat (vid förlust omvänt). Detta nollställer resultaträkningens saldo och gör att balansräkningen balanserar — 2099 visar årets resultat på skuldsidan. I enskild firma bokförs resultatet i stället mot 2019/2010 eget kapital. Nordklart skapar resultatverifikationen automatiskt som sista steg i bokslutsflödet innan året låses.$faq$, $faq$["BAS 2026"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-027', 'Bokslut, årsredovisning, INK2, NE & SRU', 'ink2_vad_ar', $faq$["Vad är INK2?","Vilken deklaration lämnar aktiebolag?","Vad ingår i inkomstdeklaration 2?"]$faq$::jsonb, $faq$INK2 är aktiebolagets inkomstdeklaration: huvudblankett plus INK2R (räkenskapsschema) och INK2S (skattemässiga justeringar).$faq$, $faq$Aktiebolag deklarerar på Inkomstdeklaration 2, som består av tre delar: huvudblanketten med överskott/underskott och identitetsuppgifter, INK2R som är ett räkenskapsschema där balans- och resultaträkningen redovisas post för post enligt fasta fältkoder, och INK2S med de skattemässiga justeringar som omvandlar bokfört till beskattningsbart resultat. Nordklart fyller INK2-underlaget automatiskt från bokslutet: kontosaldon mappas till INK2R-fält via SRU-koder, justeringarna hämtas från skatteberäkningen, och alltihop kan exporteras som SRU-filer för digital inlämning.$faq$, $faq$["SFL 30 kap"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-028', 'Bokslut, årsredovisning, INK2, NE & SRU', 'ink2r_rakenskapsschema', $faq$["Vad är INK2R?","Hur mappas kontona till räkenskapsschemat?","Fälten i INK2R — varifrån kommer siffrorna?"]$faq$::jsonb, $faq$INK2R speglar balans- och resultaträkningen i Skatteverkets fasta fältstruktur. Nordklart mappar BAS-kontona automatiskt via SRU-koder.$faq$, $faq$INK2R är räkenskapsschemat där bokslutet redovisas i standardiserade fält (t.ex. 2.19 kundfordringar, 3.1 nettoomsättning). Varje BAS-konto har en SRU-kod som styr vilket fält saldot hamnar i — mappningen ingår i Nordklarts kontoplan och kan justeras per konto vid behov. Kontrollen är att INK2R:s tillgångar, skulder, eget kapital och resultat ska stämma exakt med årsredovisningen/årsbokslutet. Nordklart genererar INK2R-underlaget från den låsta bokföringen och varnar om något konto saknar SRU-mappning.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/year-end', '/settings/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-029', 'Bokslut, årsredovisning, INK2, NE & SRU', 'ink2s_justeringar', $faq$["Vad är INK2S?","Var redovisas skattemässiga justeringar i deklarationen?","Hur fylls INK2S i?"]$faq$::jsonb, $faq$INK2S visar vägen från bokfört till skattemässigt resultat: återläggningar, avdrag, fonder och underskott, fält 4.1–4.16.$faq$, $faq$INK2S börjar med bokfört resultat (4.1 vinst eller 4.2 förlust) och redovisar sedan justeringarna öppet: 4.3 ej avdragsgilla kostnader, 4.5 ej skattepliktiga intäkter, 4.6 a schablonintäkt periodiseringsfond, avsättning/återföring av fonder, skillnad bokförda/skattemässiga avskrivningar, 4.14 a outnyttjat underskott från föregående år, fram till 4.15/4.16 överskott/underskott som förs till huvudblanketten. Nordklart bygger INK2S automatiskt från skatteberäkningen i bokslutet — posterna följer konteringen av ej avdragsgilla konton, fondverifikationer och avskrivningar.$faq$, $faq$["IL 14 kap"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-030', 'Bokslut, årsredovisning, INK2, NE & SRU', 'sru_generera', $faq$["Hur genererar jag SRU-filer?","Vad är en SRU-fil?","Exportera deklarationen digitalt?"]$faq$::jsonb, $faq$SRU-filer (INFO.SRU + BLANKETTER.SRU) skapas från bokslutet under Bokslut → Deklaration och laddas upp i Skatteverkets filöverföringstjänst.$faq$, $faq$SRU är Skatteverkets filformat för digital inlämning av deklarationsbilagor. Nordklart genererar två filer: INFO.SRU med avsändaruppgifter och BLANKETTER.SRU med själva blanketterna (INK2R och INK2S som fältkod–värde-par). Beloppen anges i hela kronor, organisationsnumret med 12 siffror och teckenkodningen är ISO 8859-1 — allt hanteras automatiskt. Filerna laddas upp via Skatteverkets e-tjänst 'Filöverföring'. Observera att huvudblanketten INK2 (första sidan) fortfarande signeras separat i e-tjänsten Inkomstdeklaration 2 eller på papper.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-031', 'Bokslut, årsredovisning, INK2, NE & SRU', 'sru_ladda_upp', $faq$["Hur lämnar jag in SRU-filerna till Skatteverket?","Var laddar jag upp BLANKETTER.SRU?","Filöverföring till Skatteverket?"]$faq$::jsonb, $faq$Logga in på Skatteverkets e-tjänst Filöverföring, ladda upp båda SRU-filerna och signera därefter huvudblanketten i e-tjänsten.$faq$, $faq$Inlämning i tre steg: 1) Ladda ner INFO.SRU och BLANKETTER.SRU från Nordklarts bokslutsflöde. 2) Logga in på skatteverket.se → Filöverföring (kräver e-legitimation och behörighet som firmatecknare eller deklarationsombud) och ladda upp filerna — tjänsten validerar formatet direkt och visar kvittens. 3) Signera huvudblanketten INK2 i e-tjänsten Inkomstdeklaration 2, där de överförda bilagorna kopplas till deklarationen. Spara kvittensen. Vid valideringsfel: kontrollera att organisationsnummer och beskattningsperiod i filerna stämmer med Skatteverkets uppgifter.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-032', 'Bokslut, årsredovisning, INK2, NE & SRU', 'deklaration_deadline_ab', $faq$["När ska aktiebolagets deklaration lämnas?","Deklarationsdeadline för AB med kalenderår?","INK2 — vilket datum gäller?"]$faq$::jsonb, $faq$Deadline styrs av räkenskapsårets slut: kalenderårsbolag deklarerar senast 1 juli (papper) eller 1 augusti (digitalt).$faq$, $faq$Aktiebolag deklarerar enligt fyra perioder baserat på bokslutsdatum. Kalenderårsbolag (bokslut 31 december) lämnar INK2 senast 1 juli året efter, med en månads förlängning vid digital inlämning (1 augusti). Bokslut 30 april → deklaration 1 november/1 december; 30 juni → 15 december/15 januari; 31 augusti → 1 mars/1 april. Slutskattebeskedet kommer några månader senare och eventuell kvarskatt förfaller ca 90 dagar efter beskedet. Nordklart visar bolagets deklarationsdeadline i deadline-bevakningen baserat på räkenskapsåret.$faq$, $faq$["SFL 32 kap 2 §"]$faq$::jsonb, '{}'::text[], array['/deadlines', '/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-033', 'Bokslut, årsredovisning, INK2, NE & SRU', 'arsredovisning_bolagsverket', $faq$["Hur skickar jag årsredovisningen till Bolagsverket?","Digital inlämning av årsredovisning?","Vad ska ingå när årsredovisningen lämnas in?"]$faq$::jsonb, $faq$Årsredovisningen med fastställelseintyg lämnas digitalt via Bolagsverkets tjänst eller på papper. Digital inlämning kräver iXBRL-format.$faq$, $faq$Det som lämnas till Bolagsverket är en bestyrkt kopia av årsredovisningen (resultat- och balansräkning, noter, förvaltningsberättelse, underskrifter) med fastställelseintyg i original där en styrelseledamot/VD intygar att stämman fastställt räkningarna, samt revisionsberättelse om bolaget har revisor. Digital inlämning sker i iXBRL-format via Bolagsverkets e-tjänst och kräver att den som skriver under intyget har e-legitimation. Nordklart genererar årsredovisningen från det låsta bokslutet; kontrollera bolagets uppgifter och datum noga innan inlämning.$faq$, $faq$["ÅRL 8 kap 3-3 c §§"]$faq$::jsonb, array['admin']::text[], array['/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-034', 'Bokslut, årsredovisning, INK2, NE & SRU', 'ixbrl_digital', $faq$["Vad är iXBRL?","Måste årsredovisningen lämnas digitalt?","Stödjer Nordklart digital årsredovisning?"]$faq$::jsonb, $faq$iXBRL är det maskinläsbara format Bolagsverket kräver för digital inlämning — en HTML-fil där varje belopp är taggat enligt K2-/K3-taxonomin.$faq$, $faq$iXBRL (Inline XBRL) kombinerar läsbar årsredovisning med maskinläsbara taggar: varje post i resultat- och balansräkningen märks med ett begrepp ur Bolagsverkets taxonomi för K2 eller K3. Digital inlämning är frivillig för de flesta mindre bolag men rekommenderas — den ger direktvalidering och snabbare registrering. Nordklart genererar årsredovisningen med korrekt taggning från bokslutsdata där formatet stöds för bolagets regelverk; alternativt kan årsredovisningen lämnas som bestyrkt papperskopia. Kontrollera valideringsresultatet från Bolagsverket och spara kvittensen.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-035', 'Bokslut, årsredovisning, INK2, NE & SRU', 'forseningsavgifter_bolagsverket', $faq$["Vad händer om årsredovisningen blir försenad?","Förseningsavgifter hos Bolagsverket?","Hur dyrt är det att missa årsredovisningsdeadline?"]$faq$::jsonb, $faq$Förseningsavgift 5 000 kr direkt vid försening, ytterligare 5 000 kr efter två månader och 10 000 kr efter fyra. Efter 11 månader hotar tvångslikvidation.$faq$, $faq$Om årsredovisningen inte kommit in inom 7 månader från räkenskapsårets utgång tar Bolagsverket ut förseningsavgift: 5 000 kr för privata bolag (10 000 kr för publika), ytterligare 5 000 kr om det dröjer mer än två månader till och ytterligare 10 000 kr efter fyra månader — totalt upp till 20 000 kr. Avgifterna är inte avdragsgilla (bokförs 6992). Har ingen årsredovisning kommit in inom 11 månader kan Bolagsverket besluta om tvångslikvidation, och styrelsen riskerar personligt betalningsansvar för bolagets förpliktelser. Sen årsredovisning kan också utgöra bokföringsbrott.$faq$, $faq$["ÅRL 8 kap 5-13 §§","ABL 25 kap 11 §"]$faq$::jsonb, '{}'::text[], array['/deadlines', '/year-end']::text[], 'high', $faq$Om deadline redan passerats: prioritera inlämningen omedelbart och kontakta vid behov redovisningskonsult — avgifterna och riskerna trappas upp snabbt.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-036', 'Bokslut, årsredovisning, INK2, NE & SRU', 'revisor_kravs', $faq$["Måste mitt aktiebolag ha revisor?","Vilka gränsvärden gäller för revisionsplikt?","Kan jag välja bort revisorn?"]$faq$::jsonb, $faq$Små AB kan välja bort revisor om högst ett av gränsvärdena överskrids två år i rad: 3 anställda, 1,5 mkr balansomslutning, 3 mkr omsättning.$faq$, $faq$Revisionsplikten gäller aktiebolag som under två på varandra följande räkenskapsår överskrider minst två av: fler än 3 anställda i medeltal, mer än 1,5 mkr i balansomslutning, mer än 3 mkr i nettoomsättning. Nystartade och mindre bolag kan alltså välja bort revisor genom bestämmelse i bolagsordningen. Utan revisor lämnas ingen revisionsberättelse med årsredovisningen. Tänk på att banker, investerare eller större kunder ändå kan efterfråga reviderade räkningar. Överskrids gränsvärdena måste revisor utses — planera i god tid.$faq$, $faq$["ABL 9 kap 1 §"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-037', 'Bokslut, årsredovisning, INK2, NE & SRU', 'faststallelseintyg', $faq$["Vad är ett fastställelseintyg?","Vem skriver under fastställelseintyget?","Intyg till Bolagsverket — vad ska stå?"]$faq$::jsonb, $faq$Fastställelseintyget intygar att årsstämman fastställt resultat- och balansräkningen och anger stämmodatum — undertecknas av styrelseledamot eller VD.$faq$, $faq$Fastställelseintyget är den formella bekräftelsen till Bolagsverket att årsstämman hållits och fastställt räkningarna. Det ska innehålla: intygande att kopian stämmer med originalet, att resultat- och balansräkningen fastställts, stämmans datum samt uppgift om stämmans beslut om resultatdisposition. Intyget tecknas i original av en styrelseledamot eller VD — vid digital inlämning signeras det med e-legitimation. Fel i intyget (fel datum, saknad underskrift) är den vanligaste orsaken till att Bolagsverket förelägger om komplettering.$faq$, $faq$["ÅRL 8 kap 3 a §"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-038', 'Bokslut, årsredovisning, INK2, NE & SRU', 'ne_bilaga', $faq$["Vad är NE-bilagan?","Hur deklarerar enskild firma?","Var redovisas firmans resultat i deklarationen?"]$faq$::jsonb, $faq$NE-bilagan är enskilda näringsidkarens deklarationsbilaga: balans- och resultaträkning plus skattemässiga justeringar fram till överskott/underskott av näringsverksamhet.$faq$, $faq$Enskilda näringsidkare redovisar verksamheten på NE-bilagan till den privata inkomstdeklarationen (INK1): del B/R med balans- och resultaträkning enligt förenklat årsbokslut, och skattemässiga justeringar (R12–R48) för bl.a. periodiseringsfond, räntefördelning, expansionsfond och egenavgifter fram till slutligt överskott/underskott. Deklarationen lämnas senast 2 maj. Nordklart tar fram NE-underlaget från bokföringen — men observera att NE-flödet i Nordklart är ett underlag och lämnas som utkast: kontrollera och komplettera justeringsposterna i Skatteverkets e-tjänst innan inlämning.$faq$, $faq$["SFL 31 kap"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'medium', $faq$Räntefördelning och expansionsfond kräver ofta rådgivare — beräkningarna bygger på kapitalunderlag som är lätta att få fel.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-039', 'Bokslut, årsredovisning, INK2, NE & SRU', 'ne_status_nordklart', $faq$["Varför är NE-flödet markerat som utkast i Nordklart?","Kan jag slutföra NE-deklarationen direkt i Nordklart?","NE-bilagan är blockerad — vad betyder det?"]$faq$::jsonb, $faq$NE-underlaget genereras från bokföringen men markeras som utkast — de skattemässiga justeringarna (räntefördelning, expansionsfond) kräver uppgifter utanför bokföringen.$faq$, $faq$Nordklart genererar NE-bilagans räkenskapsdelar (B- och R-fälten) komplett från det förenklade årsbokslutet. Däremot kräver flera justeringsposter uppgifter som inte finns i bokföringen: sparad räntefördelning, kapitalunderlag från tidigare år, expansionsfondens historik och privata pensionsavdrag. För att undvika felaktiga deklarationer lämnas NE-paketet därför medvetet som utkast/underlag — det markeras inte som komplett i Nordklart. Använd underlaget, komplettera justeringarna i Skatteverkets e-tjänst eller med din rådgivare, och lämna in där.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-040', 'Bokslut, årsredovisning, INK2, NE & SRU', 'rantefordelning', $faq$["Vad är räntefördelning?","Positiv räntefördelning i enskild firma?","Hur flyttar jag inkomst från tjänst till kapital?"]$faq$::jsonb, $faq$Positiv räntefördelning låter enskilda näringsidkare beskatta en schablonränta på kapitalunderlaget som kapitalinkomst (30 %) i stället för näringsinkomst.$faq$, $faq$Räntefördelning kompenserar för att enskild firma inte kan få kapitalbeskattad utdelning. Är kapitalunderlaget (tillgångar minus skulder vid årets ingång, med justeringar) större än 50 000 kr får du flytta underlag × (statslåneräntan + 6 procentenheter) från näringsbeskattning till kapitalbeskattning — positiv räntefördelning, frivillig och sparbar. Negativ räntefördelning (underlag under −50 000 kr) är obligatorisk åt andra hållet. Beräkningen görs på NE-bilagan; Nordklart visar kapitalunderlagets komponenter från balansräkningen men historiska sparade belopp behöver du komplettera själv.$faq$, $faq$["IL 33 kap"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'high', $faq$Räntefördelningens kapitalunderlag är komplext (övergångsposter, sparade belopp) — låt en rådgivare kontrollera beräkningen.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-041', 'Bokslut, årsredovisning, INK2, NE & SRU', 'expansionsfond', $faq$["Vad är expansionsfond?","Kan enskild firma spara vinst till låg skatt som ett AB?","Expansionsfondsskatt — hur fungerar den?"]$faq$::jsonb, $faq$Expansionsfonden låter enskild firma behålla vinst i verksamheten mot 20,6 % expansionsfondsskatt — motsvarande bolagsskatten — i stället för full inkomstbeskattning.$faq$, $faq$Med expansionsfond kan enskilda näringsidkare återinvestera vinst på liknande villkor som aktiebolag: avsatt belopp beskattas bara med expansionsfondsskatt 20,6 % nu, och resterande beskattning sker först vid återföring (då expansionsfondsskatten återfås). Taket styrs av kapitalunderlaget för expansionsfond — fonden får inte överstiga ett justerat eget kapital. Avsättning och återföring är deklarationsposter på NE-bilagan, ingen bokföring. Vid ombildning till AB kan fonden under vissa villkor föras över. Beräkningen är känslig för kapitalunderlagets komponenter — ta hjälp vid större belopp.$faq$, $faq$["IL 34 kap"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'high', $faq$Expansionsfond i kombination med räntefördelning och periodiseringsfond bör planeras med skatterådgivare.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-042', 'Bokslut, årsredovisning, INK2, NE & SRU', 'egenavgifter_ne', $faq$["Hur hanteras egenavgifter i NE-bilagan?","Schablonavdrag för egenavgifter?","Varför dras 25 % av innan skatten räknas?"]$faq$::jsonb, $faq$På NE görs schablonavdrag för egenavgifter (max 25 %) mot årets överskott; föregående års schablon stäms av mot faktiska avgifter.$faq$, $faq$Eftersom egenavgifterna är avdragsgilla men inte kända förrän skatten är beräknad används en schablonmodell på NE-bilagan: du drar av ett schablonbelopp (max 25 % av överskottet, lägre för äldre) innan beskattningsbart resultat fastställs (R43). Året därpå återförs fjolårets schablonavdrag (R40) och det faktiska påförda beloppet dras av (R41) — mellanskillnaden justerar sig själv. Nordklarts NE-underlag hanterar schablonberäkningen för året; fjolårets värden hämtar du från förra deklarationen.$faq$, $faq$["IL 16 kap 29-31 §§"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-043', 'Bokslut, årsredovisning, INK2, NE & SRU', 'lasa_rakenskapsar', $faq$["Hur låser jag räkenskapsåret?","Vad innebär det att året låses?","Kan jag bokföra i ett låst år?"]$faq$::jsonb, $faq$När bokslutet slutförs låses räkenskapsåret: inga nya verifikationer kan bokföras i perioden. Låsningen skyddar det underlag som deklarerats.$faq$, $faq$Sista steget i bokslutsflödet låser räkenskapsåret. Låsningen upprätthålls på databasnivå — varken manuella verifikationer, automation eller importer kan skriva i låsta perioder. Det säkerställer att bokföringen bakom inlämnad årsredovisning och deklaration inte ändras i efterhand, i linje med bokföringslagens krav. Upptäcks fel efter låsning rättas de i den första öppna perioden med ändringsverifikation och hänvisning till ursprungsverifikationen. Låsdatum och vem som låste loggas i audit-historiken.$faq$, $faq$["BFL 5 kap 5 §"]$faq$::jsonb, array['admin']::text[], array['/year-end', '/settings/bookkeeping']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-044', 'Bokslut, årsredovisning, INK2, NE & SRU', 'oppna_last_period', $faq$["Kan jag låsa upp en låst period?","Jag hittade ett fel efter låsningen — vad gör jag?","Öppna räkenskapsåret igen?"]$faq$::jsonb, $faq$Undvik att låsa upp. Rätta i stället felet med ändringsverifikation i innevarande period — det är den lagenliga vägen.$faq$, $faq$Huvudregeln är att låsta perioder förblir låsta: har årsredovisning eller deklaration lämnats får bokföringen bakom dem inte ändras. Fel som upptäcks efteråt rättas genom ändringsverifikation (storno) i den första öppna perioden, med tydlig hänvisning till den felaktiga verifikationen. Endast om bokslutet ännu inte lämnats någonstans kan en administratör i undantagsfall låsa upp perioden — åtgärden auditloggas och alla bokslutskontroller måste köras om innan ny låsning. Är felet väsentligt för en redan inlämnad årsredovisning, prata med revisor/rådgivare om hur det ska hanteras.$faq$, $faq$["BFL 5 kap 5 §"]$faq$::jsonb, array['owner']::text[], array['/year-end', '/settings/bookkeeping']::text[], 'high', $faq$Ändringar i redan inlämnade bokslut kan kräva rättad deklaration eller ny årsredovisning — involvera revisor eller redovisningskonsult.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-045', 'Bokslut, årsredovisning, INK2, NE & SRU', 'ingaende_balanser_nasta_ar', $faq$["Hur förs saldona över till nästa år?","Vad är ingående balanser?","Skapas nya året automatiskt efter bokslut?"]$faq$::jsonb, $faq$Vid årsavslut förs balanskontonas utgående saldon över som ingående balanser i det nya räkenskapsåret — resultatkontona börjar om från noll.$faq$, $faq$När bokslutet slutförs skapar Nordklart det nya räkenskapsåret och för över utgående balanser: alla balanskonton (klass 1–2) får sina UB som IB i nya året, medan resultatkonton (klass 3–8) nollställs — deras nettoeffekt ligger i årets resultat på 2099. I nya året omförs 2099 till 2098 i väntan på stämmans disposition. Ändras det gamla året (före låsning) räknas ingående balanser om automatiskt. Kontrollera att IB i nya året stämmer mot fastställd balansräkning — det är själva kontinuitetsprincipen i bokföringen.$faq$, $faq$["ÅRL 3 kap 5 §"]$faq$::jsonb, '{}'::text[], array['/year-end', '/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-046', 'Bokslut, årsredovisning, INK2, NE & SRU', 'kontrollbalansrakning', $faq$["Vad är en kontrollbalansräkning?","Halva aktiekapitalet förbrukat — vad gäller?","När måste styrelsen upprätta kontrollbalansräkning?"]$faq$::jsonb, $faq$Om det finns skäl att anta att eget kapital understiger halva aktiekapitalet måste styrelsen genast upprätta kontrollbalansräkning — annars riskeras personligt ansvar.$faq$, $faq$När det finns skäl att anta att bolagets eget kapital understiger hälften av det registrerade aktiekapitalet ska styrelsen genast upprätta en kontrollbalansräkning (granskad av revisorn om sådan finns). Visar den att kapitalet är förbrukat under halva ska en första kontrollstämma hållas; bolaget har sedan åtta månader på sig att läka kapitalet till fullo, annars ska stämman besluta om likvidation. Underlåtenhet ger styrelseledamöterna personligt betalningsansvar för förpliktelser som uppkommer därefter. Nordklarts balansrapport visar eget kapital löpande — reagera tidigt vid stora förluster.$faq$, $faq$["ABL 25 kap 13-20 §§"]$faq$::jsonb, '{}'::text[], array['/reports', '/kpi']::text[], 'high', $faq$Misstänkt kapitalbrist är ett akut styrelseansvar — kontakta revisor eller jurist omedelbart.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-047', 'Bokslut, årsredovisning, INK2, NE & SRU', 'forlust_hantering', $faq$["Vad händer skattemässigt vid förlust?","Hur bokförs ett negativt resultat?","Betalar bolaget skatt vid förlust?"]$faq$::jsonb, $faq$Vid förlust betalas ingen bolagsskatt. Underskottet rullas vidare och kvittas mot framtida vinster. Bokförs debet 2099, kredit 8999.$faq$, $faq$Ett skattemässigt underskott ger ingen skatt att betala och ingen återbetalning — det sparas i stället utan tidsgräns och dras av mot kommande års överskott (redovisas i INK2S ruta 4.14 a nästa år). Bokföringsmässigt bokförs årets förlust omvänt mot vinst: debet 2099, kredit 8999. Observera spärregler: vid större ägarförändringar kan beloppsspärr och koncernbidragsspärr begränsa rätten att utnyttja gamla underskott. Håll också ögonen på eget kapital — stora förluster kan aktualisera kontrollbalansräkning.$faq$, $faq$["IL 40 kap"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-048', 'Bokslut, årsredovisning, INK2, NE & SRU', 'underskottsavdrag', $faq$["Hur utnyttjar jag gamla underskott?","Var anges tidigare års förlust i deklarationen?","Sparade underskott — hur länge gäller de?"]$faq$::jsonb, $faq$Föregående års underskott anges i INK2S ruta 4.14 a och dras av mot årets överskott. Underskott sparas utan tidsgräns.$faq$, $faq$Inrullat underskott från föregående beskattningsår dras av som skattemässig justering: ange beloppet i INK2S ruta 4.14 a så minskar det årets beskattningsbara resultat; ett kvarvarande underskott rullas vidare till nästa år. Det finns ingen tidsgräns, men ägarförändringar kan utlösa beloppsspärren (underskott över 200 % av köpeskillingen faller bort) och koncernbidragsspärren (fördröjer kvittning mot koncernbidrag i fem år). Nordklarts skatteberäkning har ett fält för inrullat underskott — hämta beloppet från förra årets slutskattebesked eller deklaration.$faq$, $faq$["IL 40 kap 2-19 §§"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'medium', $faq$Underskott i samband med ägarförändringar kräver skatterådgivare — spärreglerna är komplexa och dyra att missa.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-049', 'Bokslut, årsredovisning, INK2, NE & SRU', 'bokslutschecklista', $faq$["Finns en checklista för bokslutet?","Vad ska jag gå igenom innan årsavslut?","Bokslutsförberedelser — vad ingår?"]$faq$::jsonb, $faq$Ja, bokslutsflödet fungerar som checklista: avstämningar, brytdagsposter, bokslutstransaktioner, skatt, resultat, låsning och rapporter — i ordning med statusmarkering.$faq$, $faq$Nordklarts bokslutsflöde är strukturerat som en checklista med automatiska kontroller: (1) all löpande bokföring klar — banktransaktioner hanterade, väntande åtgärder lösta; (2) avstämningar — bank, kundreskontra, leverantörsreskontra, skattekonto; (3) brytdagsposter — leverantörsfakturor och intäkter över årsskiftet; (4) bokslutstransaktioner — avskrivningar, periodiseringar, semesterlöneskuld, lager, fonder; (5) skatteberäkning och årets resultat; (6) låsning; (7) rapporter — årsredovisning/årsbokslut, INK2/NE, SIE-export till revisor. Varje punkt visar status och länkar till åtgärden, så inget steg glöms.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-050', 'Bokslut, årsredovisning, INK2, NE & SRU', 'lager_inventering', $faq$["Hur hanteras varulager i bokslutet?","Måste jag inventera vid årsskiftet?","Bokföra lagerförändring?"]$faq$::jsonb, $faq$Lagret inventeras per balansdagen och värderas till lägsta av anskaffnings- och verkligt värde. Förändringen bokförs 1460 mot 4990.$faq$, $faq$Företag med varulager ska inventera per balansdagen och upprätta inventeringslista (undertecknad, på heder och samvete). Värdering enligt lägsta värdets princip: det lägsta av anskaffningsvärde (FIFO) och nettoförsäljningsvärde; skattemässigt får alternativt 97 %-regeln användas på anskaffningsvärdet. Bokföring av förändringen: ökat lager debet 1460, kredit 4990 lagerförändring — minskat lager omvänt. Inkurans (osäljbara varor) skrivs ned. Nordklart har lagerförändringsposten i bokslutstransaktionerna; inventeringslistan sparas som underlag till verifikationen.$faq$, $faq$["IL 17 kap 3-4 §§","BFNAR 2016:10 kap 12"]$faq$::jsonb, '{}'::text[], array['/year-end', '/bookkeeping']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-051', 'Bokslut, årsredovisning, INK2, NE & SRU', 'osakra_kundfordringar', $faq$["Hur hanterar jag osäkra kundfordringar i bokslutet?","Kund som inte betalar — kan jag skriva ned fordran?","Befarad kundförlust vid årsskiftet?"]$faq$::jsonb, $faq$Osäkra fordringar skrivs ned som befarad kundförlust (6352/1519) utan momsjustering. Konstaterad förlust (konkurs) ger även momsen tillbaka.$faq$, $faq$Vid bokslutet ska kundfordringarna värderas individuellt. Befarad kundförlust (förfallen sedan länge, betalningssvårigheter): debet 6352 befarade kundförluster, kredit 1519 nedskrivning kundfordringar — momsen röres inte och fordran ligger kvar i reskontran. Konstaterad kundförlust (konkurs, ackord, resultatlösa krav): boka bort fordran helt — debet 6351, debet 26XX (momsen återfås), kredit 1510. Skattemässigt avdrag för befarad förlust kräver att förlustrisken är sannolik och individuellt prövad. Nordklarts avskrivningsflöde för fakturor hanterar båda stegen med korrekt momshantering.$faq$, $faq$["ML 7 kap 44 §","IL 16 kap"]$faq$::jsonb, '{}'::text[], array['/invoices', '/year-end']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-052', 'Bokslut, årsredovisning, INK2, NE & SRU', 'upplupna_poster_bokslut', $faq$["Vad är upplupna kostnader och intäkter?","Elräkningen för december kommer i januari — hur bokförs den?","Interimsposter i bokslutet?"]$faq$::jsonb, $faq$Upplupna kostnader (2990) avser årets kostnader som faktureras senare; upplupna intäkter (1790) är utfört men ofakturerat. Posterna vänds i nya året.$faq$, $faq$Interimsposterna säkrar att resultat hamnar på rätt år. Upplupen kostnad: el, revision eller bonus som avser december men faktureras i januari — debet kostnadskonto, kredit 2990 upplupna kostnader. Upplupen intäkt: arbete utfört i december som faktureras i januari — debet 1790 (eller 1620 pågående arbete), kredit intäktskonto. I det nya året vänds posterna (återföring) så att den riktiga fakturan inte dubbelräknas. Nordklart kan skapa interimsposter med automatisk återföring på första dagen i nya året.$faq$, $faq$["ÅRL 2 kap 4 §"]$faq$::jsonb, '{}'::text[], array['/bookkeeping', '/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-053', 'Bokslut, årsredovisning, INK2, NE & SRU', 'sie_till_revisorn', $faq$["Hur skickar jag bokföringen till revisorn?","Revisorn vill ha en SIE-fil — var hittar jag den?","Exportera året för granskning?"]$faq$::jsonb, $faq$Exportera en SIE4-fil under Import/Export eller från bokslutsflödet — den innehåller kontoplan, balanser och alla verifikationer för året.$faq$, $faq$Revisorer och redovisningskonsulter arbetar normalt med SIE4-filer. I Nordklart exporterar du under Import → Export (eller direkt från bokslutsflödet): filen innehåller kontoplan med SRU-koder, ingående och utgående balanser, resultatsaldon, samtliga verifikationer med transaktionsrader samt dimensioner (kostnadsställen/projekt) där de används. Föregående års jämförelsesiffror följer med när de finns. Komplettera gärna med huvudbok och reskontralistor som PDF om revisorn önskar. Ett bra tips är att exportera efter att alla bokslutstransaktioner utom skatt är bokförda, och igen efter låsning.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import', '/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-054', 'Bokslut, årsredovisning, INK2, NE & SRU', 'efter_bokslut_nasta_ar', $faq$["Vad händer efter att bokslutet är klart?","Vilka steg återstår efter låsningen?","Nytt räkenskapsår — vad ska jag tänka på?"]$faq$::jsonb, $faq$Efter låsning: håll årsstämma, lämna årsredovisning till Bolagsverket, deklarera INK2, bokför resultatdispositionen och fortsätt löpande i nya året.$faq$, $faq$När räkenskapsåret är låst återstår formalia: aktiebolag håller årsstämma (senast 6 månader efter årsskiftet) som fastställer räkningarna och beslutar om resultatdisposition; årsredovisningen med fastställelseintyg lämnas till Bolagsverket (senast 7 månader); INK2 med SRU-bilagor lämnas till Skatteverket enligt bolagets deklarationsperiod; utdelning bokförs vid beslut och KU31 lämnas senast 31 januari året efter utdelningen. I det nya året bokförs resultatdispositionen (2098 → 2091/2898) och den löpande bokföringen fortsätter mot de överförda ingående balanserna. Nordklarts deadline-bevakning håller ordning på datumen.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/year-end', '/deadlines']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('bokslut-055', 'Bokslut, årsredovisning, INK2, NE & SRU', 'forvaltningsberattelse', $faq$["Vad ska stå i förvaltningsberättelsen?","Måste små bolag skriva förvaltningsberättelse?","Flerårsöversikt i årsredovisningen?"]$faq$::jsonb, $faq$Alla AB ska ha förvaltningsberättelse: verksamhetsbeskrivning, väsentliga händelser, flerårsöversikt, förändringar i eget kapital och resultatdisposition.$faq$, $faq$Förvaltningsberättelsen är en obligatorisk del av årsredovisningen även för de minsta bolagen (K2). Innehåll: allmänt om verksamheten (vad bolaget gör, säte), väsentliga händelser under räkenskapsåret, flerårsöversikt med nyckeltal för minst fyra år (nettoomsättning, resultat efter finansiella poster, soliditet), förändringar i eget kapital samt styrelsens förslag till resultatdisposition. Nordklart förifyller flerårsöversikten och dispositionen från bokföringen; verksamhetsbeskrivning och händelser skriver du själv. Håll texten saklig — den är offentlig hos Bolagsverket.$faq$, $faq$["ÅRL 6 kap 1-2 §§","BFNAR 2016:10 kap 4-5"]$faq$::jsonb, '{}'::text[], array['/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-001', 'Byrå, plattform, behörigheter & säkerhet', 'skapa_team_byra', $faq$["Hur skapar jag en byrå i Nordklart?","Vi är en redovisningsbyrå — hur sätter vi upp team?","Skapa arbetsyta för byrån?"]$faq$::jsonb, $faq$Under Byrå skapar du ett team, bjuder in kollegor och kopplar kundföretag — teammedlemmar får då automatiskt åtkomst till kundernas bokföring.$faq$, $faq$Byråfunktionen bygger på team: skapa teamet under Byrå, ge det ett namn och bjud in dina kollegor. Kundföretag kopplas sedan till teamet — antingen genom att kunden bjuder in byrån eller genom att byrån skapar företaget åt kunden. Medlemskap i teamet synkas automatiskt till alla kopplade företag, så en ny kollega får direkt åtkomst till hela kundstocken utan separata inbjudningar per bolag, och en avslutad kollega förlorar all åtkomst i ett steg. Byråöversikten visar alla kunder med status för väntande åtgärder och deadlines.$faq$, $faq$[]$faq$::jsonb, array['owner']::text[], array['/agency']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-002', 'Byrå, plattform, behörigheter & säkerhet', 'bjuda_in_kollega', $faq$["Hur bjuder jag in en kollega till byrån?","Lägga till medarbetare i teamet?","Ny anställd på byrån — hur får hen åtkomst?"]$faq$::jsonb, $faq$Under Byrå → Medlemmar skickar du en inbjudan via e-post. När kollegan accepterar får hen automatiskt åtkomst till teamets alla kundföretag.$faq$, $faq$Bjud in kollegor från byråvyn: ange e-postadress och roll, så skickas en inbjudningslänk. Länken är personlig, kan bara användas en gång och är giltig i 7 dagar. När kollegan accepterar (och skapar konto om hen inte har ett) läggs hen till i teamet, och medlemskapet synkas till samtliga kundföretag som är kopplade till teamet — med den roll som teamkopplingen anger. Ingen manuell hantering per kundbolag behövs. Väntande inbjudningar kan återkallas innan de accepterats.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/agency']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-003', 'Byrå, plattform, behörigheter & säkerhet', 'koppla_kundforetag', $faq$["Hur kopplar jag ett kundföretag till byrån?","Kunden vill att vi sköter bokföringen — hur får vi åtkomst?","Lägga till kund i byråns arbetsyta?"]$faq$::jsonb, $faq$Antingen bjuder kunden in byrån till sitt företag, eller så skapar byrån företaget och bjuder in kunden — kopplingen till teamet ger alla byråmedlemmar åtkomst.$faq$, $faq$Två vägar: 1) Befintligt Nordklart-företag — kundens ägare/admin bjuder in byrån, och företaget kopplas till ert team; alla teammedlemmar får då åtkomst enligt teamets roll. 2) Ny kund — byrån skapar företaget i Nordklart, sätter upp kontoplan och bankkoppling, och bjuder in kunden som ägare/medlem i sitt eget bolag. Kopplingen kan när som helst brytas av kundens ägare, vilket omedelbart tar bort byråns åtkomst. Vem som gjort vad syns alltid i audit-loggen — byråmedlemmars åtgärder loggas med deras identitet.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/agency', '/settings/team']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-004', 'Byrå, plattform, behörigheter & säkerhet', 'roller_oversikt', $faq$["Vilka roller finns i Nordklart?","Vad är skillnaden mellan owner, admin, member och viewer?","Behörighetsnivåer i ett företag?"]$faq$::jsonb, $faq$Fyra roller: owner (allt inkl. radering), admin (inställningar och medlemmar), member (löpande arbete), viewer (endast läsa).$faq$, $faq$Varje företagsmedlemskap har en roll: Owner — full kontroll inklusive att radera företaget, hantera ägarskap och alla inställningar; det finns alltid minst en ägare. Admin — hanterar medlemmar, inställningar, automationsregler, integrationer och kan göra allt i det löpande arbetet. Member — arbetar med bokföring, fakturor, transaktioner och väntande åtgärder men ändrar inte inställningar eller medlemmar. Viewer — ser rapporter och data utan att kunna ändra något; lämplig för revisorer eller styrelseledamöter. Rollen gäller per företag — samma person kan vara admin i ett bolag och viewer i ett annat.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/team']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-005', 'Byrå, plattform, behörigheter & säkerhet', 'viewer_behorighet', $faq$["Vad kan en viewer göra?","Kan revisorn få läsbehörighet?","Read-only-åtkomst till bokföringen?"]$faq$::jsonb, $faq$En viewer ser rapporter, verifikationer, fakturor och transaktioner men kan inte skapa, ändra eller godkänna någonting.$faq$, $faq$Viewer-rollen är renodlad läsbehörighet: rapporter, huvudbok, verifikationer med underlag, fakturor, reskontror och transaktioner kan granskas och exporteras, men inga skrivåtgärder är tillåtna — inte bokföra, inte godkänna väntande åtgärder, inte ändra inställningar. Skrivförsök stoppas på serversidan, inte bara i gränssnittet. Rollen passar revisorer under granskning, styrelseledamöter och kunder som vill följa byråns arbete. Bjud in med rollen viewer under Inställningar → Team; rollen kan höjas senare vid behov.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/team']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-006', 'Byrå, plattform, behörigheter & säkerhet', 'andra_roll', $faq$["Hur ändrar jag rollen för en medlem?","Uppgradera en member till admin?","Byta behörighet på en användare?"]$faq$::jsonb, $faq$Under Inställningar → Team ändrar en ägare eller admin medlemmens roll — ändringen gäller direkt och loggas.$faq$, $faq$Rolländringar görs i teamvyn: välj medlemmen och sätt ny roll. Reglerna: ägare kan ändra alla roller; admins kan hantera roller upp till sin egen nivå men inte ändra eller ta bort ägare; ingen kan sänka den sista ägaren — ägarskap måste först överlåtas. Ändringen slår igenom omedelbart i alla sessioner, och både gammal och ny roll auditloggas. Medlemmar som kommit via ett byråteam styrs av teamkopplingens roll och ändras där i stället för per företag.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/team']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-007', 'Byrå, plattform, behörigheter & säkerhet', 'ta_bort_medlem', $faq$["Hur tar jag bort en medlem från företaget?","En anställd har slutat — hur stänger jag av åtkomsten?","Avsluta en användares behörighet?"]$faq$::jsonb, $faq$Ta bort medlemmen under Inställningar → Team — åtkomsten upphör omedelbart. Historiken över personens åtgärder bevaras i audit-loggen.$faq$, $faq$I teamvyn tar en ägare eller admin bort medlemmen; åtkomsten till företaget upphör direkt i alla aktiva sessioner. Det som personen gjort — bokförda verifikationer, godkännanden — bevaras med personens identitet i audit-loggen, eftersom spårbarheten är en del av räkenskapsinformationen. En borttagen medlem kan bjudas in igen senare. För byråmedlemmar: ta bort personen ur teamet i stället, så försvinner åtkomsten till alla kundföretag samtidigt. Glöm inte att även återkalla personliga API-nycklar om sådana skapats.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/team']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-008', 'Byrå, plattform, behörigheter & säkerhet', 'bjuda_in_kund', $faq$["Hur bjuder jag in kunden till sitt eget företag?","Kunden ska kunna se sin bokföring — hur ger jag åtkomst?","Skicka inbjudan till företagets ägare?"]$faq$::jsonb, $faq$Skicka en företagsinbjudan från Inställningar → Team med lämplig roll — kunden accepterar via länken och får åtkomst till sitt bolag.$faq$, $faq$När byrån satt upp ett kundbolag bjuds kunden in via e-post från teamvyn: välj roll efter hur aktiv kunden ska vara — owner om kunden ska ha full kontroll (vanligast, det är kundens bolag), member om kunden själv fotar kvitton och skickar fakturor, viewer om kunden bara ska följa siffrorna. Inbjudningslänken är giltig i 7 dagar och kan skickas om. När kunden accepterat ser hen sitt företag i sin egen företagsväljare, medan byråns åtkomst via teamet är oförändrad.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/team', '/agency']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-009', 'Byrå, plattform, behörigheter & säkerhet', 'inbjudan_giltighet', $faq$["Hur länge gäller en inbjudningslänk?","Inbjudan har gått ut — vad gör jag?","Kan jag skicka om en inbjudan?"]$faq$::jsonb, $faq$Inbjudningar är giltiga i 7 dagar och kan bara användas en gång. Utgångna inbjudningar skickas enkelt om från teamvyn.$faq$, $faq$Av säkerhetsskäl är inbjudningslänkar tidsbegränsade till 7 dagar, personliga och engångsanvändbara — token lagras hashad och kan inte återskapas ur systemet. Har länken gått ut eller kommit bort skickar du en ny från Inställningar → Team (den gamla blir samtidigt ogiltig). Väntande inbjudningar listas med status och kan återkallas innan de accepterats. Kontrollera skräpposten om mejlet inte kommer fram, och verifiera att e-postadressen stämmer — inbjudan är knuten till adressen.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/team']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-010', 'Byrå, plattform, behörigheter & säkerhet', 'byta_aktivt_foretag', $faq$["Hur byter jag mellan företag?","Jag har flera bolag — var växlar jag?","Företagsväljaren — var finns den?"]$faq$::jsonb, $faq$Klicka på företagsnamnet uppe i sidomenyn och välj bolag i listan — hela gränssnittet växlar till det valda företagets data.$faq$, $faq$Företagsväljaren i sidhuvudet listar alla företag du är medlem i — egna bolag och byråkunder. När du växlar byts hela kontexten: bokföring, fakturor, transaktioner, rapporter och inställningar visar enbart det aktiva företaget. Valet sparas mellan sessioner så du kommer tillbaka till samma bolag nästa gång. Datat är strikt separerat per företag på databasnivå (radnivåsäkerhet), så det finns ingen risk att åtgärder hamnar i fel bolag — men titta för vana på företagsnamnet innan du bokför, särskilt som byråmedarbetare med många kunder.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-011', 'Byrå, plattform, behörigheter & säkerhet', 'flera_foretag', $faq$["Kan jag ha flera företag på samma konto?","Jag driver både AB och enskild firma — behöver jag två konton?","Lägga till ett andra bolag?"]$faq$::jsonb, $faq$Ja, ett användarkonto kan äga och vara medlem i obegränsat antal företag — varje bolag har helt separerad bokföring och inställningar.$faq$, $faq$Nordklart är byggt för fleftöretagande: samma inloggning hanterar alla dina bolag — AB, enskild firma, flera AB — och du växlar mellan dem i företagsväljaren. Varje företag är en egen enhet med egen kontoplan, egna räkenskapsår, egna integrationer och egna medlemmar; data blandas aldrig. Nytt företag skapas från företagsväljaren → Lägg till företag och går genom samma onboarding som det första. Fakturering/abonnemang hanteras per företag. Tänk på att transaktioner mellan dina bolag ska bokföras i båda — de är separata juridiska personer.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/company']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-012', 'Byrå, plattform, behörigheter & säkerhet', 'tvafaktorsautentisering', $faq$["Hur aktiverar jag tvåfaktorsautentisering?","Sätta på MFA på mitt konto?","Skydda inloggningen med engångskoder?"]$faq$::jsonb, $faq$Under Inställningar → Konto aktiverar du TOTP: skanna QR-koden med en autentiseringsapp och bekräfta med en kod.$faq$, $faq$Nordklart använder TOTP (tidsbaserade engångskoder): gå till kontoinställningarna, välj aktivera tvåfaktorsautentisering, skanna QR-koden med valfri autentiseringsapp (Google Authenticator, 1Password, Microsoft Authenticator m.fl.) och bekräfta med den sexsiffriga koden. Därefter krävs kod utöver lösenordet vid inloggning. Spara återställningsinformationen säkert — tappar du både lösenord och autentiseringsapp krävs supportärende med identitetskontroll. Bokföringsdata är känsligt; MFA rekommenderas starkt för alla användare och kan vara obligatoriskt på plattformen.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/account']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-013', 'Byrå, plattform, behörigheter & säkerhet', 'mfa_kravs', $faq$["Varför tvingas jag aktivera MFA?","Är tvåfaktor obligatoriskt i Nordklart?","Kan jag hoppa över MFA-registreringen?"]$faq$::jsonb, $faq$På den hostade tjänsten är MFA obligatoriskt — du leds till registreringen vid första inloggning och verifierar sedan med kod varje session.$faq$, $faq$Nordklarts molntjänst kräver tvåfaktorsautentisering för alla användare: vid första inloggningen leds du till MFA-registreringen och kan inte gå vidare utan att slutföra den, och därefter krävs engångskod för att nå företagsdata. Kravet skyddar bokföring, personuppgifter i lönedata och bankkopplingar mot kontokapningar — lösenord ensamt är inte tillräckligt för ekonomisystem. Självhostade installationer kan konfigurera bort kravet, men rekommendationen är att behålla det. Byter du telefon: flytta autentiseringsappen innan du raderar den gamla.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/account']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-014', 'Byrå, plattform, behörigheter & säkerhet', 'aterstalla_losenord', $faq$["Jag har glömt mitt lösenord — hur återställer jag?","Byta lösenord i Nordklart?","Lösenordsåterställning fungerar inte?"]$faq$::jsonb, $faq$Klicka 'Glömt lösenord' på inloggningssidan — en återställningslänk skickas till din e-post. Inloggad byter du lösenord under Konto.$faq$, $faq$Vid glömt lösenord: ange din e-postadress under 'Glömt lösenord' så skickas en tidsbegränsad återställningslänk. Kommer mejlet inte fram — kontrollera skräpposten och att du anger den adress kontot är registrerat på; av säkerhetsskäl avslöjar tjänsten inte om en adress finns eller inte. Är MFA aktiverat krävs engångskoden även efter återställningen — lösenordsbyte kringgår aldrig tvåfaktorn. Inloggad byter du lösenord under Inställningar → Konto. Välj ett långt, unikt lösenord och använd gärna lösenordshanterare.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/account']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-015', 'Byrå, plattform, behörigheter & säkerhet', 'magisk_lank', $faq$["Kan jag logga in utan lösenord?","Vad är inloggning med magisk länk?","E-postinloggning i Nordklart?"]$faq$::jsonb, $faq$Ja, som alternativ kan en engångslänk skickas till din e-post — klicka på den så loggas du in. MFA-kravet gäller fortfarande.$faq$, $faq$Utöver lösenord stödjer Nordklart inloggning via magisk länk: ange din e-postadress, få en engångslänk och klicka — du loggas in utan att skriva lösenord. Länken är kortlivad och kan bara användas en gång. Observera att tvåfaktorsautentiseringen inte påverkas: har du (eller plattformen) MFA-krav måste engångskoden anges även efter länkinloggning. Metoden är praktisk men gör e-postkontots säkerhet ännu viktigare — den som kontrollerar din e-post kan begära inloggningslänkar, så skydda e-posten med MFA också.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/account']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-016', 'Byrå, plattform, behörigheter & säkerhet', 'superadmin', $faq$["Vad är en superadmin?","Kan Nordklarts personal se min bokföring?","Plattformsadministratörens åtkomst?"]$faq$::jsonb, $faq$Superadmin är plattformens driftroll för support och administration. Åtkomst är begränsad, loggad och används bara vid supportärenden.$faq$, $faq$Superadmin är en plattformsroll för Nordklarts drift- och supportpersonal — den används för att administrera abonnemang, hjälpa till vid låsta konton och utreda tekniska fel. Rollen är skild från företagsrollerna: den ger inte tillgång till ditt dagliga arbetsflöde, och all åtkomst som sker loggas. Supporten tittar i företagsdata endast i samband med ärenden och i enlighet med personuppgiftsbiträdesavtalet. Du kan alltid se dina egna medlemmar och deras roller under Inställningar → Team — superadmins listas inte där eftersom de inte är medlemmar i ditt företag.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/team']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-017', 'Byrå, plattform, behörigheter & säkerhet', 'complimentary_full_access', $faq$["Vad är Complimentary Full Access?","Mitt konto har gratis full åtkomst — vad innebär det?","Kostnadsfri fullversion?"]$faq$::jsonb, $faq$Complimentary Full Access är en plattformstilldelad förmån som ger företaget alla funktioner utan abonnemangskostnad — funktionellt identiskt med full plan.$faq$, $faq$Vissa företag beviljas Complimentary Full Access — full funktionalitet utan kostnad, t.ex. under partnerskap, pilotprogram eller kampanjer. Tilldelningen görs av plattformen (superadmin) och syns i faktureringsvyn som aktiv förmån med eventuell giltighetstid. Funktionellt är det ingen skillnad mot betald fullplan: alla tillägg, automationsfunktioner och gränser gäller lika. Om förmånen löper ut övergår företaget till vald betald plan eller begränsat läge — du varnas i god tid innan. Frågor om förmånens omfattning eller förlängning hanteras via supporten.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/billing']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-018', 'Byrå, plattform, behörigheter & säkerhet', 'prenumerationsplaner', $faq$["Vilka abonnemang finns?","Vad ingår i min plan?","Var ser jag och ändrar min prenumeration?"]$faq$::jsonb, $faq$Under Inställningar → Fakturering ser du aktuell plan, vad som ingår och kan uppgradera — funktioner och gränser styrs av planen per företag.$faq$, $faq$Abonnemanget gäller per företag och styr vilka funktioner och volymgränser som är tillgängliga — t.ex. antal verifikationer, bankkopplingar, lönebesked och tillgång till tillägg. I faktureringsvyn ser du aktuell plan, förbrukning mot gränserna och kan byta plan; uppgraderingar gäller direkt. När en funktion kräver högre plan visas det tydligt i gränssnittet i stället för att funktionen tyst försvinner. Byråer kan ha särskilda villkor för kundstockar — kontakta supporten för byråavtal.$faq$, $faq$[]$faq$::jsonb, array['owner']::text[], array['/settings/billing']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-019', 'Byrå, plattform, behörigheter & säkerhet', 'rls_dataisolering', $faq$["Hur separeras data mellan olika företag?","Kan någon annan kund se min bokföring?","Vad är radnivåsäkerhet?"]$faq$::jsonb, $faq$All data är företagsavgränsad med radnivåsäkerhet i databasen — varje fråga filtreras på ditt medlemskap, det går inte att nå andras data.$faq$, $faq$Nordklart är multitenant med säkerheten i databasen, inte bara i applikationen: varje tabell med affärsdata har radnivåsäkerhet (Row Level Security) som kräver att den inloggade användaren är medlem i det företag raden tillhör. Även om applikationskod skulle innehålla ett fel kan databasen inte lämna ut ett annat företags rader. API-nycklar är på samma sätt låsta till sitt företag. Detta gäller allt — verifikationer, fakturor, dokument, löner. Byråmedarbetare når bara de kundföretag deras team är kopplat till, och kopplingen kan brytas av kunden när som helst.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], '{}'::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-020', 'Byrå, plattform, behörigheter & säkerhet', 'audit_logg', $faq$["Vad loggas i audit-loggen?","Kan jag se vem som gjort vad i bokföringen?","Aktivitetshistorik i företaget?"]$faq$::jsonb, $faq$Alla väsentliga händelser loggas: bokföringar, godkännanden, inställningsändringar, importer, automation och medlemsändringar — med användare och tidpunkt.$faq$, $faq$Audit-loggen registrerar vem som gjorde vad och när: skapade och bokförda verifikationer, godkända/avvisade väntande åtgärder, ändrade automationsinställningar, medlems- och rollförändringar, bank- och SIE-importer, låsta perioder samt automationens egna beslut (med konfidens och orsakskoder). Automatiska åtgärder loggas som utförda av systemet med hänvisning till regeln/beslutet som utlöste dem. Loggen är läsbar för företagets administratörer och kan inte redigeras — den är en central del av spårbarheten som god redovisningssed kräver.$faq$, $faq$["BFL 5 kap"]$faq$::jsonb, array['admin']::text[], array['/settings/company']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-021', 'Byrå, plattform, behörigheter & säkerhet', 'sparbarhet_andringar', $faq$["Hur ser jag vem som bokförde en verifikation?","Vem godkände den här väntande åtgärden?","Spårbarhet på enskilda poster?"]$faq$::jsonb, $faq$Varje verifikation och åtgärd bär sin historik: skapad av, godkänd av, tidpunkter och eventuella rättelser — synligt direkt på posten.$faq$, $faq$Spårbarheten finns på objektnivå: en verifikation visar vem som skapade och bokförde den (användare eller automation), när det skedde, vilket underlag som är kopplat och eventuella rättelseverifikationer med korsreferenser. Väntande åtgärder visar hela kedjan — skapad av automationen med orsakskoder, redigerad av vem, godkänd/avvisad av vem och när. Fakturor visar utskick, påminnelser och betalningsmatchningar. Den här nivån av historik gör revision och felsökning konkret: du behöver aldrig gissa varför en post ser ut som den gör.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/bookkeeping', '/pending']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-022', 'Byrå, plattform, behörigheter & säkerhet', 'sessioner_utloggning', $faq$["Hur loggar jag ut från alla enheter?","Hantera aktiva sessioner?","Jag glömde logga ut på en annan dator?"]$faq$::jsonb, $faq$Under Inställningar → Konto kan du logga ut. Byt lösenord om du misstänker att någon annan har åtkomst — det ogiltigförklarar sessionerna.$faq$, $faq$Utloggning görs via kontomenyn. Har du varit inloggad på en delad eller borttappad enhet: byt lösenord under kontoinställningarna — det ogiltigförklarar utestående sessioner så att gamla inloggningar inte längre fungerar. Sessioner har dessutom begränsad livslängd och kräver förnyad autentisering efter utgång; med MFA aktiverat krävs engångskod vid ny inloggning. Vid misstänkt intrång: byt lösenord omedelbart, kontrollera audit-loggen för oväntade åtgärder och kontakta supporten.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/account']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-023', 'Byrå, plattform, behörigheter & säkerhet', 'api_nyckel_sakerhet', $faq$["Hur förvarar jag API-nycklar säkert?","Min API-nyckel har läckt — vad gör jag?","Bästa praxis för API-nycklar?"]$faq$::jsonb, $faq$Nycklar visas bara en gång och lagras hashade. Vid läcka: återkalla nyckeln omedelbart i inställningarna och skapa en ny.$faq$, $faq$API-nycklar ger programmatisk åtkomst till företagets data — hantera dem som lösenord: lagra i hemlighetshanterare (aldrig i källkod eller delade dokument), använd separata nycklar per integration med minsta möjliga scopes, och rotera regelbundet. Nordklart lagrar bara en hash av nyckeln, så den kan aldrig läsas ut i efterhand. Vid misstänkt läcka: återkalla nyckeln direkt under Inställningar → API (åtkomsten upphör omedelbart), skapa en ny och granska audit-loggen för anrop du inte känner igen. Nyckelanvändning är rate-limitad vilket begränsar skadan vid missbruk.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/api']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-024', 'Byrå, plattform, behörigheter & säkerhet', 'dataexport_uppsagning', $faq$["Hur får jag ut min data om jag lämnar Nordklart?","Vad händer med bokföringen vid uppsägning?","Exportera allt innan kontot stängs?"]$faq$::jsonb, $faq$Exportera SIE-filer per räkenskapsår, dokumentarkivet och registren innan uppsägning — arkiveringsplikten på 7 år ligger kvar hos företaget.$faq$, $faq$Innan ett abonnemang avslutas ska du säkra räkenskapsinformationen: SIE4-export per räkenskapsår (hela bokföringen), dokumentexport (alla underlag som zip), rapporter som PDF och registerdata som CSV. Formaten är öppna och läsbara i andra system. Kom ihåg att arkiveringsansvaret enligt bokföringslagen — 7 år — är företagets, oavsett systembyte; exporten är din arkivkopia. Efter uppsägning behålls datat under en övergångsperiod innan radering enligt villkoren, så exportera i god tid. Vid byte till annat program tar du med SIE-filerna dit.$faq$, $faq$["BFL 7 kap 2 §"]$faq$::jsonb, array['owner']::text[], array['/import', '/settings/billing']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-025', 'Byrå, plattform, behörigheter & säkerhet', 'radera_foretag', $faq$["Hur raderar jag ett företag?","Ta bort ett bolag från mitt konto?","Kan jag ångra en företagsradering?"]$faq$::jsonb, $faq$Endast ägaren kan radera ett företag, efter bekräftelse. Exportera bokföring och dokument först — raderingen är permanent.$faq$, $faq$Företagsradering är en ägaråtgärd med dubbel bekräftelse: alla medlemskap, integrationer och data tas bort permanent. Innan du raderar: exportera SIE-filer, dokumentarkiv och register — arkiveringsplikten på 7 år gäller företaget även efter att systemet lämnats, och en radering utan export kan i praktiken innebära brott mot bokföringslagen. Radera bara bolag som aldrig haft verklig bokföring (testbolag) utan föregående export. Har bolaget upphört formellt (likvidation) ska slutredovisningen vara klar först. Raderingen loggas och kan inte ångras.$faq$, $faq$["BFL 7 kap 2 §"]$faq$::jsonb, array['owner']::text[], array['/settings/company']::text[], 'high', $faq$Radera aldrig ett företag med verklig bokföring utan komplett export — räkenskapsinformationen måste bevaras i 7 år enligt lag.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-026', 'Byrå, plattform, behörigheter & säkerhet', 'radera_konto_gdpr', $faq$["Hur raderar jag mitt användarkonto?","GDPR-radering av mina uppgifter?","Ta bort min profil helt?"]$faq$::jsonb, $faq$Kontoradering begärs under Inställningar → Konto. Personuppgifter raderas, men din identitet i bokföringshistorik bevaras enligt bokföringslagen.$faq$, $faq$Du kan begära radering av ditt användarkonto: profildata, inloggningsuppgifter och personliga inställningar tas bort enligt GDPR. Två viktiga begränsningar: 1) Är du ensam ägare till företag måste dessa först överlåtas eller raderas (efter dataexport). 2) Din identitet i räkenskapsinformation — vem som bokförde en verifikation, godkände en åtgärd — bevaras under arkiveringstiden, eftersom bokföringslagens krav på spårbarhet är en rättslig förpliktelse som går före raderingsrätten (GDPR art. 17.3 b). Kontakta supporten vid frågor om vad som raderas respektive bevaras.$faq$, $faq$["GDPR art. 17","BFL 7 kap"]$faq$::jsonb, '{}'::text[], array['/settings/account']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-027', 'Byrå, plattform, behörigheter & säkerhet', 'sakerhetskopiering_drift', $faq$["Säkerhetskopieras min data?","Vad händer om Nordklart får driftstörning?","Hur skyddas bokföringen mot dataförlust?"]$faq$::jsonb, $faq$Ja, driftmiljön har kontinuerlig säkerhetskopiering. För egen rådighet kan du dessutom aktivera molnbackup till Google Drive och exportera SIE löpande.$faq$, $faq$Plattformens databas säkerhetskopieras kontinuerligt med möjlighet till återställning, och dokumentlagringen är redundant. Det skyddar mot tekniska fel på driftsidan. Därutöver rekommenderas egen rådighet: aktivera molnbackup-tillägget som synkar SIE-exporter och dokument till företagets egen Google Drive enligt schema, och ta manuella SIE-exporter vid viktiga milstolpar (momsdeklaration, bokslut). Kombinationen — plattformsbackup plus egna exporter — ger både snabb återställning och oberoende arkivkopia enligt bokföringslagens anda.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/backup']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-028', 'Byrå, plattform, behörigheter & säkerhet', 'datalagring_eu', $faq$["Var lagras min data?","Lagras bokföringen inom EU?","Vilka underleverantörer behandlar mina uppgifter?"]$faq$::jsonb, $faq$Data lagras hos molnleverantörer inom EU/EES. Personuppgiftsbehandlingen regleras i biträdesavtalet med lista över underbiträden.$faq$, $faq$Nordklart lagrar företags- och bokföringsdata hos etablerade molnleverantörer i EU/EES-regioner, i linje med GDPR:s krav på tredjelandsöverföringar. Bokföringslagen kräver dessutom att räkenskapsinformation som lagras utomlands är åtkomlig från Sverige — vilket molntjänsten uppfyller. Personuppgiftsbiträdesavtalet (DPA) beskriver behandlingen och listar underbiträden (drift, e-postutskick, AI-tolkning m.m.); väsentliga förändringar aviseras. För specifika compliance-frågor — t.ex. inför en upphandling — kontakta supporten för aktuell dokumentation.$faq$, $faq$["GDPR kap 5","BFL 7 kap 3 a §"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-029', 'Byrå, plattform, behörigheter & säkerhet', 'bankid_verifiering', $faq$["Använder Nordklart BankID?","Kan jag verifiera min identitet med BankID?","BankID vid känsliga åtgärder?"]$faq$::jsonb, $faq$BankID används för identitetsverifiering i utvalda flöden, t.ex. vid kontoverifiering — bankkopplingen godkänns dock alltid med BankID hos din bank.$faq$, $faq$BankID förekommer på två ställen: 1) I Nordklarts egna flöden där stark identitetsverifiering behövs, t.ex. verifiering av kontoinnehavare. 2) Hos externa parter — när du kopplar banken via PSD2 godkänner du alltid med BankID i bankens egen miljö, och Skatteverkets e-tjänster kräver e-legitimation vid deklarationsinlämning. Nordklart ser aldrig dina BankID-uppgifter; signeringen sker hos respektive utfärdare. Den dagliga inloggningen i Nordklart sker med e-post/lösenord plus TOTP-engångskod.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/account', '/settings/banking']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-030', 'Byrå, plattform, behörigheter & säkerhet', 'automation_installningar_behorighet', $faq$["Vem får ändra automationsinställningarna?","Kan en vanlig medlem slå på auto-bokföring?","Behörighet för bankautomation?"]$faq$::jsonb, $faq$Endast ägare och administratörer kan ändra automationslägen, trösklar och beloppsgränser — ändringarna auditloggas.$faq$, $faq$Automationsinställningarna styr vad systemet får bokföra utan mänskligt godkännande och är därför skyddade: bara roller med admin-behörighet kan ändra läge (av/föreslå/auto säker/auto full), konfidenströsklar, beloppstak och per-områdes-tillstånd som automatisk leverantörsavräkning. Varje ändring loggas med gammal och ny inställning, vem och när — så en byrå eller revisor alltid kan se vilka regler som gällde vid en viss tidpunkt. Members och viewers ser inställningarna men kan inte ändra dem. Detta förhindrar att automation aktiveras av misstag eller utan ansvarigt beslut.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/banking']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-031', 'Byrå, plattform, behörigheter & säkerhet', 'byravy_vantande', $faq$["Kan byrån se väntande åtgärder för alla kunder?","Samlad vy över kundernas att-göra?","Byråöversikt över deadlines och granskningar?"]$faq$::jsonb, $faq$Ja, byråöversikten visar alla kundföretag med antal väntande åtgärder, obokförda transaktioner och kommande deadlines — klicka för att hoppa in i rätt bolag.$faq$, $faq$Byråvyn är byggd för att hantera många kunder effektivt: varje kundföretag visas med nyckelstatus — olösta väntande åtgärder, obokförda banktransaktioner, kommande moms- och AGI-deadlines och bokslutsstatus. Så kan byrån prioritera vilken kund som behöver åtgärd i dag i stället för att logga in i bolag efter bolag. Ett klick växlar till kundens företag med full kontext. Statusen respekterar behörigheterna: bara företag kopplade till ditt team visas, och siffrorna beräknas med samma dataisolering som allt annat.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/agency', '/pending']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-032', 'Byrå, plattform, behörigheter & säkerhet', 'notisinstallningar', $faq$["Hur ändrar jag mina notisinställningar?","Jag får för många mejl från Nordklart?","Stänga av vissa notiser?"]$faq$::jsonb, $faq$Under Inställningar → Konto väljer du vilka händelser som ska ge notiser och via vilken kanal — e-post och/eller push.$faq$, $faq$Notiserna är konfigurerbara per användare och händelsetyp: betald faktura, ny väntande åtgärd, misslyckad banksynk, samtycke som snart löper ut, kommande deadlines (moms, AGI, årsredovisning) med mera. Välj kanal per typ — e-post och, om push-tillägget är aktiverat, webbpush till din enhet. Byråmedarbetare kan styra notiser per kundföretag för att undvika brus. Viktiga säkerhetsnotiser (t.ex. lösenordsbyte) kan inte stängas av. Rimlig grundnivå: deadlines och fel på, informationsnotiser efter smak.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/account']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-033', 'Byrå, plattform, behörigheter & säkerhet', 'epost_vs_push', $faq$["Finns pushnotiser i Nordklart?","Skillnad mellan e-post och pushnotiser?","Aktivera push i webbläsaren?"]$faq$::jsonb, $faq$E-postnotiser är standard. Med push-tillägget aktiverat kan du dessutom få direktnotiser i webbläsaren för tidskritiska händelser.$faq$, $faq$E-post är grundkanalen för notiser — den når dig alltid och fungerar som kvitto. Push-tillägget lägger till webbpush: direktnotiser till webbläsare/enhet som passar tidskritiska händelser som misslyckad banksynk eller nya väntande åtgärder som blockerar arbetet. Aktivera tillägget, godkänn notisbehörigheten i webbläsaren och välj händelsetyper i notisinställningarna. Push kräver att webbläsaren stödjer det och att behörigheten inte blockerats; e-post fortsätter fungera parallellt. Prenumerationen är per enhet — aktivera på de enheter du arbetar från.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/account']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-034', 'Byrå, plattform, behörigheter & säkerhet', 'behorighet_bokslut', $faq$["Vem får slutföra bokslutet?","Kan en member låsa räkenskapsåret?","Behörighet för årsavslut och periodlåsning?"]$faq$::jsonb, $faq$Att låsa perioder och slutföra bokslut kräver admin- eller ägarroll. Att låsa upp ett låst år är begränsat till ägare och auditloggas alltid.$faq$, $faq$Bokslutets känsligaste steg är behörighetsstyrda: löpande bokslutsarbete (avstämningar, bokslutstransaktioner) kan members utföra, men att låsa momsperioder, slutföra året och därmed låsa räkenskapsåret kräver admin eller ägare. Att i undantagsfall låsa upp en låst period är förbehållet ägaren och loggas med motivering. För byråkunder betyder det i praktiken: byråns medarbetare (via teamets roll) gör jobbet, och låsningen görs av den som har det formella ansvaret. Rollkraven skyddar mot att deklarerade underlag ändras av misstag.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/year-end', '/settings/team']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('byra-035', 'Byrå, plattform, behörigheter & säkerhet', 'rapportera_sakerhetsproblem', $faq$["Hur rapporterar jag ett säkerhetsproblem?","Jag har hittat en sårbarhet — vart vänder jag mig?","Ansvarsfull rapportering av säkerhetsbrister?"]$faq$::jsonb, $faq$Rapportera säkerhetsproblem direkt till supporten med märkning 'säkerhet' — beskriv fyndet men utnyttja det inte, och dela inte detaljer offentligt.$faq$, $faq$Misstänker du en sårbarhet eller ett dataläckage: kontakta Nordklarts support omgående och märk ärendet som säkerhetsrelaterat. Beskriv vad du observerat, steg för att återskapa och vilken data som kan beröras — men försök inte utnyttja bristen vidare eller komma åt andras data, och publicera inte detaljer innan problemet är åtgärdat (ansvarsfull rapportering). Gäller det ditt eget konto — misstänkt intrång, okända åtgärder i audit-loggen — byt lösenord direkt, återkalla API-nycklar och kontakta supporten parallellt. Säkerhetsärenden prioriteras.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/help']::text[], 'medium', $faq$Vid pågående intrång eller misstänkt läcka av personuppgifter: agera direkt — personuppgiftsincidenter kan behöva anmälas till IMY inom 72 timmar.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-001', 'Fakturering, kundreskontra & Bankgiro', 'skapa_faktura', $faq$["Hur skapar jag en faktura?","Ny kundfaktura?","Fakturera en kund?"]$faq$::jsonb, $faq$Fakturor → Ny faktura: välj kund, lägg rader (artiklar eller fritext), granska moms och skicka.$faq$, $faq$Under Fakturor skapar du en ny faktura: välj kund (momsbehandlingen följer kundtypen), lägg till rader med belopp och momssats, sätt betalvillkor. Fakturan sparas som utkast tills du skickar eller markerar den som skickad — då får den sitt slutliga fakturanummer, bokförs (fakturametoden) och OCR-nummer genereras.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-002', 'Fakturering, kundreskontra & Bankgiro', 'fakturanummer', $faq$["Hur sätts fakturanumren?","Kan jag välja fakturanummerserie?","Fakturanummer i följd?"]$faq$::jsonb, $faq$Nummer tilldelas löpande utan luckor när fakturan färdigställs; prefix och startnummer ställs in under Fakturering.$faq$, $faq$Fakturanummer ska vara obrutet löpande enligt god fakturased. Nordklart tilldelar numret först när fakturan färdigställs/skickas (utkast saknar nummer), vilket förhindrar luckor från raderade utkast. Prefix (t.ex. "F-") och nästa nummer ställs in under Inställningar → Fakturering.$faq$, $faq$["ML 17 kap 24 §"]$faq$::jsonb, '{}'::text[], array['/settings/invoicing']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-003', 'Fakturering, kundreskontra & Bankgiro', 'obligatoriska_uppgifter', $faq$["Vad måste stå på en faktura?","Fakturakrav enligt momslagen?","Är min faktura komplett?"]$faq$::jsonb, $faq$Momslagen kräver bl.a. datum, löpnummer, säljarens/köparens uppgifter, VAT-nummer, beskrivning, underlag och moms per sats.$faq$, $faq$En fullständig faktura innehåller: fakturadatum, löpnummer, säljarens namn/adress/momsregistreringsnummer, köparens namn/adress (och VAT-nummer vid omvänd moms), varans/tjänstens omfattning, leveransdatum, underlag per momssats, momssats och momsbelopp, samt F-skatteuppgift. Nordklarts fakturamall uppfyller kraven automatiskt utifrån dina företagsinställningar.$faq$, $faq$["ML 17 kap 24 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-004', 'Fakturering, kundreskontra & Bankgiro', 'skicka_faktura', $faq$["Hur skickar jag fakturan till kunden?","E-posta faktura som PDF?","Fakturautskick?"]$faq$::jsonb, $faq$Skicka via e-post direkt från systemet (PDF bifogas), eller ladda ner och skicka själv — statusen blir "skickad".$faq$, $faq$Knappen Skicka mejlar fakturan som PDF till kundens e-post med spårning; alternativt laddar du ner PDF:en och markerar fakturan som skickad. I båda fallen bokförs fakturan (Dr 1510 / Kr 30xx + moms under fakturametoden) och hamnar i kundreskontran. E-faktura via Peppol finns för kunder som kräver det.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-005', 'Fakturering, kundreskontra & Bankgiro', 'ocr_nummer', $faq$["Vad är OCR-numret på fakturan?","Hur genereras OCR?","Kan kunden betala med OCR?"]$faq$::jsonb, $faq$OCR-numret genereras automatiskt per faktura (Luhn-kontrollsiffra) och gör att betalningen matchas exakt.$faq$, $faq$Varje faktura får ett OCR-nummer baserat på fakturanumret med kontrollsiffra enligt Luhn/mod-10. När kunden betalar via bankgiro med OCR:et matchar Nordklart betalningen mot rätt faktura automatiskt med högsta träffsäkerhet. OCR-raden visas på fakturan när bankgiro är aktiverat under Inställningar → Fakturering.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices', '/settings/invoicing']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-006', 'Fakturering, kundreskontra & Bankgiro', 'bankgiro_visas', $faq$["Hur får jag bankgironummer på fakturan?","Fakturan saknar bankgiro?","Visa betaluppgifter?"]$faq$::jsonb, $faq$Ange bankgiro under Inställningar → Företag/Fakturering — numret skrivs då ut med OCR på fakturorna.$faq$, $faq$Bankgironumret hämtas från företagsinställningarna och visas i fakturans betalfält tillsammans med OCR-nummer. Saknar företaget bankgiro visar Nordklart bankkonto/IBAN i stället och du kan ansöka om bankgiro hos din bank — ansökan tar normalt några bankdagar och kopplas till ditt företagskonto.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/company', '/settings/invoicing']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-007', 'Fakturering, kundreskontra & Bankgiro', 'betalvillkor_forfallodag', $faq$["Hur sätter jag betalvillkor?","30 dagars betaltid standard?","Förfallodatum på fakturan?"]$faq$::jsonb, $faq$Standardbetalvillkor sätts per företag och kund; förfallodatum beräknas automatiskt från fakturadatumet.$faq$, $faq$Betalvillkoren (t.ex. 30 dagar) sätts som standard under Inställningar → Fakturering och kan överridas per kund och per faktura. Mot konsument gäller normalt 30 dagar; mellan företag är betaltiden avtalsfrihet men över 30 dagar kräver uttrycklig överenskommelse. Förfallodagen styr påminnelser och dröjsmålsränta.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/invoicing', '/customers']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-008', 'Fakturering, kundreskontra & Bankgiro', 'fakturan_bokfors', $faq$["Bokförs fakturan automatiskt när jag skickar den?","Vilket verifikat skapas vid fakturering?","Fakturametoden bokföring?"]$faq$::jsonb, $faq$Ja — vid skick bokförs Dr 1510 / Kr 30xx + Kr 26xx automatiskt (fakturametoden); kontantmetoden bokför vid betalning.$faq$, $faq$Med fakturametoden skapas verifikationen när fakturan skickas: kundfordran debiteras (1510), intäkten krediteras per momssats (3001/3002/3003 eller artikelns konto) och utgående moms (2611/2621/2631). Mixade momssatser delas per rad. Med kontantmetoden bokförs allt först vid betalningen. Verifikationen länkas till fakturan.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-009', 'Fakturering, kundreskontra & Bankgiro', 'betalning_registrera', $faq$["Hur registrerar jag att fakturan är betald?","Markera faktura som betald manuellt?","Kunden betalade kontant/Swish?"]$faq$::jsonb, $faq$Bankmatchade betalningar sköts automatiskt; manuella registreras via "Markera som betald" med datum och belopp.$faq$, $faq$Kommer betalningen via banken matchas den mot fakturan (OCR/belopp) och du godkänner. För betalningar utanför banken använder du "Markera som betald": ange betaldatum och ev. delbelopp — verifikationen (Dr 19xx / Kr 1510) skapas, betalningsraden loggas i reskontran och status uppdateras. Dubblettskydd varnar om en liknande obehandlad banktransaktion redan finns.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-010', 'Fakturering, kundreskontra & Bankgiro', 'delbetalning', $faq$["Kunden delbetalar — hur registrerar jag?","Faktura med restbelopp?","Status delbetald?"]$faq$::jsonb, $faq$Registrera delbeloppet — fakturan får status delbetald och restbeloppet ligger kvar i reskontran.$faq$, $faq$Vid delbetalning anger du beloppet (via bankmatchning eller manuellt); Nordklart bokför delbeloppet mot 1510, uppdaterar betalt/restbelopp och sätter status "delbetald". Påminnelser fortsätter bevaka restbeloppet. Flera delbetalningar summeras tills fakturan är slutbetald.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-011', 'Fakturering, kundreskontra & Bankgiro', 'kreditfaktura', $faq$["Hur gör jag en kreditfaktura?","Kreditera en felaktig faktura?","Makulera skickad faktura?"]$faq$::jsonb, $faq$Använd Kreditera på fakturan — en spegelvänd kreditfaktura skapas, bokförs och kopplas till originalet.$faq$, $faq$En skickad faktura kan inte raderas — den krediteras. Åtgärden Kreditera skapar en kreditfaktura (KR-prefix) med negativa belopp och samma moms som originalet, bokför reverseringen och sätter originalet till status krediterad. Skicka kreditfakturan till kunden. Delkreditering görs genom att redigera kreditfakturans rader innan den skickas.$faq$, $faq$["ML 17 kap 22 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-012', 'Fakturering, kundreskontra & Bankgiro', 'paminnelser', $faq$["Skickas betalningspåminnelser automatiskt?","Hur fungerar påminnelseflödet?","Påminnelseavgift 60 kr?"]$faq$::jsonb, $faq$Ja — automatiska påminnelser på nivå 1/2/3 (15/30/45 dagar), med lagstadgad avgift 60 kr och dröjsmålsränta.$faq$, $faq$Påminnelsemotorn kör dagligen: förfallna fakturor får påminnelse via e-post vid 15, 30 och 45 dagars försening (varje nivå max en gång). Påminnelseavgiften (60 kr enligt lag) bokförs automatiskt och dröjsmålsränta enligt räntelagen (referensränta + 8 %) beräknas. Stäng av per företag under Inställningar → Fakturering eller undanta enskilda kunder. Bestridna/avskrivna fakturor får aldrig påminnelser.$faq$, $faq$["Lag (1981:739) om ersättning för inkassokostnader","Räntelagen 6 §"]$faq$::jsonb, '{}'::text[], array['/settings/invoicing']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-013', 'Fakturering, kundreskontra & Bankgiro', 'drojsmalsranta', $faq$["Hur mycket dröjsmålsränta får jag ta?","Räntelagen 8 procent?","Fakturera ränta på sen betalning?"]$faq$::jsonb, $faq$Utan avtal: referensräntan + 8 procentenheter från förfallodagen — beräknas automatiskt i påminnelserna.$faq$, $faq$Dröjsmålsräntan enligt räntelagen är Riksbankens referensränta + 8 procentenheter och får tas ut från förfallodagen (mot konsument tidigast 30 dagar efter faktura). Avtalad högre ränta gäller mellan företag. Nordklart beräknar räntan i påminnelseflödet; du kan också sätta en egen räntesats i inställningarna.$faq$, $faq$["Räntelagen 6 §"]$faq$::jsonb, '{}'::text[], array['/settings/invoicing']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-014', 'Fakturering, kundreskontra & Bankgiro', 'kund_bestrider', $faq$["Kunden bestrider fakturan — vad gör jag i systemet?","Markera faktura som tvistig?","Stoppa påminnelser vid tvist?"]$faq$::jsonb, $faq$Markera fakturan som bestriden — påminnelser och automatisk matchning stoppas tills tvisten är löst.$faq$, $faq$Via fakturans åtgärd Bestriden fryses den: inga fler påminnelser, ingen automatisk avräkning, och bokslutsflaggan visar tvisten. När ni är överens återställer du fakturan (status återgår till skickad/förfallen) eller krediterar/skriver av den. Anteckna gärna tvistens grund i fakturans notering — det följer med i granskningsspåret.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-015', 'Fakturering, kundreskontra & Bankgiro', 'inkasso', $faq$["Hur skickar jag en faktura till inkasso?","Inkassokrav efter påminnelse?","Markera för inkasso?"]$faq$::jsonb, $faq$Markera fakturan som redo för inkasso och skicka underlaget till ditt inkassobolag — status spärrar vidare påminnelser.$faq$, $faq$Efter fruktlösa påminnelser markerar du fakturan "till inkasso" — Nordklart stoppar egna påminnelser och flaggar posten i reskontran. Själva inkassokravet skickas av dig eller ett inkassobolag (kräver inkassotillstånd att driva åt andra). Exportera fakturan, påminnelsehistoriken och räntespecifikationen som underlag.$faq$, $faq$["Inkassolagen"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-016', 'Fakturering, kundreskontra & Bankgiro', 'rot_rut_faktura', $faq$["Hur fakturerar jag med ROT-avdrag?","RUT-faktura till privatkund?","Fakturamodellen i systemet?"]$faq$::jsonb, $faq$Aktivera ROT/RUT på fakturan: ange arbetskostnad och kundens personnummer — avdraget beräknas och dras på fakturan.$faq$, $faq$På fakturor till privatpersoner aktiverar du ROT (30 % av arbetskostnad) eller RUT (50 %): ange personnummer och fastighetsbeteckning/BRF vid ROT, markera vilka rader som är arbete. Fakturan visar fullt belopp, avdraget och kundens att-betala. Efter kundens betalning begär du utbetalning från Skatteverket; fordran ligger på 1513 tills den betalas ut. Momsen beräknas alltid på hela beloppet.$faq$, $faq$["Skatteverket: fakturamodellen"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-017', 'Fakturering, kundreskontra & Bankgiro', 'aterkommande_fakturor', $faq$["Kan jag schemalägga återkommande fakturor?","Månadsfakturering automatiskt?","Abonnemangsfakturor?"]$faq$::jsonb, $faq$Ja — skapa ett återkommande schema så genereras fakturan automatiskt varje månad på vald dag.$faq$, $faq$Under Fakturor → Återkommande skapar du scheman: kund, rader, dag i månaden, betalvillkor och om fakturan ska auto-skickas eller läggas som utkast. Ett nattligt jobb spawnar fakturorna idempotent (aldrig dubbletter, även om jobbet körs om), pausade scheman hoppar över, och valutafakturor får kursen per fakturadatum.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices/recurring']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-018', 'Fakturering, kundreskontra & Bankgiro', 'proforma_offert', $faq$["Kan jag skicka offert eller proforma?","Skillnad proforma och faktura?","Konvertera offert till faktura?"]$faq$::jsonb, $faq$Ja — skapa proforma/offert som inte bokförs, och konvertera till skarp faktura vid accept.$faq$, $faq$Proformadokument ser ut som fakturor men saknar fakturanummer i den skarpa serien, bokförs inte och utlöser ingen moms. Vid accept konverterar du till riktig faktura med ett klick (raderna följer med, fakturan får nummer och bokförs). Proformor kan aldrig matchas mot betalningar — betalningen matchar den konverterade fakturan.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-019', 'Fakturering, kundreskontra & Bankgiro', 'kundreskontra', $faq$["Var ser jag alla obetalda fakturor?","Kundreskontra-rapport?","Åldersanalys kundfordringar?"]$faq$::jsonb, $faq$Rapporter → Kundreskontra visar öppna fakturor per kund med förfallostruktur — ska stämma mot 1510.$faq$, $faq$Kundreskontran listar alla öppna fakturor (skickade, förfallna, delbetalda) per kund med belopp och dagar sena, samt åldersanalys (0–30, 31–60, 61–90, 90+). Summan ska alltid stämma mot huvudbokens 1510 — bokslutet kontrollerar det. Kundsaldon (tillgodo från överbetalningar) syns också här.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-020', 'Fakturering, kundreskontra & Bankgiro', 'faktura_engelska', $faq$["Kan jag skicka fakturan på engelska?","Engelsk faktura till utländsk kund?","Fakturaspråk per kund?"]$faq$::jsonb, $faq$Ja — sätt språk på kundkortet så renderas fakturan på engelska med samma lagkrav uppfyllda.$faq$, $faq$Kundens språk (svenska/engelska) väljs på kundkortet och styr fakturans etiketter och e-postmall. Belopp, moms och obligatoriska uppgifter är desamma. Valutan väljs separat per faktura — en engelsk faktura kan vara i SEK och vice versa.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/customers', '/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-021', 'Fakturering, kundreskontra & Bankgiro', 'valutafaktura', $faq$["Hur fakturerar jag i euro?","Faktura i USD till amerikansk kund?","Valutakurs på fakturan?"]$faq$::jsonb, $faq$Välj valuta på fakturan — kursen hämtas för fakturadatumet, momsen visas även i SEK och kursdiffar bokförs vid betalning.$faq$, $faq$Sätt fakturans valuta (EUR/USD/…); Riksbankens kurs för fakturadatumet hämtas automatiskt och SEK-beloppen bokförs. Momsbeloppet skrivs ut i SEK enligt momslagen. När betalningen kommer räknas kursdifferensen mot betalningsdagens kurs och bokförs på 3960/7960 automatiskt.$faq$, $faq$["ML 17 kap 30 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-022', 'Fakturering, kundreskontra & Bankgiro', 'efaktura_peppol', $faq$["Kan jag skicka e-faktura via Peppol?","Kommunen kräver e-faktura?","Peppol BIS Billing?"]$faq$::jsonb, $faq$Ja — offentliga kunder ska ha e-faktura (Peppol BIS Billing 3.0); aktivera e-faktura på kundkortet.$faq$, $faq$Sedan 2019 måste leverantörer till offentlig sektor skicka e-faktura (lag 2018:1277). Nordklart skickar Peppol BIS Billing 3.0 till kundens Peppol-adress (elektronisk adress anges på kundkortet). Fakturans innehållskrav (F-skatt, bankgiro enligt svenska CIUS-regler) valideras innan avsändning.$faq$, $faq$["Lag (2018:1277) om elektroniska fakturor"]$faq$::jsonb, '{}'::text[], array['/customers', '/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-023', 'Fakturering, kundreskontra & Bankgiro', 'kundsaldo_anvanda', $faq$["Kunden har tillgodo — hur använder jag det på nästa faktura?","Kvitta kundsaldo mot faktura?","Återbetala överbetalning?"]$faq$::jsonb, $faq$Kundsaldot kan kvittas mot nästa faktura eller återbetalas — båda bokförs spårbart från kundkortet.$faq$, $faq$Under kundens sida ser du tillgodosaldon (från överbetalningar eller krediteringar). Vid kvittning avräknas saldot mot en öppen faktura (verifikat: Dr kundsaldoskuld / Kr 1510). Vid återbetalning bokförs utbetalningen mot saldot och matchas mot bankens utgående transaktion. Saldona ingår i reskontrarapporten.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/customers', '/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-024', 'Fakturering, kundreskontra & Bankgiro', 'skriv_av_faktura', $faq$["Hur skriver jag av en faktura som aldrig betalas?","Avskrivning kundförlust i fakturaflödet?","Skriv av-knappen?"]$faq$::jsonb, $faq$Fakturans åtgärd "Skriv av" bokför konstaterad kundförlust (6351 + momsåtertag) och stänger posten — motivering krävs.$faq$, $faq$När förlusten är konstaterad använder du Skriv av på fakturan: ange motivering (konkurs, misslyckad indrivning). Nordklart bokför Dr 6351 (netto), Dr 26xx (återförd moms, proportionellt på restbeloppet) / Kr 1510, sätter status avskriven och tar bort posten ur den aktiva reskontran. Allt loggas; betalar kunden ändå senare bokförs det som återvunnen fordran.$faq$, $faq$["ML 7 kap 44 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-025', 'Fakturering, kundreskontra & Bankgiro', 'fakturadatum_bakat', $faq$["Kan jag datera fakturan bakåt?","Fakturadatum i förra månaden?","Antedatera faktura?"]$faq$::jsonb, $faq$Fakturadatum ska ligga nära leveransen — bakåtdatering till stängd momsperiod blockeras.$faq$, $faq$Fakturadatum kan sättas fritt inom öppen period men ska enligt god sed ligga i nära anslutning till leveransen (momslagen kräver fakturering senast 15:e i månaden efter leverans vid EU-handel). Datering in i en låst/deklarerad period stoppas av periodlåset — då får fakturan dagens datum och leveransdatumfältet visar den faktiska perioden.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-026', 'Fakturering, kundreskontra & Bankgiro', 'paslag_avgift_smabelopp', $faq$["Kan jag lägga faktureringsavgift?","Ta betalt för pappersfaktura?","Administrativ avgift på faktura?"]$faq$::jsonb, $faq$Faktureringsavgift kräver avtal med kunden — mot konsument måste den vara överenskommen i förväg.$faq$, $faq$En faktureringsavgift får bara tas ut om den är avtalad (i offert, avtal eller villkor kunden accepterat). Lägg den som egen rad med 25 % moms (den delar leveransens momssats vid enhetlig leverans). Mot konsument utan avtal är avgiften inte tillåten.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-027', 'Fakturering, kundreskontra & Bankgiro', 'omvand_moms_faktura_kund', $faq$["Kunden är byggbolag — hur fakturerar jag utan moms?","Faktura med omvänd byggmoms?","VAT-nummer på byggfaktura?"]$faq$::jsonb, $faq$Välj momsbehandlingen omvänd byggmoms på fakturan — momsen utelämnas och obligatorisk text + kundens VAT-nummer läggs till.$faq$, $faq$Sätt kundens VAT-nummer på kundkortet och välj omvänd skattskyldighet för bygg på fakturan. Nordklart fakturerar då utan moms, skriver "Omvänd betalningsskyldighet" och redovisar försäljningen i ruta 41. Gäller när både du och kunden är byggverksamma och tjänsten är en byggtjänst.$faq$, $faq$["ML 16 kap 13 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-028', 'Fakturering, kundreskontra & Bankgiro', 'delfakturera', $faq$["Kan jag delfakturera ett projekt?","A conto-fakturering?","Slutfaktura efter delfakturor?"]$faq$::jsonb, $faq$Ja — skapa flera fakturor mot samma projekt (a conto + slutfaktura); momsen redovisas per faktura.$faq$, $faq$Delfakturering görs som separata fakturor (t.ex. "A conto 1 — projekt X"). Varje faktura bokförs och momsas för sig när den ställs ut/betalas. På slutfakturan redovisar du totalt pris minus tidigare a conto-rader så kunden ser helheten. För byggtjänster med omvänd moms gäller särskilda regler för förskott.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-029', 'Fakturering, kundreskontra & Bankgiro', 'kund_utan_orgnr', $faq$["Måste kunden ha organisationsnummer?","Fakturera privatperson?","Kundtyper i systemet?"]$faq$::jsonb, $faq$Nej — kundtypen styr: svenska företag (orgnr), privatpersoner, EU-företag (VAT-nummer) och utländska kunder hanteras olika.$faq$, $faq$Kundkortets typ styr momslogiken: svenskt företag (orgnr, 25/12/6 %), privatperson (personnummer behövs bara för ROT/RUT), EU-företag (VAT-nummer → omvänd moms efter VIES-validering), företag utanför EU (export). Fältkraven anpassas automatiskt; integritetskänsliga fält maskeras i API-svar.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/customers']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-030', 'Fakturering, kundreskontra & Bankgiro', 'faktura_pdf_arkiv', $faq$["Var hittar jag skickade fakturors PDF?","Arkiveras fakturakopior?","Ladda ner gammal faktura?"]$faq$::jsonb, $faq$Varje skickad faktura arkiverar sin PDF i dokumentarkivet — exakt den version kunden fick.$faq$, $faq$Vid skick/finalisering arkiveras fakturans PDF i dokumentarkivet kopplad till fakturan och verifikationen (BFL 7 kap). Du kan alltid ladda ner originalversionen — även om mallen eller företagsuppgifterna ändrats senare. Kreditfakturor arkiveras på samma sätt.$faq$, $faq$["BFL 7 kap"]$faq$::jsonb, '{}'::text[], array['/invoices', '/documents']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-031', 'Fakturering, kundreskontra & Bankgiro', 'andra_skickad_faktura', $faq$["Kan jag ändra en skickad faktura?","Fel pris på skickad faktura?","Redigera efter utskick?"]$faq$::jsonb, $faq$Nej — skickade fakturor är låsta. Kreditera och ställ ut en ny faktura med rätt uppgifter.$faq$, $faq$En skickad faktura är bokförd och juridiskt utställd — den kan inte redigeras. Vid fel: kreditera hela fakturan (automatiskt spegelverifikat) och skapa en ny korrekt faktura. Vid mindre fel som inte påverkar belopp/moms (t.ex. referens) kan en rättad kopia skickas med samma nummer utanför systemet, men beloppsfel kräver alltid kreditering.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-032', 'Fakturering, kundreskontra & Bankgiro', 'betalningsvillkor_konsument', $faq$["Vilka regler gäller för fakturor till konsument?","Konsumentfaktura krav?","Får jag ta förseningsavgift av privatkund?"]$faq$::jsonb, $faq$Konsumenter har rätt till 30 dagars betaltid från fakturan; påminnelseavgift 60 kr kräver avtal eller lagstöd.$faq$, $faq$Mot konsument gäller: dröjsmålsränta tidigast 30 dagar efter faktura med räntevillkor angivna, påminnelseavgift 60 kr (lagreglerad), och tydliga uppgifter om vad som köpts. ROT/RUT-avdrag och delbetalningsvillkor ska framgå. Nordklarts konsumentfakturor följer kraven när kundtypen är privatperson.$faq$, $faq$["Räntelagen","Lag (1981:739)"]$faq$::jsonb, '{}'::text[], array['/customers']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-033', 'Fakturering, kundreskontra & Bankgiro', 'fakturakopia_kund', $faq$["Kunden vill ha fakturakopia — hur skickar jag?","Skicka om en faktura?","Resend invoice?"]$faq$::jsonb, $faq$Öppna fakturan och välj Skicka igen — kopian markeras som kopia och original-PDF:en används.$faq$, $faq$Via fakturans meny skickar du om e-posten med den arkiverade PDF:en (märkt kopia). Historiken visar alla utskick med tidpunkt och mottagare. Att skicka om påverkar inte bokföring eller påminnelseschema.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-034', 'Fakturering, kundreskontra & Bankgiro', 'artikelregister', $faq$["Hur använder jag artiklar på fakturan?","Artikelpriser och konton?","Snabbrader från artikelregistret?"]$faq$::jsonb, $faq$Artiklar ger färdiga rader med pris, moms och intäktskonto — hanteras under Artiklar.$faq$, $faq$Artikelregistret innehåller namn, pris, enhet, momssats och eventuellt eget intäktskonto per artikel (t.ex. 3041 tjänster). På fakturan söker du fram artikeln så fylls raden i; priset kan justeras per faktura. Artikelstatistik visar försäljning per artikel.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/commerce/articles', '/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-035', 'Fakturering, kundreskontra & Bankgiro', 'se_fakturans_verifikat', $faq$["Var ser jag fakturans bokföring?","Hoppa från faktura till verifikation?","Vilket verifikat hör till fakturan?"]$faq$::jsonb, $faq$Fakturan länkar direkt till sina verifikat: utställande, betalningar, kreditering och eventuell avskrivning.$faq$, $faq$På fakturans sida finns länkar till alla dess verifikationer — bokföringen vid skick, varje betalningsverifikat, kreditfakturans reversering eller avskrivningens kundförlustpost. Omvänt visar verifikationen sin källa (fakturan). Kedjan gör revisionen spårbar i båda riktningarna.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices', '/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-036', 'Fakturering, kundreskontra & Bankgiro', 'paminnelse_undanta_kund', $faq$["Kan jag stänga av påminnelser för en viss kund?","Ingen påminnelse till storkund?","Undanta faktura från påminnelser?"]$faq$::jsonb, $faq$Ja — stäng av påminnelser per kund på kundkortet, eller pausa en enskild faktura.$faq$, $faq$Utöver företagets på/av-inställning kan du undanta enskilda kunder (kundkortets inställning) eller pausa en specifik faktura från påminnelseflödet. Bestridna, krediterade och avskrivna fakturor undantas alltid automatiskt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/customers', '/settings/invoicing']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-037', 'Fakturering, kundreskontra & Bankgiro', 'swish_pa_faktura', $faq$["Kan kunden betala fakturan med Swish?","Swishnummer på fakturan?","QR-kod för betalning?"]$faq$::jsonb, $faq$Ja — ange Swish-nummer i inställningarna så visas det som betalalternativ på fakturan.$faq$, $faq$Företagets Swish-nummer (Swish Företag/Handel) anges under Inställningar → Företag och visas på fakturan. Swish-betalningar kommer in via banksynken och matchas på belopp och avsändare — be kunden ange fakturanumret som meddelande för säkrast matchning.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/company']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-038', 'Fakturering, kundreskontra & Bankgiro', 'sen_fakturering', $faq$["Hur länge kan jag vänta med att fakturera?","Fakturera jobb från förra året?","Preskription av faktura?"]$faq$::jsonb, $faq$Fakturera snarast — momsen kan behöva redovisas per leveransperioden, och fordran preskriberas efter 10 år (3 år mot konsument).$faq$, $faq$Civilrättsligt preskriberas fordringar efter 10 år (3 år mot konsument) — men vänta inte: momsredovisningen knyts till leveransen och intäkten hör till rätt räkenskapsår oavsett faktureringsdag (upplupen intäkt i bokslutet). Fakturera senast månaden efter leverans som god rutin.$faq$, $faq$["Preskriptionslagen","ML 7 kap"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-039', 'Fakturering, kundreskontra & Bankgiro', 'api_fakturor', $faq$["Kan jag skapa fakturor via API?","Fakturera från mitt eget system?","API invoice endpoints?"]$faq$::jsonb, $faq$Ja — komplett fakturalivscykel via API: skapa, skicka, markera betald, kreditera, PDF — med idempotensskydd.$faq$, $faq$API:et (scope invoices:write) täcker hela flödet: POST skapar (dry-run stöds), :send skickar med PDF, :mark-paid registrerar betalning (delbetalningar och kundsaldo hanteras), :credit krediterar, GET :pdf hämtar dokumentet. Alla skrivningar kräver Idempotency-Key. Webhooks (invoice.paid m.fl.) notifierar ditt system.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/api']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-040', 'Fakturering, kundreskontra & Bankgiro', 'flera_paminnelser_skickade', $faq$["Varför fick kunden flera påminnelser samma dag?","Dubbla påminnelser?","Påminnelse trots betalning?"]$faq$::jsonb, $faq$Varje nivå skickas max en gång — dubbletter förhindras; betalningar samma dag stoppas av en sista status-koll.$faq$, $faq$Påminnelsemotorn skickar varje nivå (1/2/3) högst en gång per faktura och kontrollerar fakturans status omedelbart före utskick, så en betalning som matchats hinner stoppa påminnelsen. Har kunden ändå fått en påminnelse efter betalning beror det oftast på att betalningen ännu inte matchats — godkänn matchningen så uppdateras reskontran.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-041', 'Fakturering, kundreskontra & Bankgiro', 'fakturaavgift_klarna_stripe', $faq$["Hur bokför jag Stripe/Klarna-utbetalningar mot fakturor?","Betalväxel netto-utbetalning?","PSP-avgifter och fakturamatchning?"]$faq$::jsonb, $faq$Bokför brutto: matcha fakturorna mot full betalning och bokför växelns avgift separat som kostnad (6570).$faq$, $faq$Betalväxlar betalar ut netto (försäljning minus avgifter) i klumpar. Kvittningsförbudet kräver bruttoredovisning: intäkterna/fakturorna avräknas till fullt belopp och avgifterna bokförs som kostnad (Dr 6570) — inte bara nettoinsättningen. Använd växelns utbetalningsrapport som underlag och stäm av mot en balanspost (t.ex. 1580 fordran betalväxel).$faq$, $faq$["ÅRL 2 kap 4 §"]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-042', 'Fakturering, kundreskontra & Bankgiro', 'byta_kund_pa_faktura', $faq$["Fel kund på fakturan — kan jag byta?","Fakturerade fel bolag?","Flytta faktura till annan kund?"]$faq$::jsonb, $faq$Utkast kan byta kund fritt; skickade fakturor krediteras och ställs ut på rätt kund.$faq$, $faq$Så länge fakturan är utkast kan du byta kund (momslogiken räknas om). En skickad faktura är utställd på en juridisk motpart och kan inte flyttas — kreditera den och skapa en ny på rätt kund. Krediteringen nollar bokföringen och den nya fakturan får eget nummer.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-043', 'Fakturering, kundreskontra & Bankgiro', 'leveransdatum', $faq$["Måste leveransdatum anges på fakturan?","Skillnad fakturadatum och leveransdatum?","Delivery date på faktura?"]$faq$::jsonb, $faq$Leveransdatum ska anges när det skiljer sig från fakturadatumet — det styr momsperioden.$faq$, $faq$Momslagen kräver uppgift om leverans-/tillhandahållandedatum om det inte sammanfaller med fakturadatumet. Fältet finns på fakturan och följer med till bokföringen. För tjänsteperioder anges perioden (t.ex. "konsulttjänster juni 2026").$faq$, $faq$["ML 17 kap 24 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-044', 'Fakturering, kundreskontra & Bankgiro', 'kundfaktura_status_flode', $faq$["Vilka statusar kan en faktura ha?","Fakturans livscykel?","Vad betyder förfallen/krediterad/avskriven?"]$faq$::jsonb, $faq$Utkast → skickad → (förfallen) → delbetald/betald; sidospår: bestriden, krediterad, avskriven, inkasso.$faq$, $faq$Livscykeln: Utkast (redigerbar, obokförd) → Skickad (bokförd, i reskontran) → Förfallen (efter förfallodagen, påminnelser aktiveras) → Delbetald → Betald. Sidospår: Bestriden (fryst i tvist), Krediterad (nollad av kreditfaktura), Avskriven (konstaterad kundförlust), Till inkasso. Statusen styr vad automatiken får göra med fakturan.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('faktura-045', 'Fakturering, kundreskontra & Bankgiro', 'e_post_studsar', $faq$["Fakturamejlet kom inte fram — vad gör jag?","E-post studsade till kunden?","Fel e-postadress på fakturan?"]$faq$::jsonb, $faq$Kontrollera adressen på kundkortet och skicka om — utskickshistoriken visar leveransstatus.$faq$, $faq$Fakturans historik visar om e-posten levererades eller studsade. Vid studs: rätta kundens e-postadress och använd Skicka igen. Fakturan räknas som utställd från första skicket (bokföringen påverkas inte). För viktiga kunder kan du aktivera e-faktura via Peppol som kvitterar mottagning.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/invoices', '/customers']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-001', 'Felsökning & vanliga fel', 'period_last_fel', $faq$["Jag får felet att perioden är låst — vad gör jag?","Kan inte bokföra, perioden är stängd?","Felmeddelande om låst räkenskapsperiod?"]$faq$::jsonb, $faq$Perioden du försöker bokföra i är stängd eller låst. Bokför på ett datum i en öppen period, eller rätta felet via ändringsverifikation i innevarande period.$faq$, $faq$Felet betyder att verifikationsdatumet ligger i en period som stängts (momsdeklarerad, bokslutslåst eller spärrad av företagets låsdatum). Låset upprätthålls i databasen och gäller alla — även automation och importer. Rätt väg: hör posten hemma i den låsta perioden bokför du en ändringsverifikation i första öppna period med hänvisning, i stället för att ändra bakåt. Är perioden låst av misstag och ingenting deklarerats kan en administratör ompröva låsningen under bokslutsinställningarna — det auditloggas. Kontrollera också att verifikationsdatumet inte är ett stavfel (fel år är vanligt i januari).$faq$, $faq$["BFL 5 kap 5 §"]$faq$::jsonb, '{}'::text[], array['/bookkeeping', '/settings/bookkeeping']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-002', 'Felsökning & vanliga fel', 'verifikation_balanserar_inte', $faq$["Verifikationen balanserar inte — varför sparas den inte?","Debet och kredit stämmer inte?","Fel: summan av raderna är inte noll?"]$faq$::jsonb, $faq$Summan av debet måste vara exakt lika med summan av kredit. Kontrollera öresavrundning och att ingen rad saknar belopp.$faq$, $faq$En verifikation kan bara bokföras när debet = kredit. Vanliga orsaker till obalans: en rad har hamnat på fel sida, öresavrundning vid momsberäkning (differensen bokförs på 3740 öresutjämning), ett belopp har skrivits med fel tecken, eller en rad saknar belopp helt. Nordklart visar differensen live medan du redigerar. Vid momsberäkningar: låt systemet räkna momsen från bruttobeloppet i stället för att skriva alla rader manuellt. Kommer felet från en import är filens verifikation trasig — rätta i källsystemet och importera om.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-003', 'Felsökning & vanliga fel', 'banksynk_misslyckades', $faq$["Banksynken misslyckades — vad gör jag?","Inga nya transaktioner kommer in från banken?","Felstatus på bankkopplingen?"]$faq$::jsonb, $faq$Kontrollera kopplingens status under Inställningar → Bank: oftast är samtycket utgånget och behöver förnyas med BankID. Annars — synka om manuellt.$faq$, $faq$Felsök i ordning: 1) Status på bankkopplingen — visar den 'samtycke utgånget' måste du förnya godkännandet hos banken (PSD2-samtycken gäller max 180 dagar); knappen Förnya startar BankID-flödet. 2) Tillfälligt bankfel — bankernas API:er har ibland störningar; kör Synka nu och se om felet kvarstår. 3) Enskilt konto felar — synken isolerar fel per konto, så övriga konton fortsätter fungera; felmeddelandet visar vilket konto som stoppade. 4) Kvarstående fel — felinformationen sparas på kopplingen; kontakta supporten med tidpunkt och felkod så kan de spåra ärendet. Transaktioner går aldrig förlorade — nästa lyckade synk hämtar ikapp perioden.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/banking', '/transactions']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-004', 'Felsökning & vanliga fel', 'samtycke_utganget', $faq$["Bankens samtycke har gått ut — hur förnyar jag?","PSD2-consent expired, vad betyder det?","Måste jag godkänna bankkopplingen igen?"]$faq$::jsonb, $faq$Ja, PSD2-samtycken gäller max 180 dagar. Klicka Förnya på bankkopplingen och godkänn med BankID — historiken och inställningarna behålls.$faq$, $faq$Bankkopplingar via PSD2 kräver att du som kontohavare regelbundet förnyar ditt samtycke — som längst var 180:e dag enligt regelverket. När samtycket närmar sig utgång notifieras du i god tid, och när det gått ut markeras kopplingen som utgången och synken pausas. Förnyelsen tar en minut: öppna bankinställningarna, klicka Förnya och godkänn i bankens BankID-flöde. Alla tidigare transaktioner, matchningar och kontoinställningar påverkas inte, och den första synken efter förnyelsen hämtar ikapp det som hänt under pausen.$faq$, $faq$["PSD2"]$faq$::jsonb, array['admin']::text[], array['/settings/banking']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-005', 'Felsökning & vanliga fel', 'transaktion_matchades_inte', $faq$["Varför matchades inte transaktionen automatiskt?","Betalningen kopplades inte till fakturan — hur ser jag orsaken?","Ingen automatisk matchning på en inbetalning?"]$faq$::jsonb, $faq$Öppna transaktionen och se matchningsloggen: den visar vilka kandidater som utvärderades, poäng och exakt varför automatiken avstod.$faq$, $faq$Varje transaktion bär sin matchningshistorik — öppna den och se utvärderingen: vilka fakturor/motparter som var kandidater, deras poäng och orsakskoderna. Vanliga orsaker: referensen/OCR saknas i banktexten, beloppet avviker från fakturan (delbetalning eller samlingsbetalning), flera fakturor låg för nära varandra i poäng (tvetydighet stoppar alltid automatik), konfidensen låg under företagets tröskel, perioden är låst, beloppet överskred auto-taket, eller kategorin (t.ex. leverantörsavräkning) är avstängd i automationsinställningarna. Du kan alltid matcha manuellt — och justera inställningarna om automatiken är för försiktig för ert flöde.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/settings/banking']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-006', 'Felsökning & vanliga fel', 'dubblettvarning_filimport', $faq$["Jag får dubblettvarning när jag importerar en bankfil?","Filen är redan importerad — men jag ser inga transaktioner?","Varför hoppar importen över rader?"]$faq$::jsonb, $faq$Samma fil (eller samma transaktioner) har redan importerats för företaget. Dubblettskyddet förhindrar dubbla poster — kontrollera transaktionsvyn med rätt datumfilter.$faq$, $faq$Dubblettskyddet arbetar i två lager: hela filen känns igen via innehålls-hash per företag (exakt samma fil importeras inte om), och enskilda transaktioner känns igen via sin identitet (datum, belopp, referens, konto) så att överlappande filer inte skapar dubbla poster — nya rader importeras, redan kända hoppar över. Ser du inga transaktioner efter import: kontrollera datumfiltret i transaktionsvyn och att rätt kassakonto valdes. Importresultatet visar exakt antal importerade respektive överhoppade rader. Skyddet är per företag — samma fil kan importeras i ett annat bolag om den hör hemma där.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import', '/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-007', 'Felsökning & vanliga fel', 'sie_encoding_fel', $faq$["SIE-filen kunde inte tolkas — vad är fel?","Konstiga tecken när jag öppnar SIE-filen?","Importen säger att filen är ogiltig?"]$faq$::jsonb, $faq$Kontrollera att det är en riktig SIE-textfil (börjar med #FLAGGA) och inte t.ex. en zip eller PDF. Teckenkodning hanteras automatiskt.$faq$, $faq$Om SIE-filen avvisas: 1) Öppna den i en textredigerare — en giltig fil börjar med #FLAGGA och innehåller rader som #KONTO, #VER, #TRANS. Ser du binärt innehåll är det fel fil (zip-arkiv, PDF-utskrift). 2) Trasiga å/ä/ö i redigeraren är normalt — SIE använder gammal DOS-kodning (CP437) som Nordklart avkodar automatiskt; det är inte felet. 3) Exportera om från källprogrammet som 'SIE 4' — inte programmets eget backupformat. 4) Avbruten export ger trunkerade filer; jämför filstorlek. Kvarstår felet visar importens felmeddelande vilken rad som inte kunde tolkas — skicka det till supporten så hjälper de till.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-008', 'Felsökning & vanliga fel', 'momsrapport_stammer_inte', $faq$["Momsrapporten stämmer inte med huvudboken?","Differens mellan momsdeklarationen och momskontona?","Ruta 49 matchar inte 2650?"]$faq$::jsonb, $faq$Vanligaste orsakerna: verifikationer bokförda direkt på momskonton utan momskod, rättelser efter att perioden stängts, eller fel momsbehandling på enskilda fakturor.$faq$, $faq$Felsök så här: 1) Kör momskontrollrapporten som jämför momskontonas saldon (261x/264x) mot beräknad moms från försäljnings- och inköpskonton — den pekar ut konton där relationen inte stämmer. 2) Leta manuella verifikationer direkt på momskonton utan koppling till momspliktig försäljning/inköp — vanligaste felkällan. 3) Kontrollera fakturor med ovanlig momsbehandling (omvänd skattskyldighet, EU) under perioden. 4) Bokfördes något i perioden efter att momsrapporten skapades? Skapa om rapporten. 5) Öresdifferenser är normala (avrundning till hela kronor i deklarationen). Är deklarationen redan inlämnad med fel: rätta genom att lämna om deklarationen för perioden hos Skatteverket.$faq$, $faq$["Momsdeklarationens rutor"]$faq$::jsonb, '{}'::text[], array['/reports', '/bookkeeping']::text[], 'medium', $faq$Större oförklarade momsdifferenser bör granskas av redovisningskonsult innan deklaration — felaktig moms kan ge skattetillägg.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-009', 'Felsökning & vanliga fel', 'faktura_fel_momssats', $faq$["Fakturan fick fel momssats — hur rättar jag?","Jag skickade en faktura med 25 % men det skulle vara 12 %?","Ändra moms på en skickad faktura?"]$faq$::jsonb, $faq$En skickad faktura rättas med kreditfaktura plus ny korrekt faktura — momsen på kreditfakturan följer alltid originalfakturans sats.$faq$, $faq$Skickade fakturor ändras inte: skapa en kreditfaktura som vänder originalet (Nordklart använder originalets momssats på krediten — aldrig en schablon) och ställ ut en ny faktura med rätt momssats. Båda dokumenten refererar till varandra och kunden får korrekt underlag. Är fakturan redan betald regleras mellanskillnaden mot kunden. Bokföringen och momsrapporten blir automatiskt rätt i den period rättelsen görs. För framtiden: kontrollera artikelns momssats i artikelregistret — fel där ger fel på varje faktura — och momsbehandlingen på kunden (t.ex. EU-kund utan moms).$faq$, $faq$["ML 17 kap"]$faq$::jsonb, '{}'::text[], array['/invoices', '/articles']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-010', 'Felsökning & vanliga fel', 'ocr_tolkning_misslyckas_felsokning', $faq$["Dokumenttolkningen misslyckas hela tiden?","OCR ger fel resultat på mina kvitton?","Varför tolkas inte min uppladdade faktura?"]$faq$::jsonb, $faq$Kontrollera bildkvalitet och format: skarp bild, hela dokumentet synligt, PDF-original hellre än foto. Tillfälliga fel försöks om automatiskt.$faq$, $faq$Tolkningskvalitet beror på underlaget: använd PDF-originalet när det finns (e-postfakturor) i stället för foto; vid foto — rakt ovanifrån, bra ljus, hela dokumentet i bild, ingen skugga över beloppen. Format som stöds: PDF, JPG, PNG. Lösenordsskyddade PDF:er kan inte läsas — spara om utan skydd. Tillfälliga fel (tidsgräns, hög belastning) försöks om automatiskt med backoff; permanent misslyckade dokument visar orsak och kan alltid registreras manuellt med dokumentet som bilaga. Återkommande feltolkning av samma leverantörs fakturor? Rapportera exemplet till supporten — tolkningen förbättras löpande.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/receipts']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-011', 'Felsökning & vanliga fel', 'kan_inte_ta_bort_verifikation', $faq$["Varför kan jag inte ta bort en verifikation?","Radera en felaktig bokföring?","Det finns ingen delete-knapp på verifikationen?"]$faq$::jsonb, $faq$Bokförda verifikationer kan aldrig raderas — det är ett lagkrav. Rätta i stället med ändringsverifikation (storno) som vänder felet.$faq$, $faq$Detta är avsiktligt: bokföringslagen kräver att bokförda affärshändelser inte kan raderas eller ändras i efterhand — rättelse ska ske så att den ursprungliga uppgiften framgår. Nordklart upprätthåller det på databasnivå. Rätt arbetssätt: öppna verifikationen och välj Rätta — systemet skapar en ändringsverifikation som vänder den felaktiga posten (storno) och, om du vill, en ny korrekt post; alla tre hänvisar till varandra. Utkast som ännu inte bokförts kan däremot redigeras eller tas bort fritt. Verifikationsnummerserien förblir obruten, vilket också är ett lagkrav.$faq$, $faq$["BFL 5 kap 5 §"]$faq$::jsonb, '{}'::text[], array['/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-012', 'Felsökning & vanliga fel', 'saknar_behorighet_fel', $faq$["Jag får 'saknar behörighet' — varför?","Kan inte ändra inställningar trots att jag är inloggad?","Åtkomst nekad i Nordklart?"]$faq$::jsonb, $faq$Din roll i det aktiva företaget räcker inte för åtgärden. Kontrollera vilket företag som är aktivt och be en ägare/admin höja din roll vid behov.$faq$, $faq$Behörighetsfel har nästan alltid en av tre orsaker: 1) Fel aktivt företag — du är kanske admin i ditt eget bolag men viewer i det som råkar vara valt; kontrollera företagsväljaren. 2) Rollen räcker inte — inställningar, medlemshantering och automationsregler kräver admin; periodupplåsning kräver ägare; viewers kan inte skriva alls. Be en ägare/admin justera din roll under Inställningar → Team. 3) MFA ej verifierad — vissa känsliga vyer kräver att sessionen är tvåfaktorsverifierad; logga ut och in igen med engångskod. Behörighetskontrollen görs på serversidan, så det hjälper inte att ladda om sidan.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/team']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-013', 'Felsökning & vanliga fel', 'api_429_rate_limit', $faq$["API:et svarar med 429 — vad betyder det?","Too Many Requests från Nordklart-API:et?","Min integration blir strypt?"]$faq$::jsonb, $faq$Nyckeln har överskridit 100 anrop per minut. Anropet utfördes inte — vänta och försök igen med exponentiell backoff.$faq$, $faq$HTTP 429 betyder att API-nyckelns gräns (100 förfrågningar/minut) nåtts. Viktigt: det avvisade anropet har inte utförts, så det är säkert att skicka om. Åtgärder: implementera exponentiell backoff (vänta 1s, 2s, 4s... innan omförsök), sprid schemalagda jobb över tid i stället för att köra allt på heltimmen, använd list-endpoints med paginering i stället för objekt-för-objekt-hämtning, och byt polling mot webhooks för händelsedriven synk. Behöver integrationen strukturellt högre kapacitet — hör av dig till supporten och beskriv användningsfallet.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/api']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-014', 'Felsökning & vanliga fel', 'webhook_levereras_inte', $faq$["Mina webhooks kommer inte fram?","Webhook-leveranser misslyckas — hur felsöker jag?","Inga händelser når min endpoint?"]$faq$::jsonb, $faq$Kontrollera leveransloggen i webhookvyn: endpointen måste svara 2xx snabbt över HTTPS. Misslyckade leveranser försöks om och kan skickas om manuellt.$faq$, $faq$Felsök i webhookvyns leveranshistorik — där syns varje försök med statuskod och svar. Vanliga orsaker: endpointen svarar långsamt (kvittera med 2xx direkt och bearbeta asynkront — långsamma svar räknas som misslyckade), fel statuskod (3xx/4xx/5xx räknas som fel), certifikatproblem (endpointen måste ha giltig HTTPS), brandvägg som blockerar inkommande trafik, eller att signaturverifieringen i din mottagare kastar fel innan svaret hinner skickas. Misslyckade leveranser försöks om automatiskt med stigande intervall, och du kan skicka om enskilda händelser manuellt när endpointen är lagad. Testa gärna med en request-inspektionstjänst för att isolera om felet ligger hos endpointen.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/api']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('fel-015', 'Felsökning & vanliga fel', 'sidan_laddar_inte', $faq$["Sidan laddar inte eller visar gammal data?","Nordklart hänger sig — vad kan jag testa?","Gränssnittet ser trasigt ut efter uppdatering?"]$faq$::jsonb, $faq$Ladda om med Ctrl+Shift+R (hård omladdning). Hjälper inte det: testa inkognitoläge, annan webbläsare och kontrollera internetanslutningen.$faq$, $faq$Standardfelsökning i ordning: 1) Hård omladdning (Ctrl+Shift+R / Cmd+Shift+R) — tvingar webbläsaren att hämta senaste versionen i stället för cachad. 2) Inkognitoläge — fungerar det där är orsaken en webbläsartillägg (annonsblockerare kan störa) eller korrupt cache; rensa webbplatsdata för Nordklart. 3) Annan webbläsare/enhet — isolerar om problemet är lokalt. 4) Nätverk — företags-VPN och brandväggar kan blockera; testa annan uppkoppling. 5) Kvarstår problemet för flera användare samtidigt kan det vara en driftstörning — kontakta supporten med tidpunkt, webbläsare och skärmbild. Ditt data påverkas inte av visningsproblem; allt sparat ligger kvar på servern.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/help']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-001', 'Import/export, SIE, API & webhooks', 'importera_sie', $faq$["Hur importerar jag en SIE-fil?","Flytta bokföring till Nordklart via SIE?","Var laddar jag upp SIE4-filen?"]$faq$::jsonb, $faq$Gå till Import → SIE, ladda upp filen och följ guiden: förhandsgranskning, kontomappning, val av innehåll och import — allt kan ångras.$faq$, $faq$SIE-importen under Import läser din fil och visar en förhandsgranskning innan något skapas: upptäckta räkenskapsår, antal verifikationer, konton som behöver skapas eller mappas, ingående balanser samt eventuella varningar (obalanserade verifikationer, överlapp med befintlig bokföring eller banktransaktioner). Du väljer vad som ska importeras — kontoplan, balanser, verifikationer — och bekräftar. Importen loggas och kan ångras eller ersättas i sin helhet om något blev fel. Filer i SIE typ 1–4 stöds; typ 4 (med verifikationer) är vanligast vid systembyte.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/import']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-002', 'Import/export, SIE, API & webhooks', 'sie_typer', $faq$["Vilka SIE-typer finns det?","Vad är skillnaden mellan SIE1 och SIE4?","Vilken SIE-fil ska jag be om från mitt gamla program?"]$faq$::jsonb, $faq$SIE1 = årssaldon, SIE2 = periodsaldon, SIE3 = objektsaldon, SIE4 = fullständig med alla verifikationer. Be om SIE4 vid byte till Nordklart.$faq$, $faq$SIE-standarden har fyra exporttyper: typ 1 innehåller bara ingående/utgående årssaldon, typ 2 lägger till periodsaldon per månad, typ 3 lägger till objekt-/dimensionssaldon, och typ 4 innehåller dessutom samtliga verifikationer med transaktionsrader — den kompletta bokföringen. Vid migrering till Nordklart ska du exportera SIE4 från ditt gamla program (ofta kallad 'SIE4E' eller 'fullständig export'). Alla vanliga svenska program kan exportera SIE4. Nordklart läser även äldre teckenkodning (CP437) som formatet traditionellt använder.$faq$, $faq$["SIE-gruppens formatspecifikation"]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-003', 'Import/export, SIE, API & webhooks', 'sie_forhandsgranskning', $faq$["Vad visar förhandsgranskningen vid SIE-import?","Kan jag se innehållet innan importen körs?","Vad kontrolleras i SIE-filen före import?"]$faq$::jsonb, $faq$Förhandsgranskningen visar räkenskapsår, verifikationer, konton, balanser, dimensioner och varningar — inget skapas förrän du bekräftar.$faq$, $faq$Innan importen körs analyseras filen: upptäckta räkenskapsår med datumintervall, antal verifikationer per serie, kontoplanen med vilka konton som redan finns respektive behöver skapas, ingående/utgående balanser, dimensioner och objekt (kostnadsställen, projekt) samt filens checksumma om sådan finns. Valideringar körs samtidigt: obalanserade verifikationer stoppar importen, datum utanför angivna räkenskapsår flaggas, och överlapp med befintliga verifikationer eller bankimporterade transaktioner ger varningar. Du ser allt detta i förhandsgranskningen och väljer aktivt vad som ska importeras.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-004', 'Import/export, SIE, API & webhooks', 'kontomappning_sie', $faq$["Hur fungerar kontomappningen vid SIE-import?","Mitt gamla program hade andra konton — mappas de om?","Kan olika företag ha olika kontomappningar?"]$faq$::jsonb, $faq$Konton i filen mappas mot företagets kontoplan — okända konton kan skapas eller mappas om till befintliga. Mappningarna sparas per företag.$faq$, $faq$Under importen matchas filens konton mot företagets BAS-kontoplan. Konton som redan finns används direkt; okända konton kan antingen skapas automatiskt (med namn och SRU-kod från filen) eller mappas om till ett befintligt konto — t.ex. om det gamla programmet använde 1935 för ett bankkonto som i Nordklart ska vara 1930. Mappningarna sparas per företag, så samma användare kan ha olika mappningar i olika bolag, och de återanvänds vid nästa import. Granska mappningen noga för bank-, moms- och resultatkonton innan du bekräftar.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/import']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-005', 'Import/export, SIE, API & webhooks', 'sie_dimensioner', $faq$["Följer kostnadsställen och projekt med i SIE-importen?","Vad händer med dimensioner i SIE-filen?","Importeras #DIM och #OBJEKT?"]$faq$::jsonb, $faq$Ja. Dimension 1 (kostnadsställe) och 6 (projekt) mappas till Nordklarts kostnadsställen och projekt; övriga dimensioner bevaras som metadata på raderna.$faq$, $faq$SIE-filens #DIM- och #OBJEKT-poster läses in: dimension 1 (kostnadsställe/resultatenhet) skapas som kostnadsställen och dimension 6 som projekt i Nordklart, och verifikationsradernas objektlistor kopplas till rätt kostnadsställe/projekt. Dimensioner utanför standardnumren bevaras som metadata på transaktionsraderna så att ingen information går förlorad — de följer också med vid SIE-export. Det betyder att en import följd av export behåller dimensionsdata (roundtrip). Objektsaldon (SIE3-nivå) används för validering när de finns i filen.$faq$, $faq$["SIE-gruppens formatspecifikation"]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-006', 'Import/export, SIE, API & webhooks', 'ksumma_checksumma', $faq$["Vad är KSUMMA i en SIE-fil?","Kontrolleras filens checksumma?","SIE-filens integritet — hur verifieras den?"]$faq$::jsonb, $faq$#KSUMMA är en kontrollsumma som visar att filen inte ändrats efter export. Nordklart läser posten och noterar om den finns.$faq$, $faq$#KSUMMA är SIE-formatets inbyggda kontrollsumma (CRC) som exporterande program kan skriva för att göra filen manipulationssäker — ändras något i filen stämmer inte summan längre. Nordklart tolkar posten vid import och visar i förhandsgranskningen om filen innehåller checksumma. Oberoende av KSUMMA validerar Nordklart alltid själva innehållet: att varje verifikation balanserar, att balanser är konsistenta mellan IB/UB och verifikationerna, och att datum ligger inom räkenskapsåren — det är dessa kontroller som avgör om importen tillåts.$faq$, $faq$["SIE-gruppens formatspecifikation"]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-007', 'Import/export, SIE, API & webhooks', 'sie_teckenkodning', $faq$["Varför ser å ä ö konstiga ut i min SIE-fil?","Vilken teckenkodning har SIE-filer?","Trasiga svenska tecken vid import?"]$faq$::jsonb, $faq$SIE-standarden använder den gamla kodningen CP437, men filer förekommer även i UTF-8 och Latin-1. Nordklart detekterar kodningen automatiskt.$faq$, $faq$SIE-formatet specificerar IBM PC-teckenkodning (CP437), vilket gör att å, ä och ö ser trasiga ut om filen öppnas som vanlig text. Många moderna program exporterar dock i UTF-8 eller ISO 8859-1 i stället. Nordklarts import detekterar kodningen automatiskt genom att analysera filinnehållet, så svenska tecken i kontonamn och verifikationstexter blir rätt oavsett källprogram. Ser texterna ändå fel ut i förhandsgranskningen — avbryt, kontrollera exportinställningen i källprogrammet och importera på nytt; ingenting skapas förrän du bekräftat.$faq$, $faq$["SIE-gruppens formatspecifikation"]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-008', 'Import/export, SIE, API & webhooks', 'sie_overlapp_bank', $faq$["Vad händer om SIE-filen överlappar med banksynken?","Kan SIE-import ge dubbelbokning mot bankimporterade transaktioner?","Överlappsvarning vid SIE-import?"]$faq$::jsonb, $faq$Nordklart upptäcker datumöverlapp mellan SIE-import och bankimporterade transaktioner. Automatisk bokföring stängs av i perioden och du varnas.$faq$, $faq$Om SIE-filens verifikationer täcker samma period som redan importerade banktransaktioner finns risk att samma affärshändelse bokförs två gånger — en gång via SIE-verifikationen och en gång via bankautomationen. Nordklart hanterar det så här: importen varnar om datumöverlapp mot befintliga banktransaktioner, och automationen auto-bokför inte kategoriseringar i perioder som täcks av en slutförd SIE-import — sådana transaktioner flaggas i stället för manuell granskning så att du kan länka dem mot redan importerade verifikationer eller markera dem som hanterade. Omvänt gäller samma spärr när banken importeras efter SIE:n.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import', '/transactions']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-009', 'Import/export, SIE, API & webhooks', 'ersatta_sie_import', $faq$["Kan jag ersätta en tidigare SIE-import?","Jag fick en ny fil från gamla systemet — hur byter jag ut importen?","Ersätt import med korrigerad SIE-fil?"]$faq$::jsonb, $faq$Ja. Ersätt-funktionen tar bort den gamla importens verifikationer och importerar den nya filen i samma slot — endast i det aktuella företaget.$faq$, $faq$Om källsystemet exporterat en korrigerad fil kan du ersätta en tidigare import: Nordklart tar då bort exakt de verifikationer och balanser som skapades av den gamla importen (ingenting annat berörs) och kör den nya filen genom samma förhandsgranskning och validering. Åtgärden är begränsad till det aktiva företaget, kräver att de berörda perioderna inte är låsta, och hela förloppet auditloggas — du kan se vilka verifikationer som togs bort och vilka som skapades. Har du hunnit bokföra egna verifikationer ovanpå importen varnas du innan ersättningen körs.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/import']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-010', 'Import/export, SIE, API & webhooks', 'angra_sie_import', $faq$["Kan jag ångra en SIE-import?","Importen blev fel — hur backar jag?","Ta bort allt som en SIE-import skapade?"]$faq$::jsonb, $faq$Ja, en import kan ångras i sin helhet: alla verifikationer och balanser den skapade tas bort, förutsatt att perioderna inte är låsta.$faq$, $faq$Varje SIE-import spårar exakt vilka verifikationer, konton och balansposter den skapade. Ångra-funktionen tar bort dessa — och bara dessa — så att bokföringen återgår till läget före importen. Kravet är att de berörda perioderna fortfarande är öppna; ligger importens verifikationer i ett låst räkenskapsår måste låset hanteras först. Konton som skapades av importen men hunnit användas av annan bokföring lämnas kvar. Åtgärden är idempotent (kan köras om säkert vid avbrott) och auditloggas med vem som ångrade och när.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/import']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-011', 'Import/export, SIE, API & webhooks', 'ingaende_balanser_sie', $faq$["Hur får jag in ingående balanser från gamla systemet?","Importeras IB från SIE-filen?","Öppningsbalans vid byte till Nordklart?"]$faq$::jsonb, $faq$SIE-filens #IB-poster importeras som ingående balanser för räkenskapsåret. Alternativt registreras öppningsbalansen manuellt under Import.$faq$, $faq$Vid systembyte är ingående balanser det viktigaste: SIE-filens #IB-poster (saldo per balanskonto vid årets ingång) läses in och blir räkenskapsårets öppningsbalans i Nordklart. Kontrollen är att summan av tillgångar ska vara lika med summan av eget kapital och skulder — obalans stoppar importen. Importerar du mitt i året tar du med både IB och årets verifikationer så att aktuellt saldo blir rätt. Saknar du SIE-fil kan öppningsbalansen i stället registreras manuellt från senaste balansräkningen under Import → Öppningsbalans. Ingående balanser från SIE behandlas inte som banktransaktioner och stör inte bankavstämningen.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/import']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-012', 'Import/export, SIE, API & webhooks', 'obalanserad_verifikation_block', $faq$["Vad händer om en verifikation i SIE-filen inte balanserar?","Importen stoppades på grund av obalans — varför?","Debet och kredit stämmer inte i filen?"]$faq$::jsonb, $faq$Obalanserade verifikationer blockerar importen — varje verifikation måste ha lika stora debet- och kreditsummor. Felet visas med verifikationsnummer.$faq$, $faq$Grundregeln i dubbel bokföring är att varje verifikation balanserar. Innehåller SIE-filen en verifikation där debet och kredit inte summerar lika (efter öresavrundning) vägrar Nordklart importera — annars skulle hela balansräkningen bli fel. Felmeddelandet anger serie, verifikationsnummer och differens så att du kan hitta posten. Orsaken är oftast en trasig exportfil eller manuellt redigerad fil. Lösning: exportera om från källsystemet, eller rätta den specifika verifikationen där innan ny import. Samma validering gäller alla verifikationer som skapas i Nordklart.$faq$, $faq$["BFL 5 kap"]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-013', 'Import/export, SIE, API & webhooks', 'exportera_sie', $faq$["Hur exporterar jag en SIE-fil från Nordklart?","Ta ut bokföringen som SIE4?","Exportera året till en fil?"]$faq$::jsonb, $faq$Under Import → Export väljer du räkenskapsår och får en SIE4-fil med kontoplan, balanser, resultat och alla verifikationer.$faq$, $faq$SIE-exporten skapar en komplett SIE4-fil för valt räkenskapsår: #KONTO med kontonamn, kontotyper (#KTYP) och SRU-koder (#SRU), #IB/#UB ingående och utgående balanser, #RES resultatsaldon, samt #VER/#TRANS med samtliga verifikationer inklusive datum, text, belopp och dimensioner (kostnadsställe/projekt som objektlistor). Finns ett föregående räkenskapsår tas även dess balanser med (#RAR -1) så mottagande program får jämförelsetal. Filen fungerar i revisorsprogram, andra bokföringssystem och för arkivering. En export ändrar ingenting i bokföringen och kan köras när som helst.$faq$, $faq$["SIE-gruppens formatspecifikation"]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-014', 'Import/export, SIE, API & webhooks', 'sie_roundtrip', $faq$["Om jag importerar och sedan exporterar — blir filen likvärdig?","Bevaras all data vid SIE-roundtrip?","Tappas något mellan import och export?"]$faq$::jsonb, $faq$Kärndatat bevaras: konton, balanser, verifikationer, belopp, datum och dimensioner. Programspecifika fält utanför standarden följer inte med.$faq$, $faq$Nordklart är byggt för att en import följd av export ska bevara bokföringens kärna: kontoplan med SRU-koder, ingående/utgående balanser, resultatsaldon, alla verifikationer med rader, belopp, datum och texter, samt dimensioner och objekt (kostnadsställen/projekt). Det som inte roundtrippar är källprogrammets egna utökningar utanför SIE-standarden och exakt radformatering. Verifikationsnummer behålls i sina serier där det är möjligt. Vill du verifiera kan du jämföra balans- och resultatrapporter före och efter — de ska vara identiska.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-015', 'Import/export, SIE, API & webhooks', 'migrera_fortnox', $faq$["Hur flyttar jag från Fortnox till Nordklart?","Migrera bokföring från Fortnox?","Kan Nordklart hämta data direkt från Fortnox?"]$faq$::jsonb, $faq$Använd migreringstillägget som hämtar SIE-filer direkt från Fortnox via API, eller exportera SIE4 manuellt från Fortnox och importera.$faq$, $faq$Två vägar: 1) Nordklarts migreringstillägg kopplar mot Fortnox via OAuth och hämtar SIE-filer för valda räkenskapsår automatiskt — du godkänner kopplingen, väljer år och kör importen genom det vanliga SIE-flödet med förhandsgranskning. 2) Manuellt: exportera SIE4 i Fortnox (Register → Exportera SIE) per räkenskapsår och ladda upp filerna under Import → SIE. Ta gärna med två–tre år bakåt för jämförelsetal. Kom ihåg att också exportera kund- och leverantörsregister samt öppna fakturor — reskontran följer inte med i SIE-formatet.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/import', '/settings']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-016', 'Import/export, SIE, API & webhooks', 'migrera_andra_program', $faq$["Kan jag migrera från Bokio eller Visma?","Flytta från Briox eller BL Administration?","Vilka bokföringsprogram kan Nordklart migrera från?"]$faq$::jsonb, $faq$Migreringstillägget stödjer Fortnox, Bokio, Visma, Briox och BL — och alla program som kan exportera SIE4 fungerar via manuell import.$faq$, $faq$Nordklarts migreringstillägg har direktkopplingar mot de vanligaste svenska programmen — Fortnox, Bokio, Visma eEkonomi, Briox och BL Administration — och hämtar räkenskapsår som SIE-filer via respektive API där leverantören tillåter det. För övriga program gäller den universella vägen: exportera SIE4 (alla svenska bokföringsprogram har funktionen, det är i praktiken branschstandard) och importera under Import → SIE. Registerdata (kunder, leverantörer, artiklar) tas med via CSV-import eftersom SIE bara täcker bokföringen. Kör gärna migreringen i god tid före en momsdeadline så du hinner stämma av.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/import']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-017', 'Import/export, SIE, API & webhooks', 'importera_register_csv', $faq$["Kan jag importera kunder från en CSV-fil?","Importera artiklar och leverantörer?","Massimport av kundregister?"]$faq$::jsonb, $faq$Ja, kunder och artiklar importeras via CSV under Import — med kolumnmappning och förhandsgranskning innan något skapas.$faq$, $faq$Under Import finns CSV-import för register: ladda upp filen, mappa kolumnerna (namn, organisationsnummer, e-post, betalvillkor för kunder; artikelnummer, benämning, pris, momssats för artiklar) och förhandsgranska raderna innan importen körs. Dubbletter mot befintligt register upptäcks via organisationsnummer/artikelnummer och kan hoppa över eller uppdatera. Exportera motsvarande listor från ditt gamla program som CSV eller Excel (spara som CSV). Registerimporterna är fristående från bokföringen och kan köras när som helst.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/import', '/customers', '/articles']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-018', 'Import/export, SIE, API & webhooks', 'oppningsbalans_manuell', $faq$["Hur lägger jag in öppningsbalans manuellt?","Jag har ingen SIE-fil — kan jag skriva in ingående saldon?","Registrera ingående balanser från balansräkningen?"]$faq$::jsonb, $faq$Under Import → Öppningsbalans anger du saldot per balanskonto från senaste balansräkningen. Summan måste balansera innan den kan bokföras.$faq$, $faq$Utan SIE-fil registrerar du öppningsbalansen manuellt: utgå från den senaste fastställda balansräkningen (eller utgående saldon i gamla systemet) och ange belopp per balanskonto — bank, kundfordringar, inventarier, leverantörsskulder, momskonton, eget kapital osv. Nordklart validerar att tillgångar = eget kapital + skulder innan balansen kan sparas, och skapar sedan ingående balanser för räkenskapsåret. Förhandsgranskningen visar differensen löpande medan du fyller i. Öppna kund- och leverantörsfakturor registreras separat i respektive reskontra så att betalningarna kan matchas.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/import']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-019', 'Import/export, SIE, API & webhooks', 'bankfil_import', $faq$["Kan jag importera kontoutdrag som fil?","Vilka bankfilsformat stöds?","Importera CAMT-fil från banken?"]$faq$::jsonb, $faq$Ja, under Import → Bankfil stöds filer från SEB, Swedbank, Handelsbanken, Nordea m.fl. samt generisk CSV och CAMT.053.$faq$, $faq$Som alternativ till bankkoppling kan kontoutdrag importeras som fil: format finns för SEB, Swedbank, Handelsbanken, Nordea (inkl. Nordea Business), Länsförsäkringar, ICA Banken, Skandia, Lunar och Northmill, plus generisk CSV med kolumnmappning och ISO-standarden CAMT.053. Formatet detekteras automatiskt men kan väljas manuellt. Filen förhandsgranskas, dubbletter mot tidigare importer upptäcks via filens innehåll och transaktionernas identitet (per företag), och transaktionerna hamnar på rätt kassakonto. Efter importen körs samma automatiska matchning som vid banksynk.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import', '/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-020', 'Import/export, SIE, API & webhooks', 'exportera_rapporter', $faq$["Kan jag exportera rapporter till Excel eller PDF?","Ta ut resultatrapporten som fil?","Exportera huvudboken?"]$faq$::jsonb, $faq$Ja, rapporterna (resultat, balans, huvudbok, reskontror m.fl.) kan exporteras som PDF och Excel från rapportvyn.$faq$, $faq$Alla standardrapporter under Rapporter — resultaträkning, balansräkning, huvudbok, verifikationslista, kund- och leverantörsreskontra, momsrapport — kan exporteras: PDF för delning och arkivering, Excel (xlsx) för vidare bearbetning. Välj period och eventuella jämförelsetal innan exporten. För revisorn är SIE-filen oftast det bästa komplementet eftersom den innehåller hela bokföringen maskinläsbart. Fakturor exporteras som PDF per faktura, och hela dokumentarkivet kan tas ut som zip vid behov.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-021', 'Import/export, SIE, API & webhooks', 'api_nycklar_skapa', $faq$["Hur skapar jag en API-nyckel?","Var hittar jag API-inställningarna?","Programmatisk åtkomst till Nordklart?"]$faq$::jsonb, $faq$Under Inställningar → API skapar du nycklar med valda behörighetsscopes. Nyckeln visas en gång — spara den säkert.$faq$, $faq$API-nycklar skapas under Inställningar → API av företagets administratör: ge nyckeln ett namn, välj vilka scopes den ska ha (t.ex. läsa bokföring, skapa fakturor, hantera transaktioner) och skapa. Nyckeln (prefix nordklart_sk_) visas endast vid skapandet — den lagras hashad och kan aldrig visas igen, så spara den i en lösenordshanterare. Nycklar är knutna till företaget och respekterar dess dataisolering. Kompromissad nyckel återkallas direkt i samma vy; skapa hellre flera nycklar med snäva scopes än en bred.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/api']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-022', 'Import/export, SIE, API & webhooks', 'api_scopes', $faq$["Vad är API-scopes?","Kan jag begränsa vad en API-nyckel får göra?","Läsbehörighet kontra skrivbehörighet i API:et?"]$faq$::jsonb, $faq$Scopes begränsar nyckelns behörighet per område — t.ex. bara läsa rapporter, eller skapa fakturor men inte bokföra. Välj minsta möjliga.$faq$, $faq$Varje API-nyckel tilldelas scopes som styr exakt vilka endpoints den når: läsande scopes (rapporter, transaktioner, fakturor) respektive skrivande (skapa fakturor, registrera betalningar, bokföra verifikationer, hantera importer). Ett anrop utanför nyckelns scopes avvisas med 403. Principen är minsta privilegium: en integration som bara läser rapporter ska inte kunna skapa verifikationer. Scopes visas på nyckeln i inställningarna och kan inte utökas i efterhand — skapa i så fall en ny nyckel och fasa ut den gamla.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/api']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-023', 'Import/export, SIE, API & webhooks', 'api_rate_limit', $faq$["Finns det rate limit på API:et?","Hur många anrop per minut får jag göra?","Jag får 429-fel från API:et?"]$faq$::jsonb, $faq$API-nycklar är begränsade till 100 anrop per minut. Vid 429-svar: vänta och försök igen med exponentiell backoff.$faq$, $faq$Varje API-nyckel har en gräns på 100 förfrågningar per minut. Överskrids den svarar API:et med HTTP 429 (Too Many Requests) — anropet har då inte utförts och kan säkert göras om. Bygg klienten med exponentiell backoff (vänta t.ex. 1, 2, 4 sekunder) och batcha hellre läsningar via list-endpoints med paginering än att hämta objekt ett och ett. Behöver du kontinuerlig synk är webhooks effektivare än polling — då slipper du förbruka anrop på att fråga efter ändringar som inte skett.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/api']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-024', 'Import/export, SIE, API & webhooks', 'api_v1_oversikt', $faq$["Vilka endpoints finns i API:et?","Vad kan jag göra via Nordklarts API?","Finns API-dokumentation?"]$faq$::jsonb, $faq$API v1 täcker kunder, fakturor, leverantörsfakturor, transaktioner, verifikationer, rapporter och importer — dokumentation finns i inställningarna.$faq$, $faq$REST-API:t (under /api/v1/companies/{companyId}/...) exponerar kärnflödena: kunder och artiklar, kundfakturor (skapa, skicka, markera betald, kreditera), leverantörsfakturor, banktransaktioner och matchning, verifikationer och huvudbok, rapporter (resultat, balans, moms) samt bank- och SIE-importer. Alla anrop autentiseras med API-nyckel i Authorization-headern och är företagsavgränsade. Skrivoperationer stödjer idempotensnycklar så att omförsök inte skapar dubbletter. Dokumentation med exempel finns länkad från Inställningar → API.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/api']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-025', 'Import/export, SIE, API & webhooks', 'webhooks_konfigurera', $faq$["Hur sätter jag upp webhooks?","Kan Nordklart notifiera mitt system vid händelser?","Prenumerera på händelser via webhook?"]$faq$::jsonb, $faq$Under Inställningar → API registrerar du en webhook-endpoint och väljer vilka händelser som ska skickas dit — leveranser signeras och kan spelas upp igen.$faq$, $faq$Webhooks låter ditt system reagera på händelser i Nordklart i realtid: registrera din HTTPS-endpoint, välj händelsetyper och spara. Varje leverans är signerad så att du kan verifiera avsändaren, och misslyckade leveranser försöks om automatiskt med stigande intervall. I webhookvyn ser du leveranshistorik per endpoint med status och payload, och kan skicka om enskilda händelser manuellt. Endpointen bör svara 2xx snabbt (kvittera först, bearbeta asynkront) — långsamma svar räknas som misslyckade.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/api']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-026', 'Import/export, SIE, API & webhooks', 'webhook_handelser', $faq$["Vilka händelser kan webhooks skicka?","Får jag en webhook när en faktura betalas?","Vilka event-typer finns?"]$faq$::jsonb, $faq$Bland annat: faktura skapad/skickad/betald, transaktion synkad/matchad, verifikation bokförd, import slutförd och väntande åtgärd skapad/godkänd.$faq$, $faq$Händelsekatalogen täcker de viktigaste flödena: fakturahändelser (skapad, skickad, betald, förfallen, krediterad), banktransaktioner (synkade, matchade, bokförda), verifikationer (bokförda, rättade), leverantörsfakturor (tolkad, godkänd, betald), importer (bankfil/SIE slutförd), väntande åtgärder (skapad, godkänd, avvisad) samt påminnelser och återkommande fakturor. Varje payload innehåller händelsetyp, tidpunkt, företags-id och objektets data. Prenumerera bara på det du behöver — det minskar brus och gör felsökning enklare.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/api']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-027', 'Import/export, SIE, API & webhooks', 'webhook_signatur', $faq$["Hur verifierar jag webhook-signaturen?","Hur vet jag att en webhook verkligen kommer från Nordklart?","Webhook-säkerhet?"]$faq$::jsonb, $faq$Varje leverans signeras med en hemlighet som visas när endpointen skapas. Verifiera signaturheadern innan du litar på innehållet.$faq$, $faq$När du registrerar en webhook-endpoint får du en signeringshemlighet. Varje leverans innehåller signaturheaders (id, tidsstämpel och HMAC-signatur) beräknade över payloaden — verifiera dem i din mottagare innan du agerar på innehållet, annars kan vem som helst som känner din URL skicka förfalskade händelser. Tidsstämpeln skyddar mot replay-attacker: avvisa leveranser äldre än några minuter. Använd färdiga verifieringsbibliotek där de finns i ditt språk. Rotera hemligheten om den misstänks läckt — gamla leveranser kan spelas om efter rotationen.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/api']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-028', 'Import/export, SIE, API & webhooks', 'mcp_server_koppling', $faq$["Kan jag koppla Claude till Nordklart?","Vad är MCP-servern?","Använda AI-assistent mot min bokföring?"]$faq$::jsonb, $faq$Ja, Nordklart har en MCP-server som låter Claude Desktop/Code arbeta mot din bokföring med behörighetsstyrda verktyg — läsning och kontrollerade åtgärder.$faq$, $faq$MCP-servern (Model Context Protocol) exponerar Nordklarts funktioner som verktyg för AI-klienter som Claude: hämta rapporter, söka verifikationer, skapa fakturautkast, förbereda bokföringsförslag med mera. Kopplingen sker via API-nyckel (npx nordklart-mcp) eller OAuth för Claude-connectors, och verktygens omfattning styrs av nyckelns scopes. Viktigt: känsliga åtgärder går genom samma säkerhetsmodell som allt annat — riskfyllda bokföringar blir väntande åtgärder som kräver mänskligt godkännande i Nordklart, AI:n kan inte slutföra dem själv.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/api']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-029', 'Import/export, SIE, API & webhooks', 'mcp_oauth', $faq$["Hur ansluter jag Claude-connectorn med OAuth?","MCP med OAuth i stället för API-nyckel?","Godkänna AI-klientens åtkomst?"]$faq$::jsonb, $faq$Lägg till Nordklart som connector i Claude — du skickas till Nordklart för inloggning och godkännande, och åtkomsten kan återkallas när som helst.$faq$, $faq$För Claude-connectors används OAuth i stället för manuella nycklar: lägg till Nordklarts MCP-endpoint i Claude, så öppnas ett godkännandeflöde där du loggar in i Nordklart (med MFA om aktiverat), ser vilka behörigheter klienten begär och vilket företag åtkomsten gäller, och godkänner. Klienten får då tidsbegränsade tokens som förnyas automatiskt. Aktiva kopplingar listas under Inställningar → API där de kan återkallas omedelbart. Behörigheterna följer din egen roll i företaget — connectorn kan aldrig göra mer än du själv får.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/api']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-030', 'Import/export, SIE, API & webhooks', 'api_idempotens', $faq$["Hur undviker jag dubbletter vid API-anrop?","Vad är idempotensnycklar?","Mitt anrop fick timeout — vågar jag skicka igen?"]$faq$::jsonb, $faq$Skicka en Idempotency-Key-header på skrivande anrop: samma nyckel ger samma resultat, aldrig dubbla fakturor eller verifikationer.$faq$, $faq$Nätverksfel gör att klienter ibland inte vet om ett anrop nådde fram. Skrivande endpoints (skapa faktura, registrera betalning, bokföra) stödjer därför idempotensnycklar: sätt en unik Idempotency-Key-header per logisk operation, så returnerar ett omförsök med samma nyckel det ursprungliga resultatet i stället för att skapa en dubblett. Generera nyckeln deterministiskt från din källdata (t.ex. ordernummer) så skyddar den även mot dubbletter från din egen sida. Nordklarts interna automation använder samma princip — varje automatiskt beslut har en deterministisk nyckel.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/api']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-031', 'Import/export, SIE, API & webhooks', 'exportera_arkiv', $faq$["Kan jag exportera hela bokföringen med dokument?","Ta ut ett komplett arkiv från Nordklart?","Backup av allt inför systembyte?"]$faq$::jsonb, $faq$Ja: SIE-filer per räkenskapsår plus dokumentarkivet som zip ger ett komplett, systemoberoende arkiv av räkenskapsinformationen.$faq$, $faq$För ett fullständigt arkiv kombinerar du: 1) SIE4-export per räkenskapsår (hela bokföringen maskinläsbart), 2) dokumentexport — alla kvitton, fakturor och underlag som zip med koppling till verifikationsnummer, 3) rapporter som PDF (huvudbok, resultat- och balansräkning per år) för mänsklig läsbarhet, och 4) registerexporter (kunder, leverantörer, artiklar) som CSV. Detta uppfyller arkiveringsansvaret enligt bokföringslagen oberoende av system. Gör alltid en komplett export innan ett konto avslutas — arkiveringsplikten på 7 år ligger kvar på företaget.$faq$, $faq$["BFL 7 kap"]$faq$::jsonb, array['admin']::text[], array['/import', '/settings/backup']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-032', 'Import/export, SIE, API & webhooks', 'cloud_backup', $faq$["Kan Nordklart säkerhetskopiera till Google Drive?","Automatisk backup av bokföringen?","Molnbackup — hur aktiveras den?"]$faq$::jsonb, $faq$Ja, med backup-tillägget synkas SIE-filer och dokument automatiskt till din egen Google Drive enligt schema.$faq$, $faq$Molnbackup-tillägget kopplar företagets Nordklart-konto till din Google Drive: du godkänner åtkomst till en dedikerad mapp, och Nordklart synkar dit regelbundet — SIE-exporter av bokföringen och kopior av dokumentarkivet. Synken körs schemalagt och status (senaste lyckade backup, eventuella fel) visas i tilläggets inställningar. Backupen är din egen kopia utanför Nordklart, vilket ger extra trygghet och uppfyller önskemål om rådighet över räkenskapsinformationen. Den ersätter inte Nordklarts egen driftbackup utan kompletterar den.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/backup']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-033', 'Import/export, SIE, API & webhooks', 'gdpr_dataexport', $faq$["Kan jag få ut mina personuppgifter enligt GDPR?","Dataportabilitet — hur exporterar jag allt?","Registerutdrag från Nordklart?"]$faq$::jsonb, $faq$Ja. Företagets data exporteras via SIE-, dokument- och registerexporterna; personuppgiftsförfrågningar hanteras via supporten enligt GDPR.$faq$, $faq$GDPR ger rätt till tillgång och dataportabilitet. Företagsdata får du ut själv: bokföringen som SIE, dokumenten som zip och registren som CSV — maskinläsbara, systemoberoende format. För registerutdrag som rör dig som person (kontouppgifter, aktivitetsloggar) kontaktar du supporten som hanterar förfrågan inom lagens tidsfrist. Observera konflikten radering kontra arkivering: uppgifter som ingår i räkenskapsinformation kan inte raderas under bokföringslagens 7-åriga arkiveringstid — den rättsliga förpliktelsen går före raderingsrätten.$faq$, $faq$["GDPR art. 15, 17, 20","BFL 7 kap 2 §"]$faq$::jsonb, '{}'::text[], array['/settings/account']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-034', 'Import/export, SIE, API & webhooks', 'importfel_vanliga', $faq$["Varför misslyckas min import?","Vanliga fel vid SIE- och filimport?","Importen ger felmeddelande — vad kontrollerar jag?"]$faq$::jsonb, $faq$Vanligast: fel filformat/kodning, obalanserade verifikationer, datum utanför räkenskapsåret, dubblettfil eller obalanserad öppningsbalans.$faq$, $faq$Checklista vid importfel: 1) Filformat — är det verkligen en SIE-fil (textfil med #-poster) respektive rätt bankformat? Excel-filer måste sparas som CSV. 2) Teckenkodning — trasiga å/ä/ö tyder på kodningsproblem; exportera om från källprogrammet. 3) Obalanserad verifikation — felmeddelandet anger vilken; rätta i källan. 4) Datum utanför räkenskapsåret — kontrollera att företagets räkenskapsår i Nordklart matchar filens #RAR. 5) Dubblett — samma fil är redan importerad för företaget; det är ett skydd, inte ett fel. 6) Öppningsbalans som inte balanserar — tillgångar måste vara lika med eget kapital + skulder. Felmeddelandena anger rad eller post så långt det går.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('import-035', 'Import/export, SIE, API & webhooks', 'import_status_polling', $faq$["Hur följer jag en pågående import?","Var ser jag om importen är klar?","Importstatus och resultat?"]$faq$::jsonb, $faq$Varje import har en statusvy: pågår, slutförd eller misslyckad — med resultat (antal skapade, dubbletter, varningar) och åtgärdslänkar.$faq$, $faq$Importer körs som spårbara operationer: när du startat en bankfils- eller SIE-import ser du status i realtid — validerar, importerar, slutförd eller misslyckad. Resultatet visar antal skapade transaktioner/verifikationer, överhoppade dubbletter, automatiskt matchade poster och varningar (t.ex. SIE-överlapp). Misslyckade importer lämnar ingen halvfärdig data — de rullas tillbaka och kan köras om säkert. Historiken över tidigare importer med vem som körde dem och när finns kvar i importvyn och i audit-loggen.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-001', 'Leverantörsfakturor, kvitton & OCR', 'ladda_upp_leverantorsfaktura', $faq$["Hur laddar jag upp en leverantörsfaktura?","Var lägger jag in fakturor jag fått från leverantörer?","Kan jag ladda upp en PDF-faktura?","Registrera inkommande faktura?"]$faq$::jsonb, $faq$Gå till Leverantörsfakturor → Ladda upp och dra in PDF eller bild. Nordklart tolkar fakturan automatiskt och skapar ett granskningsförslag.$faq$, $faq$Under Leverantörsfakturor kan du ladda upp PDF, JPG eller PNG. Nordklart kör automatisk tolkning (OCR/AI-extraktion) som läser ut leverantör, fakturanummer, OCR-nummer, belopp, moms, faktura- och förfallodatum. Resultatet blir ett förslag som du granskar innan något bokförs — inget bokförs automatiskt utan din kontroll eller aktiverad automation. Dokumentet arkiveras och kopplas till verifikationen när fakturan bokförs.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-002', 'Leverantörsfakturor, kvitton & OCR', 'ocr_tolkning_funktion', $faq$["Hur fungerar OCR-tolkningen av fakturor?","Vad läser Nordklart ut ur en uppladdad faktura?","Vilka fält extraheras automatiskt?"]$faq$::jsonb, $faq$Tolkningen läser ut leverantör, organisationsnummer, fakturanummer, OCR, belopp, moms per sats, datum, förfallodatum och bank-/plusgiro.$faq$, $faq$Nordklarts dokumenttolkning kombinerar textigenkänning med AI-extraktion. Fält som tolkas: leverantörsnamn och organisationsnummer, fakturanummer, OCR-/betalningsreferens, totalbelopp, momsbelopp per momssats, fakturadatum, förfallodatum, valuta samt bankgiro/plusgiro. Varje fält får en tillförlitlighetsnivå. Osäkra fält markeras för manuell kontroll, och du kan alltid korrigera innan bokföring. Tolkningen är ett hjälpmedel — du ansvarar för att uppgifterna stämmer mot originalfakturan.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-003', 'Leverantörsfakturor, kvitton & OCR', 'fakturainkorg_epost', $faq$["Kan leverantörer mejla fakturor direkt till Nordklart?","Finns det en e-postadress för fakturainkorg?","Hur får jag in fakturor via mejl automatiskt?"]$faq$::jsonb, $faq$Ja, med tillägget Fakturainkorg får företaget en unik e-postadress. Fakturor som skickas dit tolkas automatiskt och hamnar för granskning.$faq$, $faq$Aktivera tillägget Fakturainkorg under Inställningar → Tillägg. Företaget får då en unik inkommande e-postadress som du kan ge till leverantörer eller vidarebefordra fakturor till. Bilagor (PDF/bild) tolkas automatiskt, dubbletter upptäcks, och varje faktura blir ett granskningsförslag i Leverantörsfakturor. Inget bokförs utan att du godkänner, om du inte uttryckligen aktiverat automation för säkra fall.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/supplier-invoices', '/settings']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-004', 'Leverantörsfakturor, kvitton & OCR', 'vantande_atgard_leverantorsfaktura', $faq$["Vad händer efter att jag laddat upp en faktura?","Varför ligger min leverantörsfaktura under väntande åtgärder?","Vad betyder att fakturan väntar på granskning?"]$faq$::jsonb, $faq$Uppladdade fakturor blir väntande åtgärder med föreslagen kontering. Du granskar, justerar vid behov och godkänner — först då bokförs den.$faq$, $faq$Efter tolkning skapar Nordklart en väntande åtgärd med föreslagen kontering: kostnadskonto utifrån leverantör/historik, ingående moms (2641) och leverantörsskuld (2440). Du ser tolkade fält, tillförlitlighet och det bifogade dokumentet sida vid sida. Godkänn för att bokföra, redigera förslaget först, eller avvisa. Alla beslut auditloggas med vem som godkände och när. Osäker momsbehandling gör alltid att fakturan stannar för manuell granskning.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/pending', '/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-005', 'Leverantörsfakturor, kvitton & OCR', 'granska_falt_innan_bokforing', $faq$["Måste jag kontrollera tolkade fält innan bokföring?","Kan jag ändra beloppet som OCR-tolkningen föreslog?","Hur rättar jag felaktigt tolkad faktura?"]$faq$::jsonb, $faq$Ja, granska alltid. Alla tolkade fält kan redigeras i granskningsvyn innan du godkänner bokföringen.$faq$, $faq$Innan en tolkad faktura bokförs kan du ändra samtliga fält: leverantör, belopp, moms, datum, konto och betalreferens. Fält med låg tillförlitlighet är markerade. Om totalbelopp eller moms inte stämmer med dokumentet ska du rätta innan godkännande — det bokförda underlaget måste spegla originalfakturan enligt bokföringslagen. Ändringar loggas, och dokumentet förblir kopplat till verifikationen.$faq$, $faq$["BFL 5 kap 7 §"]$faq$::jsonb, '{}'::text[], array['/pending', '/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-006', 'Leverantörsfakturor, kvitton & OCR', 'dubblettdetektering', $faq$["Hur upptäcker Nordklart dubblettfakturor?","Vad händer om jag laddar upp samma faktura två gånger?","Kan samma leverantörsfaktura bokföras dubbelt?"]$faq$::jsonb, $faq$Nordklart jämför leverantör, fakturanummer, OCR, belopp och datum. Misstänkta dubbletter varnas eller blockeras innan bokföring.$faq$, $faq$Vid uppladdning och tolkning kontrolleras fakturan mot företagets befintliga leverantörsfakturor: samma leverantör + samma fakturanummer eller OCR-referens flaggas som trolig dubblett, och samma belopp + närliggande datum ger en varning. En flaggad dubblett bokförs aldrig automatiskt — du får ta ställning i granskningsvyn och kan avvisa den eller bekräfta att det faktiskt är en ny faktura. Även själva filens innehåll (hash) jämförs så att exakt samma dokument inte skapar två poster.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/pending']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-007', 'Leverantörsfakturor, kvitton & OCR', 'samma_ocr_varning', $faq$["Varför varnar systemet om samma OCR-nummer?","Två fakturor med samma OCR från samma leverantör — vad gör jag?","Dubblett-OCR-varning, vad betyder den?"]$faq$::jsonb, $faq$Samma OCR-referens från samma leverantör tyder nästan alltid på dubblett. Kontrollera originalen — avvisa dubbletten eller bekräfta medvetet.$faq$, $faq$OCR-referensen identifierar normalt en specifik faktura, så två fakturor från samma leverantör med identisk OCR är en stark dubblettsignal. Nordklart blockerar automatisk bokföring i det läget och kräver manuellt beslut. Jämför fakturanummer, datum och belopp mot originalen. Är det en påminnelse för en redan registrerad faktura ska den inte bokföras igen — koppla i stället betalningen till den befintliga fakturan.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-008', 'Leverantörsfakturor, kvitton & OCR', 'bokfora_leverantorsfaktura', $faq$["Hur bokförs en leverantörsfaktura?","Vilka konton används när jag godkänner en leverantörsfaktura?","Vad är konto 2440?"]$faq$::jsonb, $faq$Kostnadskonto debiteras, ingående moms 2641 debiteras och leverantörsskulder 2440 krediteras. Vid betalning bokas 2440 mot 1930.$faq$, $faq$Med fakturametoden bokförs leverantörsfakturan när den ankommer: debet på kostnadskontot (t.ex. 4010 varuinköp, 5410 förbrukningsinventarier, 6540 IT-tjänster), debet 2641 ingående moms och kredit 2440 leverantörsskulder. När fakturan sedan betalas bokförs debet 2440 mot kredit 1930 företagskonto. Nordklart föreslår kostnadskonto utifrån leverantörens historik och tolkat innehåll, och betalningen matchas automatiskt mot banktransaktionen när referens och belopp stämmer.$faq$, $faq$["BAS 2026"]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-009', 'Leverantörsfakturor, kvitton & OCR', 'kontantmetod_leverantorsfaktura', $faq$["Hur hanteras leverantörsfakturor med kontantmetoden?","Jag bokför enligt kontantmetoden — när bokförs inköpet?","Skillnad fakturametod och kontantmetod för inköp?"]$faq$::jsonb, $faq$Med kontantmetoden bokförs inköpet först när fakturan betalas — direkt mot bank, utan 2440. Vid räkenskapsårets slut bokförs dock obetalda fakturor.$faq$, $faq$Kontantmetoden (tillåten vid nettoomsättning under 3 mkr) innebär att leverantörsfakturan bokförs vid betalningstillfället: debet kostnadskonto och 2641 ingående moms, kredit 1930 — konto 2440 används inte löpande. Undantag: vid räkenskapsårets utgång ska obetalda leverantörsfakturor ändå bokföras som skuld. Nordklart följer företagets valda bokföringsmetod från inställningarna, och uppladdade fakturor väntar då på betalningsmatchning i stället för att skapa skuld direkt.$faq$, $faq$["BFL 5 kap 2 §"]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/settings/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-010', 'Leverantörsfakturor, kvitton & OCR', 'matcha_leverantorsbetalning', $faq$["Hur matchas en betalning mot leverantörsfakturan?","Jag har betalat en leverantör — kopplas det automatiskt?","Matcha banktransaktion mot leverantörsfaktura?"]$faq$::jsonb, $faq$När betalningen syns på banken matchar Nordklart den mot öppna leverantörsfakturor via OCR/referens, belopp, leverantör och datum.$faq$, $faq$Utgående banktransaktioner jämförs mot företagets öppna leverantörsfakturor. Starkast signal är exakt OCR-/betalningsreferens eller fakturanummer i transaktionstexten, därefter kombinationen leverantör + exakt belopp + rimligt datum mot förfallodag. En säker träff föreslås eller bokförs enligt dina automationsinställningar — automatisk betalningsbokning av leverantörsfakturor är avstängd som standard och kräver aktivt val. Tvetydiga fall (flera möjliga fakturor) blir alltid manuell granskning.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/supplier-invoices', '/settings/banking']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-011', 'Leverantörsfakturor, kvitton & OCR', 'krav_automatisk_leverantorsmatchning', $faq$["När vågar systemet automatiskt matcha en leverantörsbetalning?","Vilka krav gäller för automatisk leverantörsmatchning?","Varför bokfördes inte leverantörsbetalningen automatiskt?"]$faq$::jsonb, $faq$Kräver: godkänd/bokförd faktura, referens- eller stark leverantörs+belopp-träff, rätt riktning och valuta, ingen nära kandidat, och att företagsinställningen tillåter det.$faq$, $faq$Automatisk avräkning av leverantörsfaktura sker bara när samtliga villkor uppfylls: fakturan tillhör samma företag och är bokförd/öppen för betalning, OCR/referens/fakturanummer matchar eller leverantör + exakt belopp + datum ger en stark träff, beloppet går åt rätt håll (utgift), fakturan är inte redan betald, ingen annan faktura ligger nära i poäng, valutan stämmer, perioden är öppen — och företaget har uttryckligen tillåtit automatisk leverantörsavräkning i automationsinställningarna (av som standard). Annars skapas ett förslag eller en väntande åtgärd i stället.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/banking', '/transactions']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-012', 'Leverantörsfakturor, kvitton & OCR', 'varfor_ingen_leverantorsmatchning', $faq$["Varför matchades inte min leverantörsbetalning?","Betalningen kopplades inte till fakturan — varför?","Systemet hittade inte rätt leverantörsfaktura?"]$faq$::jsonb, $faq$Vanliga orsaker: referensen saknas i banktexten, beloppet avviker (t.ex. samlingsbetalning), fakturan är obokförd, eller flera fakturor är för lika.$faq$, $faq$Kontrollera i tur och ordning: 1) Finns fakturan registrerad och bokförd i Nordklart? Obokförda fakturor kan inte matchas. 2) Innehåller banktransaktionens text OCR eller fakturanummer? Vissa banker skickar bara mottagarnamn. 3) Stämmer beloppet exakt? Samlingsbetalningar av flera fakturor matchas inte automatiskt. 4) Finns flera öppna fakturor från samma leverantör med liknande belopp? Då stoppas automatiken av tvetydighet. Du kan alltid matcha manuellt från transaktionsvyn — välj transaktionen och koppla rätt faktura. Matchningsloggen på transaktionen visar exakt vilka kandidater som utvärderades och varför de avvisades.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-013', 'Leverantörsfakturor, kvitton & OCR', 'delbetalning_leverantorsfaktura', $faq$["Kan jag delbetala en leverantörsfaktura?","Hur registrerar jag att halva fakturan är betald?","Delbetalning till leverantör — hur bokförs det?"]$faq$::jsonb, $faq$Ja. Betalningen bokförs mot 2440 med det betalda beloppet och fakturan visas som delbetald med kvarstående skuld.$faq$, $faq$Vid delbetalning bokförs debet 2440 leverantörsskulder och kredit 1930 med det faktiskt betalda beloppet. Fakturan behåller status delbetald och reskontran visar återstående skuld. Automatisk matchning av delbetalningar är återhållsam — de blir normalt förslag för manuell bekräftelse eftersom ett avvikande belopp också kan betyda fel faktura. När resterande belopp betalas kopplas även den transaktionen och fakturan markeras fullbetald.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-014', 'Leverantörsfakturor, kvitton & OCR', 'leverantorsfaktura_utlandsk_valuta', $faq$["Hur hanterar jag en leverantörsfaktura i euro?","Faktura i utländsk valuta — vilken kurs används?","Bokföra faktura i USD?"]$faq$::jsonb, $faq$Fakturan bokförs i SEK med kursen på fakturadatumet. Vid betalning används betalningsdagens kurs och mellanskillnaden blir valutakursdifferens.$faq$, $faq$Nordklart hämtar växelkurs från Riksbanken per fakturadatum och bokför skulden i SEK. Originalvaluta och belopp sparas på fakturan. När betalningen sker omräknas den till betalningsdagens kurs; skillnaden bokförs som valutakursvinst (3960) eller valutakursförlust (7960). Saknas kurs för datumet skapas en väntande åtgärd i stället för att gissa. Momsen på EU-/importfakturor hanteras enligt fakturans momsbehandling (ofta omvänd betalningsskyldighet).$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-015', 'Leverantörsfakturor, kvitton & OCR', 'valutakursdifferens_betalning', $faq$["Vad är valutakursdifferens vid leverantörsbetalning?","Beloppet på banken stämmer inte med fakturan i euro?","Hur bokförs kursvinst och kursförlust?"]$faq$::jsonb, $faq$Skillnaden mellan bokförd skuld (fakturadagens kurs) och faktisk betalning (betalningsdagens kurs) bokförs på 3960 (vinst) eller 7960 (förlust).$faq$, $faq$En faktura på 1 000 EUR bokförd till kurs 11,50 ger skuld 11 500 SEK. Betalas den när kursen är 11,60 dras 11 600 SEK från banken. Differensen 100 SEK bokförs som valutakursförlust på 7960 (eller motsvarande vinst på 3960 om kursen sjunkit). Nordklart beräknar och bokför differensen automatiskt när betalningen matchas mot fakturan, så att både 2440 och banken stäms av korrekt. Kursdatumen sparas på verifikationen för spårbarhet.$faq$, $faq$["BAS 2026"]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-016', 'Leverantörsfakturor, kvitton & OCR', 'omvand_skattskyldighet_eu_tjanst', $faq$["Hur bokför jag en faktura från Google eller AWS utan moms?","EU-faktura med reverse charge — vad gör jag?","Omvänd betalningsskyldighet på tjänst från utlandet?"]$faq$::jsonb, $faq$Tjänsteinköp från utlandet bokförs med omvänd betalningsskyldighet: du redovisar både utgående (2614) och ingående (2645) moms — normalt ett nollsummespel.$faq$, $faq$Fakturor från t.ex. Google Ireland, AWS eller OpenAI kommer utan moms eftersom köparen är skattskyldig. Bokföring: debet kostnadskonto (t.ex. 6540), kredit 2614 utgående moms omvänd skattskyldighet 25 %, debet 2645 ingående moms utland — momsen tar ut sig själv vid full avdragsrätt men måste redovisas i momsdeklarationen (ruta 21/22 för beskattningsunderlaget, ruta 30 utgående, ruta 48 ingående). Nordklart känner igen vanliga utländska leverantörer och föreslår rätt momsbehandling; oklar behandling stoppar automatisk bokföring och blir en väntande åtgärd.$faq$, $faq$["ML 16 kap","Momsdeklaration ruta 21-22, 30, 48"]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/reports']::text[], 'medium', $faq$Vid osäkerhet om en utländsk faktura ska hanteras med omvänd betalningsskyldighet, stäm av med redovisningskonsult eller Skatteverket.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-017', 'Leverantörsfakturor, kvitton & OCR', 'byggmoms_omvand', $faq$["Vad är omvänd byggmoms?","Faktura från underentreprenör utan moms — hur bokförs den?","Omvänd betalningsskyldighet inom byggsektorn?"]$faq$::jsonb, $faq$Byggtjänster mellan byggföretag faktureras utan moms. Köparen redovisar utgående moms på 2617 och drar samtidigt ingående moms på 2647.$faq$, $faq$Omvänd betalningsskyldighet gäller när ett byggföretag köper byggtjänster av ett annat (ML 16 kap 13 §). Leverantörens faktura ska sakna moms och ange 'omvänd betalningsskyldighet'. Du bokför: debet kostnadskonto (t.ex. 4425 inköp byggtjänster omvänd moms), kredit 2617 utgående byggmoms 25 %, debet 2647 ingående byggmoms. I momsdeklarationen redovisas underlaget i ruta 24, utgående moms i ruta 30 och ingående i ruta 48. Nordklart hanterar detta via momsbehandlingen 'byggtjänst omvänd' på fakturan eller leverantören.$faq$, $faq$["ML 16 kap 13 §","Momsdeklaration ruta 24"]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'medium', $faq$Bedömningen av om en tjänst omfattas av byggmoms kan vara komplex — kontrollera mot Skatteverkets lista eller fråga en redovisningskonsult.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-018', 'Leverantörsfakturor, kvitton & OCR', 'moms_saknas_pending', $faq$["Vad händer om momsen på fakturan är oklar?","Tolkningen hittade ingen moms — bokförs den ändå?","Faktura utan tydlig momssats?"]$faq$::jsonb, $faq$Oklar moms stoppar all automatik. Fakturan blir en väntande åtgärd där du själv anger korrekt momsbehandling innan bokföring.$faq$, $faq$Nordklart bokför aldrig automatiskt när momsbehandlingen är osäker — fel moms ger fel i momsdeklarationen. Om tolkningen inte säkert kan avgöra momssats, momsbelopp eller om omvänd betalningsskyldighet gäller, skapas en väntande åtgärd med orsakskoden 'oklar momsbehandling'. Du väljer då rätt behandling (25/12/6/0 %, EU-förvärv, import, byggmoms m.m.) och godkänner. Valet kan sparas på leverantören så framtida fakturor får rätt förslag direkt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/pending', '/supplier-invoices']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-019', 'Leverantörsfakturor, kvitton & OCR', 'representation_momsavdrag', $faq$["Hur bokför jag ett representationskvitto?","Får jag dra momsen på en affärslunch?","Representation — vad gäller för momsavdraget?"]$faq$::jsonb, $faq$Momsavdrag för måltidsrepresentation medges på underlag upp till 300 kr exkl. moms per person. Kostnaden över det är ej avdragsgill.$faq$, $faq$Vid extern och intern representation med måltid får du dra ingående moms på ett underlag om högst 300 kr exkl. moms per person och tillfälle (blandad dryck ger schablonberäkning). Själva måltidskostnaden är inte avdragsgill vid inkomstbeskattningen — bokförs på 6072 (ej avdragsgill representation) medan avdragsgill del som enklare förtäring kan gå på 6071. Nordklart har en representationsberäkning som fördelar moms och kostnad korrekt när du anger antal personer. Ange alltid syfte och deltagare på underlaget.$faq$, $faq$["ML 13 kap 27 §","IL 16 kap 2 §"]$faq$::jsonb, '{}'::text[], array['/receipts', '/expenses']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-020', 'Leverantörsfakturor, kvitton & OCR', 'kvitton_ladda_upp', $faq$["Hur laddar jag upp kvitton?","Kan jag fota ett kvitto med mobilen?","Var hamnar mina kvitton i Nordklart?"]$faq$::jsonb, $faq$Under Kvitton laddar du upp foto eller PDF. Kvittot tolkas, får förslag på kontering och kan matchas mot kortköp på banken.$faq$, $faq$Gå till Kvitton och ladda upp en bild eller PDF — mobilkamera fungerar bra så länge text och belopp är läsbara. Nordklart tolkar säljare, datum, belopp och moms, föreslår kostnadskonto och försöker matcha kvittot mot motsvarande korttransaktion från banken. Kvittot arkiveras digitalt och kopplas till verifikationen, vilket uppfyller kravet på underlag. Papperskvitton bör sparas enligt gällande arkiveringsregler tills reglerna om digitalisering är uppfyllda för ditt fall.$faq$, $faq$["BFL 7 kap"]$faq$::jsonb, '{}'::text[], array['/receipts']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-021', 'Leverantörsfakturor, kvitton & OCR', 'kvitto_vs_faktura', $faq$["Vad är skillnaden mellan kvitto och leverantörsfaktura i Nordklart?","Ska jag lägga inköpet under Kvitton eller Leverantörsfakturor?","Kortköp — kvitto eller faktura?"]$faq$::jsonb, $faq$Kvitton är direkt betalda inköp (kort/kontant) utan skuld. Leverantörsfakturor betalas senare och skapar leverantörsskuld på 2440.$faq$, $faq$Använd Kvitton för inköp som redan är betalda vid köptillfället — kortköp, Swish, kontant. De bokförs direkt mot bank/kort utan att gå via 2440 och matchas mot banktransaktionen. Använd Leverantörsfakturor för fakturor med betalvillkor: de skapar en leverantörsskuld (fakturametoden) och betalningen matchas separat när den sker. Väljer du fel typ går det att korrigera innan bokföring; efter bokföring rättar du via ändringsverifikation.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/receipts', '/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-022', 'Leverantörsfakturor, kvitton & OCR', 'dokument_koppling_verifikation', $faq$["Kopplas dokumentet till verifikationen?","Hur ser jag underlaget för en bokförd faktura?","Var hittar jag originalfakturan efter bokföring?"]$faq$::jsonb, $faq$Ja. Uppladdade dokument kopplas till verifikationen och kan öppnas direkt från verifikationslistan eller huvudboken.$faq$, $faq$Varje bokförd leverantörsfaktura och varje kvitto behåller sin dokumentkoppling. Från verifikationen kan du öppna originaldokumentet, och från dokumentarkivet ser du vilken verifikation dokumentet hör till. Kopplingen är en del av räkenskapsinformationen: dokument som är kopplade till bokförda verifikationer skyddas mot radering under hela arkiveringstiden. Det gör revisionen enklare — revisorn kan gå från siffra till underlag med ett klick.$faq$, $faq$["BFL 7 kap 1-2 §§"]$faq$::jsonb, '{}'::text[], array['/bookkeeping', '/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-023', 'Leverantörsfakturor, kvitton & OCR', 'arkivering_radera_dokument', $faq$["Kan jag radera ett uppladdat dokument?","Varför går det inte att ta bort fakturan jag laddade upp?","Hur länge sparas dokument i Nordklart?"]$faq$::jsonb, $faq$Dokument kopplade till bokförda verifikationer kan inte raderas — de är räkenskapsinformation som ska arkiveras i 7 år enligt bokföringslagen.$faq$, $faq$Bokföringslagen kräver att räkenskapsinformation bevaras i 7 år efter utgången av det kalenderår räkenskapsåret avslutades. Nordklart skyddar därför dokument som är kopplade till bokförda verifikationer mot radering — det är en databasspärr, inte bara en varning. Dokument som inte kopplats till någon bokföring (t.ex. en felaktig uppladdning som avvisades) kan tas bort. Vid byte av system ska du exportera hela arkivet innan kontot avslutas.$faq$, $faq$["BFL 7 kap 2 §"]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/settings/backup']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-024', 'Leverantörsfakturor, kvitton & OCR', 'misslyckad_ocr', $faq$["OCR-tolkningen misslyckades — vad gör jag?","Fakturan kunde inte tolkas, hur går jag vidare?","Tolkningsfel på uppladdad faktura?"]$faq$::jsonb, $faq$Dokumentet ligger kvar med status 'tolkning misslyckades'. Försök igen, ladda upp en tydligare bild eller registrera fakturan manuellt.$faq$, $faq$Om tolkningen misslyckas (dålig bildkvalitet, ovanligt format, skyddad PDF) visas dokumentet med felstatus och en förklaring. Åtgärder: 1) klicka 'Försök igen' — tillfälliga fel löses ofta av ett nytt försök, 2) ladda upp en skarpare bild eller PDF-originalet i stället för foto, 3) registrera fakturans uppgifter manuellt och koppla dokumentet som underlag. Ingenting bokförs vid misslyckad tolkning, så det finns ingen risk för felaktiga poster.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-025', 'Leverantörsfakturor, kvitton & OCR', 'ocr_retry_automatisk', $faq$["Försöker systemet tolka om automatiskt vid fel?","Behöver jag klicka igen om tolkningen kraschar?","Hur hanteras tillfälliga tolkningsfel?"]$faq$::jsonb, $faq$Ja, tillfälliga fel (tidsgränser, överbelastning) försöks om automatiskt med stigande väntetid. Först efter upprepade fel markeras dokumentet som misslyckat.$faq$, $faq$Tolkningstjänsten skiljer på tillfälliga och permanenta fel. Tillfälliga fel — nätverksproblem, tidsgränser, hög belastning hos AI-tjänsten — försöks om automatiskt med exponentiell backoff. Permanenta fel (oläsbart dokument, format som inte stöds) markeras direkt som misslyckade med tydlig orsak i gränssnittet. Du ser dokumentets aktuella status i listan: väntar, tolkas, klar för granskning eller misslyckad, och kan alltid starta ett nytt försök manuellt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-026', 'Leverantörsfakturor, kvitton & OCR', 'kreditfaktura_fran_leverantor', $faq$["Jag fick en kreditfaktura från en leverantör — hur bokförs den?","Leverantören krediterade fakturan, vad gör jag?","Hantera kreditnota från leverantör?"]$faq$::jsonb, $faq$Kreditfakturan bokförs spegelvänt: debet 2440, kredit kostnadskonto och kredit 2641. Den kvittas mot ursprungsfakturan i reskontran.$faq$, $faq$En kreditfaktura från leverantör minskar din skuld och kostnad: debet 2440 leverantörsskulder, kredit ursprungligt kostnadskonto och kredit 2641 ingående moms (momsen ska följa ursprungsfakturans sats). Registrera den som leverantörsfaktura med negativt belopp eller via kredit-flödet och koppla mot ursprungsfakturan så att reskontran visar nettoskulden. Betalar leverantören ut beloppet i stället matchas insättningen mot kreditfakturan; kvittas den mot nästa faktura matchas nettobetalningen mot båda.$faq$, $faq$["ML 17 kap"]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-027', 'Leverantörsfakturor, kvitton & OCR', 'lagga_till_leverantor', $faq$["Hur lägger jag till en ny leverantör?","Var registrerar jag leverantörsuppgifter?","Kan leverantörer skapas automatiskt vid tolkning?"]$faq$::jsonb, $faq$Under Leverantörer skapar du leverantörer manuellt, eller låter tolkningen föreslå en ny leverantör från fakturan — organisationsnummer kan slås upp automatiskt.$faq$, $faq$Gå till Leverantörer → Ny leverantör och ange namn, organisationsnummer, bankgiro/plusgiro och standardkostnadskonto. Med organisationsnummer kan uppgifter hämtas via företagsuppslag. När en faktura tolkas från en okänd leverantör föreslår Nordklart att skapa leverantören med tolkade uppgifter — du bekräftar innan den sparas. Standardkonto och momsbehandling på leverantören styr framtida konteringsförslag, vilket gör automatiken träffsäkrare för varje faktura.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/suppliers']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-028', 'Leverantörsfakturor, kvitton & OCR', 'leverantorsreskontra', $faq$["Var ser jag obetalda leverantörsfakturor?","Vad är leverantörsreskontra?","Hur mycket är vi skyldiga leverantörer just nu?"]$faq$::jsonb, $faq$Leverantörsreskontran listar alla obetalda och delbetalda leverantörsfakturor med förfallodatum. Summan ska stämma mot konto 2440.$faq$, $faq$Leverantörsreskontran (under Leverantörsfakturor eller Rapporter) visar öppna poster per leverantör: fakturanummer, belopp, betalt, kvarstående och förfallodatum, med markering av förfallna fakturor. Reskontrans summa ska stämma överens med saldot på 2440 i huvudboken — en avvikelse tyder på direktbokningar utanför fakturaflödet och flaggas i bokslutskontrollerna. Rapporten går att exportera och ligger till grund för leverantörsavstämningen vid bokslut.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/reports']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-029', 'Leverantörsfakturor, kvitton & OCR', 'forfallodatum_bevakning', $faq$["Kan Nordklart påminna mig om fakturor som ska betalas?","Hur bevakar jag förfallodatum på leverantörsfakturor?","Missa inte betalningar — finns notiser?"]$faq$::jsonb, $faq$Ja, förfallodatum bevakas i deadlinevyn och på översikten. Fakturor som närmar sig eller passerat förfall markeras tydligt.$faq$, $faq$Registrerade leverantörsfakturor med förfallodatum syns i Nordklarts deadline-bevakning tillsammans med moms- och skattedeadlines. Översikten visar fakturor som förfaller snart och fakturor som redan förfallit. Notiser kan aktiveras under inställningarna (e-post och/eller push om tillägget är aktivt). Observera att Nordklart inte betalar fakturor åt dig — betalningen gör du i internetbanken, och Nordklart matchar sedan transaktionen mot fakturan.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/deadlines', '/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-030', 'Leverantörsfakturor, kvitton & OCR', 'attestflode_godkannande', $faq$["Finns attestflöde för leverantörsfakturor?","Kan en kollega godkänna fakturor innan bokföring?","Vem får godkänna leverantörsfakturor?"]$faq$::jsonb, $faq$Granskningen i väntande åtgärder fungerar som attest: bara medlemmar med skrivbehörighet kan godkänna, och varje beslut loggas med användare och tidpunkt.$faq$, $faq$Tolkningsförslag för leverantörsfakturor hamnar i väntande åtgärder där de kräver aktivt godkännande innan bokföring. Endast användare med skrivbehörighet i företaget (owner, admin eller member) kan godkänna eller avvisa — viewers kan bara titta. Varje godkännande, avvisning och redigering auditloggas med användare, tidpunkt och vad som ändrades, vilket ger full spårbarhet på vem som släppte igenom vilken kostnad.$faq$, $faq$[]$faq$::jsonb, array['member']::text[], array['/pending', '/settings/team']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-031', 'Leverantörsfakturor, kvitton & OCR', 'auto_betalning_installning', $faq$["Kan systemet bokföra leverantörsbetalningar helt automatiskt?","Varför är automatisk leverantörsavräkning avstängd?","Slå på automatisk matchning av leverantörsbetalningar?"]$faq$::jsonb, $faq$Automatisk avräkning av leverantörsbetalningar är avstängd som standard och aktiveras medvetet under Inställningar → Bank & automation.$faq$, $faq$Leverantörsbetalningar är känsligare än kundinbetalningar — fel matchning påverkar både reskontra och kostnadsbild. Därför är 'tillåt automatisk leverantörsavräkning' av som standard. En administratör kan aktivera den under automationsinställningarna; då avräknas bara betalningar som klarar alla säkerhetskrav (referensträff, exakt belopp, entydig kandidat, öppen period, under beloppsgräns). Allt annat blir förslag. Varje automatisk avräkning loggas med konfidens och orsakskoder och kan granskas i efterhand.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/banking']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-032', 'Leverantörsfakturor, kvitton & OCR', 'periodisering_leverantorsfaktura', $faq$["Hur periodiserar jag en leverantörsfaktura?","Fakturan avser hela året — kan kostnaden fördelas per månad?","Periodisera försäkringsfaktura?"]$faq$::jsonb, $faq$Vid bokföring kan du välja periodisering: kostnaden läggs på 1790 och upplöses månadsvis till kostnadskontot under avtalsperioden.$faq$, $faq$En faktura som avser flera perioder (försäkring, licens, hyra) kan periodiseras direkt i bokföringsflödet: ange periodens start och slut så bokförs beloppet först som förutbetald kostnad (1790) och upplöses sedan automatiskt månad för månad till kostnadskontot. Upplösningarna skapas av periodiseringsmotorn och bokförs via det schemalagda jobbet — respekterar periodlås och loggas per månad. K2-företag kan använda 5 000-kronorsregeln och slippa periodisera små belopp.$faq$, $faq$["BFNAR 2016:10 punkt 7.9"]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-033', 'Leverantörsfakturor, kvitton & OCR', 'bankgiro_validering_leverantor', $faq$["Kontrolleras leverantörens bankgironummer?","Hur vet jag att bankgirot på fakturan är giltigt?","Validering av plusgiro och bankgiro?"]$faq$::jsonb, $faq$Ja, tolkade bankgiro-/plusgironummer valideras med Luhn-kontrollsiffra. Avvikelse mot leverantörens sparade nummer flaggas som varning.$faq$, $faq$Bankgiro- och plusgironummer har inbyggd kontrollsiffra (Luhn/mod10) som Nordklart validerar vid tolkning — ett feltolkat nummer fångas ofta direkt. Dessutom jämförs numret mot det som finns sparat på leverantören: om en faktura plötsligt anger ett annat bankgiro än tidigare visas en varning, eftersom det kan vara ett tecken på fakturabedrägeri. Kontrollera alltid nya betalningsuppgifter mot leverantören via en oberoende kanal innan du betalar.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/suppliers']::text[], 'high', $faq$Vid misstänkt ändrade betalningsuppgifter: betala inte förrän du verifierat med leverantören via känt telefonnummer — fakturabedrägerier med utbytta bankgiron är vanliga.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-034', 'Leverantörsfakturor, kvitton & OCR', 'ai_extraktion_falt', $faq$["Använder Nordklart AI för att tolka fakturor?","Hur säker är AI-tolkningen?","Skickas mina fakturor till någon AI-tjänst?"]$faq$::jsonb, $faq$Ja, dokumenttolkningen använder AI-modeller. Varje fält får en tillförlitlighetsnivå och osäkra fält kräver alltid manuell bekräftelse.$faq$, $faq$Dokumenttolkningen använder AI-tjänster för att läsa ut strukturerade fält ur fakturor och kvitton. Tolkningen är probabilistisk: varje fält får en tillförlitlighetspoäng, och fält under tröskeln markeras för manuell kontroll. AI:n fattar aldrig bokföringsbeslut själv — den producerar förslag som går genom samma gransknings- och automationsregler som allt annat. Dokumentdata behandlas enligt personuppgiftsbiträdesavtalet; känsliga dokument som inte ska tolkas kan registreras manuellt i stället.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lev-035', 'Leverantörsfakturor, kvitton & OCR', 'extraktion_fel_belopp', $faq$["Tolkningen läste fel belopp — vad gör jag?","Beloppet i förslaget stämmer inte med fakturan?","AI:n tolkade summan fel, hur rättar jag?"]$faq$::jsonb, $faq$Rätta beloppet direkt i granskningsvyn innan du godkänner. Är fakturan redan bokförd rättar du med ändringsverifikation, aldrig genom att ändra i efterhand.$faq$, $faq$Före bokföring: öppna förslaget, korrigera belopp/moms mot originalfakturan och godkänn — rättelsen loggas. Efter bokföring: bokförda verifikationer är oföränderliga enligt bokföringslagen, så rättelse sker via ändringsverifikation (storno) som vänder den felaktiga posten och bokför rätt belopp, med hänvisning mellan verifikationerna. Nordklarts rättelseflöde skapar båda stegen åt dig. Återkommande tolkningsfel för en viss leverantör kan bero på fakturans layout — rapportera gärna exemplet så förbättras tolkningen.$faq$, $faq$["BFL 5 kap 5 §"]$faq$::jsonb, '{}'::text[], array['/supplier-invoices', '/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-001', 'Lön, AGI & F-skatt', 'skapa_lonekorning', $faq$["Hur skapar jag en lönekörning?","Var kör jag lön i Nordklart?","Betala ut lön till anställda?"]$faq$::jsonb, $faq$Under Lön skapar du en lönekörning för månaden: välj anställda, kontrollera bruttolön, förmåner och avdrag, godkänn — då bokförs lönen och AGI-underlag skapas.$faq$, $faq$Gå till Lön → Ny lönekörning. Nordklart hämtar de anställdas grunduppgifter (månadslön, skattetabell, förmåner) och beräknar bruttolön, preliminärskatt enligt skattetabell, arbetsgivaravgifter och nettolön. Du kan lägga till rörliga delar som övertid, OB och avdrag per person. När du godkänner körningen skapas lönebesked, bokföringsverifikation och underlag till arbetsgivardeklarationen (AGI). Själva utbetalningen gör du från banken — Nordklart matchar sedan banktransaktionen mot lönekörningen.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-002', 'Lön, AGI & F-skatt', 'lonebesked', $faq$["Hur får de anställda sina lönebesked?","Kan jag skriva ut lönespecifikationer?","Var hittar jag lönebeskeden?"]$faq$::jsonb, $faq$Lönebesked genereras som PDF för varje anställd i lönekörningen och kan laddas ner eller skickas via e-post.$faq$, $faq$När en lönekörning godkänns skapas lönebesked (lönespecifikation) per anställd med bruttolön, skatteavdrag, förmåner, avdrag, nettolön samt ackumulerade värden för året. Beskeden finns som PDF under lönekörningen och kan laddas ner eller distribueras till de anställda. Lönebesked är inte lagstadgade i formen men följer god sed — de anställda behöver dem för att kontrollera skatteavdrag mot Skatteverket.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-003', 'Lön, AGI & F-skatt', 'arbetsgivaravgifter', $faq$["Hur mycket är arbetsgivaravgifterna?","Vad kostar en anställd utöver lönen?","Vilka avgifter ingår i 31,42 procent?"]$faq$::jsonb, $faq$Fulla arbetsgivaravgifter är 31,42 % av bruttolönen och inkluderar ålderspension, sjukförsäkring, föräldraförsäkring m.m. Bokförs på 7510/2731.$faq$, $faq$Arbetsgivaravgifterna är 31,42 % av bruttolön och skattepliktiga förmåner för de flesta anställda. De består av ålderspensionsavgift (10,21 %), sjukförsäkringsavgift, föräldraförsäkringsavgift, arbetsskadeavgift, arbetsmarknadsavgift, efterlevandepensionsavgift och allmän löneavgift. Bokföring: debet 7510 lagstadgade sociala avgifter, kredit 2731 avräkning lagstadgade sociala avgifter. Skulden betalas till skattekontot i samband med AGI månaden efter. Nordklart beräknar avgifterna automatiskt per anställd, inklusive reducerade satser där de gäller.$faq$, $faq$["SAL 2 kap 26 §"]$faq$::jsonb, '{}'::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-004', 'Lön, AGI & F-skatt', 'reducerade_avgifter_alder', $faq$["Är arbetsgivaravgifterna lägre för äldre anställda?","Vad gäller för avgifter för pensionärer?","Reducerade arbetsgivaravgifter för unga eller äldre?"]$faq$::jsonb, $faq$För anställda som fyllt aktuell åldersgräns betalas endast ålderspensionsavgift 10,21 %. Nordklart väljer rätt sats utifrån personnumret.$faq$, $faq$För anställda som vid årets ingång fyllt den åldersgräns som gäller (personer födda 1959 eller tidigare för inkomstår 2026 — gränsen flyttas succesivt) betalas bara ålderspensionsavgiften 10,21 % i stället för fulla 31,42 %. För de allra äldsta (födda 1937 eller tidigare) betalas inga avgifter alls. Nordklart läser åldern från personnumret och tillämpar rätt procentsats automatiskt i lönekörningen och AGI. Kontrollera alltid aktuella åldersgränser vid årsskiften eftersom de justeras i takt med pensionsåldern.$faq$, $faq$["SAL 2 kap 27-28 §§"]$faq$::jsonb, '{}'::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-005', 'Lön, AGI & F-skatt', 'skatteavdrag_tabell', $faq$["Hur beräknas skatteavdraget på lönen?","Vad är en skattetabell?","Vilken skattetabell ska den anställda ha?"]$faq$::jsonb, $faq$Preliminärskatt dras enligt den anställdas skattetabell (styrs av kommunens skattesats) och kolumn. Nordklart slår upp beloppet automatiskt.$faq$, $faq$Skatteavdraget för huvudarbetsgivare görs enligt Skatteverkets skattetabeller (29–42) som motsvarar kommunalskattesatsen, och rätt kolumn utifrån den anställdas situation (kolumn 1 för vanlig lön före 66 år, andra kolumner för pensionärer m.fl.). Nordklart innehåller aktuella tabeller och gör uppslag per anställd och månad. För sidoinkomst dras 30 %. Den anställda kan ha jämkningsbeslut som ändrar avdraget — registrera det på personalkortet. Avdragen skatt bokförs på 2710 personalskatt och betalas via skattekontot.$faq$, $faq$["SFL 11 kap"]$faq$::jsonb, '{}'::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-006', 'Lön, AGI & F-skatt', 'jamkning', $faq$["En anställd har jämkning — hur registrerar jag det?","Vad är jämkningsbeslut?","Ändrat skatteavdrag från Skatteverket?"]$faq$::jsonb, $faq$Registrera Skatteverkets jämkningsbeslut på den anställdas personalkort så används det beslutade avdraget i stället för tabellen.$faq$, $faq$Jämkning innebär att Skatteverket beslutat om ändrad preliminärskatt för en anställd, t.ex. på grund av ränteavdrag eller flera arbetsgivare. Beslutet anger antingen en procentsats eller ett justerat belopp. Lägg in beslutet på den anställda under Lön → Personal, med giltighetstid — då räknar lönekörningen med jämkningen i stället för ordinarie tabellavdrag. Spara beslutet som underlag. När beslutet löper ut återgår beräkningen till skattetabellen automatiskt.$faq$, $faq$["SFL 55 kap"]$faq$::jsonb, array['admin']::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-007', 'Lön, AGI & F-skatt', 'agi_vad_ar', $faq$["Vad är AGI?","Vad är arbetsgivardeklaration på individnivå?","Måste jag lämna AGI varje månad?"]$faq$::jsonb, $faq$AGI är arbetsgivardeklarationen som lämnas månadsvis till Skatteverket med lön, skatteavdrag och arbetsgivaravgifter per anställd.$faq$, $faq$Arbetsgivardeklaration på individnivå (AGI) ska lämnas varje månad av alla som betalat ut lön eller förmåner. Den innehåller huvuduppgift (företagets totala avgifter och avdragen skatt) samt individuppgifter per betalningsmottagare med bruttolön, förmåner och skatteavdrag. AGI ersätter de gamla årliga kontrolluppgifterna för lön. Nordklart genererar AGI-underlaget automatiskt från godkända lönekörningar, och deklarationen kan lämnas via Skatteverkets e-tjänst eller direkt via Nordklarts Skatteverket-koppling om den är aktiverad.$faq$, $faq$["SFL 26 kap 19 a-e §§"]$faq$::jsonb, '{}'::text[], array['/salary', '/skatteverket']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-008', 'Lön, AGI & F-skatt', 'agi_deadline', $faq$["När ska AGI lämnas in?","Vilket datum är AGI-deadline?","När betalas arbetsgivaravgifterna?"]$faq$::jsonb, $faq$AGI ska vara inne och avgifter/skatt betalda den 12:e månaden efter löneutbetalningen (den 17:e i januari och augusti).$faq$, $faq$Deklaration och betalning för en löneutbetalning i t.ex. mars ska vara Skatteverket tillhanda senast den 12 april. I januari och augusti är fristen i stället den 17:e. Större företag (beskattningsunderlag över 40 mkr) har den 26:e. Faller dagen på helg gäller nästa vardag. Nordklart visar AGI-deadlines i deadline-bevakningen och varnar när underlag finns men deklaration inte markerats som inlämnad. Betalningen ska finnas på skattekontot senast på förfallodagen — räkna med bankdagar.$faq$, $faq$["SFL 26 kap 26 §"]$faq$::jsonb, '{}'::text[], array['/deadlines', '/salary']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-009', 'Lön, AGI & F-skatt', 'skicka_agi', $faq$["Hur skickar jag in AGI från Nordklart?","Kan AGI lämnas direkt till Skatteverket?","Exportera AGI-fil?"]$faq$::jsonb, $faq$Med Skatteverket-kopplingen kan AGI lämnas direkt från Nordklart. Annars exporterar du AGI-filen och laddar upp den i Skatteverkets e-tjänst.$faq$, $faq$Efter godkänd lönekörning finns AGI-underlaget under Lön → AGI. Två vägar: 1) Aktivera Skatteverket-tillägget och lämna deklarationen direkt — Nordklart skickar in, bevakar kvittensen och sparar mottagningsbeviset. 2) Exportera AGI som fil och ladda upp manuellt i Skatteverkets e-tjänst Arbetsgivardeklaration. Inlämningen kräver behörighet hos Skatteverket (deklarationsombud eller firmatecknare). Status för varje period visas så du ser vilka månader som är inlämnade, kvitterade eller väntar.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/salary', '/skatteverket', '/settings/skatteverket']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-010', 'Lön, AGI & F-skatt', 'agi_kvitto_pollning', $faq$["Hur vet jag att AGI kom fram till Skatteverket?","Var ser jag kvittensen på inlämnad AGI?","AGI-status visar väntar — vad betyder det?"]$faq$::jsonb, $faq$Nordklart bevakar inlämningen och hämtar Skatteverkets kvittens automatiskt. Status ändras från 'inskickad' till 'kvitterad' när mottagandet bekräftats.$faq$, $faq$När AGI lämnas via Skatteverket-kopplingen får inlämningen ett ärende-id. Nordklart pollar Skatteverkets svarstjänst tills kvittensen kommer och sparar mottagningsbeviset på perioden. Statusflöde: utkast → inskickad → kvitterad, eller avvisad med felmeddelande om Skatteverket inte accepterade deklarationen (t.ex. felaktigt personnummer i en individuppgift). Vid avvisning rättar du underlaget och skickar om. Kvittenser och fel loggas så du alltid kan visa när och vad som lämnats.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/salary', '/skatteverket']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-011', 'Lön, AGI & F-skatt', 'bokforing_lon', $faq$["Hur bokförs en lön?","Vilka konton används vid lönebokföring?","Vad hamnar på 7010 och 2710?"]$faq$::jsonb, $faq$Bruttolön debiteras 7010/7210, personalskatt krediteras 2710, arbetsgivaravgifter bokförs 7510/2731 och nettolönen krediteras 1930 vid utbetalning.$faq$, $faq$En typisk lönekörning bokförs så här: debet 7010 (löner kollektivanställda) eller 7210 (löner tjänstemän) med bruttolönen; kredit 2710 personalskatt med avdragen preliminärskatt; kredit 2731 med arbetsgivaravgifterna och motsvarande debet 7510 lagstadgade sociala avgifter; kredit 1930 (eller 2820 löneskuld om utbetalningen sker senare) med nettolönen. Förmåner läggs till på lönearter och påverkar skatt och avgifter utan att betalas ut. Nordklart skapar verifikationen automatiskt när lönekörningen godkänns.$faq$, $faq$["BAS 2026"]$faq$::jsonb, '{}'::text[], array['/salary', '/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-012', 'Lön, AGI & F-skatt', 'matcha_lonetransaktion', $faq$["Matchas löneutbetalningen mot banken automatiskt?","Banktransaktionen för lönen — kopplas den till lönekörningen?","Hur stäms löneutbetalningar av?"]$faq$::jsonb, $faq$Ja, utgående banktransaktioner som stämmer med lönekörningens nettobelopp och datum matchas mot körningen — säkra träffar kan kopplas automatiskt om inställningen tillåter.$faq$, $faq$När lönen betalats ut jämför Nordklart utgående banktransaktioner mot godkända lönekörningar: nettobeloppet (per anställd eller som klumpsumma) och utbetalningsdatumet ska stämma. En säker träff länkar transaktionen till lönekörningens verifikation så att den inte dyker upp som obokförd. Automatisk länkning kräver att 'tillåt automatisk lönekoppling' är aktiverad i automationsinställningarna — annars läggs ett förslag som du bekräftar. Tvetydiga belopp (t.ex. flera körningar med samma summa) går alltid till manuell granskning.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/salary', '/settings/banking']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-013', 'Lön, AGI & F-skatt', 'semesterloneskuld', $faq$["Vad är semesterlöneskuld?","Hur bokförs intjänad semester?","Måste jag reservera semesterlön?"]$faq$::jsonb, $faq$Intjänad men inte uttagen semester är en skuld som bokförs på 2920 med motsvarande arbetsgivaravgifter på 2941 — kostnadsförs löpande eller vid bokslut.$faq$, $faq$Anställda tjänar in semesterlön löpande (procentregeln ger 12 % av lönen, sammalöneregeln månadslön + 0,43 % per dag). Skulden bokförs: debet 7090 förändring semesterlöneskuld, kredit 2920 upplupna semesterlöner, plus debet 7519, kredit 2941 för arbetsgivaravgifter på skulden. När semestern tas ut löses skulden upp. Nordklart beräknar semesterskulden från löneunderlaget och kan bokföra förändringen per månad eller som bokslutspost. Semesterskuldrapporten visar saldo per anställd.$faq$, $faq$["Semesterlagen 16-16 b §§"]$faq$::jsonb, '{}'::text[], array['/salary', '/reports']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-014', 'Lön, AGI & F-skatt', 'semestertillagg', $faq$["Vad är semestertillägg?","Hur räknas semesterlön för månadsavlönade?","När betalas semestertillägget ut?"]$faq$::jsonb, $faq$Med sammalöneregeln behåller den anställda månadslönen under semestern plus ett tillägg på 0,43 % av månadslönen per semesterdag.$faq$, $faq$Sammalöneregeln (vanligast för månadsavlönade) innebär ordinarie månadslön under semestern plus semestertillägg om 0,43 % av månadslönen per betald semesterdag — kollektivavtal har ofta 0,8 %. Tillägget betalas normalt ut i samband med semestern eller i juni. Alternativet procentregeln ger 12 % av förfallen lön under intjänandeåret och används för timavlönade och oregelbunden lön. Nordklart stödjer båda reglerna; valet görs per anställd och styr både utbetalning och skuldberäkning.$faq$, $faq$["Semesterlagen 16 a §"]$faq$::jsonb, '{}'::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-015', 'Lön, AGI & F-skatt', 'bilforman', $faq$["Hur hanterar jag bilförmån i lönen?","Vad kostar en förmånsbil skattemässigt?","Beräkna förmånsvärde för tjänstebil?"]$faq$::jsonb, $faq$Bilförmånsvärdet beräknas enligt Skatteverkets schablon (prisbasbelopp, ränta, nybilspris) och läggs på lönen som skattepliktig förmån.$faq$, $faq$En anställd som använder företagets bil privat beskattas för bilförmån. Förmånsvärdet beräknas schablonmässigt utifrån bilens nybilspris, prisbasbeloppsdel, ränterelaterad del och extrautrustning; miljöbilar kan ha nedsatt värde. Värdet läggs till bruttolönen vid beräkning av skatteavdrag och arbetsgivaravgifter men betalas inte ut. I Nordklart registrerar du förmånen på den anställda (registreringsnummer krävs i AGI) så följer den med i varje lönekörning och redovisas i individuppgiften. Drivmedelsförmån hanteras separat med faktiskt värde gånger 1,2.$faq$, $faq$["IL 61 kap 5-11 §§"]$faq$::jsonb, '{}'::text[], array['/salary']::text[], 'medium', $faq$Förmånsberäkning för dyrare bilar eller specialfall bör stämmas av mot Skatteverkets bilförmånsberäkning.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-016', 'Lön, AGI & F-skatt', 'friskvard_kostforman', $faq$["Vad gäller för friskvårdsbidrag?","Är gymkort skattefritt för anställda?","Hur bokförs kostförmån?"]$faq$::jsonb, $faq$Friskvårdsbidrag upp till 5 000 kr/år är skattefritt. Fri kost är en skattepliktig förmån som värderas enligt Skatteverkets schablon.$faq$, $faq$Friskvårdsbidrag är skattefritt för motion och friskvård av enklare slag upp till 5 000 kr per anställd och år — bokförs på 7699/7690 utan förmånsbeskattning. Överskjutande belopp blir skattepliktig förmån. Fri kost (t.ex. arbetsgivarbetald lunch) är däremot alltid skattepliktig och värderas per måltid enligt Skatteverkets årliga schablonbelopp; värdet läggs på lönen i lönekörningen. Fri frukost/lunch/middag i samband med representation eller tjänsteresa har särskilda undantag. Nordklart har lönearter för båda förmånstyperna.$faq$, $faq$["IL 11 kap 11-12 §§","IL 61 kap 3 §"]$faq$::jsonb, '{}'::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-017', 'Lön, AGI & F-skatt', 'milersattning', $faq$["Hur mycket är skattefri milersättning?","Ersättning för körning med egen bil i tjänsten?","Bokföra milersättning?"]$faq$::jsonb, $faq$Skattefri milersättning för egen bil i tjänsten är 25 kr/mil. Betalas via lönen utan skatt och avgifter, bokförs på 7331.$faq$, $faq$Anställda som kör egen bil i tjänsten kan få 25 kr per mil skattefritt (förmånsbil: 12 kr/mil för diesel/bensin, 9,50 kr för el). Ersättningen läggs som skattefri löneart i lönekörningen — ingen preliminärskatt eller arbetsgivaravgift — och bokförs på 7331 skattefria bilersättningar. Belopp över schablonen är skattepliktig lön. Kräv körjournal med datum, sträcka och syfte som underlag. I AGI redovisas att skattefri ersättning betalats med kryss, inte belopp.$faq$, $faq$["IL 12 kap 5 §"]$faq$::jsonb, '{}'::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-018', 'Lön, AGI & F-skatt', 'traktamente', $faq$["Hur fungerar traktamente?","Skattefritt traktamente vid tjänsteresa?","Vad är maximibeloppet för traktamente?"]$faq$::jsonb, $faq$Skattefritt traktamente vid tjänsteresa med övernattning utgår med Skatteverkets maximibelopp per hel dag, halvt belopp för halvdagar, reducerat för fria måltider.$faq$, $faq$Vid tjänsteresa med övernattning utanför den vanliga verksamhetsorten (minst 50 km) kan skattefritt traktamente betalas: helt maximibelopp per hel dag, halvt för avrese-/hemresedag efter kl 12/före kl 19, och nattraktamente om arbetsgivaren inte betalar logi. Fria måltider reducerar beloppet och kan ge kostförmån. Utlandstraktamente följer Skatteverkets normalbelopp per land. Traktamente läggs som skattefri löneart, bokförs på 7321/7323, och markeras i AGI. Belopp över schablon beskattas som lön.$faq$, $faq$["IL 12 kap 6-17 §§"]$faq$::jsonb, '{}'::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-019', 'Lön, AGI & F-skatt', 'egen_lon_ab_vs_ef', $faq$["Kan jag ta ut lön till mig själv?","Skillnad mellan lön i AB och eget uttag i enskild firma?","Hur betalar jag mig själv från företaget?"]$faq$::jsonb, $faq$I AB tar du lön som anställd (med skatt och avgifter via lönekörning). I enskild firma tar du eget uttag — ingen lön, du beskattas för resultatet.$faq$, $faq$Aktiebolag: ägaren är anställd och tar lön via lönekörning med preliminärskatt och arbetsgivaravgifter — lönen är avdragsgill för bolaget och pensionsgrundande. Enskild firma: du kan inte vara anställd av dig själv. Pengar du tar ut är eget uttag (bokförs 2013, ingen kostnad) och du beskattas i stället för verksamhetens hela resultat via NE-bilagan, med egenavgifter. Valet påverkar skatteplanering väsentligt — i AB balanseras lön mot utdelning enligt 3:12-reglerna.$faq$, $faq$["IL 57 kap"]$faq$::jsonb, '{}'::text[], array['/salary', '/bookkeeping']::text[], 'medium', $faq$Optimal fördelning mellan lön och utdelning beror på din situation — ta hjälp av skatterådgivare för 3:12-planering.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-020', 'Lön, AGI & F-skatt', 'eget_uttag_bokforing', $faq$["Hur bokför jag eget uttag i enskild firma?","Jag förde över pengar till mitt privatkonto — vad väljer jag?","Vad är konto 2013?"]$faq$::jsonb, $faq$Eget uttag bokförs debet 2013, kredit 1930. Det är ingen kostnad och påverkar inte resultatet — bara ditt egna kapital.$faq$, $faq$När du i enskild firma överför pengar till dig själv bokförs det som eget uttag: debet 2013 övriga egna uttag, kredit 1930 företagskonto. Uttaget är inte lön, inte kostnad och drar ingen skatt vid uttagstillfället — du beskattas för verksamhetens resultat oavsett hur mycket du tar ut. Motsatt riktning (du sätter in privata pengar) bokförs som egen insättning på 2018. Nordklart känner igen överföringar till registrerat privatkonto och föreslår eget uttag automatiskt för dessa transaktioner i enskild firma.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/transactions', '/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-021', 'Lön, AGI & F-skatt', 'f_skatt_vad_ar', $faq$["Vad är F-skatt?","Måste företaget ha F-skattsedel?","Skillnad mellan F-skatt och A-skatt?"]$faq$::jsonb, $faq$F-skatt innebär att företaget själv betalar sin preliminärskatt och sociala avgifter. Utan F-skatt måste dina kunder göra skatteavdrag på fakturor.$faq$, $faq$F-skatt (godkännande för F-skatt) visar att företaget ansvarar för sina egna skatter. Med F-skatt betalar kunder fakturor brutto utan skatteavdrag — därför ska 'Godkänd för F-skatt' anges på fakturor. Utan godkännande behandlas ersättning för arbete som lön hos utbetalaren. Ansökan görs hos Skatteverket (ingår i företagsregistreringen). Debiterad preliminärskatt betalas sedan månadsvis till skattekontot baserat på förväntad vinst — lämna preliminär inkomstdeklaration om resultatet ändras väsentligt.$faq$, $faq$["SFL 9 kap"]$faq$::jsonb, '{}'::text[], array['/settings/tax', '/skattekonto']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-022', 'Lön, AGI & F-skatt', 'preliminarskatt_bokforing', $faq$["Hur bokförs debiterad preliminärskatt?","F-skatten dras från skattekontot — vilket konto?","Bokföra preliminär F-skatt i AB och enskild firma?"]$faq$::jsonb, $faq$I AB bokförs preliminärskatten mot 2510/1630 (skatteskuld). I enskild firma är F-skatten privat och bokförs som eget uttag 2012.$faq$, $faq$Aktiebolag: den månatliga debiterade preliminärskatten bokförs debet 2510 skatteskulder (eller 2518 betald preliminärskatt) och kredit 1630 skattekonto när den dras — bolagsskatten är bolagets kostnad (8910). Enskild firma: F-skatten avser din privata inkomstskatt och egenavgifter, alltså inte en företagskostnad — bokför debet 2012 avräkning skatter och avgifter (eget uttag) mot kredit 1930/1630. Nordklart föreslår rätt hantering utifrån företagsformen när skattekontotransaktioner synkas.$faq$, $faq$["BAS 2026"]$faq$::jsonb, '{}'::text[], array['/skattekonto', '/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-023', 'Lön, AGI & F-skatt', 'skattekonto_oversikt', $faq$["Vad är skattekontot?","Var ser jag mitt skattekonto i Nordklart?","Hur fungerar skattekontot hos Skatteverket?"]$faq$::jsonb, $faq$Skattekontot är företagets konto hos Skatteverket där moms, arbetsgivaravgifter, personalskatt och F-skatt bokförs. Nordklart kan synka det via Skatteverket-kopplingen.$faq$, $faq$Alla skatter och avgifter går via skattekontot hos Skatteverket: inbetalningar, debiterade skatter (moms, AGI-belopp, F-skatt), ränta och utbetalningar. I bokföringen speglas skattekontot av konto 1630. Med Skatteverket-tillägget hämtar Nordklart kontoutdraget automatiskt och matchar posterna mot bokförda skulder (2650 moms, 2710 personalskatt, 2731 avgifter). Under Skattekonto ser du saldo, kommande debiteringar och vilka poster som är avstämda. Kostnadsränta på underskott är inte avdragsgill; intäktsränta är skattefri.$faq$, $faq$["SFL 61-65 kap"]$faq$::jsonb, '{}'::text[], array['/skattekonto', '/settings/skatteverket']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-024', 'Lön, AGI & F-skatt', 'skattekonto_sync', $faq$["Hur synkas skattekontot från Skatteverket?","Kan Nordklart hämta skattekontoutdraget automatiskt?","Koppla Skatteverket till Nordklart?"]$faq$::jsonb, $faq$Aktivera Skatteverket-tillägget och godkänn behörigheten — sedan hämtas skattekontots transaktioner automatiskt och stäms av mot bokföringen.$faq$, $faq$Under Inställningar → Skatteverket aktiverar du kopplingen (kräver behörighet hos Skatteverket, t.ex. via ombudsanmälan). Därefter hämtas skattekontoutdraget löpande: bokförda och kommande transaktioner som moms, arbetsgivaravgifter, avdragen skatt, F-skatt och ränta. Posterna matchas mot motsvarande skulder i bokföringen och avvikelser flaggas — t.ex. om en debiterad moms inte stämmer med den momsdeklaration som bokförts. Kommande debiteringar syns i deadline-bevakningen så du vet vad som dras och när.$faq$, $faq$[]$faq$::jsonb, array['admin']::text[], array['/settings/skatteverket', '/skattekonto']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-025', 'Lön, AGI & F-skatt', 'matcha_skattebetalning', $faq$["Hur matchas skatteinbetalningar mot moms och AGI?","Banköverföring till skattekontot — hur bokförs den?","Insättning till Skatteverket, vilket konto?"]$faq$::jsonb, $faq$Inbetalning till skattekontot bokförs 1630 mot 1930. När Skatteverket sedan drar moms/avgifter/skatt bokas respektive skuldkonto mot 1630.$faq$, $faq$Betalningen från banken till Skatteverket bokförs debet 1630 skattekonto, kredit 1930 — Nordklart känner igen bankgiro 5050-1055 och föreslår detta automatiskt. När skattekontosynken sedan visar att Skatteverket debiterat t.ex. moms bokförs debet 2650 mot kredit 1630, arbetsgivaravgifter debet 2731 mot 1630 och personalskatt debet 2710 mot 1630. Kan Nordklart entydigt para debiteringen mot en bokförd deklaration görs förslaget automatiskt; en betalning som inte kan hänföras till någon känd skuld blir en väntande åtgärd i stället för att gissas.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/skattekonto', '/transactions']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-026', 'Lön, AGI & F-skatt', 'otydlig_skattebetalning', $faq$["Vad händer om en skattebetalning inte kan matchas?","Skatteverket drog ett belopp jag inte känner igen?","Oklar post på skattekontot?"]$faq$::jsonb, $faq$Omatchade skattekontoposter blir väntande åtgärder. Kontrollera mot Skatteverkets specifikation — det kan vara ränta, ändringsbeslut eller anstånd.$faq$, $faq$När en skattekontopost inte entydigt kan kopplas till bokförd moms, AGI eller F-skatt skapar Nordklart en väntande åtgärd i stället för att auto-bokföra. Vanliga orsaker: kostnads-/intäktsränta (bokförs 8423 ej avdragsgill respektive 8314 skattefri), omprövningsbeslut, förseningsavgifter (6992, ej avdragsgill) eller ombokningar mellan perioder. Öppna posten, jämför med skattekontoutdraget hos Skatteverket och välj rätt kontering. Beslut om skattetillägg eller större avvikelser bör alltid utredas innan de bokförs.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/pending', '/skattekonto']::text[], 'medium', $faq$Oväntade beslut från Skatteverket (skattetillägg, omprövning) kan behöva överklagas inom viss tid — kontakta Skatteverket eller rådgivare snarast.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-027', 'Lön, AGI & F-skatt', 'lonebaserat_utrymme', $faq$["Vad är löneunderlagsregeln i 3:12?","Hur påverkar löner mitt utdelningsutrymme?","Lönebaserat utrymme för fåmansbolag?"]$faq$::jsonb, $faq$Huvudregeln ger utdelningsutrymme baserat på 50 % av bolagets kontanta löner — förutsatt att ägaren tagit tillräcklig egen lön (löneuttagskravet).$faq$, $faq$I fåmansbolag kan gränsbeloppet (utdelning till 20 % kapitalskatt) beräknas enligt huvudregeln med lönebaserat utrymme: 50 % av företagets totala kontanta bruttolöner året före utdelningsåret. Kravet är att ägaren (eller närstående) tagit ut lön om minst det lägsta av ett fast golv kopplat till inkomstbasbelopp eller basnivå plus 5 % av totala löner. Alternativet är förenklingsregeln med schablonbelopp. Nordklarts löneunderlag ger siffrorna, men själva K10-beräkningen och strategin (lön vs utdelning) bör göras med skatterådgivare — reglerna ändrades senast genom 2026 års 3:12-reform.$faq$, $faq$["IL 57 kap 16-19 §§"]$faq$::jsonb, '{}'::text[], array['/salary', '/reports']::text[], 'high', $faq$3:12-beräkningar påverkar din privata skatt väsentligt. Låt en skatterådgivare bekräfta gränsbelopp och löneuttagskrav innan utdelningsbeslut.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-028', 'Lön, AGI & F-skatt', 'utdelning_vs_lon', $faq$["Ska jag ta lön eller utdelning?","Vad är mest skatteeffektivt — lön eller utdelning?","Hur mycket lön behöver jag ta ut för utdelning?"]$faq$::jsonb, $faq$Lön ger pension och sjukpenning och krävs ofta för löneunderlagsregeln; utdelning inom gränsbeloppet beskattas 20 %. Balansen är individuell.$faq$, $faq$Lön är avdragsgill för bolaget, ger sjukpenninggrundande och pensionsgrundande inkomst, men bär arbetsgivaravgifter och progressiv inkomstskatt. Utdelning inom gränsbeloppet beskattas med 20 % kapitalskatt men kräver att bolaget skattat fram vinsten (bolagsskatt 20,6 %) och ger inga socialförsäkringsförmåner. Vanlig strategi: ta lön upp till brytpunkten för statlig skatt och/eller nivån som uppfyller löneuttagskravet, därefter utdelning inom gränsbeloppet. Nordklart visar löner och resultat, men beslutet bör tas med skatterådgivare — fel nivå kan kosta stora belopp.$faq$, $faq$["IL 57 kap"]$faq$::jsonb, '{}'::text[], array['/salary', '/kpi']::text[], 'high', $faq$Detta är skatterådgivning på individnivå — Nordklart kan visa underlagen men rekommendationen bör komma från en rådgivare som ser hela din situation.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-029', 'Lön, AGI & F-skatt', 'k10_blankett', $faq$["Vad är K10-blanketten?","Måste jag lämna K10 varje år?","Var får jag siffrorna till K10?"]$faq$::jsonb, $faq$K10 är bilagan till din privata deklaration där gränsbelopp och utdelning från fåmansbolag redovisas. Lämna den varje år — även utan utdelning, för att spara utrymme.$faq$, $faq$K10 lämnas av delägare i fåmansbolag med din privata inkomstdeklaration. Där beräknas årets gränsbelopp (förenklingsregeln eller huvudregeln med löneunderlag), sparat utdelningsutrymme räknas upp, och utdelning/kapitalvinst fördelas mellan kapital (20 %) och tjänst. Lämna K10 även år utan utdelning — annars tappar du dokumentationen av sparat utrymme. Underlag från Nordklart: kontanta bruttolöner (löneunderlagsrapporten), din egen lön, anskaffningsvärde på aktierna och utdelningsbeslut. Själva blanketten fylls i hos Skatteverket eller av din rådgivare.$faq$, $faq$["IL 57 kap"]$faq$::jsonb, '{}'::text[], array['/salary', '/reports']::text[], 'medium', $faq$Komplexa fall (delägarförändringar, utomstående ägande, takbelopp) kräver skatterådgivare.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-030', 'Lön, AGI & F-skatt', 'egenavgifter_ef', $faq$["Vad är egenavgifter?","Hur mycket betalar enskild firma i sociala avgifter?","Bokförs egenavgifter i firman?"]$faq$::jsonb, $faq$Egenavgifter (ca 28,97 %) betalas av enskilda näringsidkare på verksamhetens överskott — de ingår i F-skatten och bokförs inte som företagskostnad.$faq$, $faq$Enskilda näringsidkare betalar egenavgifter i stället för arbetsgivaravgifter: fulla avgifter är 28,97 % av överskottet (lägre för äldre; 7 dagars karens är standard). Avgifterna beräknas i din privata deklaration via NE-bilagan och betalas genom F-skatten/slutskatten — de bokförs alltså inte som kostnad i firman utan hanteras som schablonavdrag i deklarationen (avdrag med 25 % av överskottet innan avgiftsberäkning). I Nordklart syns detta i NE-underlaget och skatteberäkningen, inte i den löpande bokföringen.$faq$, $faq$["SAL 3 kap"]$faq$::jsonb, '{}'::text[], array['/year-end', '/reports']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-031', 'Lön, AGI & F-skatt', 'vaxa_stod', $faq$["Vad är växa-stöd?","Rabatt på arbetsgivaravgifter för första anställda?","Hur ansöker jag om växa-stöd?"]$faq$::jsonb, $faq$Växa-stöd ger nedsatta arbetsgivaravgifter (endast ålderspensionsavgift 10,21 %) för de första anställda i mindre företag, upp till ett lönetak per månad.$faq$, $faq$Växa-stödet innebär att kvalificerade företag som anställer betalar endast ålderspensionsavgiften 10,21 % i stället för 31,42 % för upp till två anställda, på lönedelar upp till 35 000 kr/månad under som längst 24 månader. Kravet är bl.a. att företaget inte haft anställda tidigare (enligt reglernas definition) och att anställningen omfattar minst tre månader och 20 timmar/vecka. Stödet begärs direkt i arbetsgivardeklarationen genom att markera individuppgiften — ingen separat ansökan. Ange växa-stöd på den anställda i Nordklart så beräknas avgiften och AGI-markeringen automatiskt. Reglerna ändras över tid — kontrollera aktuella villkor hos Skatteverket.$faq$, $faq$["Lag (2016:1053) om särskild beräkning av vissa avgifter för växande företag"]$faq$::jsonb, array['admin']::text[], array['/salary']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-032', 'Lön, AGI & F-skatt', 'kontrolluppgifter_ku', $faq$["Behöver jag lämna kontrolluppgifter (KU)?","Vad är KU31?","Kontrolluppgift för utdelning?"]$faq$::jsonb, $faq$Lön rapporteras numera månadsvis via AGI — inga årliga KU för lön. KU31 krävs dock fortfarande för utdelning till delägare, senast 31 januari.$faq$, $faq$Sedan AGI infördes rapporteras löner och förmåner per månad, så årliga kontrolluppgifter för lön är avskaffade. Kontrolluppgifter behövs fortfarande för annat: KU31 för utdelning på onoterade aktier (lämnas senast 31 januari året efter utdelningen), KU20 för ränta m.fl. Om ditt bolag beslutat om utdelning ska KU31 lämnas med mottagare, belopp och eventuell avdragen kupongskatt. Nordklart kan generera KU-underlag från registrerade utdelningar; inlämning sker via Skatteverkets e-tjänst.$faq$, $faq$["SFL 22-24 kap"]$faq$::jsonb, array['admin']::text[], array['/salary', '/skatteverket']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-033', 'Lön, AGI & F-skatt', 'lonevaxling', $faq$["Vad är löneväxling?","Kan anställda växla lön mot pension?","Hur bokförs löneväxling till tjänstepension?"]$faq$::jsonb, $faq$Löneväxling byter bruttolön mot t.ex. extra pensionsavsättning. Arbetsgivaren betalar särskild löneskatt 24,26 % på pensionspremien i stället för arbetsgivaravgifter.$faq$, $faq$Vid löneväxling avstår den anställda bruttolön mot en förmån, oftast extra tjänstepension. Eftersom pensionspremier bär särskild löneskatt (24,26 %) i stället för arbetsgivaravgifter (31,42 %) kan arbetsgivaren ge en växlingspremie på ca 5–6 % utan extra kostnad. Tänk på att sänkt bruttolön kan påverka sjukpenning, föräldrapenning och allmän pension — växling rekommenderas normalt bara över inkomsttaket. Bokföring: pensionspremie 7412, särskild löneskatt 7533/2514. I Nordklart läggs växlingen som löneart som minskar bruttolönen och skapar premieposten.$faq$, $faq$["SLPL","IL 28 kap"]$faq$::jsonb, array['admin']::text[], array['/salary']::text[], 'medium', $faq$Löneväxlingens effekt på den anställdas socialförsäkring bör förklaras av pensionsrådgivare innan avtal ingås.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-034', 'Lön, AGI & F-skatt', 'ob_overtid', $faq$["Hur lägger jag in OB-tillägg?","Registrera övertid i lönekörningen?","Vad gäller för övertidsersättning?"]$faq$::jsonb, $faq$OB och övertid läggs som rörliga lönearter i lönekörningen med antal timmar och belopp/procent — ersättningsnivåerna styrs av kollektivavtal eller anställningsavtal.$faq$, $faq$I lönekörningen lägger du till rörliga poster per anställd: OB-tillägg (kvälls-, natt-, helgtillägg) och övertidsersättning med timmar och a-pris eller procentpåslag. Nivåerna är inte lagstadgade utan följer kollektivavtal eller individuella avtal — vanliga modeller är OB som procent av månadslön/dividerad timlön och övertid 50–100 % påslag. Arbetstidslagen begränsar övertid till 200 timmar allmän övertid per år. Posterna ingår i bruttolönen och påverkar skatt, avgifter och semesterunderlag som vanligt.$faq$, $faq$["Arbetstidslagen 8 §"]$faq$::jsonb, '{}'::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-035', 'Lön, AGI & F-skatt', 'sjuklon', $faq$["Hur hanterar jag sjuklön?","Vad betalar arbetsgivaren vid sjukdom?","Registrera sjukfrånvaro i lönen?"]$faq$::jsonb, $faq$Arbetsgivaren betalar sjuklön 80 % dag 1–14 med karensavdrag på 20 % av en genomsnittlig veckas sjuklön. Från dag 15 tar Försäkringskassan över.$faq$, $faq$Vid sjukdom betalar arbetsgivaren sjuklön om 80 % av lön och förmåner under dag 1–14, minskat med ett karensavdrag som motsvarar 20 % av en genomsnittlig veckas sjuklön. Från dag 15 anmäler du till Försäkringskassan som betalar sjukpenning. Läkarintyg krävs normalt från dag 8. I Nordklarts lönekörning registrerar du sjukperioden så beräknas sjuklön och karensavdrag automatiskt och redovisas på lönebeskedet. Sjuklönekostnaden bokförs som vanlig lönekostnad; ersättning för höga sjuklönekostnader krediteras via skattekontot.$faq$, $faq$["Sjuklönelagen 6-6 a §§"]$faq$::jsonb, '{}'::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-036', 'Lön, AGI & F-skatt', 'karensavdrag', $faq$["Hur räknas karensavdraget?","Vad är karensavdrag i stället för karensdag?","Anställd sjuk en halv dag — blir det fullt karensavdrag?"]$faq$::jsonb, $faq$Karensavdraget är 20 % av en genomsnittlig veckas sjuklön och dras en gång per sjukperiod — oavsett när på dagen den anställda blev sjuk.$faq$, $faq$Karensavdraget ersatte karensdagen 2019 för att bli rättvist för dem med oregelbundna arbetstider. Beräkning: sjuklönen för en genomsnittlig arbetsvecka × 20 %. För en månadsavlönad med jämn arbetstid motsvarar det ungefär en dags sjuklön, men det dras proportionellt — blir någon sjuk mitt på dagen dras resterande del nästa sjukdag. Återinsjuknande inom fem kalenderdagar räknas som samma sjukperiod utan nytt karensavdrag. Nordklart beräknar avdraget automatiskt från den anställdas veckoarbetstid.$faq$, $faq$["Sjuklönelagen 6 a §"]$faq$::jsonb, '{}'::text[], array['/salary']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-037', 'Lön, AGI & F-skatt', 'korrigera_lonekorning', $faq$["Jag gjorde fel i en lönekörning — hur rättar jag?","Kan jag ändra en godkänd lönekörning?","Retroaktiv lönejustering?"]$faq$::jsonb, $faq$Godkända lönekörningar rättas via korrigeringskörning nästa månad eller genom rättelse av den aktuella körningen — AGI för perioden rättas med ersättningsdeklaration.$faq$, $faq$En godkänd och bokförd lönekörning ändras inte i efterhand. Alternativ: 1) Justera i nästa körning — retroaktiv lön eller avdrag läggs som egen löneart, vilket räcker för mindre fel. 2) Gör en korrigeringskörning för den aktuella månaden som vänder och ersätter felaktiga poster; då ska även AGI för den perioden rättas genom att lämna en ny (ersättnings-)deklaration till Skatteverket. Bokföringen rättas via ändringsverifikation. Utbetalt nettobelopp som blev fel regleras mot den anställda i kommande lön.$faq$, $faq$["SFL 26 kap 40 §"]$faq$::jsonb, array['admin']::text[], array['/salary']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-038', 'Lön, AGI & F-skatt', 'skattekonto_ranta', $faq$["Hur bokför jag ränta på skattekontot?","Kostnadsränta från Skatteverket — vilket konto?","Är skattekontoräntan avdragsgill?"]$faq$::jsonb, $faq$Kostnadsränta bokförs på 8423 och är inte avdragsgill. Intäktsränta bokförs på 8314 och är skattefri.$faq$, $faq$Räntor på skattekontot särbehandlas skattemässigt: kostnadsränta (vid underskott eller sen betalning) är inte avdragsgill — bokförs debet 8423 räntekostnader skattekonto, kredit 1630 — och återläggs i skatteberäkningen. Intäktsränta (vid överskott) är skattefri — bokförs debet 1630, kredit 8314 — och dras av i deklarationen. Nordklarts skattekontosynk identifierar räntetransaktioner och föreslår rätt konto automatiskt, och INK2S-underlaget plockar upp posterna som skattemässiga justeringar.$faq$, $faq$["IL 9 kap 8 §","BAS 2026"]$faq$::jsonb, '{}'::text[], array['/skattekonto', '/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-039', 'Lön, AGI & F-skatt', 'registrera_arbetsgivare', $faq$["Hur blir jag registrerad som arbetsgivare?","Måste jag anmäla till Skatteverket innan första lönen?","Arbetsgivarregistrering — var görs den?"]$faq$::jsonb, $faq$Registrera dig som arbetsgivare hos Skatteverket (verksamt.se eller blankett) innan första löneutbetalningen — därefter ska AGI lämnas varje månad.$faq$, $faq$Innan du betalar ut lön första gången ska företaget registreras som arbetsgivare hos Skatteverket, enklast via verksamt.se. Registreringen aktiverar skyldigheten att lämna arbetsgivardeklaration månadsvis — även månader utan lön ska nolldeklareras så länge registreringen är aktiv (eller så avregistrerar du dig vid längre uppehåll). När registreringen är klar lägger du upp anställda i Nordklart under Lön → Personal med personnummer, lön och skattetabell, och kan köra första lönen.$faq$, $faq$["SFL 7 kap 2 §"]$faq$::jsonb, array['admin']::text[], array['/salary', '/settings/company']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('lon-040', 'Lön, AGI & F-skatt', 'agi_rattelse', $faq$["Hur rättar jag en inlämnad AGI?","Fel i arbetsgivardeklarationen — vad gör jag?","Ersättningsdeklaration för AGI?"]$faq$::jsonb, $faq$Lämna en ny arbetsgivardeklaration för samma period — den senaste inlämnade ersätter den tidigare i sin helhet.$faq$, $faq$AGI rättas genom att du lämnar om deklarationen för den aktuella redovisningsperioden: den nya deklarationen ersätter den gamla helt, så alla individuppgifter ska vara med igen (inte bara den rättade). Rätta först lönekörningen i Nordklart via korrigeringskörning så att underlaget stämmer, generera om AGI för perioden och skicka in på nytt. Skillnader i avgifter eller avdragen skatt regleras automatiskt på skattekontot efter Skatteverkets omräkning. Rättelser långt bakåt i tiden kan ge kostnadsränta — men vänta inte, oriktiga uppgifter som inte rättas kan ge skattetillägg.$faq$, $faq$["SFL 26 kap 40 §","SFL 49 kap"]$faq$::jsonb, array['admin']::text[], array['/salary', '/skatteverket']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-001', 'Moms, VAT & periodisk sammanställning', 'momssatser', $faq$["Vilka momssatser finns i Sverige?","När är det 12 eller 6 procent moms?","Momssats på min tjänst?"]$faq$::jsonb, $faq$25 % är standard; 12 % för bl.a. livsmedel, restaurang och hotell; 6 % för böcker, kultur, idrott och persontransport.$faq$, $faq$Sverige har tre momssatser: 25 % (huvudregeln), 12 % (livsmedel, restaurang- och cateringtjänster, hotell, konstnärs egen försäljning) och 6 % (böcker/tidningar, persontransport, entré till kultur- och idrottsevenemang). Vissa tjänster är momsfria (sjukvård, utbildning, finans, bostadshyra). Nordklart sätter momsraderna utifrån vald momsbehandling per rad.$faq$, $faq$["ML 9 kap"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-002', 'Moms, VAT & periodisk sammanställning', 'momsrapport', $faq$["Hur tar jag fram momsdeklarationen?","Var finns momsrapporten?","Momsrutorna för perioden?"]$faq$::jsonb, $faq$Rapporter → Momsdeklaration visar alla rutor (05–62) beräknade från bokföringen, per momsperiod.$faq$, $faq$Momsrapporten summerar dina bokförda momskonton och försäljningsrader till Skatteverkets rutor: 05–08 försäljning, 10–12 utgående moms, 20–24 inköp med omvänd moms, 30–32 utgående moms på förvärv, 35–42 momsfri försäljning/export, 48 ingående moms, 49 att betala/få tillbaka. Klicka en ruta för att se exakt vilka verifikationer som ingår. Rapporten följer din momsperiod (månad/kvartal/år).$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-003', 'Moms, VAT & periodisk sammanställning', 'momsdeklaration_bokforing', $faq$["Hur bokför jag själva momsdeklarationen?","Nollställa momskonton vid deklaration?","Momsomföring 2650?"]$faq$::jsonb, $faq$Vid deklarationen omförs periodens momskonton till 2650; betalningen bokförs mot skattekontot 1630.$faq$, $faq$När perioden deklareras skapar Nordklart en momsomföringsverifikation: alla 26xx-saldon för perioden nollas mot 2650 Redovisningskonto för moms. Beloppet i ruta 49 blir skulden/fordran på 2650. Betalningen till skattekontot bokförs Dr 1630 / Kr 1930 och Skatteverkets dragning Dr 2650 / Kr 1630 (matchas via skattekontosynken).$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat', '/skattekonto']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-004', 'Moms, VAT & periodisk sammanställning', 'momsperiod_deadline', $faq$["När ska momsen deklareras?","Deadline momsdeklaration kvartal?","Momsdatum 12:e eller 26:e?"]$faq$::jsonb, $faq$Kvartals-/månadsmoms: den 12:e i andra månaden efter perioden (månadsmoms för större: 26:e). Helårsmoms: 26:e i andra månaden efter räkenskapsårets slut.$faq$, $faq$För månads- och kvartalsredovisning är deklarationsdagen normalt den 12:e i andra månaden efter periodens slut (t.ex. Q1 → 12 maj). Företag över 40 mkr redovisar månadsvis den 26:e i månaden efter. Helårsmoms utan EU-handel deklareras den 26:e i andra månaden efter årets slut. Nordklart visar dina exakta deadlines i kalendern.$faq$, $faq$["SFL 26 kap"]$faq$::jsonb, '{}'::text[], array['/deadlines']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-005', 'Moms, VAT & periodisk sammanställning', 'ruta49_negativ', $faq$["Vad betyder minus i ruta 49?","Får jag tillbaka moms?","Negativ moms att betala?"]$faq$::jsonb, $faq$Negativt belopp i ruta 49 betyder att ingående moms överstiger utgående — du får pengar tillbaka från Skatteverket.$faq$, $faq$Ruta 49 är utgående moms minus ingående moms. Är den negativ (mer ingående) får du momsen tillbaka till skattekontot, vanligt vid stora inköp eller uppstart. Pengarna kan betalas ut från skattekontot eller kvittas mot kommande skatter. Notera att första utbetalningen kan kräva anmält utbetalningskonto hos Skatteverket.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat', '/skattekonto']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-006', 'Moms, VAT & periodisk sammanställning', 'vies_validering', $faq$["Hur kontrollerar jag kundens VAT-nummer?","VIES-validering i systemet?","Ogiltigt EU-VAT-nummer?"]$faq$::jsonb, $faq$Nordklart validerar EU-VAT-nummer automatiskt mot VIES när du lägger upp kunden eller fakturerar utan moms.$faq$, $faq$När du anger ett EU-VAT-nummer på en kund kontrolleras det mot EU-kommissionens VIES-register och valideringsdatumet sparas. Momsfri EU-försäljning (omvänd skattskyldighet) förutsätter giltigt nummer — är numret ogiltigt ska du fakturera med svensk moms. Validera om numret regelbundet; VIES-svaret är ditt bevis vid granskning.$faq$, $faq$["ML 10 kap 42 §"]$faq$::jsonb, '{}'::text[], array['/customers']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-007', 'Moms, VAT & periodisk sammanställning', 'periodisk_sammanstallning', $faq$["Vad är periodisk sammanställning?","EC Sales List — måste jag lämna den?","Rapportera EU-försäljning?"]$faq$::jsonb, $faq$Sammanställningen listar momsfri EU-försäljning per köpares VAT-nummer — lämnas månads- eller kvartalsvis.$faq$, $faq$Säljer du varor eller huvudregelstjänster momsfritt till EU-företag ska du lämna periodisk sammanställning: köparens VAT-nummer och belopp per period. Varor rapporteras månadsvis (kvartal om under 500 tkr/kvartal), tjänster kvartalsvis. Nordklart genererar underlaget från dina EU-fakturor under Rapporter → Periodisk sammanställning. Beloppen ska stämma mot ruta 35/39 i momsdeklarationen.$faq$, $faq$["SFL 35 kap"]$faq$::jsonb, '{}'::text[], array['/reports']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-008', 'Moms, VAT & periodisk sammanställning', 'oss', $faq$["Vad är OSS och när behöver jag det?","Sälja digitala tjänster till EU-konsumenter?","Unionsordningen One Stop Shop?"]$faq$::jsonb, $faq$OSS används för B2C-försäljning till EU-konsumenter över 99 680 kr/år — du redovisar andra länders moms via Skatteverket.$faq$, $faq$Säljer du varor på distans eller digitala tjänster till privatpersoner i andra EU-länder över tröskeln 99 680 kr/år ska du ta ut köparlandets moms. I stället för att momsregistrera dig i varje land ansluter du dig till OSS (unionsordningen) hos Skatteverket och redovisar all EU-B2C-moms i en kvartalsdeklaration. Under tröskeln får svensk moms användas. OSS-försäljning bokförs separat från svensk moms.$faq$, $faq$["ML 22 kap","Skatteverket: OSS"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'medium', $faq$OSS-registrering och landspecifika momssatser bör sättas upp med redovisningskonsult.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-009', 'Moms, VAT & periodisk sammanställning', 'momsfri_verksamhet', $faq$["Min verksamhet är momsfri — hur påverkar det bokföringen?","Sjukvård/utbildning utan moms?","Ingen avdragsrätt för ingående moms?"]$faq$::jsonb, $faq$Momsfri verksamhet fakturerar utan moms och får inte dra ingående moms — den blir i stället en kostnad.$faq$, $faq$Momsfria verksamheter (sjukvård, tandvård, viss utbildning, finansiella tjänster, bostadsuthyrning) tar inte ut moms och saknar avdragsrätt — ingående moms bokförs som del av kostnaden. Ange "ej momsregistrerad" i skatteinställningarna så fakturerar Nordklart utan moms och stänger av momslyft.$faq$, $faq$["ML 10 kap"]$faq$::jsonb, '{}'::text[], array['/settings/tax']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-010', 'Moms, VAT & periodisk sammanställning', 'blandad_verksamhet', $faq$["Vi har både momspliktig och momsfri försäljning — hur gör vi med momsen?","Blandad verksamhet avdragsrätt?","Fördelningsnyckel för ingående moms?"]$faq$::jsonb, $faq$Vid blandad verksamhet dras ingående moms proportionellt efter skälig grund (ofta omsättningsfördelning).$faq$, $faq$Med både momspliktig och momsfri omsättning gäller: moms på inköp direkt hänförliga till momspliktig del dras fullt, momsfri del inte alls, och gemensamma kostnader proportioneras efter skälig grund — vanligen omsättningsandel. Fördelningen dokumenteras och ses över årligen. Nordklart låter dig ange avdragsprocent per verifikation för gemensamma kostnader.$faq$, $faq$["ML 13 kap 29 §","HFD 2023 ref. 45"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'high', $faq$Val av fördelningsnyckel i blandad verksamhet är en bedömningsfråga med rättspraxis — anlita momsexpert.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-011', 'Moms, VAT & periodisk sammanställning', 'moms_pa_frakt', $faq$["Vilken moms på frakt?","Frakt och porto på fakturan?","Moms på leveransavgift?"]$faq$::jsonb, $faq$Frakten följer varans momssats (bikostnad) — 25 % vara ger 25 % på frakten.$faq$, $faq$Fraktkostnad som du fakturerar kunden är en bikostnad som ingår i beskattningsunderlaget och följer huvudleveransens momssats. Säljer du 12 %-livsmedel blir frakten 12 %. Inköpt frakt (Postnord, DHL inrikes) har 25 % avdragsgill moms; utrikes transporter kan vara momsfria.$faq$, $faq$["ML 8 kap 2 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-012', 'Moms, VAT & periodisk sammanställning', 'moms_bil', $faq$["Får jag dra momsen på bilköp?","Moms personbil vs lätt lastbil?","Företagsbil momsavdrag?"]$faq$::jsonb, $faq$Momsen på personbilsköp får normalt inte dras (undantag: taxi, bilhandel m.fl.); lätt lastbil ger fullt avdrag.$faq$, $faq$Ingående moms vid köp av personbil är avdragsförbjuden för de flesta verksamheter — hela momsen läggs på anskaffningsvärdet. Undantag: bilhandel, taxi, uthyrning, körskola, begravningsbyrå. Lätt lastbil (flak/skåp utan säten) ger fullt momsavdrag. Vid leasing av personbil får halva momsen dras. Driftskostnader (bränsle, service) ger fullt avdrag oavsett.$faq$, $faq$["ML 13 kap 20–21 §§"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-013', 'Moms, VAT & periodisk sammanställning', 'omvand_skattskyldighet_faktura', $faq$["Vad måste stå på fakturan vid omvänd skattskyldighet?","Fakturatext reverse charge?","Omvänd moms fakturakrav?"]$faq$::jsonb, $faq$Fakturan ska sakna moms, ange köparens VAT-nummer och texten "Omvänd betalningsskyldighet".$faq$, $faq$Vid omvänd skattskyldighet (byggtjänster B2B, EU-försäljning, skrot m.m.) ska fakturan innehålla köparens momsregistreringsnummer och uppgiften "Omvänd betalningsskyldighet" (eller "Reverse charge"), och ingen moms debiteras. Nordklart lägger texten automatiskt när momsbehandlingen är omvänd och blockerar momsrader på sådana fakturor.$faq$, $faq$["ML 17 kap 24 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-014', 'Moms, VAT & periodisk sammanställning', 'felaktigt_debiterad_moms', $faq$["Jag fakturerade med moms fast det skulle varit omvänt — vad händer?","Felaktigt debiterad moms måste betalas?","Kreditera fel moms?"]$faq$::jsonb, $faq$Felaktigt debiterad moms ska ändå betalas in tills fakturan krediteras — rätta med kreditfaktura + ny faktura.$faq$, $faq$Moms som anges på en faktura ska betalas till staten även om den var felaktig (ML:s regel om felaktigt debiterad moms). Rättelsen är att utfärda kreditfaktura som speglar originalet och ställa ut en ny korrekt faktura. Köparen har inte avdragsrätt för felaktigt debiterad moms, så rätta snabbt.$faq$, $faq$["ML 16 kap 23 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-015', 'Moms, VAT & periodisk sammanställning', 'moms_kreditfaktura', $faq$["Hur påverkar en kreditfaktura momsen?","Momsen på kreditnota?","Minskar utgående moms vid kreditering?"]$faq$::jsonb, $faq$Kreditfakturan minskar utgående moms i den period den ställs ut — med samma momssats som originalfakturan.$faq$, $faq$En kreditfaktura bokförs som negativ försäljning och negativ utgående moms med originalets momssats — Nordklart ärver momsen från originalfakturan automatiskt (aldrig 0 % av misstag). Momsminskningen redovisas i den period krediteringen görs, inte retroaktivt. Kreditfakturan ska referera till originalfakturan.$faq$, $faq$["ML 17 kap 22 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-016', 'Moms, VAT & periodisk sammanställning', 'hyra_lokal_moms', $faq$["Är det moms på lokalhyra?","Frivillig skattskyldighet lokal?","Hyresvärden fakturerar med moms?"]$faq$::jsonb, $faq$Lokalhyra är momsfri som huvudregel; hyresvärd med frivillig beskattning debiterar 25 % som du får dra av.$faq$, $faq$Uthyrning av fastighet är momsfri, men hyresvärden kan välja frivillig beskattning för lokaler som används i momspliktig verksamhet — då debiteras 25 % moms som du lyfter som ingående. Bokför hyra med moms: Dr 5010 + Dr 2641 / Kr 2440. Momsfri hyra bokförs utan momsrad. Kontrollera att momsen på hyresavin är korrekt debiterad.$faq$, $faq$["ML 12 kap"]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-017', 'Moms, VAT & periodisk sammanställning', 'kvitto_utan_moms', $faq$["Kvittot visar ingen moms — kan jag ändå dra den?","Ingen momsspecifikation på underlaget?","Förenklad faktura gräns?"]$faq$::jsonb, $faq$Nej — utan momsspecifikation ingen avdragsrätt. Förenklad faktura (under 4 000 kr) räcker dock som underlag.$faq$, $faq$Avdragsrätten kräver en faktura/kvitto som visar momsen. Kvitton upp till 4 000 kr inkl. moms får vara förenklade fakturor (datum, säljare, vad som sålts, moms) — det räcker. Saknas moms helt (t.ex. momsfri säljare, utländskt kvitto) finns inget att dra; bokför hela beloppet som kostnad.$faq$, $faq$["ML 17 kap 26 §"]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-018', 'Moms, VAT & periodisk sammanställning', 'moms_pa_forskott', $faq$["Ska jag redovisa moms på förskott?","Förskottsfaktura moms innan leverans?","A conto och moms?"]$faq$::jsonb, $faq$Ja — moms på förskott redovisas när betalningen tas emot, inte vid leverans.$faq$, $faq$Vid förskotts- eller a conto-betalning inträder momsskyldigheten när betalningen inflyter (undantag bygg med omvänd moms). Fakturera förskottet med moms och redovisa i betalningsperioden. Slutfakturan momsberäknas på återstoden. Proformafakturor utlöser ingen moms — de är inte fakturor i momslagens mening.$faq$, $faq$["ML 7 kap 8 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-019', 'Moms, VAT & periodisk sammanställning', 'vidarefakturering', $faq$["Hur momsar jag vidarefakturerade utlägg?","Vidarefakturera resekostnader till kund?","Utlägg eller vidarefakturering?"]$faq$::jsonb, $faq$Vidarefakturering följer din tjänsts momssats (oftast 25 %) — även om kostnaden hade annan moms.$faq$, $faq$Kostnader du haft i eget namn och vidarefakturerar (resor, hotell, material) blir del av ditt beskattningsunderlag och momsas med din tjänsts sats — ett hotell med 12 % vidarefaktureras alltså med 25 % om din konsulttjänst är 25 %. Äkta utlägg (i kundens namn och för kundens räkning, t.ex. myndighetsavgifter) förmedlas utan moms utanför underlaget.$faq$, $faq$["ML 8 kap 2 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-020', 'Moms, VAT & periodisk sammanställning', 'helarsmoms', $faq$["Kan jag redovisa moms en gång per år?","Helårsmoms — vem får ha det?","Byta momsperiod?"]$faq$::jsonb, $faq$Företag under 1 mkr i omsättning kan välja helårsmoms; byte av period anmäls till Skatteverket.$faq$, $faq$Beskattningsunderlag under 1 mkr/år ger rätt till helårsredovisning (deklareras i samband med inkomstdeklarationen om ingen EU-handel). 1–40 mkr ger kvartal som standard, över 40 mkr månad. Periodbyte anmäls till Skatteverket och uppdateras därefter under Inställningar → Skatt så att rapporter och deadlines stämmer.$faq$, $faq$["SFL 26 kap 11 §"]$faq$::jsonb, '{}'::text[], array['/settings/tax']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-021', 'Moms, VAT & periodisk sammanställning', 'rot_rut_moms', $faq$["Hur fungerar moms på ROT/RUT-fakturor?","Momsberäkning vid ROT-avdrag?","ROT-avdrag på arbetskostnad?"]$faq$::jsonb, $faq$Momsen beräknas på HELA beloppet före ROT/RUT-avdraget — avdraget minskar bara kundens betalning.$faq$, $faq$ROT/RUT-avdraget (fakturamodellen) dras från kundens betalning, inte från beskattningsunderlaget: fakturera fullt belopp med 25 % moms på allt, minus avdragsraden (30 % av arbetskostnaden för ROT, 50 % för RUT). Kunden betalar nettot; resten söker du från Skatteverket och bokför som fordran (1513) tills utbetalning. Nordklarts ROT/RUT-fakturor räknar och redovisar detta korrekt.$faq$, $faq$["Skatteverket: fakturamodellen"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-022', 'Moms, VAT & periodisk sammanställning', 'ruta05_diff', $faq$["Ruta 05 stämmer inte mot min omsättning — varför?","Momsrapporten avviker mot resultatrapporten?","Diff i momsunderlaget?"]$faq$::jsonb, $faq$Ruta 05 visar momspliktig omsättning — momsfri försäljning, EU-export och omvänd moms ligger i andra rutor.$faq$, $faq$Resultaträkningens intäkter innehåller ALL försäljning medan ruta 05 bara tar momspliktig svensk omsättning. EU-försäljning (35/39), export (36), omvänd byggmoms (41) och momsfria intäkter redovisas separat. Klicka på rutan i momsrapporten för att se ingående verifikationer och jämför mot 30xx-kontonas fördelning.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-023', 'Moms, VAT & periodisk sammanställning', 'justera_lamnad_deklaration', $faq$["Jag hittade fel efter att momsdeklarationen lämnats — vad gör jag?","Rätta inskickad momsdeklaration?","Omprövning av moms?"]$faq$::jsonb, $faq$Små belopp kan rättas i nästa period; annars begär omprövning hos Skatteverket för den felaktiga perioden.$faq$, $faq$Skatteverket accepterar att mindre fel (i praktiken tusenlappar, ej systematiska) korrigeras i nästkommande deklaration. Större eller principiella fel rättas genom omprövning av den ursprungliga perioden (kan göras sex år bakåt). Frivillig rättelse på eget initiativ ger normalt inget skattetillägg. Bokför rättelsen i öppen period med tydlig hänvisning.$faq$, $faq$["SFL 66 kap"]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'high', $faq$Vid större momsfel eller risk för skattetillägg — koppla in redovisningskonsult innan du kontaktar Skatteverket.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-024', 'Moms, VAT & periodisk sammanställning', 'eu_trosklar', $faq$["Finns beloppsgränser för EU-momsregler?","När måste jag registrera mig för OSS?","Tröskelvärde distansförsäljning?"]$faq$::jsonb, $faq$EU-gemensam tröskel för B2C-distansförsäljning: 10 000 EUR (99 680 kr) per år — däröver köparlandets moms.$faq$, $faq$För distansförsäljning av varor och digitala tjänster till EU-konsumenter gäller en gemensam tröskel om 10 000 EUR/år (99 680 kr): under den får du använda svensk moms, över den ska köparlandets moms tas ut (via OSS). För förvärv finns tröskeln 90 000 kr för när icke-momsregistrerade köpares EU-inköp blir beskattade förvärv.$faq$, $faq$["ML 6 kap 7–12 §§"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-025', 'Moms, VAT & periodisk sammanställning', 'ruta48_for_stor', $faq$["Kan jag dra all ingående moms?","Vilken moms får inte lyftas?","Avdragsförbud moms?"]$faq$::jsonb, $faq$Avdragsförbud gäller bl.a. personbilar, stadigvarande bostad och privat konsumtion — representation begränsas till 300 kr/person.$faq$, $faq$Ingående moms får dras när inköpet hör till momspliktig verksamhet. Undantag: personbilsköp (utan särskild verksamhet), stadigvarande bostad, privata kostnader, gåvor över gränsvärdena, samt representation över underlaget 300 kr/person. Nordklarts momsbehandlingar stoppar de vanligaste felen (t.ex. halverad leasingmoms, representationsberäkning).$faq$, $faq$["ML 13 kap 20–28 §§"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-026', 'Moms, VAT & periodisk sammanställning', 'skrot_omvand', $faq$["Omvänd moms på skrot och metall?","Sälja metallskrot B2B?","Avfallshandel moms?"]$faq$::jsonb, $faq$Ja — handel med skrot och vissa metaller mellan momsregistrerade företag har omvänd skattskyldighet.$faq$, $faq$Försäljning av metallskrot och avfall mellan svenska momsregistrerade företag omfattas av omvänd skattskyldighet: säljaren fakturerar utan moms, köparen redovisar ut- och ingående moms. Samma teknik gäller mobiltelefoner/bärbara datorer m.m. vid fakturor över 100 000 kr. Använd momsbehandlingen omvänd skattskyldighet inrikes.$faq$, $faq$["ML 16 kap 11–12 §§"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-027', 'Moms, VAT & periodisk sammanställning', 'konkurs_moms', $faq$["Kunden gick i konkurs — får jag tillbaka momsen?","Momsåtervinning kundförlust?","Skriva av faktura och moms?"]$faq$::jsonb, $faq$Ja — vid konstaterad kundförlust (t.ex. konkurs) får du minska utgående moms med fakturans momsbelopp.$faq$, $faq$Vid konstaterad kundförlust återtas den redovisade utgående momsen: minska ruta 10–12 i perioden förlusten konstateras. Konkursbeslut, utmätningsförsök eller ackord räknas som konstaterad; enbart obetald faktura räcker inte. Nordklarts avskrivningsflöde på fakturan bokför momsåtertaget automatiskt (Dr 26xx). Betalar kunden senare återförs momsen igen.$faq$, $faq$["ML 7 kap 44 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-028', 'Moms, VAT & periodisk sammanställning', 'moms_hobbyverksamhet', $faq$["Måste jag momsregistrera mig direkt?","Momsbefrielse under 120 000 kr?","Liten omsättning slippa moms?"]$faq$::jsonb, $faq$Omsättning under 120 000 kr/år kan vara momsbefriad — men då får du inte heller dra ingående moms.$faq$, $faq$Sedan 2025 gäller momsbefrielse för beskattningsbar person med årsomsättning under 120 000 kr. Befrielsen är frivillig: du fakturerar utan moms men förlorar avdragsrätten. Många väljer ändå registrering för att lyfta moms på inköp. Väljer du befrielse, sätt "ej momsregistrerad" i skatteinställningarna.$faq$, $faq$["ML 18 kap"]$faq$::jsonb, '{}'::text[], array['/settings/tax']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-029', 'Moms, VAT & periodisk sammanställning', 'trepartshandel', $faq$["Vad är trepartshandel?","Mellanman i EU-kedja moms?","Ruta 37/38?"]$faq$::jsonb, $faq$Trepartshandel är EU-kedjeförsäljning A→B→C där mellanmannen B slipper momsregistrering i C:s land — särskilda rutor 37/38.$faq$, $faq$Vid trepartshandel säljer A (land 1) till B (land 2) som säljer vidare till C (land 3) men varan går direkt A→C. Som svensk mellanman redovisar du inköpet i ruta 37 och försäljningen i ruta 38, fakturerar C utan moms med hänvisning till trepartshandel, och rapporterar i periodisk sammanställning med trepartsmarkering.$faq$, $faq$["ML 10 kap 50 §"]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-030', 'Moms, VAT & periodisk sammanställning', 'moms_konto_stammer_inte', $faq$["Momsrapporten stämmer inte mot 26xx-saldona — varför?","Diff mellan momsrutor och balanskonton?","Momskontroll innan deklaration?"]$faq$::jsonb, $faq$Kör momsrapportens avstämningsvy — vanliga orsaker är manuella poster direkt på 26xx eller fel momsbehandling.$faq$, $faq$Momsrapporten bygger på verifikationernas momsbehandling/rutor medan 26xx-saldona är bokförda belopp — de ska mötas. Diffar uppstår vid manuella bokningar direkt på momskonton utan momskod, felaktig momsbehandling eller poster i fel period. Rapportens per-ruta-källvy visar varje verifikation så du hittar avvikaren. Rätta via storno innan deklarationen lämnas.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-031', 'Moms, VAT & periodisk sammanställning', 'moms_presentkort', $faq$["Hur momsas presentkort?","Sälja giltiga presentkort — moms direkt?","Enfunktions- vs flerfunktionsvoucher?"]$faq$::jsonb, $faq$Enfunktionsvoucher momsas vid försäljningen; flerfunktionsvoucher först vid inlösen.$faq$, $faq$Ett presentkort som bara kan användas till leveranser med känd momssats (enfunktionsvoucher) beskattas när kortet säljs. Kan det användas till olika momssatser (flerfunktionsvoucher) bokförs försäljningen som skuld (2421) och momsen redovisas först när kortet löses in. Obetald skuld vid giltighetstidens slut intäktsförs.$faq$, $faq$["ML 8 kap 13–15 §§"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-032', 'Moms, VAT & periodisk sammanställning', 'ruta42', $faq$["Vad hamnar i ruta 42?","Övrig momsfri omsättning?","Försäkringsersättning i momsdeklarationen?"]$faq$::jsonb, $faq$Ruta 42: momsfri omsättning som inte hör hemma i andra rutor — t.ex. momsfria tjänster, bidrag kopplade till pris.$faq$, $faq$Ruta 42 samlar omsättning som är undantagen moms och inte redovisas i EU/export-rutorna: momsfri uthyrning, sjukvård, utbildning, försäkringstjänster, vissa medlemsavgifter. Rena bidrag och skadestånd utan motprestation är inte omsättning alls och ska inte in i deklarationen. Nordklart mappar momsfria behandlingar dit automatiskt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-033', 'Moms, VAT & periodisk sammanställning', 'byta_momsmetod_bokslut', $faq$["Bokslutsmetoden för moms — vad innebär den?","Momsredovisning vid kontantmetod?","Oreglerade fakturor och moms vid årsskiftet?"]$faq$::jsonb, $faq$Med bokslutsmetoden redovisas moms vid betalning under året — men alla obetalda fakturor momsas i årets sista period.$faq$, $faq$Bokslutsmetoden (kopplad till kontantmetoden, max 3 mkr) innebär momsredovisning när betalning sker. Vid räkenskapsårets slut måste dock momsen på samtliga obetalda kund- och leverantörsfakturor tas med i årets sista momsperiod. Nordklart hanterar detta i årsskiftesflödet när kontantmetoden är vald.$faq$, $faq$["ML 7 kap 27 §"]$faq$::jsonb, '{}'::text[], array['/reports/vat', '/year-end']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-034', 'Moms, VAT & periodisk sammanställning', 'deklarera_via_api', $faq$["Kan momsdeklarationen skickas till Skatteverket automatiskt?","E-inlämning av moms?","Ladda upp momsfil?"]$faq$::jsonb, $faq$Nordklart tar fram deklarationsunderlaget och eSKD-fil; inlämningen görs på Mina sidor eller via ombud.$faq$, $faq$Momsrapporten kan exporteras som fil för uppladdning i Skatteverkets e-tjänst, eller läsas av rad för rad vid manuell inlämning. Direktinlämning via API kräver Skatteverkets ombudsbehörigheter; med Skatteverket-kopplingen kan Nordklart hämta skattekontot och pricka av att deklarationen bokförts korrekt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat', '/skattekonto']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-035', 'Moms, VAT & periodisk sammanställning', 'ruta20_21_22', $faq$["Vad är skillnaden mellan ruta 20, 21 och 22?","Inköpsrutorna i momsdeklarationen?","Var hamnar utländska tjänsteinköp?"]$faq$::jsonb, $faq$Ruta 20: EU-varuinköp. Ruta 21: EU-tjänster (huvudregeln). Ruta 22: tjänster från land utanför EU.$faq$, $faq$Underlagen för omvänd skattskyldighet delas upp: ruta 20 unionsinterna varuförvärv, ruta 21 tjänsteinköp från EU enligt huvudregeln, ruta 22 tjänsteinköp från tredjeland, ruta 23 varuinköp i Sverige med omvänd moms (skrot m.m.), ruta 24 övriga tjänsteinköp med omvänd moms (bygg). Momsen på samtliga redovisas i 30–32 och dras i 48.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-036', 'Moms, VAT & periodisk sammanställning', 'ruta50_importmoms', $faq$["Var redovisas importmoms i deklarationen?","Ruta 50 beskattningsunderlag import?","Tullvärde i momsdeklarationen?"]$faq$::jsonb, $faq$Ruta 50: beskattningsunderlaget vid import; momsen i ruta 60–62 och avdraget i ruta 48.$faq$, $faq$Momsregistrerade företag redovisar importmoms i deklarationen: underlaget (tullvärde + tull + bikostnader) i ruta 50, utgående importmoms i 60/61/62 efter momssats, och samma belopp som ingående i 48 vid full avdragsrätt. Underlaget hämtas från Tullverkets tullräkning/deklaration.$faq$, $faq$["ML 5 kap"]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-037', 'Moms, VAT & periodisk sammanställning', 'forsenad_momsdeklaration', $faq$["Vad händer om momsdeklarationen blir försenad?","Förseningsavgift moms?","Missade momsdeadline?"]$faq$::jsonb, $faq$Förseningsavgift 625 kr (1 250 kr vid upprepning); skattetillägg kan tillkomma vid oriktiga uppgifter.$faq$, $faq$Lämnas deklarationen efter deadline tas förseningsavgift ut (625 kr). Betalas momsen sent löper kostnadsränta på skattekontot. Skattetillägg (20 % av momsen) gäller bara oriktiga uppgifter, inte sen inlämning. Lämna hellre en preliminärt uppskattad deklaration i tid och rätta efteråt än att missa datumet.$faq$, $faq$["SFL 48 kap"]$faq$::jsonb, '{}'::text[], array['/deadlines']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-038', 'Moms, VAT & periodisk sammanställning', 'uthyrning_parkering', $faq$["Är parkeringsuthyrning momspliktig?","Moms på parkeringsplatser?","Garageuthyrning?"]$faq$::jsonb, $faq$Ja — upplåtelse av parkeringsplats i parkeringsverksamhet är momspliktig med 25 %.$faq$, $faq$Till skillnad från fastighetsuthyrning är parkeringsupplåtelse momspliktig (25 %). Undantag: parkering som ingår underordnat i momsfri bostads- eller lokaluthyrning till samma hyresgäst. Fakturera parkeringen med moms och bokför på separat intäktskonto.$faq$, $faq$["ML 12 kap 6 §"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-039', 'Moms, VAT & periodisk sammanställning', 'marginalbeskattning', $faq$["Vad är vinstmarginalbeskattning?","Sälja begagnade varor moms?","VMB för begagnathandel?"]$faq$::jsonb, $faq$Vid handel med begagnade varor kan moms beräknas på vinstmarginalen i stället för hela priset — momsen får inte visas på fakturan.$faq$, $faq$Vinstmarginalbeskattning (VMB) används vid inköp av begagnade varor från privatpersoner: momsen (25 %) beräknas på skillnaden mellan försäljnings- och inköpspris. Fakturan får inte specificera moms (köparen har ingen avdragsrätt) och märks "vinstmarginalbeskattning för begagnade varor". Kräver separat lagerbokföring per vara eller klumpvis.$faq$, $faq$["ML 20 kap"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-040', 'Moms, VAT & periodisk sammanställning', 'moms_ideell', $faq$["Momsregler för ideell förening?","Är föreningens försäljning momspliktig?","Allmännyttig ideell och moms?"]$faq$::jsonb, $faq$Allmännyttiga ideella föreningar är ofta undantagna moms för verksamhet med naturlig anknytning till ändamålet.$faq$, $faq$Ideella föreningar vars inkomster är skattefria enligt IL är normalt inte skattskyldiga till moms för samma verksamhet. Kommersiell sidoverksamhet kan dock bli momspliktig. Bedömningen hänger på inkomstskattefriheten — kontrollera föreningens status innan momsregistrering.$faq$, $faq$["ML 4 kap 6 §"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'medium', $faq$Momsstatus för ideella föreningar är beroende av skattefrihetsbedömningen — stäm av med Skatteverket eller rådgivare.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-041', 'Moms, VAT & periodisk sammanställning', 'ruta06_07', $faq$["Vad är ruta 06 och 07?","Momsdeklarationens försäljningsrutor 12 och 6 procent?","Uppdelning av försäljning per momssats?"]$faq$::jsonb, $faq$Ruta 05/06/07 delar upp momspliktig försäljning: 25 %, 12 % respektive 6 % underlag.$faq$, $faq$Försäljningsunderlaget redovisas per momssats: ruta 05 (25 %), 06 (12 %), 07 (6 %); motsvarande utgående moms i 10, 11 och 12. Nordklart fördelar automatiskt utifrån radernas momssats — mixade fakturor delas korrekt per rad.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-042', 'Moms, VAT & periodisk sammanställning', 'distansforsaljning_varor', $faq$["Sälja varor till privatpersoner i EU — moms?","Webbutik med EU-kunder?","IOSS för import under 150 EUR?"]$faq$::jsonb, $faq$B2C-varor inom EU: svensk moms under 99 680 kr/år, därefter köparlandets moms via OSS; import ≤150 EUR kan gå via IOSS.$faq$, $faq$Webbutiker som skickar varor till EU-konsumenter använder svensk moms tills EU-tröskeln passeras, därefter destinationslandets momssats redovisad via OSS. Säljer du importvaror ≤ 150 EUR direkt från tredjeland till EU-konsument kan IOSS användas så att momsen tas vid köpet i stället för vid gränsen. Plattformsförsäljning (Amazon m.fl.) kan flytta momsansvaret till plattformen.$faq$, $faq$["ML 6 kap","ML 22–23 kap"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-043', 'Moms, VAT & periodisk sammanställning', 'faktura_annan_valuta_moms', $faq$["Fakturera i EUR — hur redovisas momsen?","Moms på valutafaktura?","Momsbeloppet i SEK på fakturan?"]$faq$::jsonb, $faq$Momsen ska anges i SEK på fakturan (eller EUR om det är din redovisningsvaluta) — omräknad med kurs per fakturadatum.$faq$, $faq$Vid fakturering i utländsk valuta måste momsbeloppet också anges i SEK, omräknat med Riksbankens (eller ECB:s) kurs på fakturadagen. Nordklart hämtar kursen för fakturadatumet automatiskt, skriver momsbeloppet i båda valutorna på fakturan och bokför SEK-beloppen i momsdeklarationen.$faq$, $faq$["ML 17 kap 30 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-044', 'Moms, VAT & periodisk sammanställning', 'ruta35_diff_ps', $faq$["Periodiska sammanställningen matchar inte ruta 35 — vad är fel?","Diff mellan EC Sales List och momsdeklarationen?","Skatteverket frågar om ruta 35?"]$faq$::jsonb, $faq$Beloppen ska stämma överens per period — vanliga orsaker är kreditfakturor, fel period eller saknat VAT-nummer.$faq$, $faq$Skatteverket samkör ruta 35/39 mot periodisk sammanställning. Diffar beror ofta på: kreditfaktura som hamnat i annan period, försäljning bokförd som EU utan giltigt VAT-nummer (ska vara svensk moms), eller tjänst som inte följer huvudregeln (rapporteras inte i PS). Nordklarts PS-underlag bygger på samma fakturor som momsrutorna, så avvikelser syns direkt i rapportens källvy.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-045', 'Moms, VAT & periodisk sammanställning', 'moms_drivmedel', $faq$["Momsavdrag på bensin till företagsbilen?","Drivmedel privatbil vs förmånsbil moms?","Full moms på diesel?"]$faq$::jsonb, $faq$Drivmedel till verksamhetens fordon ger fullt momsavdrag — även för personbilar som är förmånsbilar.$faq$, $faq$Till skillnad från bilköpet ger driftskostnader fullt momslyft: bränsle, service, reparation, tvätt (för bil som används i verksamheten). För milersättning till anställds privata bil finns inget momslyft (ersättningen är schablon). Bokför drivmedel på 5611 med 25 % ingående moms.$faq$, $faq$["ML 13 kap 21 §"]$faq$::jsonb, '{}'::text[], array['/transactions']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-046', 'Moms, VAT & periodisk sammanställning', 'elektroniska_tjanster_b2c', $faq$["Moms på appar och streaming till konsumenter?","Digitala tjänster B2C-regler?","Var beskattas min SaaS till privatpersoner?"]$faq$::jsonb, $faq$Digitala tjänster till EU-konsumenter beskattas i köparens land (över tröskeln) — hanteras via OSS.$faq$, $faq$Elektroniska tjänster (mjukvara, streaming, e-böcker, spel) till privatpersoner beskattas där kunden finns. Under 99 680 kr/år totalt inom EU får svensk moms användas; över tröskeln krävs köparlandets moms via OSS-deklarationen. B2B faller under huvudregeln (omvänd skattskyldighet). Dokumentera kundens land (IP, betalningsland).$faq$, $faq$["ML 6 kap 58–60 §§"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-047', 'Moms, VAT & periodisk sammanställning', 'justeringsmoms_fastighet', $faq$["Vad är jämkning av moms på fastighetsinvesteringar?","Justera investeringsmoms vid ändrad användning?","Jämkningshandling vid fastighetsköp?"]$faq$::jsonb, $faq$Momsavdrag på större fastighetsinvesteringar följs upp i 10 år — ändrad användning kräver årlig justering.$faq$, $faq$Ingående moms på fastighetsinvesteringar över 200 000 kr ska jämkas under en korrigeringstid på 10 år om användningen ändras mellan momspliktig och momsfri. Vid fastighetsöverlåtelse ska en justeringshandling upprättas så förvärvaren kan ta över skyldigheten. Detta är ett komplext område — dokumentera investeringsmomsen per projekt.$faq$, $faq$["ML 15 kap"]$faq$::jsonb, '{}'::text[], '{}'::text[], 'high', $faq$Momsjämkning på fastigheter kräver specialist — fel kan bli dyra över 10-årsperioden.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-048', 'Moms, VAT & periodisk sammanställning', 'kassarabatt_moms', $faq$["Påverkar lämnad rabatt momsen?","Kassarabatt och momsunderlag?","Mängdrabatt i efterhand?"]$faq$::jsonb, $faq$Ja — rabatter minskar beskattningsunderlaget; efterhandsrabatter kräver kreditfaktura för momsjustering.$faq$, $faq$Rabatt som lämnas direkt på fakturan minskar underlag och moms automatiskt. Villkorad kassarabatt ("10 dagar −2 %") och efterhandsrabatter/bonusar justeras med kreditfaktura när de utnyttjas — annars får du inte minska momsen. Nordklart bokför kreditfakturans momsminskning i utställandeperioden.$faq$, $faq$["ML 8 kap 16 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-049', 'Moms, VAT & periodisk sammanställning', 'momskontroll_skatteverket', $faq$["Skatteverket vill se momsunderlag — vad skickar jag?","Momsgranskning förfrågan?","Underlag vid momskontroll?"]$faq$::jsonb, $faq$Skicka momsrapporten per ruta, huvudbok för momskontona och de efterfrågade verifikationerna med underlag.$faq$, $faq$Vid en momsförfrågan begär Skatteverket vanligen: specifikation av rutorna (Nordklarts momsrapport med källverifikationer), huvudbok för 26xx-kontona, samt kopior av större inköps-/försäljningsfakturor. Allt finns exporterbart i systemet; dokumentarkivet håller underlagen kopplade till verifikationerna. Svara inom angiven tid och håll dig till det efterfrågade.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat', '/documents']::text[], 'medium', $faq$Vid revision (inte bara förfrågan) — koppla in din redovisningskonsult som ombud tidigt.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-050', 'Moms, VAT & periodisk sammanställning', 'ruta_a_b_omvand', $faq$["Var redovisar jag min försäljning med omvänd byggmoms?","Ruta 41 — vad ingår?","Säljarens redovisning vid omvänd moms?"]$faq$::jsonb, $faq$Säljaren redovisar omvänd-moms-försäljning i ruta 41 (bygg) eller 35/39 (EU) — utan utgående moms.$faq$, $faq$När du säljer med omvänd skattskyldighet redovisas bara underlaget: ruta 41 för inrikes omvänd moms (byggtjänster, skrot), ruta 39 för EU-tjänster enligt huvudregeln, ruta 35 för EU-varor. Ingen utgående moms bokförs hos dig — köparen tar den. Nordklart styr rutan via fakturans momsbehandling.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-051', 'Moms, VAT & periodisk sammanställning', 'leasing_forhojd_avgift_moms', $faq$["Moms på första förhöjd leasingavgift?","Halverat momsavdrag på förhöjd hyra personbil?","Periodisera leasingmoms?"]$faq$::jsonb, $faq$Samma regler som ordinarie avgift: halv moms för personbil — avdraget tas när fakturan bokförs, kostnaden periodiseras.$faq$, $faq$Den första förhöjda leasingavgiften för personbil ger också bara 50 % momsavdrag. Momsen lyfts vid fakturans bokföring medan kostnaden (netto) periodiseras över leasingperioden via 1720. För transportbilar gäller fullt momsavdrag.$faq$, $faq$["ML 13 kap 20 §"]$faq$::jsonb, '{}'::text[], array['/supplier-invoices']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-052', 'Moms, VAT & periodisk sammanställning', 'faktureringsdatum_vs_leverans', $faq$["Vilken period hamnar momsen i — faktura- eller leveransdatum?","Moms december eller januari?","Skattskyldighetens inträde?"]$faq$::jsonb, $faq$Med fakturametoden styr fakturadatumet momsperioden (leverans och fakturering ska ligga nära varandra).$faq$, $faq$Momsen redovisas i den period skattskyldigheten inträder — vid leverans/tillhandahållande, men med fakturadatum som praktisk huvudregel när fakturan ställs ut i nära anslutning (senast 15:e i månaden efter leverans för EU-handel). Årsskiftesleveranser: fakturera i rätt period eller periodisera medvetet. Kontantmetoden styr i stället på betalningsdatum.$faq$, $faq$["ML 7 kap"]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-053', 'Moms, VAT & periodisk sammanställning', 'ruta10_negativt', $faq$["Kan utgående moms bli negativ i en period?","Minusbelopp i ruta 10?","Stora kreditfakturor och momsdeklarationen?"]$faq$::jsonb, $faq$Ja — stora krediteringar kan göra rutan negativ; deklarationen accepterar negativa rutvärden.$faq$, $faq$Om periodens kreditfakturor överstiger försäljningen blir utgående moms negativ, vilket är korrekt och accepteras i deklarationen. Nordklart summerar med tecken. Var beredd på att Skatteverket kan fråga vid stora negativa perioder — kreditfakturornas koppling till original finns som svar.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/reports/vat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-054', 'Moms, VAT & periodisk sammanställning', 'utlagg_klientmedel', $faq$["Hur hanteras klientmedel momsmässigt?","Betala för kundens räkning utan moms?","Utlägg i kundens namn?"]$faq$::jsonb, $faq$Äkta utlägg i kundens namn och för kundens räkning ligger utanför momsen — bokförs över balanskonto.$faq$, $faq$Ett äkta utlägg (fakturan är ställd till kunden, du bara förmedlar betalningen — t.ex. ansökningsavgifter, stämpelskatt) ingår inte i ditt beskattningsunderlag: bokför över 1680/2890 och vidarefakturera utan moms som "utlägg". Är fakturan ställd till dig är det i stället en vidarefakturering med moms enligt din tjänsts sats.$faq$, $faq$["ML 8 kap 2 §"]$faq$::jsonb, '{}'::text[], array['/invoices']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('moms-055', 'Moms, VAT & periodisk sammanställning', 'momsregistrering_retroaktivt', $faq$["Kan jag dra moms på inköp gjorda före momsregistreringen?","Retroaktivt momsavdrag vid start?","Moms på uppstartskostnader?"]$faq$::jsonb, $faq$Ja — ingående moms på förvärv för verksamheten före registrering kan dras (varor i lager, tjänster upp till viss tid).$faq$, $faq$Vid momsregistrering får du retroaktivt avdrag för moms på varor som fortfarande finns kvar i verksamheten och som anskaffats för den. Praktiskt hanteras det i första deklarationen med underlag. Ansök om registrering från rätt datum (verksamhetens start) så minimeras problemet.$faq$, $faq$["ML 13 kap 35 §"]$faq$::jsonb, '{}'::text[], array['/settings/tax']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-001', 'Kom igång & onboarding', 'skapa_foretag', $faq$["Hur skapar jag ett företag i Nordklart?","Hur lägger jag till ett nytt bolag?","Kan jag registrera mitt företag i systemet?","Var börjar jag när jag är ny?"]$faq$::jsonb, $faq$Skapa företaget under onboardingen — ange organisationsnummer så hämtas uppgifterna automatiskt.$faq$, $faq$När du loggar in första gången startar onboardingen automatiskt. Ange företagets organisationsnummer så hämtar Nordklart namn, adress och SNI-kod via TIC-uppslaget. Därefter väljer du företagsform (enskild firma eller aktiebolag), räkenskapsår och redovisningsmetod. Du kan skapa fler företag senare via företagsväljaren uppe till vänster.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/onboarding', '/settings/company']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-002', 'Kom igång & onboarding', 'flera_foretag', $faq$["Kan jag ha flera företag i samma konto?","Hur byter jag mellan mina bolag?","Stödjer Nordklart flera företag?"]$faq$::jsonb, $faq$Ja — en användare kan äga eller vara medlem i flera företag och växlar via företagsväljaren.$faq$, $faq$Nordklart är multitenant: varje användare kan vara medlem i flera företag, med olika roller i varje. Byt aktivt företag via företagsväljaren i sidhuvudet. All data (verifikationer, fakturor, transaktioner) är strikt separerad per företag.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/company']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-003', 'Kom igång & onboarding', 'valj_foretagsform', $faq$["Vad är skillnaden mellan enskild firma och aktiebolag i Nordklart?","Spelar företagsformen någon roll i systemet?","Varför frågar ni om bolagsform?"]$faq$::jsonb, $faq$Företagsformen styr kontoplan, egna uttag/insättningar, bokslutsflöde och deklarationstyp (NE eller INK2).$faq$, $faq$Enskild firma använder eget kapital-konton 2010–2019 (egna uttag/insättningar) och deklarerar via NE-bilagan. Aktiebolag använder 2081/2091/2093/2098 m.fl., bokför bolagsskatt och deklarerar via INK2. Bokslutsguiden och skattedispositionerna anpassas automatiskt efter vald form. Formen sätts vid onboarding och kan inte bytas utan nytt företag.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/company', '/year-end']::text[], 'medium', $faq$Osäker på val av företagsform? Det är ett skatte- och ansvarsbeslut — rådgör med en redovisningskonsult.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-004', 'Kom igång & onboarding', 'kontoplan', $faq$["Vilken kontoplan används?","Måste jag lägga upp konton själv?","Använder ni BAS-kontoplanen?"]$faq$::jsonb, $faq$Nordklart använder BAS 2026 — standardkonton aktiveras automatiskt, och du kan aktivera fler vid behov.$faq$, $faq$Vid onboarding aktiveras en standarduppsättning BAS 2026-konton anpassad efter din företagsform. Du kan aktivera ytterligare konton under Inställningar → Bokföring → Kontoplan, och SIE-importen skapar automatiskt konton som saknas. Kontonummer är alltid fyrsiffriga BAS-nummer.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-005', 'Kom igång & onboarding', 'rakenskapsar', $faq$["Hur sätter jag räkenskapsår?","Kan jag ha brutet räkenskapsår?","Var anger jag när mitt räkenskapsår börjar?"]$faq$::jsonb, $faq$Räkenskapsårets startmånad anges i företagsinställningarna; brutet räkenskapsår stöds för aktiebolag.$faq$, $faq$Ange räkenskapsårets startmånad under Inställningar → Företag. Kalenderår (januari–december) är standard. Aktiebolag kan ha brutet räkenskapsår (t.ex. juli–juni); enskilda firmor måste enligt BFL ha kalenderår. Räkenskapsperioder skapas sedan automatiskt när du bokför.$faq$, $faq$["BFL 3 kap"]$faq$::jsonb, '{}'::text[], array['/settings/company']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-006', 'Kom igång & onboarding', 'redovisningsmetod', $faq$["Vad är skillnaden mellan fakturametoden och kontantmetoden?","Vilken redovisningsmetod ska jag välja?","Kan jag byta redovisningsmetod?"]$faq$::jsonb, $faq$Fakturametoden bokför vid fakturering, kontantmetoden vid betalning. Valet styr hur fakturor bokförs i Nordklart.$faq$, $faq$Med fakturametoden (faktureringsmetoden) bokförs kundfakturan när den skickas (Dr 1510 / Kr 30xx + moms) och betalningen clearar 1510. Med kontantmetoden bokförs intäkt och moms först vid betalningen. Kontantmetoden får användas av företag med nettoomsättning under 3 mkr. Metoden ställs in under Inställningar → Bokföring och styr automatiskt verifikationernas utseende.$faq$, $faq$["BFL 5 kap 2 §"]$faq$::jsonb, '{}'::text[], array['/settings/bookkeeping']::text[], 'medium', $faq$Byte av redovisningsmetod mitt i ett räkenskapsår kan kräva justeringar — stäm av med din redovisningskonsult.$faq$, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-007', 'Kom igång & onboarding', 'ingaende_balanser', $faq$["Hur lägger jag in ingående balanser?","Jag byter från ett annat system — hur får jag in mina saldon?","Var registrerar jag öppningsbalans?"]$faq$::jsonb, $faq$Importera en SIE-fil från ditt gamla system, eller registrera ingående balanser manuellt under Import.$faq$, $faq$Det bästa sättet är att exportera en SIE-fil (SIE4) från ditt tidigare system och importera den under Import → SIE — då följer både ingående balanser, kontoplan och verifikationshistorik med. Alternativt kan du registrera öppningsbalanser manuellt via Import → Ingående balanser; de bokförs då som en särskild öppningsverifikation.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import', '/import/opening-balance']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-008', 'Kom igång & onboarding', 'bankkoppling_start', $faq$["Hur kopplar jag min bank?","Kan Nordklart hämta mina banktransaktioner automatiskt?","Vilka banker stöds?"]$faq$::jsonb, $faq$Koppla banken via PSD2 under Inställningar → Bank — de flesta svenska banker stöds via Enable Banking.$faq$, $faq$Under Inställningar → Bank ansluter du din företagsbank via en säker PSD2-koppling (Enable Banking). Du identifierar dig med BankID hos banken och godkänner läsbehörighet. Därefter synkas transaktioner automatiskt varje natt. Stöd finns för bl.a. SEB, Swedbank, Handelsbanken, Nordea, Länsförsäkringar, Danske Bank m.fl.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/banking']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-009', 'Kom igång & onboarding', 'momsregistrering', $faq$["Var anger jag att företaget är momsregistrerat?","Hur ställer jag in momsperiod?","Nordklart visar fel momsperiod — var ändrar jag?"]$faq$::jsonb, $faq$Momsregistrering och momsperiod (månad/kvartal/år) ställs in under Inställningar → Skatt.$faq$, $faq$Under Inställningar → Skatt anger du om företaget är momsregistrerat, VAT-nummer och redovisningsperiod för moms (månadsvis, kvartalsvis eller helår). Uppgifterna styr momsrapporten, deadlines i kalendern och assistentens momssvar. Är företaget inte momsregistrerat bokförs alla försäljningar utan utgående moms.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/tax']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-010', 'Kom igång & onboarding', 'f_skatt', $faq$["Var anger jag att jag har F-skatt?","Varför behöver Nordklart veta om F-skatt?","Hur syns F-skatt på fakturan?"]$faq$::jsonb, $faq$F-skattestatus anges under Inställningar → Skatt och skrivs ut på dina fakturor enligt god fakturased.$faq$, $faq$Ange F-skattestatus under Inställningar → Skatt. Texten "Godkänd för F-skatt" skrivs då ut på kundfakturor, vilket är standard i Sverige och krävs för att uppdragsgivare inte ska göra skatteavdrag. Har du inte F-skatt bör du ansöka hos Skatteverket innan du fakturerar.$faq$, $faq$["Skatteverket: F-skatt"]$faq$::jsonb, '{}'::text[], array['/settings/tax']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-011', 'Kom igång & onboarding', 'onboarding_assistent', $faq$["Vad gör assistenten under onboardingen?","Varför byggs en AI-profil för mitt bolag?","Vad är kunskapsprofilen?"]$faq$::jsonb, $faq$Assistenten sätter ihop en kompetensprofil för ditt företag baserat på bransch (SNI) och bolagsform.$faq$, $faq$Under onboardingen analyserar assistenten företagets SNI-kod och bolagsform och väljer relevanta kunskapsområden (t.ex. bygg med omvänd byggmoms, e-handel med OSS, konsult med EU-tjänster). Profilen styr vilka regler assistenten kan i detalj. Du granskar och godkänner profilen innan den aktiveras, och kan se den under Inställningar → Assistenten.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/assistant']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-012', 'Kom igång & onboarding', 'importera_kunder', $faq$["Kan jag importera mina kunder?","Hur får jag in kundregistret från gamla systemet?","Finns kundimport?"]$faq$::jsonb, $faq$Ja — kunder följer med i SIE-motparter eller kan läggas till manuellt/via API.$faq$, $faq$Kunder kan skapas manuellt under Kunder, via API:et (POST /api/v1/companies/{id}/customers) eller så byggs motpartsregistret upp automatiskt när du importerar fakturor. Vid migrering från Fortnox/Bokio/Visma via migreringsguiden följer kunddata med där källsystemet exponerar den.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/customers']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-013', 'Kom igång & onboarding', 'importera_artiklar', $faq$["Kan jag importera artiklar?","Finns artikelimport från Excel?","Hur lägger jag upp artikelregister?"]$faq$::jsonb, $faq$Ja — importera artiklar från Excel/CSV under Import → Artiklar, eller skapa dem manuellt.$faq$, $faq$Under Import → Artiklar laddar du upp en Excel- eller CSV-fil; kolumnerna detekteras automatiskt (namn, pris, momssats, intäktskonto). Du kan också exportera en mall från Artiklar → Exportera som säkert återimporteras. Artiklar används sedan för snabb radregistrering på fakturor.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import', '/commerce/articles']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-014', 'Kom igång & onboarding', 'migrera_fran_fortnox', $faq$["Hur flyttar jag från Fortnox till Nordklart?","Kan ni hämta min bokföring från Fortnox automatiskt?","Migrering från Fortnox?"]$faq$::jsonb, $faq$Använd migreringsguiden — den hämtar SIE-data direkt från Fortnox via API, upp till tre räkenskapsår.$faq$, $faq$Migreringsguiden (Inställningar → Migrering) kopplar upp mot Fortnox, Briox eller Björn Lundén via API och hämtar SIE-exporter för innevarande och de två föregående räkenskapsåren. Kontomappningen föreslås automatiskt och du granskar den innan importen körs. Bokio och andra system utan SIE-API migreras genom att du laddar upp SIE-filer manuellt.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-015', 'Kom igång & onboarding', 'testa_sandlada', $faq$["Finns det en testmiljö?","Kan jag prova utan att påverka riktiga siffror?","Vad är sandlådeläget?"]$faq$::jsonb, $faq$Ja — sandlådeföretag låter dig utforska med exempeldata utan att röra skarp bokföring.$faq$, $faq$Ett sandlådeföretag (demo) innehåller exempeldata och är tydligt märkt. Där kan du testa flöden utan risk. Vissa funktioner som AI-tolkning av dokument och skarpa bankkopplingar är avstängda i sandlådan. Skapa ett riktigt företag när du är redo — data flyttas inte mellan sandlåda och skarpt bolag.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/company']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-016', 'Kom igång & onboarding', 'bjud_in_medarbetare', $faq$["Hur bjuder jag in min kollega?","Kan flera personer jobba i samma bolag?","Lägga till användare?"]$faq$::jsonb, $faq$Bjud in medlemmar under Inställningar → Team — de får en inbjudningslänk via e-post.$faq$, $faq$Under Inställningar → Team bjuder du in användare med e-postadress och väljer roll (ägare, admin, medlem eller läsbehörighet). Inbjudan skickas som en säker länk med sju dagars giltighet. Din redovisningskonsult kan i stället kopplas via byråfunktionen så att hela byrån får åtkomst.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/team']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-017', 'Kom igång & onboarding', 'roller_oversikt', $faq$["Vilka roller finns det?","Vad får en medlem göra jämfört med admin?","Vad innebär läsbehörighet?"]$faq$::jsonb, $faq$Roller: ägare, admin, medlem (bokför) och viewer (läser). Ägare/admin hanterar inställningar och team.$faq$, $faq$Ägare och admin kan ändra företagsinställningar, hantera team och automatisering. Medlem kan bokföra, fakturera och hantera löpande arbete. Viewer (läsbehörighet) kan se allt och importera kontoutdrag råa, men aldrig bokföra eller ändra. Revisorer får ofta viewer-roll.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/team']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-018', 'Kom igång & onboarding', 'automatisering_setup', $faq$["Hur slår jag på automatisk bokföring?","Var ställer jag in automatiseringen?","Kan systemet bokföra åt mig?"]$faq$::jsonb, $faq$Automatiseringen styrs per företag under Inställningar → Automatisering — börja i förslagsläge.$faq$, $faq$Nordklart bokför aldrig något utan att du har valt det. Under Inställningar → Automatisering väljer du läge: Av, Föreslå (standard), Säker automatik eller Full automatik, plus trösklar och beloppsgränser. I förslagsläget matchas transaktioner mot fakturor och regler men allt kräver ditt godkännande. Säker automatik bokför bara exakta träffar som klarar alla kontroller.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/automation']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-019', 'Kom igång & onboarding', 'kassa_konto', $faq$["Vad är ett likvidkonto/cash account?","Varför måste banken kopplas till 1930?","Kan jag ha flera bankkonton?"]$faq$::jsonb, $faq$Varje bankkonto mappas till ett BAS-konto i klass 19 (1930, 1931, …) — flera konton stöds.$faq$, $faq$När du kopplar banken skapas ett likvidkonto per bankkonto och mappas mot ett BAS-konto i klass 19 (företagskontot brukar vara 1930, ytterligare konton 1931, 1932 osv.). Mappningen styr vilken bokföringssida bankbetalningar hamnar på och håller bankavstämningen separerad per konto, även i olika valutor.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/banking']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-020', 'Kom igång & onboarding', 'mobil', $faq$["Finns Nordklart som app?","Kan jag använda mobilen?","Fungerar det på surfplatta?"]$faq$::jsonb, $faq$Nordklart är en webbapp som fungerar i mobilens webbläsare — kvittofoto och attest funkar bra mobilt.$faq$, $faq$Nordklart körs i webbläsaren och är responsivt, så du kan fota kvitton, godkänna väntande åtgärder och kolla rapporter från mobilen. Någon separat butiksapp behövs inte. För tyngre arbete som bokslut rekommenderas större skärm.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], '{}'::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-021', 'Kom igång & onboarding', 'sprak', $faq$["Kan jag byta språk?","Finns Nordklart på engelska?","Varför är fakturan på svenska?"]$faq$::jsonb, $faq$Gränssnittet finns på svenska och engelska; fakturor kan skickas på kundens språk.$faq$, $faq$Ditt gränssnittsspråk ändras i användarinställningarna. Bokföringsbegrepp, rapporter till myndigheter och momstermer förblir svenska eftersom de följer svensk lag. Kundfakturor renderas på svenska eller engelska beroende på kundens språkinställning i kundkortet.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-022', 'Kom igång & onboarding', 'onboarding_checklista', $faq$["Vad behöver jag göra innan jag börjar bokföra?","Finns en checklista för att komma igång?","Vad är minsta setup?"]$faq$::jsonb, $faq$Minsta setup: företagsuppgifter, räkenskapsår, redovisningsmetod, momsinställningar och bankkoppling.$faq$, $faq$Innan du bokför löpande: 1) komplettera företagsuppgifter och organisationsnummer, 2) sätt räkenskapsår och redovisningsmetod, 3) ange momsregistrering och momsperiod, 4) koppla banken eller importera kontoutdrag, 5) importera ingående balanser om du byter system. Därefter flödar transaktioner in och du kan börja fakturera.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/company', '/settings/tax', '/settings/banking', '/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-023', 'Kom igång & onboarding', 'priser_plan', $faq$["Vad ingår i min plan?","Hur ser jag vilka funktioner jag har?","Varför är en funktion låst?"]$faq$::jsonb, $faq$Funktioner styrs av företagets plan/berättiganden — se Inställningar → Fakturering & plan.$faq$, $faq$Vilka moduler som är aktiva (t.ex. lön, bokslut, API) styrs av företagets plan och eventuella tillägg. Under Inställningar → Fakturering ser du aktuell plan och kan uppgradera. Om en funktion svarar "Funktionen är inte aktiverad för bolaget" behöver planen eller tillägget aktiveras.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/billing']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-024', 'Kom igång & onboarding', 'support', $faq$["Hur kontaktar jag supporten?","Var får jag hjälp?","Finns det dokumentation?"]$faq$::jsonb, $faq$Fråga assistenten först — den kan systemet och svensk redovisning. Support når du via supportmailen.$faq$, $faq$Assistenten (chattikonen) svarar på både produktfrågor och svenska redovisningsfrågor och kan ofta lösa ärendet direkt. För kontofrågor, buggar eller ärenden som kräver människa kontaktar du supporten via e-post; ha gärna företags-id och en skärmbild redo.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/chat']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-025', 'Kom igång & onboarding', 'byta_fran_bokio', $faq$["Hur flyttar jag från Bokio?","Bokio-migrering — vad ska jag tänka på?","Kan jag importera Bokio-data?"]$faq$::jsonb, $faq$Exportera SIE4 från Bokio och importera under Import → SIE; ta gärna med föregående år.$faq$, $faq$Bokio kan exportera SIE4-filer per räkenskapsår. Exportera innevarande plus föregående år, importera det äldsta året först i Nordklart (Import → SIE). Kontomappningen föreslås automatiskt; granska särskilt egna konton utanför BAS-standard. Ingående balanser följer med via #IB eller härleds från föregående års #UB.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-026', 'Kom igång & onboarding', 'verifikationsserier', $faq$["Vad är verifikationsserier?","Kan jag välja serie för olika typer av verifikat?","Varför heter mina verifikat A1, A2?"]$faq$::jsonb, $faq$Verifikationer numreras löpande per serie (A som standard); olika händelsetyper kan få egna serier.$faq$, $faq$Varje verifikation får ett löpnummer inom en serie (A1, A2, …). Under Inställningar → Bokföring kan du styra vilken serie olika källtyper använder (t.ex. fakturor i serie B). Numren tilldelas atomiskt vid bokföring och får aldrig återanvändas — luckor måste förklaras enligt BFNAR 2013:2.$faq$, $faq$["BFNAR 2013:2"]$faq$::jsonb, '{}'::text[], array['/settings/bookkeeping']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-027', 'Kom igång & onboarding', 'komplett_flytt_mitt_i_aret', $faq$["Kan jag byta till Nordklart mitt i räkenskapsåret?","Flytta bokföring mitt under året — går det?","Vad händer med det jag redan bokfört i gamla systemet?"]$faq$::jsonb, $faq$Ja — importera årets SIE-fil från gamla systemet så följer både IB och årets verifikationer med.$faq$, $faq$Exportera en SIE4-fil från ditt nuvarande system som täcker räkenskapsårets början fram till bytesdagen och importera den i Nordklart. Verifikationerna bokförs med källmärkning "import", och därefter bokför du löpande i Nordklart. Undvik att bokföra samma period i båda systemen — vid överlapp mellan SIE-import och bankimport blockerar Nordklart automatisk bokföring för att förhindra dubbletter.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/import']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-028', 'Kom igång & onboarding', 'vat_nummer', $faq$["Vad är mitt VAT-nummer?","Hur formateras svenskt momsregistreringsnummer?","Var anger jag VAT-nummer?"]$faq$::jsonb, $faq$Svenskt VAT-nummer är SE + organisationsnummer + 01. Anges under Inställningar → Skatt.$faq$, $faq$Ett svenskt momsregistreringsnummer bildas som SE följt av organisationsnumret (10 siffror, utan bindestreck) och suffixet 01, t.ex. SE556677889901. Det anges under Inställningar → Skatt och skrivs ut på fakturor. Vid EU-handel validerar Nordklart motpartens VAT-nummer mot VIES.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/tax']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-029', 'Kom igång & onboarding', 'logotyp_faktura', $faq$["Hur lägger jag in min logotyp på fakturan?","Kan jag anpassa fakturans utseende?","Fakturadesign?"]$faq$::jsonb, $faq$Ladda upp logotyp och anpassa färger/texter under Inställningar → Fakturering.$faq$, $faq$Under Inställningar → Fakturering laddar du upp logotyp och styr färger, typsnitt, sidfotstext och vilka betalsätt (bankgiro, plusgiro, Swish) som visas. Ändringarna slår igenom på nya PDF-fakturor direkt; redan skickade fakturor ändras inte.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/invoicing']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-030', 'Kom igång & onboarding', 'dokumentarkiv', $faq$["Var sparas mina underlag?","Hur länge sparas kvitton och fakturor?","Är arkiveringen laglig?"]$faq$::jsonb, $faq$Alla underlag arkiveras digitalt i 7 år enligt bokföringslagen och kan inte raderas när de är kopplade till bokföring.$faq$, $faq$Kvitton, fakturor och andra underlag lagras i Nordklarts dokumentarkiv med versionshantering och integritetskontroll. Dokument kopplade till bokförda verifikationer skyddas mot radering i 7 år (räknat från räkenskapsårets slut) enligt BFL 7 kap. Du kan därför tryggt slänga papperskvittot efter digitalisering, med undantaget att vissa originalhandlingar ska sparas 3 år.$faq$, $faq$["BFL 7 kap"]$faq$::jsonb, '{}'::text[], array['/documents']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-031', 'Kom igång & onboarding', 'tva_faktor', $faq$["Hur aktiverar jag tvåfaktorsautentisering?","Är mitt konto skyddat med 2FA?","MFA-krav?"]$faq$::jsonb, $faq$Aktivera TOTP (autentiseringsapp) under kontosäkerhet — i molntjänsten är MFA obligatoriskt.$faq$, $faq$Nordklart använder TOTP-baserad tvåfaktorsautentisering (t.ex. Google Authenticator eller 1Password). I den hostade tjänsten kräver systemet MFA innan du når företagsdata. Aktivera eller återställ under kontoinställningarna; spara återställningskoderna säkert.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-032', 'Kom igång & onboarding', 'api_kom_igang', $faq$["Hur kommer jag igång med API:et?","Var skapar jag en API-nyckel?","Finns det ett publikt API?"]$faq$::jsonb, $faq$Skapa en API-nyckel under Inställningar → API — nycklar är scopade och rate-limitade.$faq$, $faq$Under Inställningar → API skapar du nycklar med prefixet nordklart_sk_ och väljer scopes (t.ex. invoices:write, transactions:read). API:et är REST (JSON) under /api/v1 med idempotensnycklar för skrivande anrop och 100 anrop/minut per nyckel. Dokumentation finns via OpenAPI-specifikationen.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/settings/api']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-033', 'Kom igång & onboarding', 'deadline_kalender', $faq$["Vilka deadlines håller systemet koll på?","Påminner ni om momsdeklarationen?","Finns skattekalender?"]$faq$::jsonb, $faq$Ja — moms, arbetsgivardeklaration, F-skatt och årsdeadlines bevakas och visas i kalendern.$faq$, $faq$Nordklart beräknar dina deadlines utifrån momsperiod, löner och bolagsform: momsdeklaration, arbetsgivardeklaration (AGI), preliminärskatt, inkomstdeklaration och årsredovisning. De visas på översikten och kan prenumereras som ICS-kalender. Påminnelser skickas i god tid före förfallodagen.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/deadlines']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-034', 'Kom igång & onboarding', 'vad_ar_pending', $faq$["Vad betyder \"väntande åtgärder\"?","Vad är pending operations?","Varför måste jag godkänna saker?"]$faq$::jsonb, $faq$Väntande åtgärder är förslag från assistenten eller automatiken som kräver ditt godkännande innan de bokförs.$faq$, $faq$Allt som assistenten eller automatiken vill skriva i bokföringen läggs först som en väntande åtgärd (pending operation) med förhandsgranskning av verifikatet. Du godkänner eller avvisar under Väntande åtgärder. Det är säkerhetsmodellen: inget riskabelt bokförs tyst, och varje beslut loggas med vem/vad/när.$faq$, $faq$[]$faq$::jsonb, '{}'::text[], array['/pending']::text[], 'low', NULL, '2026-07-02T00:00:00Z'::timestamptz, now()),
  ('onboarding-035', 'Kom igång & onboarding', 'ta_bort_foretag', $faq$["Hur tar jag bort ett företag?","Kan jag radera all data?","Arkivera bolag?"]$faq$::jsonb, $faq$Företag arkiveras i stället för att raderas — bokföringsdata måste bevaras i 7 år enligt BFL.$faq$, $faq$Ett företag med bokförd data kan arkiveras (döljs från väljaren) men inte hårdraderas, eftersom räkenskapsinformation enligt BFL 7 kap ska bevaras i sju år. Sandlådeföretag och tomma bolag kan tas bort helt. Kontakta supporten för arkivering eller dataexport (SIE + dokument) innan avslut.$faq$, $faq$["BFL 7 kap"]$faq$::jsonb, '{}'::text[], array['/settings/company']::text[], 'medium', NULL, '2026-07-02T00:00:00Z'::timestamptz, now())
